export default [{"id":212,"question":"أذان الجمعة الأول انقضت الحكمةُ منه الآن، فهل يُعتبر بدعةً؟","title":"ما حكم الأذان الأول يوم الجمعة؟","answer":"الجواب: ليس ببدعةٍ، ولم تنقضِ الحكمة، ومَن قال هذا فقد غلط، إذا كان الأوَّلون من أصحاب النبيِّ ﷺ قد يُشغلون عن الجمعة، وقد لا ينتبهون لها؛ فكيف بحالنا أيّها الموجودون الآن؟ هل نحن أكثر انتباهًا منهم للعبادة، وأكثر حفظًا منهم للعبادة؟ كلا، هم أحفظ منا، وخيرٌ منا، فإذا فعله عثمانُ الخليفة الراشد للتَّنبيه، فمَن بعد الصحابة أشد حاجةٍ إلى التَّنبيه، وأكثر شغلًا، وأكثر غفلةً، فلم تنقضِ الحاجة، هو تنبيهٌ على أنَّ اليوم يوم جمعة؛ ليستعدَّ المؤمنُ ويُبادر بالتوجه إلى المساجد.\nوقد استمرَّ عليه المسلمون من عهد الخليفة الراشد عثمان إلى يومنا هذا في غالب الأمصار والأعصار، وقلَّ أن يوجد بلدٌ أو دولةٌ تركت ذلك.","link":"https://binbaz.org.sa/fatwas/3993/ما-حكم-الاذان-الاول-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0219.mp3","categories":["الأذان والإقامة","صلاة الجمعة"]},{"id":303,"question":"إذا دخل أحدٌ المسجد في وقت النَّهي هل يُصلي ركعتين أو يجلس؟","title":"حكم الصلاة في أوقات النهي؟","answer":"الجواب: إذا دخل الإنسانُ وقت النَّهي –مثل: بعد العصر دخل المسجد، ومثل: بعد  الصبح- فإنَّ السنة أن يُصلي ركعتين ولو كان في وقت النَّهي، هذا هو المختار من أقوال أهل العلم، وهذا الذي يقوم عليه الدليلُ، وتُسمَّى هذه الصلاة من ذوات الأسباب، والرسول  قال: إذا دخل أحدُكم المسجدَ فلا يجلس حتى يُصلي ركعتين، ولم يقل: إلا وقت العصر، وإلا وقت الفجر، لا، وقال عليه الصلاة والسلام: مَن جاء والإمام يخطب يوم الجمعة فليركع ركعتين، وليتجوَّز فيهما، فأمره بالركعتين والإمام يخطب، فهذا وقتٌ يُنهى فيه عن القيام للصلاة لو كان جالسًا، ومع هذا أمر أن يُصلي ركعتين ثم يجلس والإمام يخطب؛ وما ذاك إلا لعظم شأن هاتين الركعتين.\nوهكذا صلاة الطواف: لو جاء إلى المسجد الحرام بعد العصر وطاف يُصلي ركعتين مثل تحية المسجد؛ لأنَّها من ذوات الأسباب، وهكذا مثل الصبح؛ لقول النبي ﷺ: يا بني عبد مناف، لا تمنعوا أحدًا طاف بهذا البيت وصلَّى أيَّة ساعةٍ شاء من ليلٍ أو نهارٍ.\nوهكذا في الكسوف: لو كسفت الشمسُ بعد العصر صلَّى الناسُ؛ لأنَّ الرسول ﷺ أمر بذلك، ولم يستثنِ وقتًا دون وقتٍ، فقال: إنَّ الشمس والقمر آيتان من آيات الله، لا ينخسفان لموت أحدٍ من الناس ولا لحياته، فإذا رأيتُم ذلك فصلُّوا وادعوا، وفي اللفظ الآخر: فإذا رأيتُم ذلك فافزعوا إلى الصلاة، وإلى ذكر الله، وإلى دعائه واستغفاره، فهذه الصلاة ليس لها وقتُ نهيٍ، بل متى وُجِد الكسوفُ شُرع للناس الصلاة، ولو كان بعد العصر، ولو طلعت الشمسُ كاسفةً صلّوا صلاة الكسوف، نعم.","link":"https://binbaz.org.sa/fatwas/4305/حكم-الصلاة-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0352.mp3","categories":["أوقات النهي","صلاة الجمعة"]},{"id":729,"question":"ما حكم خروج كثيرٍ من الناس في يوم الجمعة للبرِّ من أجل النُّزهة، ويترتب على ذلك ترك صلاة الجمعة مع الجماعة؟","title":"حكم ترك صلاة الجمعة للخروج إلى البر","answer":"الجواب: لا نعلم في ذلك شيئًا، إذا بعدوا عن البلد للنزهة وصلّوا ظهرًا فلا بأس؛ لأنَّ الجمعة إنما تجب على مَن حضر وصار يسمع النِّداء دون فرسخٍ، أما إذا بَعُد عن البلد صلوا ظهرًا. ولكن يُشرع لهم ألا يفعلوا ذلك، أو يفعلوه تارةً وتارةً، حتى لا يحرموا أنفسَهم هذا الخير، يُشرع لهم المحافظة على الجمعة، حتى يسمعوا الفائدة، ويسمعوا الخطبة، ولكن لا تلزمهم الجمعة إذا بعدوا، وإنما يلزمهم الظّهر.\nس: لو خرج يوم الجمعة بعد الزوال؟\nالشيخ: لا يجوز بعد الزوال، إذا زالت الشمسُ؛ وجب عليه أن يُصلي مع الناس.","link":"https://binbaz.org.sa/fatwas/20626/حكم-ترك-صلاة-الجمعة-للخروج-الى-البر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0556ما حكم الخروج في يوم الجمعة للبر من أجل النزهة ويترتب على ذلك ترك صلاة الجمعة.mp3","categories":["صلاة الجمعة"]},{"id":845,"question":"ما حكم الصلاة الفرض أو السنة في الأوقات المنهي عنها؟ وما صحة حديث عمر، قال: \"صليتُ العصر ولما تغرب الشمس\"، قال له الرسولُ ﷺ: والله الذي لا إله إلا هو، إنَّك لم تُصلِّ، قم فصلِّ، ثم توضأ بعد المغرب وصلَّى العصر؟","title":"حكم صلاة الفرض والسنة في وقت النهي","answer":"الجواب: الصلاة فيها تفصيل في أوقات النهي:\nأما النوافل المطلقة فلا يجوز فعلها وقت النهي: بعد العصر إلى غروب الشمس، وبعد الصبح إلى ارتفاع الشمس، وعند قيام الشمس، جاء في الأحاديث المتواترة عن رسول الله ﷺ النَّهي عن ذلك.\nأما الصلاة ذات الأسباب: كصلاة الطواف في مكة، وصلاة تحية المسجد، والكسوف، ففيها خلافٌ بين أهل العلم، والصواب أنها تجوز، تجوز ذوات الأسباب في أوقات النَّهي؛ للأحاديث الصَّحيحة الواردة في ذلك المطلقة، ولقوله ﷺ: يا بني عبد مناف، لا تمنعوا أحدًا طاف بهذا البيت وصلَّى أية ساعةٍ شاء، من ليلٍ أو نهارٍ، وقوله ﷺ في الكسوف: فإذا وجدتم ذلك فصلُّوا وادعوا يعني: الكسوف، فإنَّهما آيتان من آيات الله، لا ينكسفان لموت أحدٍ ولا لحياته، فإذا رأيتم ذلك فافزعوا إلى الصلاة، فصلوا وادعوا، ولم يخصّ ذلك في وقتٍ دون وقتٍ، فدلَّ على أن صلاة الكسوف يجوز فعلها في وقت النَّهي: كالعصر، وحديث: إذا دخل أحدُكم المسجد فلا يجلس حتى يُصلي ركعتين عامٌّ أيضًا، على الصحيح.\nأما الحديث الذي أشرتَ إليه فليس كما ذكرتَ: في يوم الأحزاب قال عمر: ما صليتُ العصر حتى كادت الشمسُ تغرب، فقال النبيُّ: ما صليتُها، هو نفسه، ما قال: ما صليتَها أنت، قال النبي: ما صليتُها أنا، يعني: النبي ﷺ، ثم توضؤوا وصلّوا العصر بعدما غربت الشمس، ثم صلوا بعدها المغرب، هذا يوم الأحزاب صلاة الفريضة.\nوهذا احتجَّ به العلماء، وجمع بعض العلماء على أن المجاهدين إذا اشتدَّ القتال وحمي الوطيس ولم يتيسر لهم الصلاة جاز تأخيرها عن وقتها حتى تُصلَّى على وجهٍ صحيحٍ، فالنبي ﷺ وأصحابه في بعض أيام العدو مع الأحزاب لم يتيسر لهم أن يُصلّوا العصر حتى غابت الشمس، حتى كادت الشمس أن تغرب، وأخَّروها من أجل شغلهم بالقتال مع أعداء الله، فهذا يدل على الصحيح إذا دعت إليه الضَّرورة، ولو فات الوقت.\nقال بعضُ أهل العلم: إنَّ هذا كان قبل شرعية صلاة الخوف، والصواب أنه ليس قبلها، بل بعدها، ولو فرضنا أنه قبلها فالجمع مُقدَّم على النسخ، فصلاة الخوف تُصلَّى حيث أمكن، وإذا لم يمكن فعلها جاز التأخير للحاجة الشَّديدة أو الضَّرورة، كما فعل النبيُّ ﷺ يوم الأحزاب.\nوثبت من حديث أنسٍ رضي الله تعالى عنه: أن الصحابة في قتال الفرس لما فتحوا تُسْتَر فتحوها عند طلوع الفجر، والناس بعضهم على الأبواب، وبعضهم على السور، وبعضهم نزل البلد، فلم يتمكنوا من صلاة الفجر إلا ضُحًى، قال أنسٌ : \"فما أُحب أنَّ لي بها كذا وكذا\"؛ لأنَّهم أخَّروها لعذرٍ شرعيٍّ وضرورةٍ، وهو أنهم على أبواب البلد، وعلى سورها، والقتال حامٍ بينهم وبين العدو، ليس في إمكانهم أن يُصلوا ذاك الوقت.\nفالحاصل أنه يجوز على الصحيح تأخير الصلاة عن وقتها في وقت الحرب والجهاد مع الأعداء إذا لم تُمكن صلاة الخوف.","link":"https://binbaz.org.sa/fatwas/20884/حكم-صلاة-الفرض-والسنة-في-وقت-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0679ما حكم صلاة الفرض والسنة في الأوقات المنهي عنه؟ ابن باز فتاوى المحاضرات.mp3","categories":["أوقات النهي","صلاة الجمعة"]},{"id":1402,"question":"تطويل الخطبة أحيانًا؟","title":"ما حكم تطويل خطبة الجمعة أحيانًا؟","answer":"الجواب:\nإذا دعت الحاجة لا بأس، النبي ﷺ كان يُطَوِّلها بعض الأحيان إذا دعت الحاجة إلى ذلك، لكن الأصل والأساس القَصْد، هذا هو الأصل.","link":"https://binbaz.org.sa/fatwas/21495/ما-حكم-تطويل-خطبة-الجمعة-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تطويل الخطبة.mp3","categories":["صلاة الجمعة"]},{"id":1494,"question":"بعض الناس يوم الجمعة بين الخطبتين يدعو بسيد الاستغفار، هل له أصل في هذا الوقت؟","title":"ما المشروع قوله بين خُطبتي الجمعة؟","answer":"الجواب:\nما ورد شيء، لكن بينه وبين نفسه يدعو بما شاء، هو أو غيره، أما في هذا الموضع فما جاء فيه شيء من دعوةٍ خاصةٍ بين الخطبتين، لكن الإنسان إذا دعا بين الخطبتين لا بأس، سرًّا.\nس: إذا رفع صوتَه في مثل هذه الحالة تكون لغوًا؟\nج: لا، ما هي بخطبة، هذه ما هي تبع الخطبة، هذا شيء بينه وبين ربِّه، لا يرفع صوته.\nس: إذا رفع يكون قد لغا؟\nج: ولو رفع صوته ما هو من الخطبة، الخطبة انتهت.","link":"https://binbaz.org.sa/fatwas/21592/ما-المشروع-قوله-بين-خطبتي-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما يقال بين خطبتي الجمعة.mp3","categories":["صلاة الجمعة"]},{"id":1613,"question":"ناس سافروا وأدركتهم صلاةُ الجمعة، هل يُصلونها ظهرًا قصرًا؟","title":"حكم صلاة الجمعة للمسافر","answer":"الجواب:\nفي البَرّ؟\nس: نعم في البَرّ.\nج: لا، يُصلون ظهرًا فقط، ما عليهم جمعة.\nس: ما يقصرون الظّهر؟\nج: بلى، يُصلون الظهر ثنتين، ما عليهم إلا ظهر، الجمعة في حقِّ المقيمين المُستوطنين.\nس: يعني: يقصرون الظهر؟\nج: نعم، الظهر في حقِّهم في السفر؛ لأنَّ المسافر ليس عليه جمعة، لكن لو مرُّوا على قريةٍ أو بلدٍ وصلّوا مع الناس جمعةً أجزأتهم عن الظهر.","link":"https://binbaz.org.sa/fatwas/21717/حكم-صلاة-الجمعة-للمسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صلاة الجمعة للمسافر.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":1891,"question":"في حديثٍ يقول: مَن غسَّل واغتسل، وبكَّر وابتكر، ومشى ولم يركب ..؟","title":"متى يبدأ فضل التبكير للصلاة يوم الجمعة؟","answer":"الجواب:\nهذا لا بأس به، هذا حديث الجمعة.\nس: ما التوقيت لمثل ساعتنا اليوم؟\nج: هذا التبكير للجمعة.\nس: كم الساعة يعني على وجه التقدير؟\nج: الله أعلم، بعد ارتفاع الشمس، وبعدما يتناول الفطور، ويقضي حاجته؛ يتوجَّه.","link":"https://binbaz.org.sa/fatwas/22002/متى-يبدا-فضل-التبكير-للصلاة-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في يوم الجمعة وخصائصه.mp3","categories":["صلاة الجمعة"]},{"id":1943,"question":"شاهدتُ في أحد المساجد في أثناء الخطبة رجلًا يُوقِظ مَن بجواره فهل يأثم؟","title":"حكم الإشارة باليد للتنبيه أثناء خطبة الجمعة","answer":"الجواب:\nلا، باليد ما هو بالكلام.\nس: نعم هو باليد؟\nج: ما فيه بأس، مثل مَن يتكلم فيُشير له حتى يسكت، الإشارة تجوز حتى في الصلاة، والصلاة أعظم، فلو أشار في الصلاة لمن يتقدَّم أو يتأخَّر فلا بأس.\nس: في أثناء الخطبة وفي آخر الصفوف عادةً يكون هناك صبية، فيسمعهم يتكلَّمون فهل يُشير إليهم؟\nج: يُشير إليهم، ما فيه بأس.","link":"https://binbaz.org.sa/fatwas/22056/حكم-الاشارة-باليد-للتنبيه-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إيقاظ النائم والإشارة للأطفال أثناء خطبة الجمعة.mp3","categories":["صلاة الجمعة"]},{"id":2216,"question":"هل يُؤخذ من حديث أبي رفاعة أن الإمام إذا دعت الحاجةُ لا بأس أن يقطع خطبته؟","title":"حكم قطع الإمام خطبة الجمعة لحاجة","answer":"الجواب:\nنعم، يقطعها لحاجةٍ عارضةٍ ويُتمّها، كإرشاد إنسانٍ على خطر، وإنكار منكرٍ، وغير ذلك، مثلما كان يخطب ﷺ فدخل إنسانٌ فجلس، فقال له: قم، فصلِّ ركعتين.","link":"https://binbaz.org.sa/fatwas/22339/حكم-قطع-الامام-خطبة-الجمعة-لحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث انْتَهَيْتُ إِلى رَسولِ اللَّه وَهُوَ يَخْطُبُ فقلتُ يَا رسولَ اللَّه.. هل يجوز أن يقطع الإمام خطبة الجمعة.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":2267,"question":"رجل لحق ركعةً مع الإمام من صلاة الجمعة وهو مسافرٌ، فهل يُتم الصلاةَ ظهرًا أم قصرًا؟","title":"ماذا يفعل المسافر إذا أدرك ركعة من الجمعة؟","answer":"الجواب:\nيُصلي جمعةً، فيأتي بركعةٍ ثانيةٍ، هو وغيره، فمَن أدرك ركعةً من الجمعة أضاف إليها أخرى، سواء كان مسافرًا أو مُقيمًا، وتُجْزِئه.","link":"https://binbaz.org.sa/fatwas/22390/ماذا-يفعل-المسافر-اذا-ادرك-ركعة-من-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لحق ركعةً مع الإمام من صلاة الجمعة وهو مسافر فهل يقصر أم يتمّ.mp3","categories":["صلاة الجمعة"]},{"id":2292,"question":"ما حكم كتابة الفوائد في خطبة الجمعة؟","title":"حكم كتابة الفوائد أثناء خطبة الجمعة","answer":"الجواب:\nالذي يظهر لا، ما ينبغي، عليهم الإنصات، وإذا أرادوا الكتابةَ يكتبون بعد ذلك.\nس: بالنسبة لتسجيل الفوائد كما ذكر الأخ: لو كان الأَوْلى تسجيلها لا بأس؟\nج: لا يُسجّلها والإمام يخطب، لا، يُنْصِتْ ويُقْبِل على الخطبة.\nس: من خلال المُسَجِّل؟\nج: في المسجّل ما يُخالف.","link":"https://binbaz.org.sa/fatwas/22415/حكم-كتابة-الفواىد-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كتابة الفوائد أثناء خطبة الجمعة.mp3","categories":["صلاة الجمعة"]},{"id":2395,"question":"سنة الجمعة البعدية بعد ذكر قول شيخ الإسلام أنها تُفعل بعد الصلاة في المسجد أربع ركعات وفي البيت ركعتين دليل التخصيص؟","title":"هل الأفضل لسنة الجمعة أربع ركعات مطلقًا؟","answer":"الجواب:\nلا، الأفضل أربع ركعات مطلقًا، بعضهم يستدل بأن النبي ﷺ كان يصلي في بيته ركعتين، لكن ما يدل على ترك الأربع، الأفضل أربع مطلقًا حتى في البيت؛ لأن الرسول ﷺ قال: من كان مصليًا فليصلي بعدها أربعًا، وفي الحديث الآخر: إذا صليتم الجمعة فصلوا بعدها أربعًا هذا عام يعم البيت ويعم المسجد، كون النبي ﷺ صلاها في بيته ركعتين يدل على أن الأمر مُخَفَّف مُيَسَّر، والحمد لله.","link":"https://binbaz.org.sa/fatwas/22520/هل-الافضل-لسنة-الجمعة-اربع-ركعات-مطلقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سنة الجمعة البعدية.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":2412,"question":"سنة الجمعة البعدية الأفضل في البيت؟","title":"هل تُؤدى سُنة الجمعة البعدية في البيت؟","answer":"الجواب:\nأفضل في البيت، وإن صلاها في المسجد فلا بأس، لكن الأفضل أربع كما في الحديث الآتي: من كان مصليًا بعد الجمعة فليصل بعدها أربعًا إن صلاها في البيت فلا بأس، وإن صلاها في المسجد فلا بأس، وفي البيت أفضل، وإن صلاها في المسجد فالحمد لله الأمر واسع.","link":"https://binbaz.org.sa/fatwas/22539/هل-تودى-سنة-الجمعة-البعدية-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سنة الجمعة البعدية الأفضل في البيت.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":2442,"question":"سُنة الجمعة أيهما أفضل في البيت أو في المسجد؟","title":"هل الأفضل لسُنة الجمعة البيت أم المسجد؟","answer":"الجواب:\nالنوافل كلها في البيت أفضل، وإن صلاها في المسجد فلا بأس، كلها الأفضل في البيت، النبي ﷺ قال: أفضل صلاة المرء في بيته إلا المكتوبة.\nس: ما الفرق بين سنة الجمعة في أن يصلي في المسجد أربعًا وفي البيت ركعتين، هل هذا التفريق صحيح؟\nالشيخ: الأصل مثل ما أخبر النبي ﷺ: مَنْ كان مُصَلِّيًا بعد الجمعة فليصل بعدها أربعًا السنة أربع، هذا السنة، الكمال أربع في البيت أو في المسجد؛ لقوله ﷺ: من كان مصليا بعد الجمعة فليصل بعدها أربعًا، وفي اللفظ الآخر: إذا صليتم بعد الجمعة فصلوا بعدها أربعًا رواه مسلم.\nس: هذا الأمر يدل على الوجوب؟\nالشيخ: لا، مَنْ كان مُصَلِّيًا.","link":"https://binbaz.org.sa/fatwas/22571/هل-الافضل-لسنة-الجمعة-البيت-ام-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أين تؤدى سنة الجمعة في البيت أو في المسجد.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":2449,"question":"الصلاة بين الأذان والإقامة كيف تُؤدى يوم الجمعة...؟","title":"هل لصلاة الجمعة راتبة قبلها؟","answer":"الجواب:\nالجمعة ما لها راتبة قبلها، يصلي ما تيسّر قبلها، يصلي ثنتين أو أربع أو ثمان أو عشر، ما لها حد محدود، يصلي ما تيسر، أقلها ثنتان قبل الجمعة، ما لها راتبة قبلها، يصلي ما تيسر، يصلي أربع هذا الأفضل بتسليمتين.","link":"https://binbaz.org.sa/fatwas/22578/هل-لصلاة-الجمعة-راتبة-قبلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للجمعة راتبة قبلها.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":2469,"question":"مس الحصى المقصود به اللعب بالحصى؟","title":"معنى مس الحصى ونحوه أثناء خطبة الجمعة","answer":"الجواب:\nالعبث يعني العبث.\nس: تنتفي العلة الآن، لأن المساجد الآن ليس فيها حصى؟\nالشيخ: الحمد لله، لكن قد يعبث بشيء آخر.","link":"https://binbaz.org.sa/fatwas/22598/معنى-مس-الحصى-ونحوه-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مس الحصى في الجمعة هل تنتفي الآن لأن المساجد ليس فيها حصى.mp3","categories":["صلاة الجمعة"]},{"id":2470,"question":"حديث أبي هريرة من توضأ فأحسن الوضوء ثم أتى الجمعة هل هذا صارف لحديث: غسل الجمعة واجب على كل محتلم؟","title":"هل غُسْل الجمعة واجب أم مستحب؟","answer":"الجواب:\nهذا من أدلة عدم الوجوب؛ لأن قوله ﷺ: من توضأ يدل على أن الغسل ما هو بواجب، سُنة مؤكّدة.","link":"https://binbaz.org.sa/fatwas/22599/هل-غسل-الجمعة-واجب-ام-مستحب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من توضأ فأحسن الوضوء ثم أتى الجمعة هل يدل على الوجوب.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":2477,"question":"هل تَخَطِّي الرقاب مِن التفرقة بين الاثنين؟","title":"معنى تخطي الرقاب والتفرقة بين الاثنين","answer":"الجواب:\nهذا وهذا، لا يُفَرِّق بين اثنين يجلس بينهم، يُفَرِّقهم ويجلس بينهم، يَصُفّ بينهم، يَصُفّ حيث انتهى الصف، لا يُفّرِّق بين الناس. وأمر آخر وهو: لا يتخطى رقاب الناس في الصفوف، يذهب إلى طرف الصف ولا يتخطى رقاب الناس إلا إذا وجد فُرجة خَلَّوها، هم الذين أساؤوا، يتخطاها ليسد الفرجة، وأما إذا كانت الصفوف مستقيمة فلا يتخطى شيئًا، لا يُدَوِّر، يروح إلى منتهى الصف ويَصُفّ ولا يُدَوِّر يتخطى رقاب الناس.","link":"https://binbaz.org.sa/fatwas/22606/معنى-تخطي-الرقاب-والتفرقة-بين-الاثنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التفرقة بين الاثنين من تخطي الرقاب.mp3","categories":["صلاة الجمعة"]},{"id":2587,"question":"في أثناء الخُطبة يكون هناك صغار سن يشوِّشون على الناس فهل ينبِّههم أو يشير لهم؟","title":"حكم الإشارة للأطفال بالسكوت وقت الخُطبة","answer":"الجواب: يشير لهم الذين حولهم بالتسكيت، الإشارة تكفي.\nس: هل يكلف الإمام أحداً بأن ينظر إليهم؟\nالشيخ: الإمام له يتكلم، يقول: سكّتوهم، ما في بأس، الإمام له أن يتكلم للمصلحة، الخطيب نفسه، كما تكلم النبي ﷺ في بعض الخُطُب.","link":"https://binbaz.org.sa/fatwas/22720/حكم-الاشارة-للاطفال-بالسكوت-وقت-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الإشارة للأطفال بالسكوت وقت الخطبة.mp3","categories":["صلاة الجمعة"]},{"id":2588,"question":"إلقاء الخطبة عن طريق الورقة أفضل أم عن طريق... اتباعاً لهديه عليه الصلاة السلام؟","title":"هل الخُطبة عن ظهر قلب أفضل من قراءتها؟","answer":"الجواب: حسب التيسير، الذي يقدر عن ظهر قلب أحسن، والذي ما يقدر؛ يكتبها وما في بأس، وعن ظهر قلب أوْلى وأجْمع للقلوب وأحسن، وإذا ما تيسر؛ يكتبها ويلقيها من كتابه.","link":"https://binbaz.org.sa/fatwas/22721/هل-الخطبة-عن-ظهر-قلب-افضل-من-قراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إلقاء الخطبة ظهر قلب أو من الورق.mp3","categories":["صلاة الجمعة"]},{"id":2589,"question":"كثير من الناس يدخل يوم الجمعة والإمام يخطب ولا يصلون تحية المسجد؛ فهل للإمام أن يُنْكر...؟","title":"حكم تحية المسجد أثناء خطبة الجمعة","answer":"الجواب: لا، السُّنة يصلون، من دخل والإمام يخطب يصلي التحية، والإمام عليه أن ينبِّههم، ولهذا لما رأى النبي رجلًا دخل ولم يصل التحية قال: قم فصل ركعتين، وهو في الخطبة عليه الصلاة والسلام.\nس: لكن هم كُثر هل يُنَبّه كل واحد يدخل؟\nالشيخ: لا، يُنَبِّه بالعموم ويَعرِفون إن شاء الله..... يقول: من دخل فليصل ركعتين، من دخل المسجد فليصل ركعتين، ولو كان الإمام يخطب ينبِّههم؛ حتى يبلغ أمر الله.","link":"https://binbaz.org.sa/fatwas/22722/حكم-تحية-المسجد-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة تحية المسجد والإمام يخطب يوم الجمعة.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":2851,"question":"إذا قال الخطيب يوم الجمعة: صلوا على النبيﷺ، هل يقولها الشخص بينه وبين نفسه؟","title":"كيف تكون الصلاة والتسليم أثناء الجمعة؟","answer":"الجواب: بين وبينه نفسه، إذا قال: صلوا، عند ذكر النبيﷺ، ولو ما قال: صلوا، عند الشهادة أن محمدًا رسول الله يُصلي عليه.","link":"https://binbaz.org.sa/fatwas/23004/كيف-تكون-الصلاة-والتسليم-اثناء-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة على رسول الله عند خطبة الجمعة.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":3327,"question":"بالنسبة لصلاة  النساء هل (تجزئها) الجمعة؟","title":"هل تجزئ الجمعة عن الظُّهر للمرأة؟","answer":"الجواب: إذا حضرنها يصلينها جمعة، وإلا صلينها في بيوتهن ظهرًا، النساء ما عليهن جمعة، لكن لو حضرن الجمعة أجزأتهن، لكن إذا لم يحضرن يصلين الظهر في البيت أربعًا، مثل المريض يصلي الظهر في البيت، والمرأة تصلي الظهر في البيت، والبيت أفضل بيوتهن خير لهن.","link":"https://binbaz.org.sa/fatwas/23493/هل-تجزى-الجمعة-عن-الظهر-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا حضرت المرأة الجمعة هل تجزئها أم لابد أن تصلي ظهرًا.mp3","categories":["صلاة الجمعة","قضايا المرأة"]},{"id":3456,"question":"دخل في وقت أذان الجمعة: ينتظر وقت الأذان، أم يبدأ فيركع؟","title":"ما يفعل من دخل المسجد أثناء أذان الجمعة؟","answer":"الجواب: الأفضل يجيب المؤذن، ثم يصلي ركعتين؛ حتى يجمع بين السُّنَّتين.","link":"https://binbaz.org.sa/fatwas/23633/ما-يفعل-من-دخل-المسجد-اثناء-اذان-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من دخل المسجد والمؤذن يؤذن للجمعة.mp3","categories":["صلاة الجمعة"]},{"id":3546,"question":"بعض أئمة الجوامع يتقدم ويجلس مع المصلين يوم الجمعة قبل الصلاة بساعة، فقيل له: إن السنة أن تأتي عند الخطبة فقال: أفضل أدرك الأجر؟","title":"حكم تبكير خطيب الجمعة قبل الأذان بوقت","answer":"الجواب: ما أعلم مانعًا، أعمال النبي ﷺ وأقواله يجب التوفيق بينها، فلا منافاة بين القول والفعل، من تأخر لحاجة فلا بأس، أو لعذر، ومن تقدم فلا بأس؛ لأن أقواله ﷺ لا تخالف أفعاله، أفعاله تُفَسّر بأقواله، وأقواله تُفَسّر بأفعاله.","link":"https://binbaz.org.sa/fatwas/23728/حكم-تبكير-خطيب-الجمعة-قبل-الاذان-بوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم حضور خطيب الجمعة قبل الجمعة بوقت.mp3","categories":["صلاة الجمعة"]},{"id":3615,"question":"غسل الجمعة سنة؟","title":"ما حكم غسل الجمعة ووقته؟","answer":"الجواب: سنة مؤكدة نعم.\nس: سلمك الله، لو اغتسل للجمعة بعد الفجر، ثم أحدث، يتوضأ أو يغتسل مرة ثانية؟\nالشيخ: يكفي الوضوء، يوم الجمعة كله محل اغتسال قبل الصلاة يعني، لكن كونه يغتسل عند الذهاب أفضل.\nس: ومن اغتسل بعد الفجر؟\nالشيخ: إذا اغتسل بعد الفجر كفى، لكن إذا كان عند ذهابه إلى الجمعة يكون أفضل؛  من راح فليغتسل عندما راح..... إذا تيسر الغسل عند توجهه إلى الجمعة يكون أفضل.\nس: إذا اغتسل بعد الفجر ثم نام؟\nالشيخ: ولو، يحصل المقصود إذا كان بعد الفجر يحصل المقصود، لكن الأفضل عند توجهه إلى الجمعة.\nس: هل له أن يغتسل قبل الفجر؟\nالشيخ: لا، في اليوم، غسل يوم الجمعة، الغسل يكون في النهار.\nس: الغسل بين الأذان والإقامة؟\nالشيخ: المقصود ما دام بعد الصبح يجزئ.","link":"https://binbaz.org.sa/fatwas/23797/ما-حكم-غسل-الجمعة-ووقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في غسل الجمعة.mp3","categories":["صلاة الجمعة"]},{"id":3616,"question":"إذا ذهب الصبي إلى الجمعة فهل يؤمر بالاغتسال؟","title":"هل يؤمر الصبي بالغسل إذا ذهب للجمعة؟","answer":"الجواب: الغسل في حق المحتلم.","link":"https://binbaz.org.sa/fatwas/23798/هل-يومر-الصبي-بالغسل-اذا-ذهب-للجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يغتسل الصبي إذا ذهب للجمعة.mp3","categories":["صلاة الجمعة"]},{"id":3617,"question":"هل للإنسان أن يستمر مصليا إلى دخول الخطيب أو ...؟","title":"متى ينتهي وقت التطوع قبل خطبة الجمعة؟","answer":"الجواب: له أن يصلي مائة أو ألف حتى يدخل الخطيب، الحمد لله، محل صلاة إلى دخول الخطيب، ما في وقت نهي.","link":"https://binbaz.org.sa/fatwas/23799/متى-ينتهي-وقت-التطوع-قبل-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة التطوع قبل الجمعة.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":3619,"question":"من خصائص الجمعة أن ما لها وقت نهي؟","title":"هل يوجد وقت نهي قبل صلاة الجمعة؟","answer":"الجواب: نعم؛ لأن الرسولﷺ قال: فصلى ما قُدر له، ثم أنصت حين يخطب الإمام دلّ على أنها كلها محل صلاة.","link":"https://binbaz.org.sa/fatwas/23801/هل-يوجد-وقت-نهي-قبل-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من خصائص الجمعة لا وقت نهي فيها.mp3","categories":["صلاة الجمعة"]},{"id":3620,"question":"هل للخطيب أن يبكّر ليصلي ويقرأ القرآن؟","title":"حكم تبكير الخطيب للمسجد يوم الجمعة","answer":"الجواب: في بيته أفضل، مثل ما كان النبي ﷺ يفعل، النبي ما كان يأتي إلا وقت الخطبة.","link":"https://binbaz.org.sa/fatwas/23802/حكم-تبكير-الخطيب-للمسجد-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للخطيب أن يبكر.mp3","categories":["صلاة الجمعة"]},{"id":3621,"question":"قول من قال أن صلاة الجمعة يبتدئ وقتها كصلاة العيد؟","title":"هل صح أن الجمعة يبتدئ وقتها كصلاة العيد؟","answer":"الجواب: ضعيف، قول ضعيف، الصواب: إذا زالت الشمس.","link":"https://binbaz.org.sa/fatwas/23804/هل-صح-ان-الجمعة-يبتدى وقتها-كصلاة-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل وقت صلاة الجمعة كصلاة العيد.mp3","categories":["صلاة الجمعة"]},{"id":3622,"question":"الخطيب إذا تنفل من بيته وقرأ القرآن هل يكون مثل من قرّب بدنة إذا بدأ في أول الوقت؟","title":"كيف يكون فضل التبكير لخطيب الجمعة؟","answer":"الجواب: الله أعلم، لكن يُرجى له الخير، لكن الرسول ما كان يأتي إلا عند الخطبة، فهو إذا كان حبس نفسه من أجل اتباع السنة يُرجى له الخير إن شاء الله.","link":"https://binbaz.org.sa/fatwas/23805/كيف-يكون-فضل-التبكير-لخطيب-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا تنفل الخطيب من بيته وقرأ القرآن هل يكون مثل من قرب بدنة..mp3","categories":["صلاة الجمعة"]},{"id":3623,"question":"ما المراد بالساعة يوم الجمعة، هل هي الزمن المعروف؟","title":"المراد بالساعة يوم الجمعة في فضل التبكير","answer":"الجواب: تجزئة النهار اثنا عشر ساعة، النهار مجزأ اثنا عشر ساعة، فإذا راح في الساعة الأولى كما في الحديث، اثنا عشر ساعة مجزأ.","link":"https://binbaz.org.sa/fatwas/23806/المراد-بالساعة-يوم-الجمعة-في-فضل-التبكير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المراد بالساعة يوم الجمع.mp3","categories":["صلاة الجمعة"]},{"id":3624,"question":"معنى قوله: ولا يفرق بين اثنين؟","title":"معنى \"ولا يفرق بين اثنين؟\" في الجمعة","answer":"الجواب: يعني يصف حيث انتهى الصف، لا يؤذي الناس.","link":"https://binbaz.org.sa/fatwas/23807/معنى-ولا-يفرق-بين-اثنين-في-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى ولا يفرق بين اثنين في الجمعة.mp3","categories":["صلاة الجمعة"]},{"id":3626,"question":"هل يصلي على النبي ﷺ إذا ذكره الخطيب؟","title":"هل يُصلّى على النبي ﷺ أثناء الخطبة؟","answer":"الجواب: لا بأس به، بينه وبين نفسه، لا يشوّش على من حوله.","link":"https://binbaz.org.sa/fatwas/23809/هل-يصلى-على-النبي-ﷺ-اثناء-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة على النبي حال الخطبة.mp3","categories":["صلاة الجمعة"]},{"id":3627,"question":"اعتاد بعض الناس في الحرم المكي إذا أذن المؤذن الأذان الثاني قام أغلب الناس يصلون ركعتين؟","title":"حكم صلاة ركعتين بعد الأذان الثاني للجمعة","answer":"الجواب: لا، هذا خلاف السنة، السنة الجلوس للإنصات، هذا ما هو داخل بين كل أذانين صلاة.\nس: الأذان الأول أحسن إليك يا شيخ؟\nالشيخ: ما له أصل، هذا للتنبيه، ما بعده صلاة في الأذان الأول، تركها أوْلى، ومثله الأذان الثاني كذلك، يتهيؤون للإنصات.","link":"https://binbaz.org.sa/fatwas/23810/حكم-صلاة-ركعتين-بعد-الاذان-الثاني-للجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة ركعتين إذا أذن المؤذن الأذان الثاني في الجمعة.mp3","categories":["صلاة الجمعة"]},{"id":3657,"question":"الخطيب إذا أخطأ في خطبته هل يرد عليه ويقال: إنك قد أخطأت أمام الناس؟","title":"هل يُردُّ على الخطيب إذا أخطأ في الخطبة؟","answer":"الجواب: إذا كان خطؤه واضحًا وخالف الشرع، بالكلام الطيب. أما إن كان خطأ سهل ما يضر، خطأ نحوي أو كذا، سهل.  أما إذا كان أحلَّ حرامًا أو أوجب ما لا يجب؛ يبين له بالأدلة الشرعية، لا بأس.","link":"https://binbaz.org.sa/fatwas/23845/هل-يرد-على-الخطيب-اذا-اخطا-في-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يرد على الخطيب إذا أخطأ في خطبته.mp3","categories":["صلاة الجمعة"]},{"id":4012,"question":"قوله: وما كنا نقيل ولا نتغدى إلا بعد الجمعة، هل في هذا دليل جواز إقامة صلاة الجمعة قبل الزوال؟","title":"هل تجوز إقامة صلاة الجمعة قبل الزوال؟","answer":"الجواب: لا، ما هو صريح، ليس بصريح، احتج بعض أهل العلم على ذلك، لكن ليس بصريح؛ لأنهم يبكّرون إلى الجمعة، والتبكير يدعو إلى تأخير القائلة، إلى بعد الصلاة؛ لأن الرسول كان يقيمها في الغالب إذا زالت الشمس، هذا هو المعروف عنه عليه الصلاة والسلام؛ يبكر بها من حين تزول الشمس، فإذا صلوا أراحوا رواحلهم واستراحوا.  لكن هناك أدلة أخرى يحتج بها بعض أهل العلم على جوازها قبل الزوال مثل حديث الساعات، وأنه بعد الساعة الخامسة يحضر الملائكة يستمعون الذكر، هذه وأحاديث أخرى في الباب قد يؤخذ منها شيء من هذا.  لكن الأحوط الذي عليه الجمهور ألا تُصلى إلا بعد الزوال، هذا الذي عليه جمهور أهل العلم.\nس: لو صليت قبل الزوال بقليل؟\nالشيخ: يصح، الصحيح يصح؛ لأنها السادسة.","link":"https://binbaz.org.sa/fatwas/24247/هل-تجوز-اقامة-صلاة-الجمعة-قبل-الزوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إقامة صلاة الجمعة قبل الزوال.mp3","categories":["صلاة الجمعة"]},{"id":4030,"question":"يستعملها يوم الجمعة (جلسة القرفصاء)؟","title":"حكم جلسة القرفصاء يوم الجمعة","answer":"الجواب: الصحيح لا حرج؛ لأن الحديث الذي فيه النهي ضعيف، الحديث الذي فيه النهي عن الاحتباء ضعيف، لكن بعض الصحابة فعله، ولكن إذا كانت تسبب نومًا أو شيء من الكسل يتركها، الذين كرهوها قالوا: إن الاحتباء قد يسبب النوم والكسل، ولاسيما في الخطبة، والمفروض أنه يستمع وينصت ويهتم.","link":"https://binbaz.org.sa/fatwas/24266/حكم-جلسة-القرفصاء-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم جلسة القرفصاء يوم الجمعة.mp3","categories":["صلاة الجمعة"]},{"id":4260,"question":"التسنُّن قبل الجمعة كم ركعة؟","title":"كم عدد ركعات التسنُّن قبل الجمعة؟","answer":"الجواب: ما في حد محدود يصلي ثنتين أو أربع أو عشر أو مئة، النبي قال: وصلى ما قُدر له، يعني ما كتب الله له.","link":"https://binbaz.org.sa/fatwas/24530/كم-عدد-ركعات-التسنن-قبل-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التسنن قبل الجمعة.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":4763,"question":"أحسن الله عملك لو جمع بين الجمعة والعصر؟","title":"ما حكم جمع العصر مع صلاة الجمعة؟","answer":"لا، الجمعة ما تجمع مع العصر، لا يصلى مع الجمعة تصلى في وقتها، العصر تجمع مع الظهر مع الجمعة لا.\nس: طيب إذا جمعت؟\nالشيخ: يعيدها، إذا جمعوا يعيدون العصر.","link":"https://binbaz.org.sa/fatwas/25122/ما-حكم-جمع-العصر-مع-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تُصلّى الجمعة مع العصر، وما حكم الجمع.mp3","categories":["أحكام الجمع","صلاة الجمعة"]},{"id":4785,"question":"بعض المؤسسات في أوروبا لا يسمحون للمسلم أن يترك العمل لأجل يصلي الجمعة فما حكمه؟","title":"حكم من يمنعه عمله عن أداء صلاة الجمعة","answer":"هذا مثل الحارس، إذا كان ما يُسمح له يكون عذرًا له، مثل الحارس الذي يحرس البيوت، أو يحرس السجون، أو يحرس الأموال، عذر له يصلي ظهرًا إذا لم يتيسر له حضور الجمعة، كالمريض يكون معذورًا، يُعذر في الجمعة جماعة منها من لا يستطيع الحضور لكونه حارسًا أو لكونه مريضًا أو لكونه خائفًا أو ما أشبه ذلك.","link":"https://binbaz.org.sa/fatwas/25152/حكم-من-يمنعه-عمله-عن-اداء-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يمنعه عمله عن أداء صلاة الجمعة.mp3","categories":["صلاة الجمعة"]},{"id":4809,"question":"استعمال السواك عند سماع الخطبة، هل يكون من اللغو؟","title":"ما حكم استعمال السواك أثناء خطبة الجمعة؟","answer":"لا يستاك، لا يعبث، لا بالسواك ولا بغيره.\nس: إذا فعل ذلك يكون لغوًا؟\nج: يُخشى عليه.","link":"https://binbaz.org.sa/fatwas/25205/ما-حكم-استعمال-السواك-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استعمال السواك عند سماع الخطبة.mp3","categories":["صلاة الجمعة"]},{"id":4811,"question":"التشميت أثناء خطبة الجمعة؟","title":"هل يجوز تشميت العاطس أثناء خطبة الجمعة؟","answer":"لا يشمّت، النبي ﷺ يقول: إذا قلت لصاحبك أنصت فقد لغوت فلا يشمِّت ولا يرد السلام.","link":"https://binbaz.org.sa/fatwas/25209/هل-يجوز-تشميت-العاطس-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التشميت أثناء خطبة الجمعة.mp3","categories":["صلاة الجمعة"]},{"id":4847,"question":"هل ساعة الإجابة يوم الجمعة تتنقل مثل ليلة القدر؟","title":"هل تتنقل ساعة الإجابة يوم الجمعة؟","answer":"الراجح أنها في العصر وعند جلوس الإمام على المنبر.\nس: هل تتنقل؟\nج: لا.","link":"https://binbaz.org.sa/fatwas/25295/هل-تتنقل-ساعة-الاجابة-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تتنقل ساعة الإجابة يوم الجمعة.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":4931,"question":"السواك أثناء الخطبة؟","title":"حكم استعمال السواك أثناء الخطبة","answer":"الجواب: لا ينبغي لأنه نوع من العبث.","link":"https://binbaz.org.sa/fatwas/27022/حكم-استعمال-السواك-اثناء-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استعمال السواك أثناء الخطبة.mp3","categories":["صلاة الجمعة"]},{"id":5235,"question":"مَن دخل المسجد والإمام يخطب هل يجلس ويستمع الخطبة أم يُصلي ركعتين؟","title":"حكم تحية المسجد لمَن دخل والإمام يخطب","answer":"الجواب: المشروع أن يُصلي ركعتين، ثم يجلس، يبدأ بالصلاة، يقول النبيُّ ﷺ: إذا جاء أحدُكم والإمام يخطب فليركع ركعتين، وليتجوَّز فيهما، هكذا أمر النبيُّ ﷺ، فيبدأ بالصلاة ثم يجلس.","link":"https://binbaz.org.sa/fatwas/30182/حكم-تحية-المسجد-لمن-دخل-والامام-يخطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 335.mp3","categories":["صلاة الجمعة"]},{"id":5326,"question":"يقول: ما حكم حضور الخطبة يوم الجمعة، وما هو الدليل؟","title":"ما حكم حضور الخطبة يوم الجمعة؟","answer":"الجواب: الواجب على المؤمن إذا سمع المؤذن أن يبادر بالتوجه إلى المسجد ليسمع الخطبة ويصلي؛ لأن المقصود من الخطبة: وعظ الجماعة، وعظ المسلمين وتذكيرهم وتعليمهم، فالواجب أن يبادروا لحضورها حتى يستفيدوا من توجيهات الخطيب وتذكيره، وحتى يتمكن من أداء الصلاة من أولها ولا يفوته شيء، ولهذا قال جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ [الجمعة:9] فالواجب السعي من حين النداء وإذا بكّر قبل ذلك فهو أفضل، كما في الحديث الصحيح يقول ﷺ عن المبكر إلى الجمعة كالمهدي بدنة، والذي بعده كالمهدي بقرة، والذي بعده كالمهدي كبشًا أقرن، والذي بعده كالمهدي دجاجة، وفي الساعة الخامسة كالمهدي بيضة.[1]","link":"https://binbaz.org.sa/fatwas/30993/ما-حكم-حضور-الخطبة-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 047.mp3","categories":["صلاة الجمعة"]},{"id":5330,"question":"عند دعاء الإمام في نهاية الخطبة كثير من الناس يؤمن على دعائه فهل يعد هذا من الكلام واللغو في الخطبة؟","title":"ما حكم التأمين على الدعاء في خطبة الجمعة؟","answer":"الجواب: لا حرج، بينه وبين نفسه، يؤمِّن -بغير تشويش- على دعاء الإمام، مثل دعائه في القنوت يؤمِّن عليه.[1]","link":"https://binbaz.org.sa/fatwas/31000/ما-حكم-التامين-على-الدعاء-في-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 051.mp3","categories":["صلاة الجمعة"]},{"id":5374,"question":"صلَّى جماعة جمعة في الدور الثاني في أحد المساجد، وفي أثناء الصلاة انقطع المُكبر، وصاروا لا يسمعون صوت الإمام، فتقدم أحدُهم وأتمَّ لهم الصلاة؟","title":"حكم من انقطع عنهم صوت الإمام في صلاة الجمعة","answer":"الجواب: ما في بأس، طيب، يُكمل بهم، والحمد لله. س: يُكمل لهم جمعة؟ ج: نعم، يُكمل لهم؛ إن صلّوا ركعةً صلّوا ركعةً، وإلا ما صلّوا ركعة؟ س: يقول: في أثناء الصلاة. ج: إن كانوا صلوا ركعةً يُتممون، مثل: الذي أدرك ركعةً من الجمعة. س: وإذا كان أقلَّ من ركعةٍ؟ ج: نعم؟ س: إذا كان في الركعة الأولى؟ ج: الظاهر إذا كان في الركعة الأولى يُصلون ظهرًا، ما يُصلون جمعةً، فاتتهم الجمعة، أما إذا كانوا أدركوا ركعةً يُتممون جمعةً. س: وإن سمعوا الخُطبتين يُصلونها ظهرًا؟ ج: نعم؟ س: أقول: يُتمون ظهرًا وإن سمعوا الخطبتين؟ ج: إيه، لكن ما صلّوا مع الإمام، فاتتهم صلاةُ الإمام، ما صلّوا مع الإمام.[1]","link":"https://binbaz.org.sa/fatwas/31108/حكم-من-انقطع-عنهم-صوت-الامام-في-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/dorar_saniya_najdiya004.mp3","categories":["صلاة الجمعة","صلاة الجماعة"]},{"id":5542,"question":"شروط الخُطبة؟","title":"ما شروط خُطبة الجمعة؟","answer":"الجواب: أن يكون فيها حمدُ الله، والثناء على الله، والشهادتان، ووعظ الناس وتذكيرهم، وبعضهم شرط فيها الصلاة على النبي ﷺ، وبعضهم شرط قراءة آيةٍ، فينبغي أن يفعل هذا، ينبغي أن يحمد الله ويُثني عليه، ويتشهد الشَّهادتين، ويُصلي على النبي ﷺ، ويعظ الناس ويُذكرهم. والمقصود: وعظ الناس، وتذكيرهم، وتعليمهم، وتوجيههم إلى الخير، وتحذيرهم من الشرِّ، وإنْ قرأ آيةً في أثناء الخطبة أو آيات كان هذا مما ينبغي؛ لأنه كان يقرأ آيات في الخطبة عليه الصلاة والسلام، لكن اختلفوا: هل هذا شرط أم لا؟ فقومٌ جعلوه شرطًا، وقومٌ قالوا: ليس بشرطٍ، ولكن مشروع أن يقرأ بعض الآيات، فإذا قرأ آيةً أو آيتين أو أكثر؛ لأنَّ هذا متأكد خروجًا من خلاف مَن قال بعدم صحَّتها من دونها. س: الحمد والثَّناء في الخطبتين؟ ج: في الخطبتين، نعم.[1]","link":"https://binbaz.org.sa/fatwas/31480/ما-شروط-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 006.mp3","categories":["صلاة الجمعة"]},{"id":5545,"question":"حديث: من لغا فلا جمعةَ له؟","title":"ما معنى حديث \"مَنْ لغا فلا جمعةَ له\"؟","answer":"الجواب: هذا جاء في \"صحيح مسلم\": مَن مسَّ الحصى فقد لغا، ومَن لغا فلا جمعةَ له، يعني: يفوته فضلها، وأما الحديث هذا فهو كمثل الحمار يحمل أسفارًا فهذا في صحَّته نظر، فمجالد ليس ممن يعتمد عليه؛ اختلط، روايته فيها لين، إلا أن تكون له شواهد، هذا التَّشبيه: \"مَن لغا مثله كمثل الحمار\" أمر عظيم. س: تكون باطلةً أم ناقصةً مَن مسَّ الحصى؟ ج: يفوته فضلها، يعني: ليست له جمعة، يعني: فضل الجمعة، ولا يُعيد، ليس عليه الإعادة. س: مَن لغا فلا جمعةَ له؟ ج: لا فضلَ له، ليس له جمعة، فضل الجمعة. س: الحديث صحّته؟ ج: رواه مسلم في الصحيح.[1]","link":"https://binbaz.org.sa/fatwas/31488/ما-معنى-حديث-من-لغا-فلا-جمعة-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 008.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":5597,"question":"ترون قبل الجمعة بكم يلزم الشخص بالذهاب إلى الصلاة وعدم فتح محله؟","title":"متى يُلزم المرء بالذهاب إلى صلاة الجمعة؟","answer":"الجواب: ما يلزمه إلا إذا نُودي للصلاة، هذا اللزوم، مثلما قال الله: إِذَا نُودِيَ لِلصَّلَاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ [الجمعة:9] الأذان الأخير. س: فقط، ما يمديه يا شيخ؟ ج: المقصود هذا الواجب، وما قبله سُنة، يُبكر هذا سنة. س: لكن هل يترك مَن يعمل في السوق؟ ج: يعمل حتى يُؤذن الأذان الأخير، ثم يُمنع، إن وجد يُمنع. س: لكن حضور الخطبة؟ ج: هذا نص القرآن: إِذَا نُودِيَ لِلصَّلَاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ، نص القرآن. س: يعني على هذا لو فاته شيء من الخطبة لا يأثم؟ ج: ما يضرّ، ما يأثم. س: ظاهر الأمر: إِذَا نُودِيَ لِلصَّلَاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا [الجمعة:9] ألا يلزم منه حضور خطبة الجمعة؟ ج: هو يسعى، لكن قد يعوقه الوضوء، إذا ما استغله إلا بعد الأذان قد يعوقه الوضوء فيفوته بعض الشيء. س: على هذا لا يُقال لرجل الهيئة أن يُلزم صاحب المحل بالإغلاق قبل الأذان؟ ج: نعم، نعم.[1]","link":"https://binbaz.org.sa/fatwas/31559/متى-يلزم-المرء-بالذهاب-الى-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 036.mp3","categories":["صلاة الجمعة"]},{"id":5599,"question":"في غير يوم الجمعة إذا تمَّ عقد البيع بعد إقامة الصلاة؟","title":"ما حكم البيع بعد إقامة الصلاة يوم الجمعة؟","answer":"الجواب: لا يجوز له أن يتأخَّر عن الصلاة، لا في البيع، يجب أن يُبادر إلى الصلاة ويُصلي مع الجماعة، ولا يجوز له التأخر. س: هل عقد البيع صحيح؟ ج: ما أعلم مانعًا؛ لأنه جاء النص بنداء الجمعة، لكن لا يجوز له التأخر، ولا يجوز له البيع والشراء، يُعطله عن صلاة الفريضة، يجب أن يُبادر في صلاة الفريضة: الظهر والعصر والمغرب والعشاء، ولو ما هو جمعة، حيث إن هذا واجب عليه.[1]","link":"https://binbaz.org.sa/fatwas/31564/ما-حكم-البيع-بعد-اقامة-الصلاة-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 039.mp3","categories":["صلاة الجمعة"]},{"id":5600,"question":"بعض الإخوة يقول: في الأسبوع الماضي خطب أحد الأئمة في صلاة الجمعة خطبة واحدة ثم صلَّى ركعتين ثم انصرف الناس واختلفوا بعد ذلك في صحة هذه الصلاة، هل يُعيد ويُصلى مع هذا الإمام؟","title":"هل تصح صلاة الجمعة بخطبة واحدة؟","answer":"الجواب: نعم يُعيدها ظهرًا، من شرط صلاة الجمعة خطبتان كما فعل النبي ﷺ، وقال: صلوا كما رأيتُموني أُصلي اللهم صلِّ عليه وسلم.[1]","link":"https://binbaz.org.sa/fatwas/31567/هل-تصح-صلاة-الجمعة-بخطبة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 040.mp3","categories":["صلاة الجمعة"]},{"id":5601,"question":"حضور خطبة الجمعة واجب؟","title":"هل يأثم من يتأخر عن خطبة الجمعة؟","answer":"الجواب: نعم إذا تيسر. س: ما يأثم بترك بعضها مثل الصلاة في الجماعة؟ ج: الذي يظهر لي أنه يجب عليه أن يحضر؛ لأن الله شرع الخطبة ليستفيد الناس وليتعلموا ويستفيدوا يوم الجمعة.[1]","link":"https://binbaz.org.sa/fatwas/31568/هل-ياثم-من-يتاخر-عن-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 041.mp3","categories":["صلاة الجمعة"]},{"id":5714,"question":"ما صحة حديث: من غسل واغتسل وبكر وابتكر ومشى ولم يركب، ودنا من الإمام ولم يلغ، كان له بكل خطوة يخطوها أجر سنة، عمل صيامها وقيامها ذكر صاحب الروض بأن رجاله ثقات؟","title":"ما صحة حديث: «من غسل واغتسل وبكر وابتكر»","answer":"الجواب: هذا حديث مشهور، والذي يظهر لي، ويغلب على ظني أنه لا بأس برجاله، وهو يدل على التبكير إلى الجمعة، والحرص على المبادرة إليها، والقرب من الإمام، والإنصات، واستماع الخطبة.  وجاء في هذا المعنى أحاديث كثيرة تدل على شرعية التبكير، والمسارعة إلى الجمعة، والاغتسال فيها والطيب، والدنو من الإمام، والإنصات، كل هذا من القرب العظيمة.","link":"https://binbaz.org.sa/fatwas/1028/ما-صحة-حديث-من-غسل-واغتسل-وبكر-وابتكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_50.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":5828,"question":"هل صحيح أن الأرض لا تأكل من أجساد الأنبياء؟ وهل معنى ذلك أن جسد الرسول ﷺ ما يزال كما هو يوم دفن؟","title":"ما صحة القول بأن الأرض لا تأكل أجساد الأنبياء","answer":"الجواب: جاء عن النبي ﷺ فيما رواه أهل السنن أنه قال -عليه الصلاة والسلام-: خير أيامكم يوم الجمعة وفي لفظ: إن من خير أيامكم يوم الجمعة؛ فأكثروا عليّ من الصلاة فيها، فإن صلاتكم معروضة علي اللهم -صل عليه وسلم- قالوا: يا رسول الله، كيف تعرض صلاتنا عليك، وقد أرمت؟ يعني بليت، قال: إن الله حرم على الأرض أن تأكل أجساد الأنبياء أخرجه أهل السنن.  لكن ليس إسناده بذاك السالم، أعله بعض أهل العلم، والمشهور عند أهل العلم صحته، وأن إسناده حسن، لا بأس به، وهو يدل على أن أجساد الأنبياء لا تأكلها الأرض، بل تبقى طرية سليمة، كما أخبر به النبي -عليه الصلاة والسلام- لكن الحديث ليس من الأحاديث المقطوع بصحتها، بل فيها كلام لبعض أهل العلم، ولكن الراجح: أنه جيد، وأنه لا بأس بإسناده. وهذا ليس خاصًا بالأنبياء، بل قد يقع ذلك لبعض الصالحين؛ فقد شاهد الناس، وعلم الناس قديمًا، وحديثًا أجسادًا مدفونة مئات السنين لا تأكلها الأرض من أجساد الصالحين، والأخيار، ومن الشهداء، وغير الشهداء، فالله -جل وعلا- على كل شيء قدير  فله الحكمة البالغة، جل وعلا.  ولكن جاء النص في أجساد الأنبياء خاصة: إن الله حرم على الأرض أن تأكل أجساد الأنبياء وروحه ﷺ في الجنة، في أعلى عليين في الرفيق الأعلى وجسده في الأرض. لكن جاء في الحديث الذي رواه أبو داود بإسناد جيد: أن النبي -عليه الصلاة والسلام- قال: ما من أحد يسلم عليّ إلا رد الله علي روحي حتى أرد عليه وهذا الرد قد يكون مباشرة، وقد يكون بواسطة الملائكة، فإنه جاء في الحديث الآخر: إن لله ملائكة سياحين يبلغوني عن أمتي السلام فهو يبلغ السلام بواسطة الملائكة التي تنقل سلام الأمة إليه -عليه الصلاة والسلام- وروحه في أعلى عليين في الجنة في خير مكان -عليه الصلاة والسلام- وجعل الله له منزلة في الجنة في أعلى المنازل، وهي الوسيلة أعلى منزلة في الجنة له، عليه الصلاة والسلام.  وهكذا أرواح المؤمنين، أرواح المؤمنين بعد الموت في الجنة، جاء في الحديث أنها طائر يعلق في شجر الجنة، شبه طائر يجعلها الله كطائر تطير في الجنة حيث شاءت، وتأكل من ثمار الجنة، وتأوي إلى جسدها إذا شاء الله .  أما أرواح الشهداء فالله جعلها في أجواف طير خضر عوضًا من أجسادهم التي قتلوا في سبيل الله، أعطاهم الله هذه الطير الخضر تكون أرواحهم في أجوافها، تسرح في الجنة، يسرحون في الجنة حيث شاؤوا، ثم يعودون إلى قناديل معلقة تحت العرش، تقع فيها، وتستقر فيها، وتسرح في الجنة حيث شاءت. وبهذا نعلم أن أرواح الأنبياء، والمؤمنين كلها في الجنة في هذه الدنيا في البرزخ تذهب إلى الجنة، ويرفعها الله إلى الجنة، وتأكل من نعيمها، وخيرها، ولكن أرواح الأنبياء أفضل، وروح نبينا ﷺ أفضل الأرواح، وأعلاها، وأكثرها فضلًا. وهذه الأرواح تعود إلى أجسادها إذا شاء الله، تعود لأجسادها عند السؤال، عند سؤال الملك بعد الدفن تعود الروح إلى الجسد، وتجيب عما يسأل عنه، إذا قال: من ربك؟ ربي الله، من نبيك؟ نبي محمد، ما دينك؟ ديني الإسلام، فعند ذلك يوسع الله له في قبره، ويفتح له بابًا إلى الجنة، يأتيها من روحها، وطيبها، ويقول: يا رب أقم الساعة حتى أرجع إلى أهلي، ومالي؛ لأنه يرى أنه سوف يزداد خيرًا.  أما ذاك المجرم الكافر إذا عذب -نعوذ بالله- يقول: رب لا تقم الساعة، رب لا تقم الساعة، لأنه يعلم أنه ينتقل إلى ما هو أشر من ذلك، نسأل الله العافية، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/1164/ما-صحة-القول-بان-الارض-لا-تاكل-اجساد-الانبياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_163.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":5873,"question":"ما صحة الحديث الذي يقول: يأتي يوم القيامة كل ألف من الناس يدخل الجنة واحد، ويدخل النار تسعمائة وتسع وتسعون؟","title":"ما صحة حديث «يأتي يوم القيامة كل ألف من الناس..»؟","answer":"الجواب: هذا حديث صحيح الرسول ﷺ قال: يأمر الله يوم القيامة، يدعو الله آدم يوم القيامة، فيقول الله لآدم يوم القيامة: ابعث بعث النار، فيقول: يا ربي ما بعث النار؟ قال: من كل ألف تسعمائة وتسعة وتسعون في النار، وواحد في الجنة لكن قال في حديث: إنكما في أمتين ما كانتا في أحد إلا كثرتاه يأجوج ومأجوج، فهؤلاء الكفرة كلهم، والسليم واحد. فهذا يدل على كثرة الكفرة في قديم الزمان، وحديثه، وإلا الكفار أكثر بكثير، وأن أهل الجنة قليلون، ومع ذلك يأتي على أبواب الجنة يوم، وعليها زحام، وعليها ضغط من كثرة الداخلين إلى الجنة، فالنار أمرها أعظم، وأكبر؛ لأن أكثر الخلق يتبع هواه، ويعصي مولاه، ولا يطيع الرسل، ولا ينقاد لما جاؤوا به، هذا حال الأكثرين كما قال سبحانه: وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ [يوسف:103].  ويقول سبحانه: وَقَلِيلٌ مِنْ عِبَادِيَ الشَّكُورُ [سبأ:13] ويقول : إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَقَلِيلٌ مَا هُمْ [ص:24] ويقول في قصة الأنبياء بعد كل قصة: إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُمْ مُؤْمِنِينَ [الشعراء:8].","link":"https://binbaz.org.sa/fatwas/1230/ما-صحة-حديث-ياتي-يوم-القيامة-كل-الف-من-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_227.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":5974,"question":"ما درجة حديث: هجر المسلم سنة كسفك دمه؟","title":"الحكم على حديث: هجر المسلم سنة كسفك دمه","answer":"الجواب: ما أعرف له أصلًا، ولكن التهاجر محرم، النبي قال: لا تهاجروا، لا تقاطعوا، لا تدابروا وقال: لا يحل لمسلم أن يهجر أخاه فوق ثلاث هذا المعروف، ولكن هذا الحديث لا أعرف له أصلًا.","link":"https://binbaz.org.sa/fatwas/1367/الحكم-على-حديث-هجر-المسلم-سنة-كسفك-دمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_325.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":5979,"question":"ما درجة حديث: هجر المسلم سنة كسفك دمه؟","title":"الحكم على حديث: هجر المسلم سنة كسفك دمه","answer":"الجواب: ما أعرف له أصلًا، ولكن التهاجر محرم، النبي قال: لا تهاجروا، لا تقاطعوا، لا تدابروا وقال: لا يحل لمسلم أن يهجر أخاه فوق ثلاث هذا المعروف، ولكن هذا الحديث لا أعرف له أصلًا.","link":"https://binbaz.org.sa/fatwas/1367/الحكم-على-حديث-هجر-المسلم-سنة-كسفك-دمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_325.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6017,"question":"جماعة عسكرية انتقلت من الرياض إلى مكان ما لمدة شهرين، هل يجوز لهم أن يصلوا الجمعة في الصحراء؟ وهل ينطبق عليهم حكم المسافر؛ علمًا أنهم هناك يستلم منهم كل يوم سرية لتكون على هيئة الاستعداد، والباقون يلعبون الكرة، ويأكلون من نعم الله؟","title":"حكم صلاة الجمعة لمن هو في مهمة عسكرية","answer":"الجواب: المسافر ونحوه ليس عليه جمعة، إنما يبقون يصلون صلاة المسافرين ظهرًا، وعصرًا، وليس عليهم جمعة، والذي قام لحاجته في البرية ينتظر أمرًا، أو يسعف جيشًا، أو ما أشبه ذلك، هذا حكمه حكم المسافرين، وليس حكمه حكم المقيمين، حتى يقيم صلاة الجمعة، فإذا أقام في قطعة من البر في الصحراء ينتظر الأوامر، فهذا حكمه حكم المسافرين.  أما إذا أقام شهرين عامدين عازمًا على شهرين، فالذي عليه جمهور أهل العلم أنه يتم أربعًا، ولكن لا يكون من أهل الجمعة، يتم أربعًا فقط، ظهرًا، وعصرًا، وعشاء إذا كان جازمًا على أكثر من أربعة أيام. أما إنسان ما يدري تحت الأوامر، هل يقيم يومًا، أو خمسة أيام، وقد يقيم أكثر، فلا يدري متى يؤمر بالرحيل؟! فهذا له القصر أبدًا، حتى يعمد بالإقامة الطويلة التي يعرف أنها إقامة معزوم عليها أكثر من أربعة أيام؛ لأن الرسول أقام أربعة أيام في مكة قبل الحج، وكان يصلي قصرًا؛ فدل ذلك على أن إقامة أربعة أيام، وما حولها، وما دونها حكمه حكم السفر، فإذا نوى أكثر من ذلك؛ فالجمهور على أنه يتم أربعًا، فإن الأصل تمام الأربع، ترك في السفر، وما يلحق في السفر، وبقي ما سوى ذلك على الأصل. السؤال: وإذا صلوا جمعة خلال هذه الشهرين، فهل يعيدونها ظهرًا؟ الجواب: الله أعلم، لا أدري، محل نظر.","link":"https://binbaz.org.sa/fatwas/1385/حكم-صلاة-الجمعة-لمن-هو-في-مهمة-عسكرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_341.mp3","categories":["صلاة الجمعة"]},{"id":6048,"question":"هل قراءة آية إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ [الأحزاب:56] في كل خطبة بدعة؟ وهل آية إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ [النحل:90] حيث إن الخطباء يداومون على قراءة هذه الآيات؟","title":"حكم مداومة الخطيب على: {إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ}","answer":"الجواب: ما أعلم شيئًا في هذا؛ لأن هذا حث على الصلاة على النبي ﷺ ودعوتهم إلى الصلاة على النبي -عليه الصلاة والسلام- لأن الآية جامعة: إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ [النحل:90]، آية جامعة فيها خير عظيم، وتنبيه للمسلمين، فهذا من الوعظ.","link":"https://binbaz.org.sa/fatwas/1459/حكم-مداومة-الخطيب-على-ان-الله-وملاىكته-يصلون-على-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_388.mp3","categories":["الدعوة والدعاة","صلاة الجمعة"]},{"id":6089,"question":"إذا انتدب أحد الموظفين إلى مسافة قصر، أو مسافة تقصر فيها الصلاة لمدة أسبوع، أو أسبوعين، أي أنه يعلم بالتقريب المدة التي سيبقاها في البلد المنتدب إليها، فهل يجوز له القصر؟ وهل هناك فترة إذا مكثها، أو عرف أنه سيمكثها؟","title":"هل هناك فترة إذا مكثها المسافر أتم صلاته؟","answer":"الجواب: إذا عرف أنه سيمكث أكثر من أربعة أيام؛ أتم عند الجمهور، عند أكثر العلماء، إذا عرف أنه سيقيم أكثر من أربعة أيام؛ أتم عند أكثر أهل العلم، وقال بعض أهل العلم: إذا كانت المدة خمسة عشر يومًا، وقال بعضهم تسعة عشر يومًا، وقال بعضهم عشرين يومًا، إذا أقام هذه المدة؛ قصر، وإذا علم أنه يقيم أكثر منها؛ أتم أربعًا.  وبكل حال إذا كان يعرف أنه يقيم أكثر من أربعة أيام؛ فالأحوط له الإتمام؛ حتى يسلم من التبعة، أما إذا كان ما يدري، يقيم أربعًا، أو ثلاثة، أو خمسة، أو ستة، أو عشرة، ما عنده ضبط؛ فهذا يصلي قصرًا، يصلي ثنتين ثنتين؛ لأنه مسافر، ولا يدري متى تنتهي مدته، مثل الذي جاء في قتال الأعداء، أو جاء في خصومة، ما يدري متى تنتهي، أو حاجة يطلبها من إنسان، ما يدري متى ينتهي، هذا ليس له إقامة معلومة، هذا له حكم السفر. لكن إذا كان وحده؛ ما يصلي وحده، يصلي مع الناس، ويتم أربعًا، يصلي مع الجماعة، لا يصلي واحدة، أما إذا كان له إخوة، وأصحاب يصلون معه؛ فهم مخيرون، إن شاؤوا يصلون وحدهم ثنتين ثنتين قصرًا، وإن شاؤوا صلوا مع الناس، وجمعوها، وأتموا أربعًا.","link":"https://binbaz.org.sa/fatwas/1504/هل-هناك-فترة-اذا-مكثها-المسافر-اتم-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_434.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":6090,"question":"إذا كان الرجل مسافرًا، فمر على أهل قرية، وأراد أن يصلي بهم الجمعة، حيث لا يوجد في هذه القرية خطيب، أو أن المسافر أعلم من المقيم، فهل يجوز للمسافر الخطبة، أو الصلاة؟","title":"حكم إمامة المسافر للمقيمين في الجمعة","answer":"الجواب: لا حرج في ذلك، اختلف العلماء في ذلك، بعض أهل العلم قال: لا؛ لأن المسافر لا جمعة عليه، ولكن الصواب: أنه لا بأس عليه، ولا حرج إذا صلى بهم؛ لأن جنسه مخاطب بالجمعة لما حضر بينهم، والصلاة بينهم.  وبعض أهل العلم يرى أنه يجب عليه أن يصلي معهم لما حضر، وتجب عليه كغيره، وبكل حال فسقوطها عنه تخفيفًا، وتيسيرًا بسبب السفر لا يمنع من كونه يؤم بها، ويخطب الناس بها، ولا حرج في ذلك في أصح قولي العلماء.","link":"https://binbaz.org.sa/fatwas/1498/حكم-امامة-المسافر-للمقيمين-في-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_428.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":6118,"question":"إذا صادف يوم العيد يوم الجمعة، وصليت صلاة العيد، فهل الأفضل أن أصلي صلاة الجمعة، أم أقضيها ظهرًا؟","title":"حكم ترك صلاة الجمعة لمن صلى صلاة العيد","answer":"الجواب: الأفضل أن يصلي صلاة الجمعة؛ لأن الرسول كان يصليها -عليه الصلاة والسلام- كان يصلي الجمعة، والعيد جميعًا، ولكن رخص للناس من حضر صلاة العيد، من شاء صلى الجمعة، ومن شاء صلى ظهرًا، النبي ﷺ كان يجمع، فإذا صلى الجمعة مع الناس؛ كان أفضل حتى يحصل له فضل الجمعة، وسماع الخطبة ... وإن صلى الظهر، ولم يصل الجمعة يوم العيد؛ لأنه قد صلى العيد؛ جاز ذلك على الصحيح، كما جاءت به السنة عن النبي ﷺ أنه رخص لمن حضر العيد بترك الجمعة. ولكن إذا حضر الجمعة، وصلاها؛ كان أفضل لما فيه من الخير العظيم، والنبي ﷺ كان يصلي الجمعة، ويصلي العيد جميعًا، كما قال النعمان فيما رواه مسلم في الصحيح قال: \"كان يقرأ في الجمعة بسبح، والغاشية، وهكذا في العيد، وربما اجتمعا في يوم فقرأ بهما جميعًا في الصلاتين، صلاة العيد، وصلاة الجمعة\" رواه مسلم في الصحيح.","link":"https://binbaz.org.sa/fatwas/1530/حكم-ترك-صلاة-الجمعة-لمن-صلى-صلاة-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_460.mp3","categories":["صلاة العيدين","صلاة الجمعة","فضائل الأزمنة والأمكنة"]},{"id":6132,"question":"ما صحة حديث من ترك ثلاث جمع متتالية؛ طبع الله على قلبه؟","title":"الحكم على حديث: «من ترك ثلاث جمع متتالية»","answer":"الجواب: هذا صحيح في الحديث الصحيح: من ترك ثلاث جمع من غير عذر؛ طبع الله على قلبه وهذا وعيد عظيم، نسأل الله العافية! وأبلغ من هذا ما تقدم في الحديث الذي رواه مسلم في الصحيح لينتهن أقوام عن ودعهم الجمعات، أو ليختمن الله على قلوبهم، ثم ليكونن من الغافلين.","link":"https://binbaz.org.sa/fatwas/1573/الحكم-على-حديث-من-ترك-ثلاث-جمع-متتالية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_478.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6133,"question":"بعض الأولاد يبكرون يوم الجمعة، ويأتي أناس أكبر منهم، ويقيمونهم، ويجلسون مكانهم، ويحتجون بقوله ليلني منكم أولوا الأحلام، والنهى هل هذا جائز؟","title":"حكم إبعاد الأولاد من الصفوف المتقدمة إذا سبقوا إليها","answer":"الجواب: هذا يقوله بعض أهل العلم، ويرى أن الأولى بهم أن يصفوا وراء الرجال، ولكن هذا فيه نظر، والأولى أنهم إذا تقدموا ألا يقاموا إذا سبقوا إلى الصف الأول، أو إلى الصف الثاني، فلا يقيمهم من جاء بعدهم، لأنهم سبقوا إلى حق.. فلا يقامون أيضًا، في إقامتهم تنفير لهم من الصلاة، ومن المسابقة؛ فلا يليق ذلك. لكن لو اجتمع الناس، جاؤوا مجتمعين في سفر، أو لأي سبب، اجتمعوا صف الرجال أولًا، ثم الصبيان ثانيًا، ثم النساء بعدهم، إذا صادف ذلك، وهم مجتمعون، أما أن يخرجوا من الصفوف، ويزالون، ويصف مكانهم الكبار؛ فلا ينبغي هذا؛ لأنه مخالف للقواعد الإسلامية المعروفة، من سبق إلى مباح؛ فهو أحق به؛ ولأن هذا فيه تنفير لهم من المسابقة.","link":"https://binbaz.org.sa/fatwas/1577/حكم-ابعاد-الاولاد-من-الصفوف-المتقدمة-اذا-سبقوا-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_479.mp3","categories":["صلاة الجمعة","تربية الأولاد"]},{"id":6135,"question":"أحد الإخوة يقول: إن بعض خطباء المساجد ليسوا -مضمون سؤاله يعني-: هم ليسوا على المستوى المطلوب بما يقوموا به من هذا العمل الخطير، ويعتمدون على ديوان ابن نباتة، بينما هناك كثير من رجال العلم يتمنون أن تتاح لهم الفرصة لأداء الخطبة، ولو بدون مكافأة، فما رأي سماحتكم في ذلك؟","title":"الشروط الواجب توافرها في الخطيب","answer":"الجواب: على كل حال يوجد من أئمة المساجد، وخطباء الجمع من ليس تتوفر فيه القدرة على الخطب المفيدة الكافية، ولكن هذا كما قال ربنا : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول الناس على ما جاء في الأحاديث... فليس كل مكان... فيه العلماء الذين لهم الميزة، ولهم القدرة على الخطبة الكافية، ولهذا يحتاج الناس إلى طالب في الثانوي، بعض الأحيان طالب في المتوسط، وبعض الأحيان الذي إنما حضر جلسات العلماء، فيستفاد منه، ويولى الخطبة للحاجة، يعني لشدة الحاجة، ولعدم من يقوم مقامه.  فهذه المسائل الإمامة، والخطابة على كل حال يعتنى فيها بالأفضل، فالأفضل، ويلتمس فيها الأفضل، فالأفضل، حسب الطاقة، ولا يجب أن يكون من أكبر العلماء على حسب ما تيسر؛ لأن العلماء قد يتأخر كثير منهم عن الخطابة لأسباب كثيرة، وقد يكون بعضهم بعيد عن محل الخطابة، وإن كانت السيارات متيسرة، بحمد الله. ليس الناس كلهم سواء في الرغبة في الخطابة، والحرص عليها، وإلا فوزارة الحج، والأوقاف تلتمس، وتطلب من عنده كفاية يتقدم حتى .. فهم يطلبون من يقبل على ذلك، ويستجيبون من مصر، ومن غير مصر، من يتولى ذلك عند الحاجة. فالحاصل أن كثيرًا من إخواننا ليس عندهم النشاط بالقيام في خطب الجمعة، وبإمامة المساجد، وكثير منهم لا يود ذلك، ويرى أنها تحبسه ... عن الأسفار، وعن كذا، وعن كذا، فلهذا لا تجده يوافق على الإمامة، والخطابة لهذه الأسباب التي أشير إليها، والذي يريد ذلك، ويوافق على ذلك مشكور، ومأجور، يكتب إلى الأوقاف أنه مستعد لهذا، أو يكتب لي، أو إلى من شاء من المشايخ، ونتوسط له، وندعو له، ونشكره أيضًا، ويعطى معاشًا أيضًا.","link":"https://binbaz.org.sa/fatwas/1598/الشروط-الواجب-توافرها-في-الخطيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_492.mp3","categories":["صلاة الجمعة","الدعوة والدعاة"]},{"id":6136,"question":"صلاة الجمعة من زوال الشمس؟","title":"هل تجوز صلاة الجمعة قبل زوال الشمس؟","answer":"الجواب: تجوز قبل زوال الشمس، ولكن الأفضل بعد الزوال؛ خروجًا من خلاف العلماء، أكثر العلماء يقولون: لا بدّ أن تكون صلاة الجمعة بعد الزوال، هذا قول الأكثرين.  وذهب قوم من أهل العلم إلى جوازها قبل الزوال في الساعة السادسة، وفيها أحاديث دالة على ذلك صحيحة، فإذا صلوها قبل الزوال بقليل؛ صحيحة، ولكن ينبغي أن تؤخر بعد الزوال؛ خروجاً من خلاف العلماء، وتيسيرًا على الناس؛ حتى يحضروا جميعًا، وحتى تكون الصلاة في وقت واحد، هذا يكون أولى، وإلا فهي مجزئة قبل الزوال.","link":"https://binbaz.org.sa/fatwas/1592/هل-تجوز-صلاة-الجمعة-قبل-زوال-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_486.mp3","categories":["صلاة الجمعة"]},{"id":6143,"question":"هل يكتفى بالغسل الواجب قبل صلاة الفجر للجمعة، أم لا؟","title":"غسل يوم الجمعة ووقته","answer":"الجواب: السنة يوم الجمعة غسل يوم الجمعة، والأفضل عند الذهاب عند التوجه إلى المسجد، هذا هو الأفضل، وإذا اغتسل في أول النهار؛ أجزأ، يوم الجمعة سنة مؤكدة، وقال بعض أهل العلم بالوجوب، فينبغي المحافظة على هذا الغسل يوم الجمعة في يوم الجمعة، والأفضل أن يكون عند توجهه، وعند قصده الذهاب إلى الجمعة؛ لأن هذا أبلغ في النظافة، وأبلغ في قطع الروائح الكريهة، مع العناية بالطيب، واللباس الحسن.  وكذلك ينبغي له إذا خرج إليها أن يعتني بالخشوع، وأن يقارب بين خطاه؛ لأن الخطا تحط به سيئاته، وترفع بها درجاته، فينبغي أن يكون له خشوع، وعناية، وإذا وصل إلى المسجد؛ قدم رجله اليمنى، وصلى على رسول الله -عليه الصلاة والسلام- ويقول: أعوذ بالله العظيم، وبوجهه الكريم، وسلطانه القديم، من الشيطان الرجيم، اللهم افتح لي أبواب رحمتك، ثم يصلي ما قدر الله له، ولا يفرق بين اثنين، وبعد ذلك يجلس ينتظر إما في قراءة، وإما في ذكر، واستغفار، أو سكوت حتى يأتي الإمام، ثم ينصت إلى الخطبة إذا تكلم الإمام، ثم يصلي معه، فإذا فعل ذلك؛ فقد أتى خيرًا عظيمًا، وجاء في الحديث الصحيح، أن الله -جل وعلا- يغفر له ما بينه، وبين الجمعة الأخرى، وزيادة ثلاثة أيام؛ لأن الحسنة بعشر أمثالها.  السؤال:....؟ الجواب: الوضوء يجزئ لكن الغسل أفضل.","link":"https://binbaz.org.sa/fatwas/1582/غسل-يوم-الجمعة-ووقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_482.mp3","categories":["صلاة الجمعة"]},{"id":6154,"question":"أطال الله بعمرك إذا واحد والإمام يخطب، وسلم عليه؟","title":"حكم رد السلام أثناء الخطبة","answer":"الجواب: يشير إليه، ما في سلام وقت الخطبة، ما في سلام ، ولا كلام.\n\nالسؤال: وإذا أعمى؟ الجواب: إذا أخذت بيده ما يضر، لكن لا تكلمه؛ لأن الرسول ﷺ أمر بالإنصات، وقال: إذا قلت: أنصت، والإمام يخطب؛ فقد لغوت فهو أمر بمعروف، ومع هذا نهي عن هذا. كذلك قال في الحديث الصحيح: من مس الحصا؛ فقد لغا، ومن لغا؛ فلا جمعة له فينبغي في مثل هذا أن ينصت، وإذا سلم عليه أحد؛ يشير له، وإذا وضع يده في يده لما مدها؛ فلا بأس، لكن من غير كلام، ويعلمه بعد ذلك بعد انتهاء الخطبة، يعلمه أن هذا لا ينبغي، فإذا دخل والإمام يخطب؛ لا يسلم، ولا يسلم على الذي جنبه، وإذا عطس؛ يحمد الله في نفسه، ولا يرفع صوته.","link":"https://binbaz.org.sa/fatwas/1586/حكم-رد-السلام-اثناء-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_484.mp3","categories":["صلاة الجمعة"]},{"id":6160,"question":"هل يكفي غسل الجنابة عن غسل الجمعة؟","title":"حكم الاكتفاء بغسل الجنابة عن غسل الجمعة","answer":"الجواب: نعم إذا كان في النهار يكفي، لكن إذا نواهما جميعًا فهو أفضل، ينويهما جميعًا، يغتسل عن الجنابة ناويًا معه غسل الجمعة.","link":"https://binbaz.org.sa/fatwas/1590/حكم-الاكتفاء-بغسل-الجنابة-عن-غسل-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_485.mp3","categories":["صلاة الجمعة","الغسل"]},{"id":6195,"question":"خرجت مع كفيلي إلى البر، ونقيم في مزرعة، وقد بقينا حتى الآن مدة شهر، وما زلنا، فما حكم القصر، والجمع في الصلاة؟","title":"حكم الجمع والقصر لمن سافر أكثر من أربعة أيام","answer":"الجواب: إذا خرج الإنسان إلى مزرعة، أو إلى النزهة، فهو على تفصيل، إن أراد الإقامة أكثر من أربعة أيام في محله، وعزم على هذا، فالذي عليه الجمهور أنه يتم الصلاة، وهو الأحوط له أن يتم أربعًا، أما إذا كان ما عنده نية، ما يدري كم يقيم؟ يقيم يومين، أو ثلاثًا، أو أربعًا، ما عنده جزم، فهذا الأفضل له أن يصلي قصرًا ثنتين ثنتين، الظهر، والعصر، والعشاء ثنتين، ولا بأس أن يجمع إذا كان ما عنده أي جزم، هل يقيم يومين، أو ثلاثًا، أو أربعًا، أو أكثر، ما يدري، أو ينتظر ناسًا يجونه، أو يبحث عن ضالة، يعني قد سافر لها مسافة قصر، أو يطلب خصيمه يدوره، ما عنده الجزم على أيام معلومة، فهذا يقصر. أما إذا عزم على الإقامة أكثر من أربعة أيام؛ فإنه يتم أربعًا عند جمهور أهل العلم؛ لأن الرسول ﷺ عزم على إقامة أربعة أيام في مكة، وهو يقصر؛ فدل على أن الأيام الأربع لا تمنع من القصر، والأصل بعد ذلك الإتمام. \n\nالسؤال: ويجمع إذا أبيح له القصر؟\nالجواب: إذا أبيح له القصر له الجمع، وترك الجمع أفضل، المقيمين ترك الجمع لهم أفضل إذا كانوا مقيمين ،كل الصلاة في وقتها أفضل.\n\nالسؤال: إذا مرت عليه أربعة أيام أو خمسة أيام؟\nالجواب:  إذا كان ما عزم على شيء معلوم فيقصر ولو مر عليه سنة، إذا كان ما عين ما يدري كم يقيم ينتظر مثلاً ضالة  روح يدورها ، أو عبد آبق أو خصيم رجل يدوره ، أو ما أشبه ذلك.","link":"https://binbaz.org.sa/fatwas/1678/حكم-الجمع-والقصر-لمن-سافر-اكثر-من-اربعة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_552.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":6337,"question":"ما صحة حديث: \"العلماء ورثة الأنبياء إذا لم يتبعوا السلطان\" أو إذا لم يتبعوا الدنيا، فإن اتبعوا الدنيا..؟","title":"الحكم على حديث العلماء ورثة الأنبياء إذا لم يتبعوا السلطان","answer":"الجواب: أما الحديث أن العلماء ورثة الأنبياء فهذا معروف، وله طرق، وهو جيد، أما زيادة: إذا لم يتبعوا السلطان، أو نحو هذا فهذه لا أصل لها، هذه زيادة باطلة، ما لها أصل في الحديث. لكن معروف أن زيارة السلطان، والاتصال بالسلطان على قسمين: الزيارة التي يرجى منها الخير، والتوجيه، والإرشاد، والنصيحة، هذه مطلوبة، والزيارة التي للميل، والهوى، والموافقة على الباطل، وغير ذلك مما يضر المسلمين، هذه لا تجوز. فالزيارة قسمان للسلاطين، والأمراء، والملوك، من زارهم للتوجيه، والإرشاد والنصيحة، وإرشادهم إلى الخير، وتوجيههم إليهم، وتحذيرهم من خلافه، فهو مأجور، وهذا واجب عليه، وقد زار أهل العلم السلاطين من عهد الصديق، إلى عهد بني أمية، إلى عهد بني العباس، إلى غيرهم، فما زال أهل العلم يزورنهم، ويتصلون بهم؛ للتوجيه، والإرشاد، والنصيحة، والشفاعة للمظلومين، ورفع الظلم إلى غير ذلك. أما زيارة الأمراء، والسلطان لأجل المال، والشهوات، والطعام، والأكل، فهذا مذموم.","link":"https://binbaz.org.sa/fatwas/1912/الحكم-على-حديث-العلماء-ورثة-الانبياء-اذا-لم-يتبعوا-السلطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_696.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6345,"question":"ما صحة حديث: شرار العلماء الذين يأتون إلى الأمراء؟","title":"الحكم على حديث شرار العلماء الذين يأتون الأمراء","answer":"الجواب: ما أعرف له صحة، ولو صح فالمقصود زيارتهم الخبيثة، لو صح، فالمراد بالزيارة التي للشهوة، والمال، والموافقة على الباطل. وإذا أهمل العلماء الأمراء؛ فسدوا، إذا أهمل العلماء الأمراء، وانزووا عنهم؛ فسد الأمر، وضاعت الحقوق، فالمصلحة، والخير في أن يزورهم العلماء، ويرشدوهم، ويطلبوا منهم التوجيه، والإرشاد، والنصيحة عن الظلم، ونصر المظلومين، وإزالة الظلم عنهم، كما زارهم العلماء سابقًا من عهد الصحابة إلى يومنا هذا. أما كون العلماء يتركونهم، ويهجرونهم، ولا يزورونهم؛ فهذا خطأ، هذا غلط، لا يقوله إلا الجهلة الذين لا يعرفون المصالح العامة.","link":"https://binbaz.org.sa/fatwas/1913/الحكم-على-حديث-شرار-العلماء-الذين-ياتون-الامراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_697.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6366,"question":"ما صحة حديث: \"العلماء ورثة الأنبياء إذا لم يتبعوا السلطان\" أو إذا لم يتبعوا الدنيا، فإن اتبعوا الدنيا..؟","title":"الحكم على حديث العلماء ورثة الأنبياء إذا لم يتبعوا السلطان","answer":"الجواب: أما الحديث أن العلماء ورثة الأنبياء فهذا معروف، وله طرق، وهو جيد، أما زيادة: إذا لم يتبعوا السلطان، أو نحو هذا فهذه لا أصل لها، هذه زيادة باطلة، ما لها أصل في الحديث. لكن معروف أن زيارة السلطان، والاتصال بالسلطان على قسمين: الزيارة التي يرجى منها الخير، والتوجيه، والإرشاد، والنصيحة، هذه مطلوبة، والزيارة التي للميل، والهوى، والموافقة على الباطل، وغير ذلك مما يضر المسلمين، هذه لا تجوز. فالزيارة قسمان للسلاطين، والأمراء، والملوك، من زارهم للتوجيه، والإرشاد والنصيحة، وإرشادهم إلى الخير، وتوجيههم إليهم، وتحذيرهم من خلافه، فهو مأجور، وهذا واجب عليه، وقد زار أهل العلم السلاطين من عهد الصديق، إلى عهد بني أمية، إلى عهد بني العباس، إلى غيرهم، فما زال أهل العلم يزورنهم، ويتصلون بهم؛ للتوجيه، والإرشاد، والنصيحة، والشفاعة للمظلومين، ورفع الظلم إلى غير ذلك. أما زيارة الأمراء، والسلطان لأجل المال، والشهوات، والطعام، والأكل، فهذا مذموم.","link":"https://binbaz.org.sa/fatwas/1912/الحكم-على-حديث-العلماء-ورثة-الانبياء-اذا-لم-يتبعوا-السلطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_696.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6512,"question":"ما صحة حديث: ما بعد الشرك بالله إلا أن يضع الرجل نطفته في فرج حرام؟","title":"الحكم على حديث: ما بعد الشرك بالله إلا","answer":"الجواب: جاء في هذا حديث، لكنه ضعيف، ولكن الزنا مثل ما سمعتم من أكبر الكبائر، فالله جعله بعد القتل، وبعد الشرك، وأكبر الكبائر الشرك بالله -جل وعلا- ثم القتل، ثم الزنا، الرتبة الثالثة -نعوذ بالله- أعظم شيء الشرك بالله -جل وعلا- الكفر، ثم يليه القتل، ثم يليه الزنا، نسأل الله العافية. قال الله -جل وعلا-: وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ [الفرقان:68] جعله في المرتبة الثالثة، فالنبي ﷺ سئل قال له ابن مسعود: يا رسول الله أي الذنب أعظم؟ قال: أن تجعل لله ندًا وهو خلقك -يعني الشرك- قال ثم أي؟ قال: أن تقتل ولدك خشية أن يطعم معك، قال: ثم أي؟ قال: أن تزاني بحليلة جارك فجعل الزنا في المرتبة الثالثة، وجعله مع زوجة الجار أقبح -نسأل الله العافية- مع زوجة الجار، ومع الأقارب أقبح وأقبح، نسأل الله العافية، ومع المرأة التي لها زوج، كل هذا أقبح الزنا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2269/الحكم-على-حديث-ما-بعد-الشرك-بالله-الا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_892.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6530,"question":"ما حكم الصلاة في المطار الجديد، علمًا بأنه يبعد عن الرياض حوالي ثلاث وخمسون كيلو مترًا، هل ركعتين أو أربع ركعات؟","title":"حكم القصر في مكان بعيد لكنه من البلد","answer":"الجواب: لا، يصلي صلاة مقيم؛ لأنه تبع الرياض، تبع البلد، والبناء حوله، وهو ليس بسفر.","link":"https://binbaz.org.sa/fatwas/2374/حكم-القصر-في-مكان-بعيد-لكنه-من-البلد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_908.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":6532,"question":"ما صحة حديث: اطلب العلم من المهد إلى اللحد: وحديث: لا يموتن أحدكم إلا وهو يحسن الظن بالله، فإن حسن الظن بالله ثمن الجنة؟","title":"ما صحة: «اطلب العلم من المهد»، و «لا يموتن أحدكم إلا»؟","answer":"الجواب:\n\nحديث: \"اطلبوا العلم من المهد إلى اللحد\" هذا ما هو بصحيح، موضوع، عند أهل العلم، ليس بصحيح، الذي في المهد ما يطلب العلم، ولا يعرف العلم اطلبوا العلم من المهد إلى اللحد هذا ليس بصحيح، ولكن المعنى الجد في طلب العلم، والحرص على طلب العلم، والحديث غير صحيح. وكذلك الحديث الآخر: اطلبوا العلم ولو في الصين ليس بصحيح.\nأما حديث: لا يموتن أحدكم إلا وهو يحسن ظنه بالله فهو حديث صحيح رواه مسلم، وغيره عن النبي ﷺ قال: لا يموتن أحدكم إلا وهو يحسن ظنه بالله وقال النبي ﷺ يقول الله : أنا عند ظن عبدي بي، وأنا معه حين يذكرني فيظن بالله الحسن طيب هذا من أهم المهمات، ولكن يلزم ما يحصل له إذا أحسن عمله، إذا أحسن العمل حسن ظنه، وأما الذي أساء العمل ما يستقيم له حسن الظن، وقد أساء العمل؛ لأن سوء العمل يدعوه إلى سوء الظن كما قال الشاعر: \n\n\n\t\n\t\t\n\t\t\tإذا ساء فعل المرء ساءت ظنونه\n\t\t\n\t\n\n\nفالمقصود: أن من أسباب حسن الظن بالله الاجتهاد في طاعته، والحذر من معصيته  فمن أحسن طاعته بالله، واستقام على أمر الله، وتباعد عن محارم الله، حسن ظنه بالله، ومن ساءت أعماله؛ ساءت ظنونه، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2381/ما-صحة-اطلب-العلم-من-المهد-و-لا-يموتن-احدكم-الا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_914.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6533,"question":"من تعلم العلم ليجاري به العلماء، ويماري به السفهاء، ويصرف به وجوه الناس إليه، أدخله الله النار أرجو أن تشرحوا هذا الحديث شرحًا موجزًا؟","title":"ما صحة حديث: «من تعلم العلم ليجاري به العلماء»؟","answer":"الجواب: هذا حديث ضعيف الإسناد، ولكن معناه صحيح، من تعلم العلم للمباهاة -مباهاة العلماء- أو مجاراة السفهاء، أو لأجل أن يثنوا عليه الناس، ويقولون: إنه كذا، وإنه كذا، هذا مرائي ما قصد وجه الله، فيكون مع المرائين، متوعد بالنار -نعوذ بالله- ولهذا قال: فالنار النار -نسأل الله العافية- فمعناه صحيح، ومعناه الحذر من الرياء، وأن الواجب أن يتعلم العلم، لا لمباهاة العلماء، ولا لمماراة السفهاء، ولا لأجل يصرف وجوه الناس إليه، وثنائهم عليه، ومدحهم له، لا، ولكن يجب أن يتعلمه؛ ليعرف به دينه، وليعبد الله به، وليعلمه الناس، ويدعو إلى شريعة الله، وأحكامه، هكذا يجب التعلم. أما للرياء، والسمعة، والمباهاة، ومماراة السفهاء، أو لأجل حطام الدنيا، فهذا من الرياء الذي حرمه الله، وتوعد عليه بالنار.","link":"https://binbaz.org.sa/fatwas/2370/ما-صحة-حديث-من-تعلم-العلم-ليجاري-به-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_904.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6538,"question":"ما مدى صحة حديث: هلك المتنطعون الذي رواه مسلم؟","title":"الحكم على حديث: «هلك المتنطعون»","answer":"الجواب: هذا حديث صحيح رواه مسلم، وغيره هلك المتنطعون قالها ثلاثًا -عليه الصلاة والسلام- والتنطع التكلف، والتعمق في الشيء والابتداع، هذا من حجة أهل السنة على أهل البدع؛ لأنها تنطع، وتكلف، فالمتنطع هو المتكلف المتعمق الذي يسأل عن أشياء، ويأتي بأشياء ما شرعها الله .","link":"https://binbaz.org.sa/fatwas/2371/الحكم-على-حديث-هلك-المتنطعون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_905.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6576,"question":"هل ورد حديث، أو أثر يقول: إن المدمن في أكل اللحم كالمدمن في شرب الخمر؟","title":"هل ورد أثر أن المدمن في أكل اللحم كمدمن الخمر؟","answer":"الجواب: أثر عن بعض الصحابة أنه حذر من الاستمرار على أكل اللحوم، وقال: إن لها ضراوة مثل ضراوة الخمر، يعني الذي اعتادها ما يخليها، الذي اعتاد اللحوم يبتلى بالحرص عليها حتى ولو تدين، فينبغي أنه يكون تارة، وتارة، تارة يأكل لحمًا، وتارة لا يأكل لحمًا، حتى لا يكون له ضراوة، حتى لا يعتادها؛ فيشق على نفسه. وإلا اللحوم ما هي مثل الخمر، الخمر محرم، واللحوم مباحة، لكن المقصود: أن الذي يعتادها -بعض السلف يكره اعتيادها- يقول: ينبغي أن يكون تارة، وتارة، حتى لا يعتادها؛ فيشق عليه.","link":"https://binbaz.org.sa/fatwas/2399/هل-ورد-اثر-ان-المدمن-في-اكل-اللحم-كمدمن-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_928.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6578,"question":"التهنئة في العيد -أي عيد الفطر وعيد الأضحى- وما يفعله الناس من المصافحة، أو الالتزام، أو التعانق، والرسائل بعد صلاة العيدين، حتى ولو كانوا معًا قبل الصلاة، هل لهذا أصل؟ وإن كان لذلك أصل فما هي الصفة الصحيحة؟","title":"حكم التهنئة يوم العيد والمعانقة والمصافحة","answer":"الجواب: ما أعلم لهذا أصلًا، لكن كان السلف يهنئ بعضهم بعضا: تقبل الله منك، تقبل الله منا ومنك، فإذا قابله، وصافحه، وقال: تقبل الله منا ومنك، وعيدك مبارك؛ فلا نعلم به بأسًا، هذا من العهد الأول بارك الله لك في العيد، أو تقبل الله منا ومنك، وكلمات نحو هذا، لا بأس، يكفي. أما المعانقة لا نعلم لها أصلًا، لكن معروفة بين الناس فيما بينهم إذا تقابلوا، وإلا تركها أولى، تكفي المصافحة، أو الدعاء بالقبول عند اللقاء، يكفي.","link":"https://binbaz.org.sa/fatwas/2433/حكم-التهنىة-يوم-العيد-والمعانقة-والمصافحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_960.mp3","categories":["صلاة العيدين","صلاة الجمعة","فضائل الأزمنة والأمكنة"]},{"id":6597,"question":"هل السواك أثناء خطبة الجمعة جائز؟ وهل الذي يستاك أثناء الخطبة ينطبق عليه قول الرسول: من لغا؛ فلا جمعة له؟","title":"حكم السواك أثناء خطبة الجمعة","answer":"الجواب: من مس الحصى فقد لغا الأولى: أنه لا يستاك وقت الخطبة؛ لأنه نوع من العبث، نوع من العمل، فلا يستاك حتى.. لأنه مأمور بالإنصات، فلا يقوم يصلي، ولا يقرأ  ولا يتكلم مع أحد ولا يعبث بالحصى، ولا بثيابه، ينصت، يقبل على الخطبة. المقصود: من الخطبة ماهو المقصود؟ المقصود من الخطبة: وعظ الحاضرين، فالمشروع لهم والواجب عليهم: أن ينصتوا، وأن يستمعوا لما يقال؛ حتى يستفيدوا، فلا يشتغل لا بالسواك، ولا باللحية، ولا بمس الحصى.","link":"https://binbaz.org.sa/fatwas/2449/حكم-السواك-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_976.mp3","categories":["صلاة الجمعة"]},{"id":6605,"question":"سافرت إلى بلاد غير مسلمة زيارة عمل، وكنت أحيانًا أصلي الظهر مع العصر جمع تأخير، والمغرب مع العشاء جمع تأخير، وأحيانًا أصلي العصر مع الظهر جمع تأخير، والعشاء مع المغرب كذلك، وأحيانًا أصلي الظهر مع العصر قبل غروب الشمس، والمغرب مع العشاء في منتصف الليل، وذلك لأسباب منها وجودي خارج الفندق، حيث يصعب وجود مكان للصلاة، وكذلك لا أعرف مواعيد الصلاة بالضبط في تلك الديار، فأفيدوني في حكم ذلك جزاكم الله خيرًا؟","title":"المدة التي يقصر فيها المسافر","answer":"الجواب:  إذا كان المسافر إلى بلد ما ليس عنده عزم على إقامة معينة، بل يطلب حاجة، أو يطلب شخصًا، أو يطلب سلعة لا يدري متى تنتهي إقامته؛ فهذا له أن يقصر الظهر ثنتين، والعصر ثنتين، والعشاء ثنتين، وله أن يجمع بين المغرب، والعشاء في وقت إحداهما، وبين الظهر، والعصر في وقت إحداهما، وليس له أن يؤخر عن وقت الثانية، ليس له أن يؤخر المغرب والعشاء إلى بعد نصف الليل أبدًا، بل يجب أن يكون قبل نصف الليل، ولو في الطريق يصلي، كذلك الظهر، والعصر لا يؤخرها حتى تصفر الشمس، يجب أن يجمع بينهما قبل أن تصفر الشمس في وقت العصر إذا لم يقدمها في وقت الظهر. أما إذا كان عنده إقامة معينة، أكثر من أربعة أيام؛ فالذي عليه جمهور أهل العلم أنه يتم إذا عزم عزمًا تامًا على أن يقيم إقامة أكثر من أربعة أيام، فجمهور أهل العلم على أنه يتم أربعًا، ولا يصلي ثنتين، ولا يقصر في هذه الحال؛ لأن النبي ﷺ قصر في أربعة، وذلك في حجة الوداع، وهي آخر أسفاره -عليه الصلاة والسلام- والأصل في المقيم الإتمام، وفي المسافر القصر، فإذا أقام أكثر من أربعة أيام؛ فهو مقيم، ويتم أربعًا؛ خروجًا من خلاف العلماء. وقال بعضهم: حد الإقامة أن تكون خمسة عشر يومًا، وقال بعضهم: تسعة عشر يومًا، ولكن الذي عليه الجمهور أن تكون أربعة أيام، فأقل، فإذا عزم على الإقامة أكثر من ذلك أتم، أما مادام مترددًا، ولا يدري هل يقيم ثلاثًا، أو يومين، أو عشرًا، أو عشرين، ما عنده جزم؛ فهذا يصلي صلاة المسافر، ويجمع جمع المسافر، لكن لا يتجاوز الوقت الثاني، لا يتجاوز العشاء، والمغرب نصف الليل، ولا يؤخر الظهر، والعصر إلى اصفرار الشمس .. كما بينته السنة عن رسول الله -عليه الصلاة والسلام-... يكفي، نسأل الله التوفيق، والهداية، وصلاح النية، والعمل.","link":"https://binbaz.org.sa/fatwas/2461/المدة-التي-يقصر-فيها-المسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_988.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":6609,"question":"سافرت إلى بلاد غير مسلمة زيارة عمل، وكنت أحيانًا أصلي الظهر مع العصر جمع تأخير، والمغرب مع العشاء جمع تأخير، وأحيانًا أصلي العصر مع الظهر جمع تأخير، والعشاء مع المغرب كذلك، وأحيانًا أصلي الظهر مع العصر قبل غروب الشمس، والمغرب مع العشاء في منتصف الليل، وذلك لأسباب منها وجودي خارج الفندق، حيث يصعب وجود مكان للصلاة، وكذلك لا أعرف مواعيد الصلاة بالضبط في تلك الديار، فأفيدوني في حكم ذلك جزاكم الله خيرًا؟","title":"المدة التي يقصر فيها المسافر","answer":"الجواب:  إذا كان المسافر إلى بلد ما ليس عنده عزم على إقامة معينة، بل يطلب حاجة، أو يطلب شخصًا، أو يطلب سلعة لا يدري متى تنتهي إقامته؛ فهذا له أن يقصر الظهر ثنتين، والعصر ثنتين، والعشاء ثنتين، وله أن يجمع بين المغرب، والعشاء في وقت إحداهما، وبين الظهر، والعصر في وقت إحداهما، وليس له أن يؤخر عن وقت الثانية، ليس له أن يؤخر المغرب والعشاء إلى بعد نصف الليل أبدًا، بل يجب أن يكون قبل نصف الليل، ولو في الطريق يصلي، كذلك الظهر، والعصر لا يؤخرها حتى تصفر الشمس، يجب أن يجمع بينهما قبل أن تصفر الشمس في وقت العصر إذا لم يقدمها في وقت الظهر. أما إذا كان عنده إقامة معينة، أكثر من أربعة أيام؛ فالذي عليه جمهور أهل العلم أنه يتم إذا عزم عزمًا تامًا على أن يقيم إقامة أكثر من أربعة أيام، فجمهور أهل العلم على أنه يتم أربعًا، ولا يصلي ثنتين، ولا يقصر في هذه الحال؛ لأن النبي ﷺ قصر في أربعة، وذلك في حجة الوداع، وهي آخر أسفاره -عليه الصلاة والسلام- والأصل في المقيم الإتمام، وفي المسافر القصر، فإذا أقام أكثر من أربعة أيام؛ فهو مقيم، ويتم أربعًا؛ خروجًا من خلاف العلماء. وقال بعضهم: حد الإقامة أن تكون خمسة عشر يومًا، وقال بعضهم: تسعة عشر يومًا، ولكن الذي عليه الجمهور أن تكون أربعة أيام، فأقل، فإذا عزم على الإقامة أكثر من ذلك أتم، أما مادام مترددًا، ولا يدري هل يقيم ثلاثًا، أو يومين، أو عشرًا، أو عشرين، ما عنده جزم؛ فهذا يصلي صلاة المسافر، ويجمع جمع المسافر، لكن لا يتجاوز الوقت الثاني، لا يتجاوز العشاء، والمغرب نصف الليل، ولا يؤخر الظهر، والعصر إلى اصفرار الشمس .. كما بينته السنة عن رسول الله -عليه الصلاة والسلام-... يكفي، نسأل الله التوفيق، والهداية، وصلاح النية، والعمل.","link":"https://binbaz.org.sa/fatwas/2461/المدة-التي-يقصر-فيها-المسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_988.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":6621,"question":"يقول عبدالله بن عمر -رضي الله عنهما-: لو سافرت ميلًا؛ لقصرت الصلاة، اقتداء بهذا الصحابي، فإني أسافر من الرياض إلى الدرعية، وصليت العشاء قصرًا في صلاتي، فهل صلاتي صحيحة، أم لا؟","title":"حكم القصر لمن انتقل من الرياض إلى الدرعية","answer":"الجواب: لا، هذا غلط، هذا ما هو بسفر، السفر ما يعد سفرًا، يحتاج إلى الزاد، والمزاد، وضبطه العلماء بيومين قاصدين مرحلتين، يعني أربعة برود، أما الدرعية -الآن-والرياض شيء واحد، الدرعية ما هي بسفر، الدرعية اتصلت بالرياض، وصارت محلًا واحدًا، فالذي يقصر بين الدرعية، والرياض غلط، عليه أن يعيد الصلاة أربعًا، ولا يقصر إلا في سفر يعد سفرًا، يعني المسافة يعدها الناس سفرًا، يحتاج صاحبها إلى الزاد، والماء يحمله معه؛ لأنه سفر، والغالب يكون سبعين كيلو، ثمانين كيلو، هذا هو الغالب.","link":"https://binbaz.org.sa/fatwas/2443/حكم-القصر-لمن-انتقل-من-الرياض-الى-الدرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_970.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":6709,"question":"ما صحة حديث: \"لا تسلموا على يهود أمتي\" قالوا: يا رسول الله من هم؟ قال: \"هم الذين لا يشهدون صلاة العصر\"؟","title":"الحكم على حديث: «لا تسلموا على يهود أمتي»","answer":"الجواب:  لا أصل لهذا، لا نعرف لهذا أصلًا، وإنما الثابت قوله ﷺ: لا تبدؤوا اليهود، ولا النصارى بالسلام، وإذا لقيتم أحدهم في طريق؛ فاضطروهم إلى أضيقه رواه مسلم، وقال -عليه الصلاة والسلام-: إذا سلم عليكم أهل الكتاب؛ فقولوا: وعليكم وأما هذا الأثر الذي ذكره السائل ما له أصل.","link":"https://binbaz.org.sa/fatwas/2584/الحكم-على-حديث-لا-تسلموا-على-يهود-امتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1080.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6710,"question":"ما مدى صحة حديث: لا طاعة لمخلوق في معصية الخالق؟","title":"الحكم على حديث: «لا طاعة لمخلوق في معصية الخالق»","answer":"الجواب: كله صحيح، الحديث صحيح إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فلا يجوز طاعة الأب، أو الزوج، الأمير، أو السلطان في معاصي الله، فإذا قال له السلطان، أو الأمير، أو أبوه، أو الزوج للزوجة اشربوا الخمر لا يطيعه في ذلك. السؤال: غير شرب الخمر، إذا قال احلق لحيتك؟ الجواب: أو قال احلق لحيتك، أو سب أباك، أو سب أمك، أو لا تطع أباك، ولا تطع أمك، كل هذا.. لا يطيعه في ذلك، أو لا تُصَلِّ في الجماعة.","link":"https://binbaz.org.sa/fatwas/2600/الحكم-على-حديث-لا-طاعة-لمخلوق-في-معصية-الخالق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1096.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6720,"question":"ما صحة حديث: \"لا تسلموا على يهود أمتي\" قالوا: يا رسول الله من هم؟ قال: \"هم الذين لا يشهدون صلاة العصر\"؟","title":"الحكم على حديث: «لا تسلموا على يهود أمتي»","answer":"الجواب:  لا أصل لهذا، لا نعرف لهذا أصلًا، وإنما الثابت قوله ﷺ: لا تبدؤوا اليهود، ولا النصارى بالسلام، وإذا لقيتم أحدهم في طريق؛ فاضطروهم إلى أضيقه رواه مسلم، وقال -عليه الصلاة والسلام-: إذا سلم عليكم أهل الكتاب؛ فقولوا: وعليكم وأما هذا الأثر الذي ذكره السائل ما له أصل.","link":"https://binbaz.org.sa/fatwas/2584/الحكم-على-حديث-لا-تسلموا-على-يهود-امتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1080.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6721,"question":"ما مدى صحة حديث: لا طاعة لمخلوق في معصية الخالق؟","title":"الحكم على حديث: «لا طاعة لمخلوق في معصية الخالق»","answer":"الجواب: كله صحيح، الحديث صحيح إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فلا يجوز طاعة الأب، أو الزوج، الأمير، أو السلطان في معاصي الله، فإذا قال له السلطان، أو الأمير، أو أبوه، أو الزوج للزوجة اشربوا الخمر لا يطيعه في ذلك. السؤال: غير شرب الخمر، إذا قال احلق لحيتك؟ الجواب: أو قال احلق لحيتك، أو سب أباك، أو سب أمك، أو لا تطع أباك، ولا تطع أمك، كل هذا.. لا يطيعه في ذلك، أو لا تُصَلِّ في الجماعة.","link":"https://binbaz.org.sa/fatwas/2600/الحكم-على-حديث-لا-طاعة-لمخلوق-في-معصية-الخالق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1096.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6726,"question":"ذكرتم أن من أسباب انحراف الأولاد الفراغ الذي يعيشون فيه، فما هو رأيكم في الحلول، والخطوات التي يتبعها المربي في تربية أولاده؛ لئلا يشعرهم بوقت الفراغ؟","title":"كيفية استغلال فراغ الأولاد","answer":"الفراغ إذا لم يشغل بحق، فإن النفوس تشغله بالباطل، فلا بد من سد الفراغ بما ينفع، وإذا كان عند الولد فراغ يشغله، إما بالمطالعة، وإما بمسابقات تنفع في شيء من العلم، والدين، وإما بنوادي نافعة، يلقى فيها المحاضرات الطيبة، والكلمات النافعة، والعظات الصالحة، وما أشبه ذلك، فلا بد من شغل الفراغ بشيء ينفع، ولا يضر، حتى ولو مباحًا، حتى لا يقع في الباطل، وحتى لا يقع في أيدي قرناء السوء، فلا بد أن يشغل فراغه بما ينفعه، من المطالعة في دروسه، من توجيه إلى الخير، من إشغاله بمراجعة الدروس مع أبيه، أو مع رجل طيب، أو مع أخيه، إيجاد أشياء في البيت تشغلهم عن الباطل، أشياء مباحة، يشغلهم عن الباطل... ثم يبيتون مبكرين، لا يسهرون، لا بد من فعل شيء ينفعهم، إما في الدين، وإما في الدنيا.","link":"https://binbaz.org.sa/fatwas/2614/كيفية-استغلال-فراغ-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1110.mp3","categories":["صلاة الجمعة","تربية الأولاد"]},{"id":6731,"question":"لي أخ في موسكو، ولا يستطيع إقامة صلاة الجمعة، وسألنا علماء الأزهر، فقالوا: إن الجمعة لا تجب في ديار الكفار، فهل على ذلك دليل، أم أنكم ترون غير ذلك؟","title":"حكم صلاة الجمعة في بلاد الكفار","answer":"الجواب: على كل حال المسافر لا تلزمه جمعة، فإنه يصلي ظهرًا، فإذا كان المقيم إقامة طويلة؛ لزمته الجمعة مع الناس، مع المسلمين الذين يصلون الجمعة، فإذا كان في بلاد ما فيها جمعة، ولا يصلي أحد جمعة صلى ظهرًا، ولا تلزمه الجمعة، يصلي ظهرًا، أما إن وَجَدَ مسلمين يصلون الجمعة، فإنه تلزمه أن يصلي معهم تبعا لهم، يصلي معهم الجمعة، وإلا فلا شيء عليه.","link":"https://binbaz.org.sa/fatwas/2605/حكم-صلاة-الجمعة-في-بلاد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1101.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":6746,"question":"إذا وافق العيد يوم جمعة، فهل تجزئ صلاة العيد عن صلاة الجمعة؟ وإذا صلوا يوم الجمعة، فهل تعتبر صلاة الجمعة كفارة إلى الأسبوع القادم؟","title":"إجزاء صلاة العيد عن الجمعة وصلاتها ظهراً","answer":"الجواب: إذا وافق العيد يوم الجمعة، فقد بين النبي ﷺ أن من صلى العيد؛ أجزأته عن الجمعة، ويصلي ظهرًا، فإذا صلى مع الناس صلاة العيد؛ فالأئمة يقيمون صلاة الجمعة -أئمة الجوامع عليهم أن يقيموا صلاة الجمعة- ويصلوا بالحاضرين، ومن لم يحضر، ومن صلى العيد؛ عليه أن يصلي في بيته ظهرًا، أو مع بعض إخوانه ظهرًا كما قال النبي -عليه الصلاة والسلام-.  والجمعة جعلها الله كفارة إذا تطهر في بيته، ثم أتى، وصلى ما قدر الله له، وحضر الخطبة، وأنصت، ولم يفرق بين اثنين، ولم يؤذ أحدًا؛ صارت جمعته كفارة لما بينه، وبين الجمعة الأخرى، وزيادة ثلاثة أيام؛ لأن الحسنة بعشر أمثالها، لكن ليس معناه أنها كفارة يضيع الصلوات التي بعدها، ويضيع الحقوق لا، يقوم بالحقوق عليه، ويتقي الله، ويقوم بالحقوق في جميع أوقاته من الصلوات، وغيرها، وهو لا بد محل الزلات، ومحل السيئات، فتكون هذه الجمعة كفارة للصغائر التي قد تقع منه. وأما الواجبات؛ عليه أن يؤديها، بعض الجهلة، يقول: ستكفيني صلاة الجمعة، ويضيع الصلوات.. هذا منكر عظيم، وكفر، وضلال، نسأل الله العافية. الكفارة مثل ما أن التوبة كفارة، ومثل ما أن الصلوات الخمس كفارة، لكن ليس معنى هذا أن هذا الرجل الذي يصلي الجمعة يضيع الصلوات الأخرى ويقول: سيكفر عنه بالجمعة الأخرى، أو يضيع الحقوق الأخرى، ولا يأمر بالمعروف، ولا ينهى عن منكر، أو يعق والديه، أو يقطع أرحامه، أو يشهد بالزور، أو يدعي بالباطل، يريد أنها تكفر عنه الجمعة، لا جهل كبير، وضلال بعيد، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/2621/اجزاء-صلاة-العيد-عن-الجمعة-وصلاتها-ظهرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1117.mp3","categories":["صلاة الجمعة","صلاة العيدين"]},{"id":6770,"question":"هل حديث طلب العلم فريضة على كل مسلم، ومسلمة أن المسلمة مضمومة في الحديث؟","title":"الحكم على حديث (طلب العلم فريضة على كل مسلم)","answer":"الجواب: لا، المشهور على كل مسلم فقط، والحديث ضعفه الأكثرون، ولكن صححه بعض أهل العلم، وهو كذلك، فإن له طرقًا كثيرة يرتقي بها إلى درجة الحسن، لكنه على كل مسلم، يجب على كل مسلم. والمعنى: إذا كان على مسلم، فالمسلمة دخلت؛ لأنه ما وجب على هذا وجب على هذا -كما تقدم- الأحكام بينهم ثابتة، فما وجب على المسلم؛ وجب على المسلمة، وما وجب عليها؛ وجب على المسلم، إلا ما خصه الدليل بواحد منهما. السؤال: أنا أحد الدارسين في الكلية المتوسطة بالرياض، هناك أحد الإخوة المدرسين حليق اللحية، يلبس بنطلونًا، وقميصًا، ويلاحظ عليه في صلاته؛ حيث يسجد على رؤوس أصابع اليدين، وينصب قدميه في الجلوس، ويحاول دائمًا أن يؤم المصلين في مسجد الكلية، علمًا أن خلفه من هو أحق منه علمًا، وصفة، وقد قمنا بمناصحته عدة مرات، ولكن دون جدوى، فاتصلنا برئيس قسم الدراسات الإسلامية بالكلية، وشرحنا له الوضع، ولكن دون جدوى، وفي يوم الثلاثاء الماضي، أم المذكور المصلين بصلاة الظهر، ولشعوره بعدم رضا المصلين عنه؛ وقف بعد الصلاة ليحدث، ويذكر، فأخذ يتخبط في الأحاديث، حتى أنه قال: يتقدم الإنسان للإمامة ملتحيًِا، أو غير ملتحي، فإنما اللحية سنة، وبعد هذا القول اضطررنا على قطع حديثه، وإجباره على الجلوس، وعدم الاستمرار؛ ما سبب حدوث ضجة في المسجد، نرجو عمل اللازم لإيقافه، وغيره عند حده، وجزاكم الله خيرًا؟\n\nالجواب: تكتب لنا كتابا غير هذه توضح فيها المدرسة والشخص حتى يعالج الموضوع، أما هذه مبهمة.  السؤال: نرجو من سماحتكم أن ترسلوا من قبلكم إلى الخدمات الطبية بالحرس الوطني في القسم العام مستشفى الملك فهد، والخدمات الطبية بالأمن العام حتى يرى فضيلتكم ما يخالف نصوص القرآن الكريم والسنة المطهرة حفظكم الله آمين؟ الجواب: نسأل الله الهداية للجميع، يلاحظ إن شاء الله، يلاحظ يلاحظ.","link":"https://binbaz.org.sa/fatwas/2663/الحكم-على-حديث-طلب-العلم-فريضة-على-كل-مسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1159.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6775,"question":"نرجو توضيح مسألة صلاة المزحوم في صلاة الجمعة الوارد في كتاب العدة شرح العمدة؟","title":"كيفية صلاة المزحوم في صلاة الجمعة","answer":"الجواب: المزحوم إذا زحم بعدما صلى ركعة هذا يكمل لنفسه، يأتي بركعة ثانية، ويكمل لنفسه، وإن كان مزحوماً قبل أن يؤدي ركعة؛ فلا تجزئه الجمعة، إذا ما تيسر له أن يركع مع الإمام، ويسجد مع الإمام فما أدرك الجمعة، أما إذا زحم بعدما صلى ركعة، أو جاء والإمام قد صلى ركعة، وصلى ركعة مع الإمام، ثم زحم، وصلى الثانية وحده؛ لا يضره.  فالحاصل: أنه إذا أدرك ركعة مع الإمام الأولى، أو الثانية؛ أدرك الجمعة، كملها جمعة، وإن أحيل بينه وبين ذلك؛ يصلي ظهرًا لنفسه، مثل المسبوق.","link":"https://binbaz.org.sa/fatwas/2630/كيفية-صلاة-المزحوم-في-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1126.mp3","categories":["صلاة الجمعة"]},{"id":6814,"question":"قال رسول الله ﷺ: \"يا علي لا تنم إلا أن تأتي بخمسة أشياء: هي قراءة القرآن كله، وتصدق بأربعة آلاف درهم، وزيارة الكعبة المشرفة، وحفظ مكانك في الجنة، وإرضاء الخصوم\" قال علي: وكيف ذلك يا رسول الله؟ قال: أما تعلم أنك إذا قرأت قُلْ هُوَ اللَّهُ أَحَدٌ  [الإخلاص: 1] ثلاث مرات، فقد قرأت القرآن كله، وإذا قرأت الفاتحة أربع مرات؛ تصدقت بأربعة آلاف درهم، وإذا قلت: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد يحيي، ويميت، وهو على كل شيء قدير؛ فقد زرت الكعبة، وإذا قلت: لا حول، ولا قوة إلا بالله عشر مرات؛ حفظت مكانك في الجنة، وإذا قلت: أستغفر الله العظيم الذي لا إله إلا هو الحي القيوم، وأتوب إليه ثلاث مرات؛ فقد أرغمت الخصوم» ما صحة هذا الحديث؟","title":"ما صحة حديث: «يا علي! لا تنم إلا أن تأتي بخمسة أشياء»؟","answer":"الجواب:\nهذا باطل، مكذوب على الرسول ﷺ قد نبهنا على هذا أكثر من مرة، مكذوب، ولكن هذه الأذكار طيبة، الإنسان يقولها، طيبة يذكر الله، ويقرأ القرآن طيب، لكن هذا مكذوب على الرسول ﷺ الكلام هذا.","link":"https://binbaz.org.sa/fatwas/2684/ما-صحة-حديث-يا-علي-لا-تنم-الا-ان-تاتي-بخمسة-اشياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1182.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6869,"question":"بعض الناس يصوم بعض أيام رجب مستدلًا بالحديث الذي يقول: اللهم بارك لنا في رجب، وشعبان، وبلغنا رمضان فما مدى صحة هذا الحديث؟","title":"درجة حديث: \"اللهم بارك لنا في رجب وشعبان\"","answer":"الجواب: حديث ضعيف، حديث، غير صحيح، ولا حجة فيه، اللهم بارك لنا في رجب لا حجة في تخصيصه بشيء، لكنه ضعيف.","link":"https://binbaz.org.sa/fatwas/2757/درجة-حديث-اللهم-بارك-لنا-في-رجب-وشعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1249.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":6879,"question":"إذا سافرت مسافة 80 كم، وعدت من نهاري، هل يجوز لي القصر، أم لا؟","title":"السفر الذي يترتب عليه أحكام السفر","answer":"الجواب: إذا سافر الإنسان مسافة قصر، ولو عاد في يومه، وليلته؛ فهو في حكم المسافرين ثمانين كيلو، أو سبعين كيلو، أو ما يقارب ذلك.  المقصود: إذا سافر مسافة قصر، ولو رجع في يومه، أو ليلته؛ فهو مسافر في الذهاب، والإياب، له أحكام السفر.","link":"https://binbaz.org.sa/fatwas/2768/السفر-الذي-يترتب-عليه-احكام-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1260.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":6895,"question":"إذا سافرت مسافة 80 كم، وعدت من نهاري، هل يجوز لي القصر، أم لا؟","title":"السفر الذي يترتب عليه أحكام السفر","answer":"الجواب: إذا سافر الإنسان مسافة قصر، ولو عاد في يومه، وليلته؛ فهو في حكم المسافرين ثمانين كيلو، أو سبعين كيلو، أو ما يقارب ذلك.  المقصود: إذا سافر مسافة قصر، ولو رجع في يومه، أو ليلته؛ فهو مسافر في الذهاب، والإياب، له أحكام السفر.","link":"https://binbaz.org.sa/fatwas/2768/السفر-الذي-يترتب-عليه-احكام-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1260.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":7009,"question":"ما صحة حديث: اللهم بارك لنا في شامنا ويمننا فقالوا: وفي نجدنا، فسكت. وهل صحيح أن قرن الشيطان يطلع من نجد؟","title":"الحكم على حديث: «اللهم بارك لنا في شامنا ويمننا»","answer":"الجواب:\n\nهذا صحيح، حديث صحيح اللهم بارك لنا في شامنا ويمننا قالوا: وفي نجدنا، فأعادها مرات، ثم قال: هناك قرن الشيطان يعني في الشرق، وأنه في نجد، وفي الشرق كله، ونجد بين الرسول ﷺ أن هناك مضر وربيعة عندهم من الشر والجفاء، قال: أصحاب الإبل.\n\nبين -عليه الصلاة والسلام- أن قبائل العرب عندها من الجهل، وعندها من الشر ما عندها، إلا من هداه الله، وليس المقصود نجد فقط، المقصود به الشرق هاهنا من حيث يطلع قرن الشيطان، يعني من الشرق كله، شرق المدينة، وشرق الدنيا كلها، لأنه هناك وجد أصناف البدع، وأصناف الشرور، وظهرت الشيوعية، وظهر الفساد هناك في الشرق.\n\nوكذلك يوجد في الجزيرة هذه من الشرور، وارتد كثير من العرب بعد موته ﷺ وشر في بني حنيفة، وبني أسد، وفي بني تميم، وادعى بعضهم النبوة، مسيلمة في بني حنيفة، وسجاح في بني تميم، وطليحة في بني أسد، وعماها شر كبير، ثم هداهم الله، ودخلوا في دين الله، ولكن الشر من جهة خراسان، ومن جهة ما وراء ذلك من جهة الصين، ومن جهة البلاد .... فيها شر كثير،......","link":"https://binbaz.org.sa/fatwas/2936/الحكم-على-حديث-اللهم-بارك-لنا-في-شامنا-ويمننا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1384.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7023,"question":"صلاة الجمعة بالنسبة لهم؟","title":"حكم صلاة الجمعة لمن لا يسمع الأذان","answer":"الجواب:\n\nكذلك ما عليهم جمعة إذا كانوا لا يسمعون الأذان، بعيد المسافة، يعني طويلة ما يسمعون الأذان فلا جمعة عليهم.\n\nالسؤال: ولو تعمدوا أن يبعدوا عن أماكن سماع الأذان؟\n\nالجواب: ولو، لو كانوا بعيدين لهم حكم السفر، وإن كانوا ما هم بعيدين بعد كلي؛ فلهم حكم العذر؛ لعدم سماع المؤذن، ومشقة المجيء، وحدها بعض أهل العلم الفرسخ.\n\nالسؤال: لو ظلوا على ذلك يعني كل مرة يذهبون في العطل؛ ليتمتعوا .. ويحرموا من الجمعة؟\n\nالجواب: ينبغي لهم ألا يفعلوا؛ لئلا يحرموا أنفسهم فضل الجمعة وسماع الخطب.\n\nالسؤال: لو جعلوها عادة كل جمعة؟\n\nالجواب: ينبغي أن يعلموا ويرشدوا، أنه ينبغي لهم أن يحافظوا على الجمعة، وأن يستفيدوا من الخطيب، ومن مواعظ الجمعة، لكن متى ذهبوا؛ لم تلزمهم الجمعة، إذا بعدوا بحيث لا يسمعون النداء.","link":"https://binbaz.org.sa/fatwas/2959/حكم-صلاة-الجمعة-لمن-لا-يسمع-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1409.mp3","categories":["صلاة الجمعة"]},{"id":7102,"question":"ما رأي سماحتكم في الحديث الذي يقول: \"داعب ولدك سبعًا، وأدبه سبعًا، وعلمه سبعًا\" وفي رواية: \"ثم اترك حبله على غاربه\"؟","title":"درجة صحة حديث داعب ولدك سبعاً","answer":"الجواب:\n\nليس له أصل، هذا لا أصل له، نعوذ بالله، إنما المحفوظ عن النبي ﷺ أنه قال: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع.","link":"https://binbaz.org.sa/fatwas/3130/درجة-صحة-حديث-داعب-ولدك-سبعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1489.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7152,"question":"ذكرتم في الجمعة الماضية: أن الجمعة تقام بحضور ثلاثة فأكثر، وفي كتاب الفقه المرحلة الابتدائية ما نصه: يشترط لصحة الجمعة حضور أربعين من المكلفين من أهل البلد، كيف نوافق بين هذين الأمرين، حيث سألنا بعض الطلاب الذين حضروا عن هذا الأمر، ووقعنا في حرج للأهمية، نرجو هذا الموضوع ؟","title":"العدد الذي تقام به صلاة الجمعة","answer":"الجواب:\n\nاشتراط الأربعين قول لجماعة من أهل العلم، وهو مذهب حنبلي، الذي يدرس في المدارس هو مذهب الحنابلة، معروف عند جمع من أهل العلم، ولكن القول الراجح: أنه لا يشترط أربعون، وليس عليه دليل، اشتراط الأربعين  حديث ضعيف.\n\nفلو اجتمعت القرية، عشرة ساكنون، عشرون ساكنون، خمسة ساكنون مستوطنون في القرية؛ شرع لهم أن يصلوا الجمعة، كما يصلوا الجماعة، ولا يشترط أربعون في أصح أقوال العلماء.\n\nالمسألة فيها خلاف كثير بين أهل العلم، لكن هذا هو الأصح من أقوالهم؛ لأنه ليس هناك دليل على تعيين عدد أكثر من الثلاثة، الثلاثة هم الجمع، يحصل بهم الإمام والمأمومون، إمام ومأمومون اثنان، هذا أقل عدد يكون فيه جمع، وأداء الجمعة.\n\nالسؤال: يعني تجب عليهم الجمعة، صارت واجبة عليهم؟ \n\nالجواب: نعم.","link":"https://binbaz.org.sa/fatwas/3189/العدد-الذي-تقام-به-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1547.mp3","categories":["صلاة الجمعة"]},{"id":7161,"question":"ذكرتم في الجمعة الماضية: أن الجمعة تقام بحضور ثلاثة فأكثر، وفي كتاب الفقه المرحلة الابتدائية ما نصه: يشترط لصحة الجمعة حضور أربعين من المكلفين من أهل البلد، كيف نوافق بين هذين الأمرين، حيث سألنا بعض الطلاب الذين حضروا عن هذا الأمر، ووقعنا في حرج للأهمية، نرجو هذا الموضوع ؟","title":"العدد الذي تقام به صلاة الجمعة","answer":"الجواب:\n\nاشتراط الأربعين قول لجماعة من أهل العلم، وهو مذهب حنبلي، الذي يدرس في المدارس هو مذهب الحنابلة، معروف عند جمع من أهل العلم، ولكن القول الراجح: أنه لا يشترط أربعون، وليس عليه دليل، اشتراط الأربعين  حديث ضعيف.\n\nفلو اجتمعت القرية، عشرة ساكنون، عشرون ساكنون، خمسة ساكنون مستوطنون في القرية؛ شرع لهم أن يصلوا الجمعة، كما يصلوا الجماعة، ولا يشترط أربعون في أصح أقوال العلماء.\n\nالمسألة فيها خلاف كثير بين أهل العلم، لكن هذا هو الأصح من أقوالهم؛ لأنه ليس هناك دليل على تعيين عدد أكثر من الثلاثة، الثلاثة هم الجمع، يحصل بهم الإمام والمأمومون، إمام ومأمومون اثنان، هذا أقل عدد يكون فيه جمع، وأداء الجمعة.\n\nالسؤال: يعني تجب عليهم الجمعة، صارت واجبة عليهم؟ \n\nالجواب: نعم.","link":"https://binbaz.org.sa/fatwas/3189/العدد-الذي-تقام-به-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1547.mp3","categories":["صلاة الجمعة"]},{"id":7163,"question":"الجميع يعلم أن الشيخ ناصر الدين الألباني من كبار علماء الحديث والرجال، فهل غابت عنه العلل التي تضعف حديث أسماء؟ وما هي حجته في إباحة كشف الوجه، والكفين، نرجو الإفادة؟","title":"توجيه كلام الألباني في تحسين حديث أسماء في كشف الوجه","answer":"الجواب:\n\nالشيخ ناصر الدين الألباني من إخواننا المعروفين، معروف فضله وعلمه، ولكن مثل غيره من العلماء له أغلاط، وله أخطاء يعرفها أهل العلم، وهذا من أخطائه وأغلاطه في هذا الحديث، وفي أشياء أخرى، بل في نفس الحجاب. \n\nوقوله بالجواز السفور هو قد غلط في هذا، كما غلط من هو أكبر منه، فلا يظن أن فلانًا أو فلانًا معصوم، فالشافعي له أخطاء، ومالك له أخطاء، وأحمد بن حنبل وهم أكبر منه، لهم أخطاء، وأبو حنيفة له أخطاء، وغيرهم من أهل العلم.\n\nكل واحد له مسائل معدودة غلط فيها، خفي عليه الحق، إما ما بلغه الحديث، أو بلغه من طريق ضعيفة، أو غير هذا من الأسباب، فكل عالم له أخطاء، وكفى المرء نبلًا أن تعد مثالبه، كل إنسان ما يسلم من الأخطاء.","link":"https://binbaz.org.sa/fatwas/3187/توجيه-كلام-الالباني-في-تحسين-حديث-اسماء-في-كشف-الوجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1545.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7172,"question":"نرجو بيان صحة هذه الأحاديث: \"الدين المعاملة\" \"تخيروا لنطفكم فإن العرق دساس\" \"المؤمن يألف ولا خير فيمن لا يألف ولا يؤلف\"؟","title":"درجة حديث: «الدين المعاملة»وحديث: «تخيروا لنطفكم»","answer":"الجواب:\n\nليس بحديث، إنما هو من كلام الناس، الحديث: الدين النصيحة أما \"الدين المعاملة\" فليس من الأحاديث.\n\nوأما حديث \"تخيروا لنطفكم\" فهذا ليس بصحيح، بل هو من الأحاديث الضعيفة التي لا يعتمد عليها، ولكن معناه صحيح، المعنى صحيح أن الإنسان ينبغي له أن يتخير من المناسب الطيبة المعروفة بالدين والخير والأخلاق الفاضلة.\n\nوأما المؤمن يألف ولا يؤلف ما أعرف صحته، ولا أعرف حال سنده، ولا أدري عن حاله، يراجع إن شاء الله ويكون في الجمعة الآتية يبين حاله إن شاء الله.","link":"https://binbaz.org.sa/fatwas/3211/درجة-حديث-الدين-المعاملة-وحديث-تخيروا-لنطفكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1559.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7234,"question":"ذكر في كتاب \"إتحاف الجماعة\" للتويجري حديث رواه مسلم في مقدمته، قد قال ما معناه: عن عبدالله بن عمر أن في البحر شياطين مسجونة أوثقها سليمان يوشك أن تخرج وتعلم الناس قرآنا، وحديث آخر معناه: أن في آخر الزمان تأتي شياطين إلى المساجد تعلم الناس أمور دينهم، فما صحة ذلك مع الشرح إن أمكن؟","title":"ما صحة أحاديث تعليم الشياطين الناس أمور دينهم؟","answer":"الجواب:\n\nهذا مما تلقاه عن بني إسرائيل -والله أعلم- أخبار بني إسرائيل التي ما جاء فيها نص مما لا يصدق ولا يكذب، هذه من أخبار بني إسرائيل، النبي ﷺ قال: حدثوا عن بني إسرائيل ولا حرج.\n\nفالواجب التثبت؛ لأنه قد يأتي شياطين إنس -ما هم شياطين جن- يتكلمون ويعظون ويذكرون ويحللون ما حرم الله، ويحرمون ما أحل الله، يجب الحذر، فلا يؤخذ العلم إلا ممن عرف بالخير والهدى، ما يؤخذ العلم ممن هب ودب ،ولا يعرف حاله، لا.\n\nعلى أهل الإسلام ألا يأخذوا العلم إلا ممن عرف بالعلم والخير والأمانة، لا يؤخذ العلم من ناس مجهولين لا يدرى عنهم إلا بالدليل، لا بد من الدليل.","link":"https://binbaz.org.sa/fatwas/3291/ما-صحة-احاديث-تعليم-الشياطين-الناس-امور-دينهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1616.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7250,"question":"ما صحة الحديث الذي يقول: إن أحد الصحابة  مر بالنبي ﷺ ومعه ثلاثة آصع من بر لكي يعطيها أختًا له، فتوفي عنها زوجها، أو أخت توفي عنها زوجها، ولها أيتام، وهم فقراء، فتبسم النبي ﷺ وتعجب له، وقال: \"إنه بقي في أجله ثلاثة أيام، وبسبب صلته لأخته؛ أجل الله عمره ثلاثين عامًا عن كل صاع عشر سنوات\" ما صحة هذا؟","title":"درجة حديث: «إنه بقي في أجله ثلاثة أيام، وبسبب صلته»","answer":"الجواب:\n\nلا أعلم هذا، ولا أعرفه، ولا أظنه صحيحًا.","link":"https://binbaz.org.sa/fatwas/3319/درجة-حديث-انه-بقي-في-اجله-ثلاثة-ايام-وبسبب-صلته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1643.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7257,"question":"ما صحة الحديث الذي يقول: إن أحد الصحابة  مر بالنبي ﷺ ومعه ثلاثة آصع من بر لكي يعطيها أختًا له، فتوفي عنها زوجها، أو أخت توفي عنها زوجها، ولها أيتام، وهم فقراء، فتبسم النبي ﷺ وتعجب له، وقال: \"إنه بقي في أجله ثلاثة أيام، وبسبب صلته لأخته؛ أجل الله عمره ثلاثين عامًا عن كل صاع عشر سنوات\" ما صحة هذا؟","title":"درجة حديث: «إنه بقي في أجله ثلاثة أيام، وبسبب صلته»","answer":"الجواب:\n\nلا أعلم هذا، ولا أعرفه، ولا أظنه صحيحًا.","link":"https://binbaz.org.sa/fatwas/3319/درجة-حديث-انه-بقي-في-اجله-ثلاثة-ايام-وبسبب-صلته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1643.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7267,"question":"نحن قادمون من بلاد بعيدة، ثم نزلنا بالرياض، فهل نعتبر مسافرين تطبق علينا أحكام السفر، أم مقيمين؟","title":"حكم قصر الصلاة للمسافر ومدته","answer":"الجواب:\n\nالمسافر إذا نزل في البلد، وعنده نية الإقامة أكثر من أربعة أيام؛ فهو في حكم المقيمين، يصلي أربعًا، ولا يجمع إذا كانت نيته الإقامة أكثر من أربعة أيام بلياليها، هذا هو الذي عليه جمهور أهل العلم.\n\nأما إذا نزل وهو إنما أراد يومًا، أو يومين، أو ثلاثًا فهو مسافر، أو ما عنده يقين، ما يدري متى يسافر، لا يدري يسافر غدًا، أو بعد غد، يطلب حاجة لا يدري متى يحصلها، أو خصمًا له يطلبه، أو ما أشبه ذلك من الحاجات التي لا يعلم متى تنتهي، فهذا حكمه حكم المسافرين، ولو عاش سنة ما دام بهذه النية. \n\nالسؤال: ...\n\nالجواب: إن كان واحدًا وجب أن يصلي مع الجماعة، وإن كانوا اثنين، فأكثر فهم بالخيار إن صلوا قصرًا ثنتين؛ فلا بأس، وإن صلوا مع الناس صلوا أربعًا، أما إن كان واحدًا فالواحد يصلي مع الناس، لا يدع الجماعة.","link":"https://binbaz.org.sa/fatwas/3338/حكم-قصر-الصلاة-للمسافر-ومدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1659.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":7275,"question":"النساء يوم الجمعة يتسننون، يقولون: هذه سنة الجمعة الساعة الحادية عشر كذا، يركعون لهن أربع ركعات، أو ركعتين ...؟","title":"حكم سنة الجمعة القبلية والبعدية","answer":"الجواب:\n\nالنساء ليس عليهن جمعة، وليس لهن سنة جمعة، الجمعة للرجال، وليس لها سنة قبلها، سنتها بعدها ركعتان، أو أربع ركعات في المسجد، أو في البيت، وأما قبلها فيصلي ما كتب الله له، إذا جاء المسجد يصلى ما كتب الله له ركعتين، أو أربعًا أو ستًا أو ثمانًا، أو أكثر، ليس لها حد محدود، وليس لها راتبة قبلها، ولكن يصلي الإنسان يوم الجمعة ما تيسر قبل الصلاة، ويصلي بعدها ركعتين، أو أربعًا.\n\nفقد ثبت عنه ﷺ أنه كان يصلي ركعتين في بيته -عليه الصلاة والسلام- وقال: من كان مصليًا بعد الجمعة؛ فليصل أربعًا فإن صلى أربعًا فهو أفضل، وإن صلى ثنتين؛ كفى ذلك.\n\nوأما النساء فليس عليهن جمعة إذا صلين في بيوتهن، وإذا صلين الضحى تكون صلاة الضحى ما هي بصلاة الجمعة، إذا صلين في بيوتهن الضحى يوم الجمعة فهذه يقال لها: صلاة الضحى، ما هي سنة الجمعة، يقال لها: صلاة الضحى.\n\nأما إن صلين مع الناس في المسجد؛ فإنهن يصلين مع الناس كصلاة الناس ركعتين يوم الجمعة، تجزئهن عن الظهر، إذا صلت المرأة مع الناس في المساجد يوم الجمعة أجزأتها الجمعة عن الظهر، وإذا صلت قبلها ركعات فهي سنة الضحى، وليست سنة الجمعة، وإذا صلت بعدها تكون ركعتين، أو أربعًا سنة الجمعة إذا صلت مع الناس الجمعة.\n\nأما في بيتها فليس لها جمعة، بل تصلي ظهرًا أربع ركعات في بيتها، وليس لها جمعة في البيت، وإن صلت مع الناس صلت معهم ركعتين وأجزأتها والحمد لله.","link":"https://binbaz.org.sa/fatwas/3346/حكم-سنة-الجمعة-القبلية-والبعدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1667.mp3","categories":["صلاة الجمعة"]},{"id":7292,"question":"حديث: لا غيبة في فاسق؟","title":"درجة حديث: لا غيبة في فاسق","answer":"الجواب:\n\nليس بصحيح، لكن جاء بالأدلة ما يدل على جواز غيبة الفاسق فيما أظهر، مثل قول النبي ﷺ لما أستأذن عليه بعض الناس قال: بئس أخو العشيرة أو قال: بئس ابن العشيرة فلما دخل عليه انبسط له، فقالت له عائشة في ذلك، فقال: يا عائشة: إن شر الناس من تركه الناس اتقاء شره.\n\nفالمقصود: أنه إذا كان معروفًا بالبدعة، معروفًا بالفسق الظاهر، فلا غيبة له، إذا قيل: إن هذا فلانًا يفعل كذا احذروه، ابتعدوا عنه، هذا لا غيبة له في هذا الشيء الذي أظهره من البدعة والمنكر.","link":"https://binbaz.org.sa/fatwas/3356/درجة-حديث-لا-غيبة-في-فاسق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1677.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7374,"question":"هل يجوز التحدث مع الخطيب يوم الجمعة إذا غلط في آية، أو أردت الاستفسار منه؟","title":"حكم التحدث مع خطيب الجمعة أثناء الخطبة لحاجة","answer":"الجواب: لا حرج، لا بأس أن يسأل الخطيب عن بعض المسائل كما فعل الصحابة مع النبي ﷺ كان يخطب يوم الجمعة، فجاءه رجل فقال: يا رسول الله هلكت الأموال، وانقطعت السبل، فادع الله أن يغيثنا، فاستغاث للمسلمين، وطلب الله أن يغيث العباد -عليه الصلاة والسلام- فأغاثهم الله، وجاءهم مرة رجل هو يخطب في الناس فقال: يا رسول الله غريب جاء يسأل عن دينه لا يدري ما دينه؟ فنزل وعلمه، ثم عاد إلى خطبته -عليه الصلاة والسلام-.  فالمقصود: أنه لا بأس أن يسأل عن شيء وهو يخطب، ولا مانع أن يرد عليه إذا غلط في الآية، ينبهه على ذلك، لا بأس.","link":"https://binbaz.org.sa/fatwas/3467/حكم-التحدث-مع-خطيب-الجمعة-اثناء-الخطبة-لحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1771.mp3","categories":["صلاة الجمعة"]},{"id":7400,"question":"تعلمون أن السجون تضم مجموعة كبيرة من الشباب، والذين أراد الله أن يدخلوا إلى هذا المكان الموحش -أعاذنا الله وإياكم من شره- ولكن المشكلة أنه يخبرني أحد الإخوة الذين دخلوا سجن العود: أنه لا تقام فيهم الصلاة، ولا يؤمر بها الشرطةُ المسجونين، كما أنها لا تقام فيهم صلاة الجمعة، مع أن عددهم كبير، ويصلي منهم ما يقارب 1%.فسؤالي: لماذا لا يؤمر بتعميم جميع سجون المملكة من قبل وزارة الداخلية بالأمر إلى الصلاة ومعاقبة من لم يصل؟","title":"حكم إقامة صلاة الجمعة في السجون","answer":"الجواب: هذا الخبر في صحته نظر، فلا يزال الدعاة يزورون السجون هنا، وفي المنطقة الغربية والشرقية، فالدعاة يتصلون بين وقت وآخر ويرشدونهم ويعلمونهم، ولن يبلغنا عنهم هذا الذي ذكره الكاتب، ولكن -إن شاء الله- ننظر في الأمر، ونتثبت في الأمر، إذا كان هناك شيء من هذا؛ فلا بد من العناية بأمر السجناء، وتوجيههم إلى الخير، لا من جهة صلاة الجماعة، ولا من جهة صلاة الجمعة إذا أمكن.  وإذا لم يمكن فهم معذورون، المسجون معذور عن صلاة الجمعة، إلا إذا تيسر إقامتها بينهم، فهذا أمر آخر قد سئل عن ذلك وقرر أهل العلم أن السجين ليس عليه جمعة إلا إذا تيسر أن يقيمها وتقام الجمعة حوله وأمكن حضوره إياها، أو تقوم في السجن وأمكن أن يحضرها، فهذا إذا أمكن ممكن، ولكن كثير من السجناء لا يمكن حضورها؛ لأنهم في محل خاص، ويخاف من تنقلهم شرًا، أو هروبًا. فالحاصل: أن هذا محل نظر في جهة الجمعة.","link":"https://binbaz.org.sa/fatwas/3506/حكم-اقامة-صلاة-الجمعة-في-السجون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1810.mp3","categories":["صلاة الجمعة"]},{"id":7403,"question":"ذكر ابن الجوزي في كتابه \"بستان الواعظين\" ما ورد في الأثر: من أنه من صام من الشهر ثلاثة أيام، وقام إحدى لياليه، وقرأ في الركعتين جميعًا: الفاتحة والإخلاص ثلاث مرات؛ كان ممن يتجاوزون الصراط يوم القيامة بسرعة فائقة، فما صحة ذلك؟","title":"ما صحة حديث: «من صام من الشهر ثلاثة أيام»؟","answer":"الجواب: لا أصل لهذا، ليس بصحيح، وإنما السنة الوتر كما فعل النبي ﷺ، والصلاة كما فعل النبي ﷺ ولا يزيد على ذلك، أما هذا الحديث الذي ذكره ابن الجوزي فليس بصحيح، أما على هذه الكيفية فلا أصل. أما صيام ثلاثة أيام من كل شهر فهي ثابتة، صيام ثلاثة أيام من كل شهر والوتر مشروع مأمور به، أما كونه يقرأ الفاتحة وسورة (قل هو الله أحد) ثلاث مرات، أو يقوم ليلة من الشهر فقط، فهذا لا أصل له، بل السنة أن يقوم جميع الليالي، ويوتر في جميع الليالي، ويقرأ الفاتحة وما تيسر معها، وليس بشرط أن يكون قل هو الله أحد ثلاث مرات، ما تيسر.  هذا الحديث بهذا اللفظ غير صحيح، ولكن المؤمن يوتر كما أمر الله، يقرأ الفاتحة وقل هو الله أحد أو سورة أخرى، ولكن الأفضل قل هو الله أحد في ركعة الوتر، وهي واحدة يختم بها صلاته، يقرأ فيها الفاتحة وقل هو الله أحد، هذا أفضل، وإن قرأ غير قل هو الله أحد؛ فلا بأس ولا حرج، يصح، ويصوم من الشهر ثلاثة أيام، وإذا كانت البيض كان أفضل، وإن صامها في غير البيض؛ فلا بأس، صامها في أول الشهر، أو في وسطه، أو في آخره؛ فلا بأس، وإن صامها مفرقة؛ فلا بأس، أو مجتمعة؛ فلا بأس، أو صامها الإثنين والخميس مفرقة؛ فلا بأس، كله طيب.","link":"https://binbaz.org.sa/fatwas/3509/ما-صحة-حديث-من-صام-من-الشهر-ثلاثة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1813.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7418,"question":"ذكر ابن الجوزي في كتابه \"بستان الواعظين\" ما ورد في الأثر: من أنه من صام من الشهر ثلاثة أيام، وقام إحدى لياليه، وقرأ في الركعتين جميعًا: الفاتحة والإخلاص ثلاث مرات؛ كان ممن يتجاوزون الصراط يوم القيامة بسرعة فائقة، فما صحة ذلك؟","title":"ما صحة حديث: «من صام من الشهر ثلاثة أيام»؟","answer":"الجواب: لا أصل لهذا، ليس بصحيح، وإنما السنة الوتر كما فعل النبي ﷺ، والصلاة كما فعل النبي ﷺ ولا يزيد على ذلك، أما هذا الحديث الذي ذكره ابن الجوزي فليس بصحيح، أما على هذه الكيفية فلا أصل. أما صيام ثلاثة أيام من كل شهر فهي ثابتة، صيام ثلاثة أيام من كل شهر والوتر مشروع مأمور به، أما كونه يقرأ الفاتحة وسورة (قل هو الله أحد) ثلاث مرات، أو يقوم ليلة من الشهر فقط، فهذا لا أصل له، بل السنة أن يقوم جميع الليالي، ويوتر في جميع الليالي، ويقرأ الفاتحة وما تيسر معها، وليس بشرط أن يكون قل هو الله أحد ثلاث مرات، ما تيسر.  هذا الحديث بهذا اللفظ غير صحيح، ولكن المؤمن يوتر كما أمر الله، يقرأ الفاتحة وقل هو الله أحد أو سورة أخرى، ولكن الأفضل قل هو الله أحد في ركعة الوتر، وهي واحدة يختم بها صلاته، يقرأ فيها الفاتحة وقل هو الله أحد، هذا أفضل، وإن قرأ غير قل هو الله أحد؛ فلا بأس ولا حرج، يصح، ويصوم من الشهر ثلاثة أيام، وإذا كانت البيض كان أفضل، وإن صامها في غير البيض؛ فلا بأس، صامها في أول الشهر، أو في وسطه، أو في آخره؛ فلا بأس، وإن صامها مفرقة؛ فلا بأس، أو مجتمعة؛ فلا بأس، أو صامها الإثنين والخميس مفرقة؛ فلا بأس، كله طيب.","link":"https://binbaz.org.sa/fatwas/3509/ما-صحة-حديث-من-صام-من-الشهر-ثلاثة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1813.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7456,"question":"حديث دخل النار رجل في ذباب هل هذا صحيح أم لا؟","title":"الحكم على حديث دخل النار رجل في ذباب","answer":"الجواب: لا بأس به، رواه أحمد بإسناد جيد، ومعناه أنه تقرب بالذباب للصنم؛ فدخل به النار -نعوذ بالله- فإذا تقرب بالذباب، أو بالدجاجة، أو بالذبيحة، أو بالدراهم إلى الأصنام، أو إلى غيرها من المعبودات من دون الله؛ صار شركًا بالله ، فهذا فيه الحذر من الشرك، وضرب به النبي ﷺ المثل ليحذر من الشرك. الله -جل وعلا- قال: فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2]، قُلْ إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لَا شَرِيكَ لَهُ [الأنعام:162، 163].  فمن قرب لغير الله وإن كان شيئًا حقيرًا؛ يكون شركًا بالله ، فيجب على المؤمن أن يطهر نفسه وعقيدته من سائر أنواع الشرك، ومنها الذبح لغير الله، وفي الحديث لعن الله من ذبح لغير الله.","link":"https://binbaz.org.sa/fatwas/30204/الحكم-على-حديث-دخل-النار-رجل-في-ذباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_794_2.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7458,"question":"هل حديث: ما من عام إلا والعام الذي بعده أشر منه إلى يوم القيامة صحيح؟","title":"درجة حديث «ما من عام إلا والذي بعده أشر منه»","answer":"الجواب:\nأما حديث لا يأتي عام إلا والذي بعده شر منه حتى تلقوا ربكم. فهو حديث صحيح، رواه البخاري في الصحيح عن أنس أن النبي ﷺ قال: لا يأتي عام إلا والذي بعده شر منه حتى تلقوا ربكم وفي لفظ آخر قال: لا يكون عام خير من عام، ولا أمير خير من أمير، ولكن ذهاب علمائكم وخياركم، ثم يحدث أقوام يقيسون الأمور بآرائهم؛ فيهدم الإسلام ويثلم.  وهذا هو الواقع، فكلما تقدم الزمان، وتأخر عهد النبوة؛ قل العلم، وكثر الجهل، كما هو الحال اليوم في القرن الخامس عشر، والرابع عشر الماضي، فإن العلم قد قل كثيرًا، والجهل قد انتشر في غالب البلدان، فقل أن تجد بلدًا فيها العلماء الذين يكفون لحاجة البلاد، ويشار إليهم بالعلم، والفضل، والاستقامة، فالمصيبة عظيمة.  ولكن ليس معناه أن الزمان دائمًا يكون شرًّا مما قبله .. لا هذا وصف أغلبي، وقد يقع في بعض الزمان في بعض الأوقات في جهة من الجهات ما يكون حال أهلها أحسن من حالهم الأولى في بعض الأحيان.  كما وقع في عهد عمر بن عبدالعزيز الخليفة الراشد، فإن المسلمين قد حصل لهم بولايته خير عظيم، وكان الحال في زمانه أحسن من حال من قبله، كزمن الوليد وأخيه سليمان، كان زمان عمر بن عبدالعزيز أحسن بكثير في إقامة العدل وتحكيم الشريعة، وهذا يدل على أن قوله ﷺ: لا يأتي عام إلا والذي بعده شر منه يعني وصف أغلبي ليس بوصف عام ليس فيه استثناء، بل وصف أغلبي.  قال بعض أهل العلم في مثل هذا: إنه بالنسبة إلى عموم الزمان لا بالنسبة إلى الأمكنة، فقد يكون مثلاً حال دمشق المدينة الرياض أهل بغداد في وقت متأخر أحسن من حالها في وقت متقدم، ولكن المراد العموم يعني عموم الدنيا، كل زمان أدنى من الذي قبله بعموم الدنيا، لكن قد يكون في بعض الأمكنة بالنسبة إلى بعض الناس حالهم أحسن من الذي قبل، كما جرى في أماكن كثيرة ظهرت فيها البدع، ثم جاء صاحب سنة فدعا إلى الله، وأقام العدل، وأقام السنة، ونهى عن البدعة؛ فصار حالهم أحسن من ذي قبل.  وكما جرى في الجزيرة العربية، فإنه حصل فيها من الشرك والبدع والخرافات في القرن الحادي عشر وما قبله شيء كثير، فجاء الله بدعوة الشيخ محمد بن عبدالوهاب -رحمة الله عليه- فدعا إلى الله في الجزيرة، وفي نفس نجد، دعا إلى الله جل وعلا وأقام السنة، ونهى عن البدعة، ونصره آل سعود؛ فصار حال نجد أحسن كثيرًا من حالها قبل ذلك؛ بسبب الدعوة الإسلامية، وبسبب إنكار البدع، والشرك، وبسبب تحكيم الشريعة، هذا أمر معلوم واضح واقع.  وهكذا في زمن شيخ الإسلام ابن تيمية في دمشق وفي مصر، وفي زمن ابن القيم وابن كثير حال زمان ذلك أحسن من الزمان الذي قبله؛ بسبب دعاة الحق، وظهور السنة وقمع البدعة. والله المستعان.","link":"https://binbaz.org.sa/fatwas/30508/درجة-حديث-ما-من-عام-الا-والذي-بعده-اشر-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_95_2.mp3","categories":["الحكم على الأحاديث","صلاة الجمعة"]},{"id":7503,"question":"هذه رسالة من المرسل: محمد مفرج الدوسري، يسأل عدة أسئلة أولها يقول: هل الجندي أثناء عمله ليس عليه جمعة ولا جماعة؟","title":"حكم ترك الجندي للجمعة والجماعة أثناء عمله","answer":"الجواب: هذا فيه تفصيل: الجندي إذا كان حارساً على شيء للدولة، كأن يكون حارساً على سجن أو حارساً على مال يخشى عليه، أو على محل من المحلات يخشى أن تنتهك، هذا ليس عليه جماعة ولا جمعة، بل يصلي فرداً، أما جنس الجندي إذا لم يكن حارساً على شيء ولا مريضاً فإن عليه مثل ما على الناس؛ عليه أن يصلي الجمعة والجماعة، هذا الإطلاق ليس له وجه، الجندي مثل غيره، إلا إذا كان هناك عذر شرعي؛ من مرض، أو خوف لو خرج إلى الجماعة أو الجمعة، أو كان حارساً على شيء يخشى عليه، كأن يكون حارساً على باب السجن، أو على أموال تحت يده يحرسها يخشى عليها، أو ما أشبه ذلك، فهذا عذر. نعم.","link":"https://binbaz.org.sa/fatwas/4464/حكم-ترك-الجندي-للجمعة-والجماعة-اثناء-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00802.mp3","categories":["صلاة الجماعة","صلاة الجمعة"]},{"id":7587,"question":"هذه الرسالة من الدمام وردت من محمد عبد الله البكري ، يقول في رسالته: إذا دخل المسلم إلى المسجد وعند وصوله إلى الصف شرع المؤذن في الأذان، فهل على المسلم أن يبدأ بأداء تحية المسجد أو ينتظر واقفاً حتى يفرغ المؤذن حتى يتابعه ويحصل على فضل المتابعة، وخاصة في الأذان الأول من يوم الجمعة حيث أنه سوف يؤدي تحية المسجد أثناء خطبة الإمام وقد يفوته بعض الخطبة، نرجو إفادتنا؛ لأن كثيراً من الناس يتشاكسون عند هذه المسألة؟","title":"أفضلية الجمع بين ترديد الأذان وصلاة تحية المسجد يوم الجمعة","answer":"الجواب: الأفضل لمن دخل المسجد وقد شرع المؤذن في الأذان أنه يقف حتى يجيب المؤذن ثم يصلي تحية المسجد، هذا هو الأفضل إذا تيسر؛ لقول النبي ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول هكذا أمر النبي عليه الصلاة والسلام، فالسنة لك يا أيها الداخل أن تقف وأن تجيب المؤذن ثم تصلي ركعتين إذا تيسر ذلك، فإن كان هذا يشق عليك لأن المؤذن يطول، أو لأنك لا تتحمل الوقوف، فابدأ بالركعتين ولا حرج والحمد لله، ثم تجيب المؤذن بعد ذلك إذا أمكنك، إذا أمكنك بأن انتهيت منها والمؤذن لا يزال يؤذن تجيب المؤذن والحمد لله، أما أن تجلس فلا، لا ينبغي لك الجلوس حتى تؤدي الركعتين، إما بعد الفراغ من الأذان حتى تجمع بين المصلحتين والفضيلتين، وإما أن تبدأ بالركعتين وتترك الاستجابة للمؤذن ولا حرج عليك في ذلك، لكن كونك تجمع بين مصلحتين وتتحمل الوقوف حتى تجمع بين إجابة المؤذن وبين صلاة ركعتين، هذا هو الأفضل لك وهو الأحسن إذا تيسر ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4640/افضلية-الجمع-بين-ترديد-الاذان-وصلاة-تحية-المسجد-يوم-الجمعة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_019/01905.mp3","categories":["صلاة الجمعة"]},{"id":7660,"question":"هذه الرسالة مقدمة من عبد الله بن حمود فهيد القحطاني من العود يقول: فضيلة الشيخ عبد العزيز بن عبد الله بن باز الموقر، بعد التحية والاحترام أرجو إفتائي على سؤالي هذا: أسأل أنني أصلي بجماعة صلاة الجمعة، بحيث أنني تقدمت بالصلاة بهم وقرأت الخطبة، حيث أنه لا يوجد لدى الجماعة المذكورون في سؤالي هذا وهم من أهالي القرية، وإنني يا فضيلة الشيخ! لا أريد معاش على ذلك، وإنما أسأل: هل علي ذنب من تقدمي للصلاة بهم بحيث أنهم قدموني لأخطب بهم وأصلي بهم، والله يحفظكم وجزاكم الله خير الجزاء؟","title":"حكم من تقدم للخطابة والإمامة يوم الجمعة لعدم وجود الإمام","answer":"الجواب: لا حرج في هذا، أنت محسن، إذا تقدم الإنسان بإخوانه، قدمه إخوانه يصلي بهم لأن إمامهم غير حاضر، أو لأن إمامهم توفي أو مستقيل ولم يرسل إليهم إمام وخطيب فقدموا أحدهم وصلى بهم فلا حرج في ذلك، إذا كان أهلاً للإمامة وأهلاً للخطبة فلا بأس، وهو مشكور ومأجور، وليس من شرط ذلك أن يعطى راتباً أو يعين من جهة الحكومة، وإنما الراتب للمساعدة، ليس بشرط، وإنما تبذل الحكومة الرواتب للأئمة والخطباء لمساعدتهم وإعانتهم على هذا الأمر العظيم وعلى هذا المشروع الجليل، فإذا احتسب بعض الجماعة وصلى بجماعته الجمعة أو الأوقات ابتغاء ما عند الله عز وجل فله أجره عند الله سبحانه وتعالى، ولا حرج عليه. نعم.\nالمقدم: أنا أعتقد أن السائل عبد الله القحطاني من العود، حينما سأل هذا السؤال أنه يعتقد أنه لا بد أن هناك مثل أمر يصدر من الحج والعمرة؟\nالشيخ: لا ما هو بشرط، ما هو بشرط، ما هو بشرط، هذا في التوظيف يعني الذي يستحق صاحبه الراتب هذا يكون من جهة المسئولين، أما كونه يتبرع إنسان ويصلي بجماعة ما حضر إمامهم ولا حضر خطيبهم سواء كان في وقت معين أو في أوقات متعددة فلا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4806/حكم-من-تقدم-للخطابة-والامامة-يوم-الجمعة-لعدم-وجود-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_037/03702.mp3","categories":["صلاة الجمعة"]},{"id":7669,"question":"هذه رسالة وردت من المرسل الأخ زيدان خلف من بغداد من العراق يقول: أشكر المجيبين على أسئلة المستمعين في برنامجكم نور على الدرب، وأفيدكم أني أبلغ من العمر ستة عشر سنة، وأخذت أصلي من يوم اثنين وعشرين أربعة تسعة وسبعين وإلى حد الآن لم أعرف، ولم أصل صلاة الجمعة لأنني لا أعرفها، فما يقول فضيلة الشيخ أرجو الإفادة وفقكم الله؟","title":"ما حكم ترك صلاة الجمعة؟","answer":"الجواب: على السائل أن يتوب إلى الله عز وجل، وأن ينيب إليه، وأن يبادر بصلاة الجمعة مع الناس، ونسأل الله أن يمن عليه بالعفو عما مضى، وعليه البدار بالتوبة، والإقلاع عما مضى من تركه للجمعة، وأن يحرص على حضورها كلما جاء وقتها مع المسلمين.\nونسأل الله جل وعلا أن يعفو عما سلف، وعليه التوبة الصادقة، والندم على ما مضى منه، والعزم أن لا يعود في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4866/ما-حكم-ترك-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_039/03902.mp3","categories":["صلاة الجمعة"]},{"id":7757,"question":"يقول المستمع محمد عبده: ما حكم الذي يقطع الجمعة ثلاث أو فترة كبيرة ولم يذهب، علماً بأني أشتغل حارس في محل بعيد عن المدينة، ولم يسمح لي صاحب العمل للذهاب من هذا المكان؟","title":"حكم من ترك الجمعة مرات متعددة لأجل الحراسة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفالصلوات الخمس فرض على المسلمين، وهي عمود الإسلام كما في الحديث الصحيح عن النبي ﷺ أنه قال بني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمداً رسول الله، وإقام الصلاة، وإيتاء الزكاة،، وصوم رمضان، وحج البيت وصلاة الجمعة إحدى الخمس في يوم الجمعة وهي فرض عظيم، وهي فرض الوقت، وقد جاء فيها نصوص خاصة، فتركها أعظم من ترك سواها من الصلوات، فالواجب على من تركها المبادرة بالتوبة إلى الله والرجوع إليه سبحانه وتعالى، والندم على ما مضى، والعزم ألا يعود، وقد جاء عنه ﷺ أنه قال: لينتهين أقوام عن ودعهم الجمعات يعني: عن تركهم الجمعات أو ليختمن الله على قلوبهم، ثم ليكونن من الغافلين، وهذا وعيد عظيم، أن ترك الجمعة من أسباب الختم على القلب والطبع عليه وأن يكون صاحبه من الغافلين نعوذ بالله، وجاء عنه عليه الصلاة والسلام أنه قال: من ترك صلاة الجمعة ثلاث مرار بغير عذر طبع على قلبه فالحاصل أن ترك الجمعة من أعظم أسباب الطبع على القلب والختم عليه؛ فيجب على المؤمن أن يبادر بالتوبة، إذا ترك ذلك أن يبادر بالتوبة والندم والإقلاع، والجمهور على أنه يقضي بدلها ظهراً، ولكن ذهب بعض أهل العلم إلى أن تركها كفر وردة عن الإسلام، وهكذا بقية الصلوات، إذا تركها حتى خرج الوقت والعياذ بالله كفر بذلك لقول النبي عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر فالأمر عظيم وخطير، فالواجب عليه البدار بالتوبة والحذر من العود إلى مثل ذلك والاستكثار من العمل الصالح لعل الله أن يتوب عليه سبحانه وتعالى، قال عز وجل: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] وإذا قضى كما قال الجمهور قضاها ظهراً فلا بأس، ولكن لا يلزمه على الصحيح؛ لأن الكافر لا يقضي، وإنما الواجب عليه التوبة، وترك الصلاة كفر، ترك الصلاة عمداً كفر، فالواجب على من ترك ذلك أن يبادر بالتوبة، ولا يلزمه القضاء في أصح قولي العلماء. نعم.","link":"https://binbaz.org.sa/fatwas/4954/حكم-من-ترك-الجمعة-مرات-متعددة-لاجل-الحراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_044/04401.mp3","categories":["صلاة الجمعة"]},{"id":7916,"question":"أيضاً يقول: من تكلم والإمام يخطب أو قال للذي بجانبه: اسكت. فقد لغى، فإذا أنا بجوار واحد وعطس وحمد الله، فقلت له: يرحمك الله، فهل لغيت، وإذا كنت قد لغيت فماذا يجب علي، علماً قلت له والإمام يخطب؟","title":"حكم الكلام أثناء خطبة الجمعة","answer":"الجواب: لا يجوز الكلام والإمام يخطب مع الناس، لا مع العاطس ولا مع غيره، الواجب الإنصات لسماع الخطيب، إلا مع الخطيب لا بأس، إذا أراد أن يسأل الخطيب عن شيء، أو ينكر عليه شيئاً أخطأ فيه يجب إنكاره، فالكلام مع الخطيب لا بأس، والخطيب لا بأس يتكلم هو؛ لأن هذا من جنس خطبته، أما الناس فيما بينهم فلا. حتى ولو عطس وحمد الله، لا تقول: يرحمك الله، كما لا تقوله في الصلاة، إذا عطس وهو يصلي وحمد الله ما يقال: يرحمك الله، هكذا في الخطبة المستمع لها كالمصلي فلا يتكلم، ولا يرد السلام، ولا يبدأ بالسلام، ولا يشمت العاطس، هذا هو الواجب عليه؛ لقول النبي ﷺ: إذا قلت لصاحبك: (أنصت) يوم الجمعة والإمام يخطب فقد لغوت مع أنه أمره بالمعروف، سماه لاغياً وهو آمر بالمعروف.\nوفي الحديث الآخر: من تكلم يوم الجمعة والإمام يخطب فهو كمثل الحمار يحمل أسفاراً، والذي يقول له: أنصت، ليست له جمعة، هذا يدل على أن الجمعة تلغو ويفوته ثوابها بسبب كلامه حال الخطبة، ولو أن كلامه في أمر طيب، في أمر بمعروف، أو نهي عن منكر، أو تشميت عاطس، فالواجب ترك ذلك، كما يجب ترك ذلك مع المصلي، فهكذا مع المستمع للخطبة، فلا ترد السلام على المصلي بالكلام ولا تبدؤه. البدء لا بأس تبدأ المصلي وهو يرد بالإشارة، لكن في الخطبة لا. أنت مأمور بالإنصات، فتنصت ولا تتكلم والإمام يخطب، لا بتشميت عاطس ولا برد سلام.\nوهكذا أخوك الذي في الصف لا يتكلم، وإذا حمد الله في نفسه فأنت لا تقول: يرحمك الله والإمام يخطب؛ امتثال لأمر النبي ﷺ فيما أمر به من الإنصات، وحذراً من الوعيد الذي جاء فيه ذلك وهو إلغاء الجمعة وعدم حصول ثوابها.\nالملقي: شكراً أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5415/حكم-الكلام-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_063/06305.mp3","categories":["صلاة الجمعة"]},{"id":7933,"question":"الرسالة الأخيرة التي بين يدينا في هذا اللقاء وردتنا من الجمهورية العربية السورية يقول مرسلها صالح سعيد سويد من سوريا، لديه مجموعة أسئلة أو لديه سؤلان، يقول السؤال الأول: هل تنوب صلاة الجمعة عن صلاة الظهر، أرجو توضيح ذلك على كافة المذاهب؟","title":"إجزاء صلاة الجمعة عن صلاة الظهر","answer":"الجواب: نعم، إذا صلى الجمعة كفت عن صلاة الظهر عند جميع أهل العلم، إذا صلى جمعة على الوجه الشرعي الذي شرعه الله فإنها تجزي عن صلاة الظهر، في قول آخر لبعض العلماء أنه إذا كان في البلد عدة جوامع فإنه يصلي الظهر بعد الجمعة احتياطاًً؛ لأنه يخشى أن تكون بعض الجمعات لم تصح بسبب أنها صليت من دون عذر في التعدد، وهذا قول ليس بشيء ولا ينبغي أن يعول عليه، متى تعددت الجمع في البلد للحاجة إليها فإن كل جمعة مجزئة لمن صلى، فإذا كان في البلد أربعة جوامع خمسة جوامع كلها مجزئة عن صلاة الظهر والحمد لله، ولا ينبغي أن يصلى بعدها ظهرا، كما يفعل بعض الناس في بعض البلدان، يصلي الظهر بعد الجمعة احتياطاً، هذه بدعة لا وجه لها ولا أصل لها، فمن صلى جمعة كفته والحمد لله، فالله فرض علينا خمس صلوات ما هي بست، فمن صلى الظهر بعد الجمعة أتى بست صلوات وهذا منكر، الله إنما فرض على العباد خمس صلوات في اليوم والليلة خمس، والخامسة صلاة الجمعة في يوم الجمعة، فمن أتى بالظهر بعدها فقد أتى بسادسة، وهذا لا يجوز وهذا بدعة، فالجمعة كافية بحمد الله، إذا صلى الجمعة كفت والحمد لله. نعم.\nالمقدم: أحسنتم أثابكم الله، هو في الحقيقة جعل ذيل للسؤال ولكنكم أجبتم عنه؛ لأنه يقول ما التعلل الذي يتعلل به من يصلون الظهر بعد الجمعة وقد ذكرتم ذلك.\nالشيخ: نعم، نعم.","link":"https://binbaz.org.sa/fatwas/5459/اجزاء-صلاة-الجمعة-عن-صلاة-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_066/06607.mp3","categories":["صلاة الجمعة"]},{"id":7962,"question":"بعث بهذه الرسالة يقول من السودان تأتيكم رسالة الأخت حرم يوسف محمد يوسف من قرية الشليخة بالجزيرة الطالبة بمدرسة تقول: السؤال الأول: إذا كان ينبغي للمرأة الصلاة مع الجماعة، فكيف لا تجب عليها صلاة الجمعة؟","title":"حضور المرأة للجمعة والجماعة","answer":"الجواب: المرأة الأفضل لها صلاتها في بيتها، لا يشرع لها صلاة الجماعة، لكن إن صلت مع الجماعة فلا بأس ولا يمنعها زوجها من الجماعة إذا خرجت متسترة بدون طيب ولا فتنة فلا بأس، ولكن بيتها هو خير لها في الجمعة وغيرها بيت المرأة خير لها صلاة الجمعة والجماعة جميعاً، لكن لو صلت مع الناس أجزأها ذلك بشرط أن تخرج تفلة غير متزينة ولا متطيبة طيباً يفتن الناس ويطلع عليه الناس. نعم.","link":"https://binbaz.org.sa/fatwas/5505/حضور-المراة-للجمعة-والجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_069/06910.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":7964,"question":"أيضاً تقول: إذا توفر في المرأة شروط الإمام فهل ينبغي لها أن تصلي بالنساء في جماعة أم لا؟","title":"حكم إمامة المرأة للنساء في الصلاة","answer":"الجواب: إن صلت بهن فهو أفضل في بيتها، صلت بهن في بيتها جماعة فهو أفضل ولكن لا يجب؛ لأن الجماعة غير واجبة في حق النساء، لكن لو صلت بهن جماعة للتعليم والتوجيه هذا طيب، وقد روي عن أم سلمة و عائشة أنهما صلتا ببعض النساء جماعة، فهذا من باب التعليم والتوجيه إلى الخير ولكن لا يجب.\nالمقدم: أيضاً تقول: لكن قبل أن نمضي عن سؤالها هذا، هل تتقدم في الجماعة؟\nالشيخ: تصلي في وسطهن.\nالمقدم: في وسطهن؟\nالشيخ: في وسطهن نعم.","link":"https://binbaz.org.sa/fatwas/5506/حكم-امامة-المراة-للنساء-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_069/06911.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":7994,"question":"طيب بالنسبة لهذه المناسبة القراءة في المسجد هناك في بعض الدول الإسلامية في يوم الجمعة يقوم شخص على مكان مرتفع ويقرأ القرآن بتجويد والآخرين ينصتون إليه ولا يقرءون، فهل هذا مسنون أم لا؟","title":"حكم قراءة القرآن بصوت مرتفع يوم الجمعة","answer":"الجواب: ما نعلم له أصل، هذا أشبه بالبدع، أقول: هذا أشبه بالبدع، أقول هذا غير مشروع فيما نعلم؛ لأن هذا يمنع الناس من القراءة قد يريد بعض الناس يقرأ قد يريد يصلي يشوش عليه إذا دخل يصلي ركعتين أو أكثر، فالأولى أن كل إنسان يقرأ لنفسه، أما لو كانوا في مكان مخصوص مجتمعين مثلما كان النبي صلى الله عليه وسلم يقرأ عليهم وهم يستمعون له فلا بأس، أو كانت جماعة محدودة في المسجد وأحبوا أنهم يستمعون له حتى يدخل الخطيب فلا بأس، أما واحد يقوم على المنبر يقرأ على الناس فهذا لا وجه ولا ينبغي.\nأو في غير المنبر ... يجهر جهراً يضر غيره، ويشوش على المصلين الداخلين وعلى القراء كل هذا لا يصلح، وليس له أصل فيما نعلم. نعم.","link":"https://binbaz.org.sa/fatwas/5562/حكم-قراءة-القران-بصوت-مرتفع-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_074/07405.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":8103,"question":"رسالة وصلت إلى البرنامج من شبرا باعثها أخونا (م. ق. أ. الغامدي ) كما يقول، أخونا يقول: لدينا مدرس مصري الجنسية متعلم ومثقف حسب ما نعرف في الدين ولا يفارق المسجد وقت الصلوات ولكن إذا صلى صلاة الجمعة معنا قام وصلى أربع ركعات معاً بدون تسليم بينها وصلى بعدها ركعتين، فهل هذه الصلاة صحيحة أم لا؟","title":"حكم من يداوم على أربع ركعات بسلام واحد عقب الجمعة","answer":"الجواب: هذا فيه تفصيل: إن كان قصده أن يصلي الظهر احتياطاً وأن الجمعة يرى أنها لا تكفيه كما يفعله كثير من الناس في بلدان كثيرة ويقولون: إن البلد إذا كان فيه جمعات يخشى أن لا يصح بعضها، فلهذا يصلون الظهر احتياطاً مع الجمعة، هذه بدعة ولا تجوز وعليه التوبة إلى الله من ذلك.\nوهكذا جميع من يتعاطى هذا الأمر ممن يصلي الظهر بعد الجمعة، هذا كله غلط وبدعة، فالواجب عليهم التوبة إلى الله من ذلك، ومتى وجدت أسباب إقامة جمعة ثانية وثالثة ورابعة في البلد الواسعة والمتباعدة فلا حرج في ذلك، ولا بأس.\nفيجوز أن تقام جمعتان أو أكثر في البلد الواحدة إذا كانت واسعة الأرجاء متباعدة أو كان المسجد ضاق بأهله واحتاجوا إلى مسجد ثاني، أو كانت مسجدان، كانا مسجدان فضاقا واحتاج المسلمون إلى ثالث في المدينة، كل هذا لا بأس به، ومتى وجد المسوغ لتعدد الجمعة فلا وجه لصلاة الظهر بل هذا من البدع ومن التنطع والغلو في الدين الذي لا وجه له.\nأما إن كان قصده إن هذه راتبة كما جاء في الحديث عنه عليه السلام أنه قال: إذا صلى أحدكم الجمعة فليصل بعدها أربعاً، فهذا لا بأس به، لكن الأفضل أن يصليها ثنتين ثنتين، هذا هو الأفضل لا يسردها أربع، يقول النبي صلى الله عليه وسلم: صلاة الليل مثنى مثنى، وفي اللفظ الآخر: صلاة الليل والنهار مثنى مثنى، فالأفضل أنه يصلي ثنتين ثنتين أربعاً بعد الجمعة، وإن صلى في بيته ثنتين بعد الجمعة كفى ذلك وإن صلى أربعاً فهو أفضل، أما الثنتان الأخريان فلا أعلم لهما وجهاً إلا أنه جاء عن ابن عمر رضي الله تعالى عنهما أنه كان في مكة يصلي بعد الجمعة أربعاً ثم ثنتين، فلعل هذا سمع خبر ابن عمر فصلى هذا؛ لأن ابن عمر ذكر ذلك عن النبي صلى الله عليه وسلم، فلا نعلم أسباب ذلك، وإذا فعله من أجل حديث ابن عمر الذي سمعه فلا بأس بذلك.\nأما المحفوظ الذي نعرفه من السنة، فهو أنه يصلي أربعاً بعد الجمعة في المسجد أو في بيته وإذا اكتفى بثنتين في بيته كما كان النبي صلى الله عليه وسلم يفعل فلا بأس بذلك، وإن كان هذا الرجل صلاها من أجل أنه سمع عن ابن عمر أنه فيه أربعاً وثنتين فلا حرج في ذلك، لكن الأفضل أنه يصلي ثنتين ثنتين كل ثنتين بسلام لا يسرد الأربع.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/5899/حكم-من-يداوم-على-اربع-ركعات-بسلام-واحد-عقب-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_101/10106.mp3","categories":["صلاة الجمعة"]},{"id":8123,"question":"كثيرون سماحة الشيخ هم الذين يسألون عن إعادة صلاة الظهر بعد صلاة الجمعة ومن بينهم صاحب هذه الرسالة يقول: ما حكم إعادة صلاة الظهر بعد صلاة الجمعة هل هي واجبة أم مندوبة، لأنه عندنا الإمام يقوم بإعادة صلاة الظهر بعد صلاة الجمعة ويقول: خوفًا من قبول صلاة الجمعة وذلك لعدم توفر جميع أركان الجمعة، أفيدونا أفادكم الله؟","title":"حكم إعادة صلاة الظهر عقب صلاة الجمعة","answer":"الجواب: إعادة صلاة الظهر بعد صلاة الجمعة أمر محدث لم يكن في عهد أصحاب النبي ﷺ ولا في عهد التابعين لهم بإحسان، والجمعة تكفي عن الظهر وهي فرض الوقت، فلا يجوز أن يجمع بينهما، الله فرض علينا خمس صلوات في يوم الجمعة وفي غير يوم الجمعة، في يوم الجمعة خمس: الفجر والجمعة والمغرب والعشاء، هذه خمس، الفجر والجمعة والعصر والمغرب والعشاء خمس فروض، فإذا صلى ظهراً بعد الجمعة فقد زاد سادسة، فلا وجه لذلك فهي بدعة، ونرجو ممن يتعاطى هذا من أهل العلم أن يعيدوا النظر وأن يتبصروا في الأدلة ومتى أعادوا النظر وفقهم الله للبصيرة في هذا، أرجو من إخواني أهل العلم الذين يفعلونها أن يعيدوا النظر، الرسول عليه السلام يقول: من عمل عملاً ليس عليه أمرنا فهو رد يعني: فهو مردود، ويقول عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد متفق على صحته من حديث عائشة رضي الله عنها.\nفالواجب على أهل العلم الذين يعيدونها أن يتقوا الله وأن يتركوا هذه الإعادة فإنها بدعة لا وجه لها، ومتى صليت الجمعة أجزأت عن الظهر، وإذا كان عندهم شك في الجمعات ولهم النظر في الموضوع ليس إلى غيرهم فلينظروا، فالجمعة التي لا حاجة إليها تلغى، والجمعة التي لها حاجة تبقى، أما مجرد الظنون والشكوك والأوهام فلا وجه لها، الأصل أن هذه الجمعة إنما أقيمت للحاجة إليها، إما للتباعد وإما لكون الجمعة الموجودة أو إما لكون المسجد الموجود يضيق بالناس ولا يسعهم أو لأسباب أخرى اقتضاها الشرع.\nفالأصل أن هذه الجمعات مجزئة هذا هو الأصل فلا يجوز ظن السوء وحمل الناس على أنهم صلوا جمعة غير صحيحة؛ هذا سوء ظن لا وجه له بل يجب حمل الناس على أحسن المحامل وأن هذه الجمعة إنما أقيمت للحاجة إليها فلا حاجة إلى صلاة الظهر بعدها، والرسول ﷺ قال في الحديث الصحيح: وشر الأمور محدثاتها وكل بدعة ضلالة يقول ﷺ: (أما بعد) -يقول في خطبة الجمعة كما روى مسلم في الصحيح- أما بعد: فإن خير الحديث كتاب الله وخير الهدي هدي محمد ﷺ وشر الأمور محدثاتها وكل بدعة ضلالة، فليس للعالم ولا لغير العالم أن يحدث في دين الله ما ليس منه، ولكن الخطر على العالم أكثر لأنه يقتدى به، والواجب أن ينظر وأن يتأمل حتى يحكم فيما فعل على بصيرة ولا شك أن هذه بدعة لا وجه لها، فالواجب تركها على العالم وغير العالم. نعم.\nالمقدم: جزاكم الله خيراً، من أين تسرب هذا الشك سماحة الشيخ؟\nالشيخ: لأنه هناك خلاف بين العلماء في إقامة الجمعة الثانية والثالثة والرابعة، بعض أهل العلم يقول: لابد في المدينة من جمعة واحدة ولا حاجة إلى جمعات وهذا قول خاطئ؛ لأن المدن تختلف فليس كل مدينة يكفيها جمعة واحدة، بعض المدن بين أطرافها مسافات طويلة والمسجد لا يسع من حوله من الناس ولا يسع من بعد عنه ولا يستطيعون المجيء إليه، فلهذا قرر العلماء رحمة الله عليهم إقامة جمعات في بلاد واحدة، اتسعت البلد وتباعدت أطرافها وكثر سكانها يكون في كل حي منها جمعة يكفي أهله، هذا هو الواجب وهذا الذي قد تقرر عند أهل العلم، فإذا وجدت الأسباب كالتباعد أو ضيق المسجد أو صارت البلد فيها قبيلتان أو قبائل بينهم تشاحن ما يستطيعون أن يجتمعوا في مسجد واحد يخشى أن يقع بينهم فتنة جعل لكل قبيلة مسجد يخصهم دفعاً للفتن، هذا كله من الأسباب. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/5919/حكم-اعادة-صلاة-الظهر-عقب-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_103/10304.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":8126,"question":"سماحة الشيخ إذا لوحظ على خطبة الجمعة أنها لم تؤد وظيفتها التي كانت معروفة من ذي قبل، وإنما تحولت الخطب إلى أشياء وأشياء لا تمت إلى حاجة الناس الحقيقية بصلة؟","title":"اهتمام خطيب الجمعة بقضايا المجتمع","answer":"الجواب: ينصحون، ينصح القائمون عليها الخطباء يوجهون من أهل العلم ومن المسئولين عن الجمعة حتى يخطبوا خطباً تفيد المجتمع فيما يتعلق بوعظهم وتذكيرهم وتنبيههم على ما قد يقع من الأمور المنكرة في المجتمع الذي هم فيه هكذا ينبهون.\nالمقدم: لكن إذا كانوا محمولين على نوعية معينة من الخطب؟\nالشيخ: لابد أن يعالجوا الموضوع حتى مع من حملهم، لابد أن يعالجوا الموضوع لأنه في الغالب لا تخلو من وعظ حتى ولو حملوا، لا تخلو من وعظ يحصل به -إن شاء الله- الإجزاء، لكن المطلوب أن يتحروا حاجة المجتمع وما يقع فيه من شرور حتى ينبهوا المجتمع على ما قد يقع فيه من أخطاء ليستقيم وينتبه فيؤدي ما أوجب الله ويدع ما حرم الله.\nفإذا كان الخطباء قد عين لهم أشياء فينبغي أن يدرسوها مع المسئولين وأن يقترحوا ما يرونه أصلح وأنفع، والغالب أنما يعين لهم الذي يجزي؛ لأنه لا يخلو من وعظ وتذكير إما بالجنة أو بالنار أو بيوم القيامة أو بما يرضي الله من الأعمال الصالحات كالمحافظة على الصلوات، وكأداء الزكاة، وكصوم رمضان، وما أشبه ذلك مما يحصل به التذكير، لكن المطلوب من الخطباء فوق ذلك أن يجمعوا بين هذا وبين غيره مما يحتاجه المجتمع. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/5922/اهتمام-خطيب-الجمعة-بقضايا-المجتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_103/10305.mp3","categories":["صلاة الجمعة"]},{"id":8199,"question":"نبدأ برسالة الأخ لطفي يقول لطفي محمد حسين اليماني في رسالته: يوجد مسجد تقام فيه صلاة الجمعة والجماعة، وصار الآن ضيق على المصلين، وخاصة يوم الجمعة وبني مسجد حديث أكبر من الأول، فإذا أقيمت صلاة الجمعة في المسجد الحديث، هل جائز أم لا، للعلم أن القرية الصغيرة لا تقام فيها جماعتين يوم الجمعة؟","title":"حكم صلاة الجمعة في المسجد الجديد لضيق القديم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله نبينا محمد، وعلى آله وأصحابه وأتباعه بإحسان إلى يوم الدين.\nأما بعد:\nفيقول السائل: إن القرية التي هو فيها، فيها مسجد صغير يضيق بالناس في الجمعة، وقد بني مسجد واسع، فهل تنقل الصلاة إلى المسجد الواسع، هذا يرجع إلى أهل البلد، فعليك أن تراجع أهل البلد، وتراجع فضيلة قاضي البلد، وهو ينظر في الموضوع، فإن كان المسجد الأول لا يسع الناس، انتقل إلى المسجد الثاني وصلي فيه، ولا يصلى جمعتين من دون مسوغ شرعي، ولكن بكل حال، هذا يرجع إلى فضيلة قاضي البلد وأعيانها، ينظروا في الموضوع، وفيهم إن شاء الله الكفاية. نعم.","link":"https://binbaz.org.sa/fatwas/6007/حكم-صلاة-الجمعة-في-المسجد-الجديد-لضيق-القديم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_094/09401.mp3","categories":["صلاة الجمعة"]},{"id":8339,"question":"سماحة الشيخ! وردت بعض الأمور بودي أن نستفسر عنها لو تكرمتم حتى لا يكون هناك إشكال متوقع، بالنسبة للجمعة والمرأة سماحة الشيخ إذا صلتها في بيتها؟","title":"حكم الجمعة والجماعة للمرأة","answer":"الجواب: الجمعة ليست واجبة على المرأة، بل هي على الرجال، وهكذا الجماعة ليست واجبة على المرأة بل هي على الرجال، والسنة للمرأة أن تصلي في بيتها الجمعة وغير الجمعة، ..... في بيتها أفضل لها، لكن إن صلت مع الناس أجزأتها الجمعة عن الظهر، إذا كانت متسترة متحفظة متحجبة، وتخرج من غير طيب فهذا لا بأس عليها، من أجل سماع الفائدة سماع الخطبة سماع المواعظ لا بأس، لكن تكون حريصةً على الحجاب والستر والبعد عن الفتنة، وتكون في طريقها غير متطيبة، تخرج بدون طيب متحجبةً متسترة وتصلي مع الناس، كما كان بعض النساء في عهد النبي ﷺ يصلين مع الرسول ﷺ، ولكنه قال: وليخرجن تفلات يعني: بدون رائحة طيبة؛ لئلا تفتن الناس، ويكن غير متجملات في الخروج؛ لئلا يفتن الناس أيضاً، وقال ﷺ: وبيوتهن خير لهن وبيوتهن أفضل في الفرض والنفل في جميع الأحوال، لكن لو صلت مع الجماعة مع الستر والحجاب والعناية والبعد عن أسباب الشر، وعن الرائحة الطيبة الطيب فلا بأس بذلك، وهكذا بقية الأوقات الظهر والعصر والمغرب والعشاء والفجر لو صلت مع الناس بهذا الشرط، بشرط العناية بالستر والحجاب وعدم الطيب فلا بأس بذلك، ولكن مع هذا كله بيتها أفضل لها وأبعد لها عن الفتنة، والله ولي التوفيق.\nالمقدم: جزاكم الله خيراً، إذاً أفهم مما تفضلتم به سماحة الشيخ أن المرأة لا جمعة عليها؟\nالشيخ: ليس عليها جمعة تصليها في بيتها، لكن إذا صلت مع الناس الجمعة أجزأتها وكفتها، كالمريض ليس عليه جمعة، ومع هذا لو صلى مع الناس أجزأته الجمعة، وكالعبد المملوك ليس عليه جمعة وإذا صلى مع الناس أجزأته نعم.\nوهكذا المسافر لو صلى مع الناس الجمعة أجزأته عن الظهر هو ما عليه جمعة المسافر، لو مر بلداً وهو مسافر وصلى معهم الجمعة أجزأته عن الظهر نعم.\nالمقدم: أختنا سماحة الشيخ تلفت النظر في مقدمة رسالتها حيث تقول: حيث لم نجد أحداً يخبرنا ويهدينا إلى الصواب، ويبدو لي أن لسماحة الشيخ وقفة عند هذا، بلد بأكمله لا يوجد فيه من يخبر أهله عن شيء من أمور دينهم، لا بد لسماحة الشيخ أن يقول شيئاً؟\nالشيخ: هذا حسب علمها، قالت فيه على حسب ...، والذي نعتقده أنه يوجد في بغداد من الأخيار ومن طلبة العلم من يعلم هذا، ويستطيع أن يوجه الناس إلى الصلاة الشرعية والوضوء الشرعي وغير هذا، نعتقد أن في بغداد من الأخيار إن شاء الله من يقوم بهذا، لكن لم يكن عندها وحولها في حارتها وحيها من يعلمها هذا، هذا هو المظنون بها والمعتقد أنها تريد من حولها في حيها وحارتها ومن يتصل بها. نعم.","link":"https://binbaz.org.sa/fatwas/6155/حكم-الجمعة-والجماعة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_112/11202.mp3","categories":["صلاة الجماعة","صلاة الجمعة"]},{"id":8354,"question":"ما حكم صلاة الجمعة إذا صادفت يوم العيد؟ هل تجب إقامتها على جميع المسلمين، أم على فئةٍ معينة، ذلك أن بعض الناس يعتقد أنه إذا صادف العيد الجمعة، فلا جمعة إذاً؟","title":"حكم إقامة الجمعة يوم العيد","answer":"الجواب: الواجب على إمام الجمعة وخطيبها أن يقيم الجمعة، وأن يحضر في المسجد ويصلي بمن حضر، كان النبي يقيمها ﷺ في يوم العيد، يصلي العيد ويصلي الجمعة عليه الصلاة والسلام، وربما قرأ في العيد وفي الجمعة جميعاً بسبح والغاشية، فيهما جميعاً، كما قاله النعمان بن بشير رضي الله عنهما فيما ثبت عنه في الصحيح، لكن من حضرها من الناس حضر العيد، ساغ له ترك الجمعة وأن يصلي ظهراً في بيته أو مع بعض إخوانه إذا كان حضر العيد، وإن صلى الجمعة مع الناس كان أفضل وأكمل، وإن ترك صلاة الجمعة لأنه حضر العيد وصلى العيد فلا حرج عليه، لكن عليه أن يصلي ظهراً، فرداً أو جماعة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6203/حكم-اقامة-الجمعة-يوم-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11311.mp3","categories":["صلاة الجمعة"]},{"id":8456,"question":"رسالة وصلت إلى البرنامج من اليمن، باعثها أحد الإخوة يقول -حاتم سيف غالب من اليمن-: نحن نسكن في قرية لا يوجد بها مسجد، فهل يجب علينا الذهاب إلى مسجد في قرية تبعد عنا مسافة اثنين كيلو متر لصلاة الجمعة، وهل تجب على من يجد صعوبة في الوصول إلى المسجد الموجود في تلك القرية، حيث أن الطريق جبلي ووعر، وما حكم من يصليها ظهراً في منزله؟","title":"حكم صلاة الجمعة إذا كان المسجد في قرية بعيدة","answer":"الجواب: هذا فيه تفصيل: إذا كان المسجد بعيداً لا يسمعون النداء، كما ذكره السائل إذا كانوا لا يسمعون النداء ويشق عليهم الذهاب إلى المسجد لم يلزمهم ذلك، وعليهم أن يصلوا ظهراً في محلهم إن لم يتيسر لهم إقامة الجمعة، فإن تيسر لهم إقامة الجمعة أقاموها، فيقيموا الجمعة عندهم في محلهم في قريتهم ولا حاجة إلى ذهابهم إلى القرية الأخرى، إذا كانوا ثلاثة أو أكثر وجب عليهم في أصح أقوال أهل العلم أن يقيموا الجمعة وليس من شرطها أربعون على الصحيح، هذا قول ضعيف فإذا وجد في القرية ثلاثة أو أربعة أو خمسة أو عشرة أقاموا الجمعة، وخطب بهم أحدهم وصلى بهم وخطب بما تيسر مما فيه عظة وذكرى للحاضرين والحمد لله، يحمد الله ويصلي على النبي صلى الله عليه وسلم ويتشهد الشهادتين ويعظ إخوانه ويذكرهم بما تيسر، ثم يجلس ثم يقوم فيخطب الثانية ويذكر إخوانه مثلما فعل في الأولى، ثم يصلي بهم ركعتين يجهر فيهما بالقراءة كما هو معلوم، ولا يلزمهم الذهاب إلى المسجد البعيد فإن الكيلوين فيهما بعد ومشقة، ولا سيما إذا كانت الأرض فيها وعورة جبلية.\nفالمقصود أنهم يقيموا الجمعة في محلهم ويكفي، أما إذا تيسر لهم أن يذهبوا مع إخوانهم ويكثروا جمعهم، ولا مشقة عليهم فذهابهم مع إخوانهم هناك وصلاتهم معهم أفضل، كلما كثرت الجماعة وكلما تجمع المسلمون كان خيراً لهم وأفضل، ولكن لا يلزمهم والحال ما ذكر، فلهم أن يقيموا الجمعة في محلهم ويصلوا في محلهم والحمد لله.","link":"https://binbaz.org.sa/fatwas/6462/حكم-صلاة-الجمعة-اذا-كان-المسجد-في-قرية-بعيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12303.mp3","categories":["صلاة الجمعة"]},{"id":8549,"question":"له سؤال ثالث يقول: أرى كثيراً من المزارعين -هداهم الله- يتركون عمالهم في مزارعهم ويذهبون لصلاة يوم الجمعة، فهل عليهم إثم مع العلم أنهم يقولون أو يحتجون بأن هؤلاء العمال يحرسون المزرعة أو شيء من ذلك؟","title":"حكم صلاة الجمعة على العمال الذين من خارج البلد","answer":"الجواب: أما العمال فعليهم الجمعة، تلزمهم بغيرهم إذا كانوا من الخارج، تلزمهم بغيرهم ، وإذا كانوا من الوطن تلزمهم مثل الناس الآخرين، ولا يجوز تركهم في المزرعة ولا يصلون الجمعة، بل يجب عليهم أن يصلوا الجمعة مع الناس إذا كانوا من البلد أو عمال من الخارج تلزمهم بغيرهم أيضاً، لكن إذا كانت المزرعة تحتاج إلى حراسة يبقى فيها من تحصل به الحراسة واحد أو اثنان الذين تدعو لهم الحاجة، والبقية يلزمهم أن يصلوا مع الناس، ولا يجوز تركهم جميعاً، بل يبقى منهم من تحصل به الحراسة ويكتفى بالحراسة، والباقون عليهم أن يصلوا جمعة مع الناس، والله المستعان. نعم.\nالمقدم: وهذا صاحب المزرعة يأثم يا فضيلة الشيخ إذا تركهم؟\nالشيخ: يأثم إيه، يأثم ما في شك، إذا تساهل معهم يأثم، إذا لم يأمرهم ولم يفسح لهم يأثم، أما إذا أمرهم وبين لهم أن هذا هو الواجب عليهم، وأن عليهم أن يصلوا فلم يمتثلوا وجلسوا بعده ولم يذهبوا فالإثم عليهم، لكن ينبغي له بعد ذلك إذا علم أن يحاسبهم على هذا، إما أن يستقيموا وإما أن يبعدهم، حتى لا يكون راضياً بأفعالهم القبيحة. نعم.\nالمقدم: جزاكم الله خير وبارك الله فيكم","link":"https://binbaz.org.sa/fatwas/6634/حكم-صلاة-الجمعة-على-العمال-الذين-من-خارج-البلد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20607.mp3","categories":["صلاة الجمعة"]},{"id":8561,"question":"له سؤال ثانٍ في هذه الرسالة يقول فيه: أنا أحد سكان المناطق الريفية، ويوجد بجوارنا قرية بها مسجد تؤدى به صلاة الجمعة، ولكن سكان هذه القرية بيننا وبينهم نزاع، وهم الذين أقاموا المسجد على حسابهم الخاص، وأنا أكرههم، فهل يجوز لي أن أؤدي صلاة الجمعة بهذا المسجد؟","title":"حكم ترك صلاة الجمعة بسبب بعض المشاكل","answer":"الجواب: نعم، يجوز بل يجب أن تؤدى الصلاة معهم، ولا تدع صلاة الجمعة إلا إذا كان هناك مسجد آخر تؤدى فيه صلاة الجمعة فلا بأس، أما إذا كان ما هناك جمعة إلا هذه الجمعة فالواجب عليك أن تؤديها معهم ولو كان بينك وبينهم شيء، ولو كنت تكرههم، فالعبادة حق الله، والجمعة فرض عليك، فعليك أن تؤديها مع إخوانك المسلمين وإن كان بينك وبين أهل القرية بعض الشيء، إلا إذا كان حضورك يفضي إلى قتل وفتنة فالتمس مسجداً آخر ولا تحضر معهم، هذا عذر شرعي، إذا كنت تخاف القتل، إذا حضرت قتلوك، هذا عذر شرعي، لكن ما دام أنه مجرد كراهة بينك وبنيهم شيء من الوحشة وتكرههم لذلك، فهذا ليس بعذر، والواجب عليك أن تحضر وأن تصلي معهم صلاة الجمعة؛ لأن صلاة الجمعة فريضة؛ يقول النبي ﷺ: لينتهين أقوام عن تركهم الجمعات أو ليختمن الله على قلوبهم ثم ليكونن من الغافلين، ثم يقول سبحانه في كتابه العظيم: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ [الجمعة:9]، فالواجب البدار للسعي للجمعة، والحضور وحضورها مع المسلمين، ولا ينبغي أن يمنعك من ذلك شيء من وحشة أو كراهة بينك وبين أهل المسجد أو بعض أهل المسجد. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6649/حكم-ترك-صلاة-الجمعة-بسبب-بعض-المشاكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20710.mp3","categories":["صلاة الجمعة"]},{"id":8679,"question":"يسأل أيضاً ويقول: أمي تصلي الصلوات الخمس وحتى السنن تصليها كاملة بما فيها الضحى والوتر، ولكن في يوم الجمعة لا تصلي إلا في الجامع الذي يبعد حوالي تسعة كيلو مترات، وأنا أنصحها بأن صلاة المرأة في بيتها هي الأحسن، وحتى صلاة الجمعة أيضاً في البيت هي الأحسن والأصوب للمرأة، لكنها تأبى إلا الذهاب في الجمعة إلى الجامع، فهل في خروجها لأداء الصلاة حرج؟","title":"حكم خروج المرأة إلى المسجد لصلاة الجمعة","answer":"الجواب: لا حرج، النبي ﷺ قال: لا تمنعوا إماء الله مساجد الله فإذا خرجت لأجل تسمع الخطبة وتستفيد وهي متسترة متحجبة متحفظة فلا بأس بذلك ولا حرج عليها، لكن بيتها أفضل لها تصلي ظهراً، تصلي في بيتها يوم الجمعة ظهراً أربعاً، وإن خرجت فلا تمنعوها، إذا كانت متحفظة متحجبة سليمة تريد الخير وسماع الخطبة وتستفيد فلا بأس بذلك ولا حرج عليها إن شاء الله، وقد كان النساء يصلين مع النبي ﷺ في مسجده عليه الصلاة والسلام، ويحضرن الخطبة وصلاة الجمعة، كان كثير من النساء يحضرن الجمع مع النبي ﷺ، فلا بأس بذلك ولا حرج، ولكن بيوتهن خير لهن. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6823/حكم-خروج-المراة-الى-المسجد-لصلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21510.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":8700,"question":"رسالة وصلت إلى البرنامج من الأخ عبدالله يوسف عبدالله ، أخونا يقول: قرأت في كتاب الفقه على المذاهب الأربعة رأياً للمالكية في شروط صحة الجمعة التي من صحتها الإمام، وحتى الإمام من شروطه شرطان: أحدهما: أن يكون هو الخطيب، وإذا كان من خطب غير من صلى فالصلاة باطلة إلا أن يكون هنالك عذر منع الإمام، ولم أجد إشارة لهذا الشرط عند الشافعية حيث أنني رأيت في صلاة الجمعة أحداً يخطب وآخر يصلي، فما هي الإجابة، هل صحيح أنه يجب أن من يخطب هو الذي يصلي، وإذا كنت مالكياً فكيف تكون صلاتي هل هي باطلة كما ورد في رأي المالكية، أفيدونا جزاكم الله عنا خير الجزاء، ووفقنا في اتباع الرأي الصائب؟","title":"حكم اشتراط أن يكون الخطيب والإمام واحداً في الجمعة","answer":"الجواب: المسألة مسألة خلافية بين أهل العلم، والصواب: أنه لا يشترط أن يكون الخطيب هو الإمام في الصلاة؛ لأن الخطبة منفصلة ليس لها اتصال بالصلاة، فالصلاة منفصلة والخطبة منفصلة، فالأفضل والسنة أن يتولى الخطابة من يتولى الإمامة فيكون هو الإمام وهو الخطيب يوم الجمعة، وهكذا العيد، لكن لو قدر أن الخطيب لم يتيسر له ذلك بأن أصابه مانع أو حيل بينه وبين ذلك فالصلاة صحيحة، وهكذا لو صلى باختياره ولم يخطب بل استناب من يخطب عنه فلا بأس، الصحيح أنه لا حرج في ذلك؛ لأن هذا منفصل، هذه عبادة مستقلة وهذه عبادة مستقلة، فالذين أجازوا أن يتولى الإمامة غير الخطيب لا حرج في ذلك ولا بأس بذلك قولهم صحيح.\nفالصواب في هذا أنه لا بأس أن يتولى الإمامة غير من تولى الخطبة هذا هو الصواب؛ لأن هذه عبادة مستقلة وهذه عبادة مستقلة ولكن الأفضل والأولى أن يتولاهما واحد كما فعله النبي ﷺ والخلفاء بعده، السنة أن يكون الإمام هو الخطيب، لكن لو عرض عارض ومنع مانع فصلى غير الخطيب فلا بأس.","link":"https://binbaz.org.sa/fatwas/6847/حكم-اشتراط-ان-يكون-الخطيب-والامام-واحدا-في-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_131/13107.mp3","categories":["صلاة الجمعة"]},{"id":8743,"question":"يسأل أيضاً ويقول: سمعت من بعض طلبة العلم إنكارهم على من خطب الجمعة وترك ما اعتاده الخطباء من ختم الخطبة الأولى من الجمعة بقول الخطيب -دائماً-: أقول قولي هذا وأستغفر الله لي ولكم من كل ذنب فاستغفروه إنه هو الغفور الرحيم، أو ختم الخطبة الثانية بقوله: إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالإِحْسَانِ [النحل:90] الآية، ومن ترك هذا أنكر عليه حتى قال طالب علم: ترك هذه الآية وعدم ختم الخطبة بها بدعة ومخالف للسنة، أفتونا جزاكم الله خير؟","title":"حكم ختم الخطبة الأولى بـ (أقول قولي هذا)، والثانية: {إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ}","answer":"الجواب: لا حرج في ترك ما ذكر فلا حرج أن يترك الخطيب: أقول قولي هذا وأستغفر الله ولا حرج أن يترك الآية إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالإِحْسَانِ [النحل:90] في الخطبة الثانية، كل هذا لا حرج فيه، فمن قال ذلك فلا بأس ومن ترك ذلك فلا بأس وختمها بالصلاة على النبي ﷺ أو بآية أخرى كل هذا لا حرج فيه.\nوالذي يقول: إن ترك هذا بدعة هذا غلط وليس عنده خبر، والختم بهذه الآية يروى عن عمر بن عبد العزيز أنه كان يختم بهذه الآية، وأما أقول قولي هذا وأستغفر الله فيروى عن النبي ﷺ.\nفبكل حال أن هذا ليس بأمر لازم وختم الخطبة بـ (أقول قولي هذا) أو بآية كريمة كله ليس بلازم بل إذا نوع الخطيب ختم الخطب بأنواع منوعة من الصلاة على النبي ﷺ ومن آيات أخرى أو أحاديث كله حسن، حتى لا يظن الناس أن هذا شيء لازم، لأن الخطيب التزم بهذه الآية وبقول أقول قولي هذا يظن بعض الناس أن هذا شيء لازم وأنه سنة مؤكدة وأن تركه بدعة كما ظنه من قلت عنه، ولكن متى نوع الخطيب فتارة يأتي بهذه الآية وتارة لا يأتي بها، وتارة يأتي بقول أقول قولي هذا وأستغفر الله وتارة لا يأتي به علم الناس أن الأمر واسع، وأنه لا حرج في ختم الخطب بهذه الآية أو بغيرها، أو بقول: (أقول قولي هذا) أو بغيره، حتى يكون هذا الأمر واضحاً للناس وبيناً فلا يقع الناس في الغلط، والله ولي التوفيق. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6901/حكم-ختم-الخطبة-الاولى-بـ-اقول-قولي-هذا-والثانية-ان-الله-يامر-بالعدل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_216/21606.mp3","categories":["صلاة الجمعة"]},{"id":8745,"question":"سؤال الأخ فواز محمد علي -الثاني- يقول فيه: نحن إخوة في الله نخرج يوم الجمعة في سفرة إلى منطقة تقع ضمن حدود المدينة، ويبلغ عددنا عشرون، ونقيم خطبة الجمعة مع الصلاة، فهل صلاتنا تجزئ أو مقبولة أم لا؟","title":"حكم صلاة الجمعة في السفر القصير والطويل","answer":"الجواب: إن كنتم مسافرين فالمسافر ليس عليه جمعة، إذا كانت المسافة طويلة تعد سفراً فإن المسافر ليس عليه جمعة ولا تصح، وعليكم أن تصلوا ظهراً قصراً ثنتين السنة أن تقصروها ثنتين، وإن كنتم حول البلد قريب من البلد تسمعون الأذان، أو يمكنكم سماع الأذان فعليكم أن تصلوا الجمعة مع الناس، فأما إن كنتم لستم مسافرين وبعيدين عن محل الجمعة فإنكم تصلونها ظهراً، وليس لكم أن تصلوا الجمعة لأن الجمعة إنما تقام في المدن والقرى لا في الصحاري ولا في البوادي ولا في الأسفار، فالواجب عليكم إن كنتم قريبين أن تصلوا مع الناس جمعة وإن كنتم بعيدين فإن كنتم مسافرين.. في حكم المسافرين صليتم ظهراً قصراً هذا هو الأفضل، وإن كنتم قريبين لستم مسافرين ولكنكم لا تستطيعون حضور الجمعة لبعدكم فإنكم تصلونها ظهراً أربعاً.\nهذا هو الواجب، وهذا هو الذي قرره أهل العلم والله أعلم. نعم.\nالمقدم: يعني: الذين يخرجون للتنزه يوم الجمعة؟\nالشيخ: إن كانوا بعيدين يعني: مثل سبعين كيلو ثمانين كيلو عن البلد صلوا ظهراً قصراً لأنهم مسافرون، وإن كانوا قريبين في ضواحي المدينة ثلاثين كيلو عشرين كيلو خمسة وعشرين كيلو تقريب أربعين كيلو، هؤلاء يصلون ظهراً أربعاً ولا يصلون جمعة. لكن إن كانوا قريبين يسمعون النداء في طرف البلد وجب عليهم أن يصلوا الجمعة مع الناس.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6897/حكم-صلاة-الجمعة-في-السفر-القصير-والطويل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_216/21603.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":9011,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: أنا مدرسة في قرية من قرى نجران في المملكة العربية السعودية ويرافقني والدي محرم لي، وإننا من الأردن ولنا بعض الأسئلة لو تكرمتم:السؤال الأول: نحن في قرية بعيدة عن القرية الكبيرة بما يقرب من عشرين كيلو متر، وأهل القرية لا يؤدون صلاة الجمعة ولا نملك وسيلة نقل إلى القرية المجاورة لنا حتى إننا لا نستطيع إحضار ماء الشرب إلا بالكلفة، نرجو أن تفتونا في موضوعنا جزاكم الله خيراً؟","title":"مشروعية إقامة الجمعة في القرى الصغيرة وإن كانوا ثلاثة","answer":"الجواب: عليكم أن تصلوا ظهراً؛ لأن المسافة طويلة فلا يلزمكم الذهاب إلى هناك والتكلف ولكن ينبغي لأهل القرية التي أنتم فيها أن يقيموا صلاة الجمعة، الواجب عليهم أن يقيموا صلاة الجمعة في قريتهم ولو كانوا أقل من أربعين، فليس اشتراط الأربعين شرطاً معتبراً على الصحيح، فعليهم أن يقيموا صلاة الجمعة وأن يطلبوا من الجهات الدينية أو من جهة المحكمة تعيين الإمام الذي يصلي بهم وفي إمكانهم الاتصال بإدارة الأوقاف حتى تؤمن لهم الإمام.\nفالحاصل أن الواجب على أهل القرية أن يصلوا جمعة ولو كانوا عشرة ولو كانوا عشرين، حتى ولو كانوا ثلاثة على الأقل، أقل عدد تجب عليه الجمعة ثلاثة في أصح أقوال أهل العلم، فإذا كانوا في قرية مستوطنين وجبت عليهم الجمعة ولا يجوز لهم أن يصلوا ظهراً، والإمام في الإمكان تحصيله بواسطة الأوقاف الجهة المسئولة أو بواسطة المحكمة أو بواسطة الأخيار الطيبين الذين يعرفون حالهم فيمكن أن يتوجه إليهم بعض طلبة العلم حتى يصلي بهم.\nفالمقصود أن هذا واجب عليهم ليس لهم التساهل فيه وأنت أيها السائل من جملتهم، إذا أقاموا الجمعة صليت معهم. نعم.","link":"https://binbaz.org.sa/fatwas/7169/مشروعية-اقامة-الجمعة-في-القرى-الصغيرة-وان-كانوا-ثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14704.mp3","categories":["صلاة الجمعة"]},{"id":9090,"question":"أولى رسائل هذه الحلقة سماحة الشيخ رسالة وصلت إلى البرنامج من الأخ خيري أحمد خيري النصري فيما يبدو من الرياض، أخونا يسأل مجموعة من الأسئلة من بينها سؤال يقول: نرى بعض الناس يستعملون المسواك داخل المسجد وأثناء الخطبة وقبلها مع أن بعض الناس يشمئزون من ذلك، فما هو قولكم لمثل هؤلاء، وهل هو جائز استعمال السواك أثناء الخطبة جزاكم الله خيراً؟","title":"السواك وحكم استعماله أثناء خطبة الجمعة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن استعمال السواك من السنن التي فعلها المصطفى عليه الصلاة والسلام ورغب فيها، فصح عنه عليه الصلاة والسلام أنه قال: لولا أن أشق على أمتي لأمرتهم بالسواك عند كل صلاة، وفي اللفظ الآخر: لأمرتهم بالسواك مع كل وضوء، وصح عنه عليه الصلاة والسلام أنه قال: السواك مطهرة للفم مرضاة للرب فلا حرج في استعماله في المسجد وغير المسجد، ويسن استعماله عند الدخول في الصلاة قبل أن يكبر وعند أول الوضوء، وعند دخول المنزل، قالت عائشة رضي الله عنها لما سئلت: بأي شيء يبدأ إذاا دخل البيت عليه الصلاة والسلام؟ قالت: كان يبدأ بالسواك يعني: إذا دخل بيته عليه الصلاة والسلام.\nفالسواك من السنن المشروعة وفيه من تطييب النكهة وتنظيف الأسنان والتشجيع على الخير ما هو معلوم، لكن وقت الخطبة لا يستعمل، وقت الخطبة يكون المؤمن منصتاً تاركاً للحركة لا يعبث بشيء ولا يستاك، ولكن ينصت للخطيب ويستفيد من الخطبة ويتدبر ويتعقل، أما قبل الخطبة فلا بأس، قبل الصلاة لا بأس، حال كونه جالس في المسجد لا بأس، عند الصلاة مشروع، عند الوضوء مشروع. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7250/السواك-وحكم-استعماله-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_150/15001.mp3","categories":["صلاة الجمعة"]},{"id":9422,"question":"إذا دخلت المسجد والإمام يخطب في يوم الجمعة هل الأفضل أن أصلي تحية المسجد أم أجلس للاستماع للخطبة؟","title":"حكم تحية المسجد أثناء خطبة الجمعة","answer":"الجواب:  صل التحية ثم اجلس، النبي ﷺ قال إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين ولما دخل رجل والنبي ﷺ يخطب فجلس أمره النبي ﷺ أن يقوم فيصلي ركعتين عليه الصلاة والسلام، هذا يدل على تأكد هاتين الركعتين، وأنه يصليهما قبل أن يجلس وإن كان الإمام يخطب، فهما متأكدتان. نعم.","link":"https://binbaz.org.sa/fatwas/7587/حكم-تحية-المسجد-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19008.mp3","categories":["صلاة الجمعة"]},{"id":9538,"question":"يقول أخيراً في رسالته الأخ عبدالقادر: إذا كان إمام المسجد يعتمد في خطبه على كتاب ابن نباتة ومعظم المصلين حفظوا خطبه بالتكرار، فهل يجوز ترك الخطبة والاستماع لخطبة الحرم الشريف من المذياع في الإذاعة وبعد الفراغ منها أذهب للمسجد لأداء الصلاة، أفيدونا أفادكم الله؟","title":"حكم ترك الاستماع لخطبة الجمعة بحجة تكرار الخطيب لخطبه","answer":"الجواب: لا ما يصلح، لا يصلح هذا، الواجب أنه ينصح حتى ينشأ خطباً مناسبة، أو يعطى كتباً من المؤلفات في الخطب المفيدة لأن هناك كتباً كثيرة مؤلفة في الخطب بحمد الله كثيرة يمكنه أن يستفيد منها، فيعطى بعض الكتب المفيدة ويوصى بأن يغير تارة كذا وتارة كذا حتى ينفع الناس وحتى يأتيهم بشيء جديد يحرك قلوبهم ويفيدهم، أما أن تتأخر حتى تأتي بعد ذلك لا، المشروع لك المسابقة حتى تأتي في المسجد قبل الخطبة وقبل الصلاة بوقت، تصلي ما قسم الله وتنتظر الصلاة ليحصل له فضل التبكير.\nالمقصود أن الإمام يغير ويستعين بالله ثم بالكتب التي ألفت في خطب الجمعة ويستعين بالله ثم بإخوانه الطيبين إذا كان ما عنده خطب حتى يضعوا له خطباً مناسبة مفيدة، والمسلم أخو المسلم، وطلبة العلم إخوة فيما بينهم يتعاونون. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7704/حكم-ترك-الاستماع-لخطبة-الجمعة-بحجة-تكرار-الخطيب-لخطبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24603.mp3","categories":["صلاة الجمعة"]},{"id":9560,"question":"تسأل هذه السائلة أيضاً وتقول: هل تجوز صلاة المرأة في المسجد وهي مستترة ومحتشمة ولم تمس طيباً ولم تتبرج، وهي تريد بذلك وجه الله عز وجل إلا أن زوجها غير راض عنها. أفيدونا أفادكم الله؟","title":"حكم صلاة المرأة في المسجد وزوجها غير راض بذلك","answer":"الجواب: نعم، لها أن تصلي في المسجد مع التستر لا بأس إلا إذا منعها، ولكن ليس له منعها، النبي ﷺ قال: لا تمنعوا إماء الله مساجد الله، فإذا خرجت وهي تفلة يعني لا رائحة ولا تكشف ولا تبرج بل مستورة متحجبة مضبوطة بدون طيب فلا بأس ولو كان غير راضي إذا لم يمنعها، وهو ممنوع منهي .... الرسول ﷺ قال: لا تمنعوا إماء الله مساجد الله وإن جلست ولم تخرج تطييباً لنفسه ومراعاة لخاطره فهو أفضل لأن بيتها خير لها، بيتها خير لها وأفضل ولأن في هذا أيضاً رضا زوجها ومجاملته، ولأن هذا قد يكون أسلم لها، قد يفضي هذا إلى الطلاق، فالأولى لها والأفضل أن تبقى في البيت ما دام لا يرضى، ولكن لا يلزمها ذلك؛ لأن الرسول ﷺ قال:  لا تمنعوا إماء الله مساجد الله وقال في الحديث:  وبيوتهن خير لهن. نعم.","link":"https://binbaz.org.sa/fatwas/7725/حكم-صلاة-المراة-في-المسجد-وزوجها-غير-راض-بذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_270/27009.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":9689,"question":"وهذه رسالة وردتنا من مجدي جلال عبد اللطيف من مصر مركز شبين القناطر القليوبية ويعمل في المملكة، يقول الأخ مجدي: بأنه شاب صالح، ونشأ في أسرة مسلمة فقيرة إلى الله ، وقد سافر إلى المملكة لأجل البحث عن الرزق وعن العمل وأن يساعد والده في رزقه ورزق إخوانه، ولكنه يقول: إنني أعمل في مزرعة هذه المزرعة تبعد عن المدن مئات من الكيلو مترات، حيث أعمل في الصحراء أو في البر كما يقولون، ولا يوجد مسجد للصلاة، فأصلي الأوقات في مكان العمل أو في محل النوم، أما صلاة الجمعة فلا أصليها سوى ظهراً؛ لأنني في مزرعة بمفردي وليس معي سوى الله سبحانه وتعالى، فما الحكم فيما مضى من صلاة الفروض وصلاة الجمعة، وأفيدوني أفادكم الله؟","title":"حكم الجمعة والجماعة على من يعمل في مزرعة بصحراء","answer":"الجواب: هذا هو الذي عليك يا أخي! عليك أن تصلي وحدك والحمد لله، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] ، ما دمت في صحراء ما عندك مساجد صل وحدك والحمد لله، وتصلي الظهر يوم الجمعة ليس عليك جمعة، وتؤذن وتقيم إذا جاء الوقت تؤذن وتقيم ولو أنك واحد، هذا هو المشروع لك، تؤذن الأذان الشرعي وتقيم لنفسك وتصلي كل صلاة في وقتها وأنت على خير عظيم والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7898/حكم-الجمعة-والجماعة-على-من-يعمل-في-مزرعة-بصحراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25407.mp3","categories":["صلاة الجماعة","صلاة الجمعة"]},{"id":9774,"question":"لنفس السائلة من العراق تقول: متى يكون وقت صلاة الجمعة بالنسبة للرجال والنساء؟ وهل هناك سور مخصصة تقرأ في الجمعة أفيدونا بارك الله فيكم؟","title":"بيان القول في وقت صلاة الجمعة وحكمها على المرأة","answer":"الجواب: صلاة الجمعة يدخل وقتها بعد الزوال، هو وقت صلاة الظهر، وقتها وقت صلاة الظهر، والمرأة ليس عليها جمعة، إنما عليها ظهر، تصلي ظهراً لكن لو صلت مع الناس الجمعة أجزأت، لو صلت مع الناس الجمعة ركعتين أجزأتها عن الظهر، كالمريض العاجز والمسافر إذا صلوا مع المقيمين ومع الأصحاء صلى المريض مع الأصحاء وصبر على المشقة أجزأته عن الظهر، وإن صلى وحده صلى ظهراً، وهكذا المسافر إذا صلى مع الناس أجزأته الجمعة عن الظهر، وإن صلى وحده صلى ظهراً، فهكذا المرأة ليس عليها جمعة ولكن لو صلت مع الرجال أجزأتها عن الظهر.\nوذهب بعض أهل العلم إلى أن الجمعة وقتها أوسع، وأنه يدخل وقتها قبل الظهر.. في الساعة السادسة قبل زوال الشمس.\nوذهب آخرون إلى أن وقت الجمعة أوسع من هذا كله، وأنه يدخل بارتفاع الشمس قيد رمح إلى خروج وقت الظهر، وإلى هذا ذهب أحمد رحمه الله وجماعة من السلف واحتجوا بأدلة جيدة فمن صلاها قبل الزوال صحت، ولكن الأفضل أن يكون بعد الزوال، خروجاً من خلاف العلماء وعملاً بالأدلة كلها.\nلكن المرأة ليس عليها جمعة كما تقدم، بل تصلي في بيتها ظهراً وهو أفضل لها، وإن صلت مع الناس لأجل سماع الخطبة سماع الفائدة فلا بأس تصلي معهم جمعة وتجزئها والحمد لله. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7941/بيان-القول-في-وقت-صلاة-الجمعة-وحكمها-على-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_258/25802.mp3","categories":["صلاة الجمعة"]},{"id":9864,"question":"نفس السائل يقول في هذه الرسالة: إذا حدث أن غلط الإمام في خطبة الجمعة فرد عليه بعض المصلين فهل يعتبر هذا المصلي قد لغا أم لا؟ أفيدونا بارك الله فيكم.","title":"حكم الكلام مع الخطيب أثناء الخطبة","answer":"الجواب: الرد على الإمام في الخطبة أو سؤاله عن شيء في الخطبة أو طلبه شيئاً في الخطبة ليس من اللغو في الخطبة، وليس بممنوع، فقد جاء رجل إلى النبي ﷺ وهو يخطب في يوم الجمعة، فقال: يا رسول الله! هلكت الأموال، وانقطعت السبل، فادع الله يغيثنا، فأجابه النبي ﷺ واستغاث ربه ولم ينكر عليه، فإذا خاطب رجل الإمام -الخطيب- قال له: يا خطيب! يا فلان! ادع الله لنا، أو استغث لنا، أو فتح عليه غلطاً وقع له، فلا حرج عليه في ذلك، وليس بداخل في هذا وليس بممنوع. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8039/حكم-الكلام-مع-الخطيب-اثناء-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26307.mp3","categories":["صلاة الجمعة"]},{"id":9892,"question":"يسأل عن الآية الكريمة: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ [الجمعة:9] السؤال يقول: لماذا خص الله الجمعة في هذه الآية؟","title":"لماذا خص الله الجمعة في: {إِذَا نُودِيَ لِلصَّلاةِ مِنْ يَوْمِ الْجُمُعَةِ}؟","answer":"الجواب: لعظم شأنها ولأنها تفوت ... يحضرها، تفوت، لا يصلي إلا ظهرًا بعد ذلك، فالواجب عليه أن يسارع إليها وألا يشتغل ببيع ولا غيره حتى يدركها لعظم شأنها ولأنها فرض الأسبوع ويجتمع لها المسلمون وفيها فضل عظيم، فينبغي للمؤمن أن يحافظ عليها وأن يحذر المعوقات. نعم.","link":"https://binbaz.org.sa/fatwas/8060/لماذا-خص-الله-الجمعة-في-اذا-نودي-للصلاة-من-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27304.mp3","categories":["صلاة الجمعة"]},{"id":10047,"question":"أحد الإخوة بعث برسالة من اليمن يقول: أنا (ص. أ. ع) يقول: أعمل في محطة بنزين تبعد عن المسجد ما يقرب من اثنين كيلو متر، ومنذ أن بدأت أعمل في هذه المحطة لم أصل صلاة الجمعة بل أبقى في المحطة؛ خوفاً عليها من الحريق أو من أي شيء آخر، ما رأيكم هل أكون آثماً في هذا العمل؟","title":"حكم التخلف عن صلاة الجمعة والجماعة بعذر الانشغال بالحراسة","answer":"الجواب: هذا فيه تفصيل: إن كنت حارساً عليها مأموراً بالحراسة لا يسمح لك ....... معذور، كالحارس عند أبواب المكاتب وأبواب العمارات والحارس في مواضع أخرى، في مواضع يخشى عليها فالحارس معذور، أما إن كان من اجتهادك فلا يجوز لك، بل تغلق الباب وتحفظ الأشياء التي يجب حفظها وتذهب إلى الجمعة أو إلى صلاة الجماعة، وهذا هو الواجب عليك إذا كان ليس هناك خطر، أما إذا كان هناك خطر وأن الحراسة لابد منها فلا حرج عليك كما تقدم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8225/حكم-التخلف-عن-صلاة-الجمعة-والجماعة-بعذر-الانشغال-بالحراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30309.mp3","categories":["صلاة الجماعة","صلاة الجمعة"]},{"id":10054,"question":"أحد الإخوة بعث برسالة من اليمن يقول: أنا (ص. أ. ع) يقول: أعمل في محطة بنزين تبعد عن المسجد ما يقرب من اثنين كيلو متر، ومنذ أن بدأت أعمل في هذه المحطة لم أصل صلاة الجمعة بل أبقى في المحطة؛ خوفاً عليها من الحريق أو من أي شيء آخر، ما رأيكم هل أكون آثماً في هذا العمل؟","title":"حكم التخلف عن صلاة الجمعة والجماعة بعذر الانشغال بالحراسة","answer":"الجواب: هذا فيه تفصيل: إن كنت حارساً عليها مأموراً بالحراسة لا يسمح لك ....... معذور، كالحارس عند أبواب المكاتب وأبواب العمارات والحارس في مواضع أخرى، في مواضع يخشى عليها فالحارس معذور، أما إن كان من اجتهادك فلا يجوز لك، بل تغلق الباب وتحفظ الأشياء التي يجب حفظها وتذهب إلى الجمعة أو إلى صلاة الجماعة، وهذا هو الواجب عليك إذا كان ليس هناك خطر، أما إذا كان هناك خطر وأن الحراسة لابد منها فلا حرج عليك كما تقدم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8225/حكم-التخلف-عن-صلاة-الجمعة-والجماعة-بعذر-الانشغال-بالحراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30309.mp3","categories":["صلاة الجماعة","صلاة الجمعة"]},{"id":10086,"question":"مستمع رمز إلى اسمه بالحروف (م. ج) يسأل ويقول: هل للجمعة أذان واحد أم أذانان؟ وهل بينهما سنة قبلية للجمعة؟","title":"حكم الأذان الأول والثاني للجمعة","answer":"الجواب: الجمعة لها أذان واحد، هذا هو الأصل، وهذا هو المفترض عند دخول الخطيب وهو الواقع في عهد النبي ﷺ، كان إذا دخل الخطيب أذن بلال ، ثم زاد عثمان أذانًا ثانيًا مستحب لتنبيه الناس على أن اليوم يوم الجمعة قبل الأذان الأول، يعني قبل الأذان السابق الذي عند دخول الخطيب يأذن به قبل الوقت بنص ساعة أو نحوها أو ساعة؛ حتى يعلم الناس الجمعة، وحتى يستعدوا للمجيء، وقد درج السلف على هذا تأسيًا بـعثمان  في عهد عثمان وفي عهد علي وعهد الصحابة بعد عثمان ، ثم درج عليه السلف الصالح، فهذا مشروع من عمل الخلفاء الراشدين، والرسول عليه السلام قال: عليكم بسنتي وسنة الخلفاء الراشدين المهديين من بعدي، ومعلوم أن عثمان رضي الله عنه وعليًّا رضي الله عنه كلهم من الخلفاء الراشدين.\nفالسنة أن يؤتى بأذان أول للجمعة؛ للتنبيه، كما فعل عثمان ومن بعده ، أما الأذان الأول الذي عند دخول الخطيب فهذا هو الموجود في عهد النبي ﷺ وهو المفترض. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8255/حكم-الاذان-الاول-والثاني-للجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27614.mp3","categories":["الأذان والإقامة","صلاة الجمعة"]},{"id":10114,"question":"يقول صاحب هذه الرسالة: يوجد في هذه القرية مدرسة داخلية للطلبة وبها مسجد تقام به الصلوات الخمس في فترات الدراسة، هل يجوز إقامة الجمعة في مثل هذا المسجد؟ مع العلم بأن الدراسة سوف تتعطل في فترات الإجازات.","title":"حكم إقامة الجمعة في مسجد المدرسة","answer":"الجواب: هذا فيه التفصيل: إذا كان المسجد حوله مساجد أخرى تقام فيها الجمعة لا يجوز أن تقام فيه، بل على الطلبة وغيرهم أن يصلوا الجمعة مع الناس في الجوامع الموجودة، أما إذا كان القرية ما فيها جامع قريب والجوامع عنها بعيدة في القرى الأخرى فلهم أن يقيموها في هذا المسجد إذا كان حول المسجد أناس مقيمون، ولو أنهم ثلاثة فأكثر، إذا كانوا مقيمين مستوطنين فلهم أن يصلوا الجمعة ومن حضر معهم من الناس من طلبة وغيرهم، إلا إذا كان هناك مسجد قريب يسمعون النداء لا يشق عليهم الذهاب إليه وجب عليهم أن يذهبوا إلى المسجد القريب ويكفي، لكن متى كانت المساجد بعيدة التي تقام فيها الجمعة ويشق عليهم الذهاب إليها ولا يسمعون النداء، يعني النداء بغير المكبرات، النداء العالي عند خلو الأصوات وعدم وجود ما يمنع عن السماع فإنهم في هذه الحالة لهم أن يصلوا الجمعة في مسجدهم، إذا كان المسجد حوله أناس مستوطنون ثلاثة أو أكثر في أصح قولي العلماء، ولا يشترط أن يكونوا أربعين ولا اثني عشر، ليس على هذا دليل، بل متى وجد ثلاثة أو أربعة أو خمسة مستقيمون مستوطنون في البلد فإنهم يصلون الجمعة إذا كان ما حولهم جوامع بعيدة عنهم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8285/حكم-اقامة-الجمعة-في-مسجد-المدرسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33403.mp3","categories":["صلاة الجمعة"]},{"id":10150,"question":"آخر سؤال لأخينا يقول: أنا شاب في مكان عملي وأثناء دوامي لا يسمح لي بالخروج من مكان العمل، ذهبت إلى صلاة الجمعة، هل تصح؟","title":"حكم من لا يستطيع صلاة الجمعة بسبب رفض صاحب العمل","answer":"الجواب: الأقرب -والله أعلم- أنها تصح صلاة الجمعة، لكن لا يجوز لك حتى تخبرهم، حتى تخبرهم بأنك لا تستطيع أن تترك الجمعة، فإما أن يسمحوا لك إما أن يضعوا بدلك، لا تفرط في عملك إلا بإذنهم، يعني: الحراسة أمرها عظيم والخطر في تركها كبير، في بعض الأحيان الواجب عليك أن تستأذن أو تعتذر تقول: لا.. لا أوافق على هذا الأمر، أو تستأذنهم فإذا أذنوا لك صليت الجمعة وإلا فالزم الحراسة وصل في مكانك ظهراً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8330/حكم-من-لا-يستطيع-صلاة-الجمعة-بسبب-رفض-صاحب-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30712.mp3","categories":["صلاة الجمعة"]},{"id":10437,"question":"يقول: إذا وافق العيد الجمعة، فهل تصلى صلاة الجمعة؟","title":"حكم صلاة الجمعة إذا وافقت يوم عيد","answer":"الجواب: نعم، يصلي الإمام بالناس الحاضرين صلاة الجمعة، ومن حضر العيد لا تلزمه الجمعة، لكن إذا صلاها يكون أفضل له وخيراً له، وإلا فلا تلزمه يصلي ظهراً، من حضر العيد يصلي ظهراً إذا لم يحضر الجمعة، وإن حضر الجمعة كان أفضل، والإمام يقيم الجمعة ويصلي بمن حضر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8616/حكم-صلاة-الجمعة-اذا-وافقت-يوم-عيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31808.mp3","categories":["صلاة الجماعة","صلاة الجمعة","صلاة العيدين","الصلاة على الميت"]},{"id":10476,"question":"بماذا تنصحون الذين يصطحبون أطفالهم إلى المسجد يوم الجمعة، فيشغلون المصلين بالكلام واللعب والخطيب على المنبر؟","title":"حكم اصطحاب الأطفال إلى المسجد يوم الجمعة","answer":"الجواب: الطفل الذي دون السبع ينبغي أن يبقى عند أهله حتى لا يشغل الناس، ينبغي أن يبقى عند أهله حتى لا يحصل به إيذاء للناس، أما إذا كان الطفل قد كمل السبع فأكثر فهذا يصلي مع الناس؛ لأن الرسول ﷺ أمر الأولياء بأمرهم بالصلاة قال: مروا أبناءكم بالصلاة لسبع واضربوهم عليها لعشر، فعلى آبائهم وعلى إخوانهم الكبار أن يخرجوا بهم إلى الصلاة، وأن يوجهوهم ويؤدبوهم إذا آذوا الناس ويمنعوهم، حتى يستقيموا على الطريق السوي، وحتى يصلوا مع الناس من دون أذى.","link":"https://binbaz.org.sa/fatwas/8651/حكم-اصطحاب-الاطفال-الى-المسجد-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28103.mp3","categories":["صلاة الجمعة","تربية الأولاد"]},{"id":10502,"question":"يقول: أنا إنسان مشغول بالإبل والأغنام، وأكثر الأوقات لا أصلي الجمعة، فهل علي إثم مع العلم أن المسجد يبعد عني قرابة خمسة عشر كيلو متر؟","title":"حكم ترك صلاة الجمعة لبعد المسجد","answer":"الجواب: هذا بعيد، معذور أنت ... هذا بعيد، لكن إذا كنت قريب تسمع النداء عند هدوء الأصوات وعند هدوء الرياح تسمع النداء يلزمك، النبي عليه الصلاة والسلام قال: من سمع النداء فلم يأت فلا صلاة له، أما البعيد مثل خمسة عشر كيلو وعشرة كيلو وأشباه ذلك، هذا بعيد، صل مع من معك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8677/حكم-ترك-صلاة-الجمعة-لبعد-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28210.mp3","categories":["صلاة الجمعة"]},{"id":10509,"question":"هل هناك شروط يجب توفرها في خطيب الجمعة؟","title":"الشروط التي ينبغي توافرها في خطيب الجمعة","answer":"الجواب: إي نعم، أن يكون ذا علم ويستطيع أن يسمع الناس الخطبة، ويكون له أثراً في وعظهم وتذكيرهم، ينبغي أولًا لابد من كونه مسلم، هذا لابد منه، .... الصلاة بغير مسلم ما تصح، وإذا كان عدلًا كان هو الأولى وفي عدالته خلاف، لكن كونه عدلاً معروفاً بالخير، هذا الذي ينبغي حتى تقبل موعظته وحتى تؤثر، ويكون من أهل العلم والبصيرة فيما وكل إليه، ... كل هذا مطلوب في الخطيب، أما كونه مسلم هذا شرط، وجماعة من أهل العلم يقولون: لابد أن يكون عدلاً أيضاً شرط، ولكن الصواب أنه ليس بشرط، لو خطب وهو عاصي صحت الخطبة إذا كان مسلمًا، ولكن إذا كان بالاختيار ينبغي لولاة الأمور والمسئولين أن يختاروا ... الخطيب الرجل الطيب الصالح الفقيه، الصالح للخطبة في صوته ووعظه وتذكيره. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8684/الشروط-التي-ينبغي-توافرها-في-خطيب-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28217.mp3","categories":["صلاة الجمعة"]},{"id":10524,"question":"يقول في سؤال آخر: علمنا أنه يحرم البيع بعد النداء الثاني في يوم الجمعة، فهل هذا ينطبق على أصحاب سيارات الأجرة والباصات الذين يتقاضون على إركاب الركاب قيمة معينة وجهونا؟ وهل من توجيه لهم، جزاكم الله خيراً؟","title":"حكم تقاضي أجرة السيارات بعد النداء الثاني للجمعة","answer":"الجواب: نعم، تأجير السيارات بيع؛ لأن الأجرة بيع، بيع المنافع، يدخل في الآية الكريمة: إِذَا نُودِيَ لِلصَّلاةِ مِنْ يَوْمِ الْجُمُعَةِ  [الجمعة:9] تقف السيارات، ويقف أهل التكاسي ويتوجهون إلى المسجد يجب عليهم، ولا يجوز لهم أن يؤجروها في هذه الحال، بل يوقفونها ويتوجهون إلى المسجد إذا سمعوا النداء هذا هو الواجب عليهم؛ لأن التأجير نوع من البيع، بيع المنافع يسمى: أجرة، وهو بيع. نعم.\nالمقدم: جزاكم الله خيرًا، سماحة الشيخ! إذا كان النداء الثاني يتفاوت من مسجد إلى آخر، قد يكون بين بعض المساجد والبعض الآخر ما يقرب من نصف ساعة، ما هو توجيه سماحة الشيخ؟\nالشيخ: متى سمع المنادي في المحل الذي فيه كفى.\nالمقدم: إذًا العبرة بالمحل...؟\nالشيخ: بالمحل الذي هو فيه. نعم.\nالمقدم: بارك الله فيكم، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8699/حكم-تقاضي-اجرة-السيارات-بعد-النداء-الثاني-للجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28313.mp3","categories":["صلاة الجمعة","الإجارة"]},{"id":10578,"question":"المستمع حامد شاكر من حريملا، بعث برسالة وضمنها خمسة أسئلة، في سؤاله الأول يقول: تعلمون وفقكم الله أن رد السلام واجب، وأن الإنصات بخطبة الجمعة واجب، فإذا سلم أحد الأشخاص والخطيب يخطب فهل أرد عليه، خاصةً إذا ألح علي واضطرني إلى الرد أفتونا مأجورين جزاكم الله خيراً؟","title":"حكم رد السلام أثناء خطبة الجمعة","answer":"الجواب: السلام وهو في وقت الخطبة غير مشروع، بل يصلي التحية ويجلس ولا يسلم على أحد، حتى ينتهي الخطيب، وإذا سلم عليك لا ترد إلا بالإشارة كما لو سلم عليك في الصلاة ترد بالإشارة ويكفي، وليس له أن يلح في طلب السلام، وإذا مد يده تمد يدك ولا تتكلم بشيء حتى ينتهي الخطيب، فإذا سكت الخطيب ترد عليه والحمد لله.\nوالمؤمن يتأدب بالآداب الإسلامية ويتعلم، كما أنه في الصلاة يرد بالإشارة، فهكذا إذا سلم عليه أخوه والإمام يخطب يرد بالإشارة، الإشارة بيده أو برأسه، ويكفي والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8754/حكم-رد-السلام-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_324/32402.mp3","categories":["صلاة الجمعة"]},{"id":10583,"question":"المستمع حامد شاكر من حريملا، بعث برسالة وضمنها خمسة أسئلة، في سؤاله الأول يقول: تعلمون وفقكم الله أن رد السلام واجب، وأن الإنصات بخطبة الجمعة واجب، فإذا سلم أحد الأشخاص والخطيب يخطب فهل أرد عليه، خاصةً إذا ألح علي واضطرني إلى الرد أفتونا مأجورين جزاكم الله خيراً؟","title":"حكم رد السلام أثناء خطبة الجمعة","answer":"الجواب: السلام وهو في وقت الخطبة غير مشروع، بل يصلي التحية ويجلس ولا يسلم على أحد، حتى ينتهي الخطيب، وإذا سلم عليك لا ترد إلا بالإشارة كما لو سلم عليك في الصلاة ترد بالإشارة ويكفي، وليس له أن يلح في طلب السلام، وإذا مد يده تمد يدك ولا تتكلم بشيء حتى ينتهي الخطيب، فإذا سكت الخطيب ترد عليه والحمد لله.\nوالمؤمن يتأدب بالآداب الإسلامية ويتعلم، كما أنه في الصلاة يرد بالإشارة، فهكذا إذا سلم عليه أخوه والإمام يخطب يرد بالإشارة، الإشارة بيده أو برأسه، ويكفي والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8754/حكم-رد-السلام-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_324/32402.mp3","categories":["صلاة الجمعة"]},{"id":10633,"question":"رسالة وصلت إلى البرنامج من المستمع: سلام عبد الستار مصري، يقول: نحن اثنان نعمل في مزرعة وتبعد كثيراً عن المدينة، وليست لدينا سيارة، ولذلك فقد تأخرنا عن صلاة الجمعة لمدة أربعة أشهر، ما حكم ما فعلنا؟","title":"حكم صلاة الجمعة لمن كان يعمل خارج المدينة","answer":"الجواب: ليس عليكم جمعة ما دمتم بعيدين عن المدن، ليس عليكم إلا الظهر؛ لأنكم في حكم المسافرين، أو في حكم غير المقيمين.\nفالحاصل: أن الإنسان الذي يقيم في مزرعة بعيدة وليس مستوطناً فيها ليس عليه جمعة؛ لأنه عامل ليس بمستوطن، أما إذا أقام أهلها فيها مستوطنين فإنهم يقيمون الجمعة فيها، يصلون صلاة الجمعة فيها، أما العمال الذين يقيمون فيها للعمل ثم ينتقلون عنها فهؤلاء ليس عليهم جمعة وإنما عليهم الظهر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8811/حكم-صلاة-الجمعة-لمن-كان-يعمل-خارج-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_328/32813.mp3","categories":["صلاة الجمعة"]},{"id":10757,"question":"رسالة بعث بها المستمع يسلم سالم عبودان الجابري من حضرموت يقول في أحد أسئلته: يوجد في قريتنا مسجد يتسع لحوالي أربعين شخصاً، وعدد سكان القرية لا يزيد عن اثني عشر شخصاً، ولهذا فنحن لا نصلي صلاة الجمعة في هذا المسجد، وإنما نذهب إلى مسجد آخر يبعد عنا بضعة كيلو مترات، والسبب هو عدم توفر أربعين شخصاً لقيام صلاة الجمعة، فهل يجوز قيام صلاة الجمعة بهذا العدد القليل وهو اثنا عشر شخص، جزاكم الله خيراً؟","title":"حكم إقامة صلاة الجمعة بأقل من أربعين شخصاً","answer":"الجواب: نعم يجوز في أصح أقوال العلماء، ينبغي لكم أن تقيموا الجمعة في محلكم، إذا كان عندكم إمام يصلح لذلك والحمد لله، إذا كان المسجد الذي يجمع فيه بعيداً عنكم وفيه مشقة، يعني: يبعد عنكم عدة كيلوهات تقيموا في قريتكم الجمعة والحمد لله، ولو كانوا خمسة ولو ستة أقل ذلك ثلاثة، إذا كانوا ثلاثة مستوطنين أحرار مقيمين في القرية جاز لهم أن يجمعوا ولو أنهم ثلاثة أو أربعة، أما اشتراط أربعين فليس بصحيح قول ضعيف مرجوح عند أهل العلم، فلا بأس ولا حرج عليكم أن تجمعوا في قريتكم وإن كنتم اثني عشر أو أقل من ذلك، ما لم تنقصوا عن ثلاثة هذا هو الصواب.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8937/حكم-اقامة-صلاة-الجمعة-باقل-من-اربعين-شخصا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_347/34707.mp3","categories":["صلاة الجمعة"]},{"id":10759,"question":"رسالة بعث بها المستمع يسلم سالم عبودان الجابري من حضرموت يقول في أحد أسئلته: يوجد في قريتنا مسجد يتسع لحوالي أربعين شخصاً، وعدد سكان القرية لا يزيد عن اثني عشر شخصاً، ولهذا فنحن لا نصلي صلاة الجمعة في هذا المسجد، وإنما نذهب إلى مسجد آخر يبعد عنا بضعة كيلو مترات، والسبب هو عدم توفر أربعين شخصاً لقيام صلاة الجمعة، فهل يجوز قيام صلاة الجمعة بهذا العدد القليل وهو اثنا عشر شخص، جزاكم الله خيراً؟","title":"حكم إقامة صلاة الجمعة بأقل من أربعين شخصاً","answer":"الجواب: نعم يجوز في أصح أقوال العلماء، ينبغي لكم أن تقيموا الجمعة في محلكم، إذا كان عندكم إمام يصلح لذلك والحمد لله، إذا كان المسجد الذي يجمع فيه بعيداً عنكم وفيه مشقة، يعني: يبعد عنكم عدة كيلوهات تقيموا في قريتكم الجمعة والحمد لله، ولو كانوا خمسة ولو ستة أقل ذلك ثلاثة، إذا كانوا ثلاثة مستوطنين أحرار مقيمين في القرية جاز لهم أن يجمعوا ولو أنهم ثلاثة أو أربعة، أما اشتراط أربعين فليس بصحيح قول ضعيف مرجوح عند أهل العلم، فلا بأس ولا حرج عليكم أن تجمعوا في قريتكم وإن كنتم اثني عشر أو أقل من ذلك، ما لم تنقصوا عن ثلاثة هذا هو الصواب.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8937/حكم-اقامة-صلاة-الجمعة-باقل-من-اربعين-شخصا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_347/34707.mp3","categories":["صلاة الجمعة"]},{"id":10982,"question":"تقول السائلة: هل صحيح بأن من قرأ سورة الكهف له فضل يوم الجمعة، وما هو الحديث الذي يبين فضل هذه السورة العظيمة؟","title":"استحباب قراءة سورة الكهف يوم الجمعة","answer":"الجواب:  هذه السورة يستحب قراءتها يوم الجمعة، جاء فيها أحاديث فيها ضعف، ولكن ثبت عن بعض الصحابة أنه كان يقرؤها، عن أبي سعيد الخدري  ويروي عن ابن عمر، وهذا يدل على أن لها أصلًا؛ لأن الصحابي لما واظب عليها دل على أن عنده علمًا من ذلك، فالأفضل قراءتها يوم الجمعة. نعم.","link":"https://binbaz.org.sa/fatwas/9160/استحباب-قراءة-سورة-الكهف-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28703.mp3","categories":["صلاة الجمعة","القرآن وعلومه"]},{"id":10998,"question":"ننتقل إلى رسالة أخرى وصلت إلى البرنامج من اليمن ناحية الزهرة، وباعث الرسالة الأخ: أحمد علي عمر يقول: أنا شاب أدرس في الثانوية، ولدي أب وأم ويوجد لديهم غنم، ويوم العطلة وهو يوم الجمعة أذهب لرعي الغنم، وذلك خارج إرادتي، فهل أرفض أمر أبي وأمي وأذهب إلى صلاة الجمعة، أم أبقى مع الغنم؟ جزاكم الله خيرًا.","title":"حكم طاعة الوالدين في رعي الغنم وقت صلاة الجمعة","answer":"الجواب:  إذا كان والداك في حاجة إليك، والغنم في حاجة إليك ما فيها من يرعاها، فلا مانع من مساعدة والدك وبره، وأن تذهب للرعي، ويكون عذرًا لك ذلك في صلاة الظهر، تصلي ظهرًا إذا لم يكن هناك أحد يكفيك الرعي حتى تصلي الجمعة، إذا كنت قريبًا من مساجد الجمعة.  أما إن كنت بعيدًا، الغنم بعيدة عن مساجد الجمعة فهي لا تسمع النداء بعيدة، فليس عليك إلا الظهر، وهذا من بر والديك، أما إن تيسر من يكفيك رعيها وقت الصلاة، وأنت قريب من الجوامع تسمع الأذان تصلي الجمعة وترجع إليها إذا وجدت من يكفيك من نساء ثقات، أو إنسان آخر يقوم مقامك ليس عليه جمعة كالمريض ونحوه فلا بأس بذلك، أو صبي صغير ما عليه جمعة، تثق به في رعايتها فلا بأس، يلزمك أن تصلي الجمعة إذا كنت قريبًا تسمع النداء، أما إذا كنت بعيدًا فلا جمعة عليك، تصلي ظهرًا والحمد لله، وتبر والديك، وتساعدهما، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9176/حكم-طاعة-الوالدين-في-رعي-الغنم-وقت-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36510.mp3","categories":["صلاة الجمعة"]},{"id":10999,"question":"يقول يوجد في قريتنا أناس يحضرون يوم الجمعة ومعهم ريحان، فيقومون برميه على المصلين والإمام يخطب، فهل هذا مخل بالصلاة؟","title":"حكم توزيع الريحان في الجمعة والإمام يخطب","answer":"الجواب:  ليس هذا مخلًا بالصلاة إذا طرحوه في المسجد لا يضر -إن شاء الله- لأجل الرائحة الطيبة، ومسألته سهلة، لا تشغلهم عن سماع الخطبة، ولا عن تحية المسجد، إذا دخلوا ورموه، وصلوا تحية المسجد، وجلسوا يسمعون الخطبة، ليس في هذا شيء، أما إذا كان له مؤنة يشوش على الناس، أو يشغلهم عن تحية المسجد وقتًا طويلًا ينبغي تأجيله إلى وقت آخر، أو التبكير به يوم الجمعة قبل الخطبة حتى يطرح في المسجد، أما وقت الخطبة فينبغي له إذا جاء أن يشتغل بركعتي التحية، تحية المسجد ركعتين، ثم يستمع للخطبة، أما إذا كان شجرة في يده يرميها وهو ماشي ما تشوش على أحد فلا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9178/حكم-توزيع-الريحان-في-الجمعة-والامام-يخطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36512.mp3","categories":["صلاة الجمعة"]},{"id":11021,"question":"كونه يلقي الدروس قبل خطبة الجمعة ما رأيكم في هذا العمل ...؟","title":"حكم إلقاء الدروس قبل صلاة الجمعة","answer":"الجواب:  الأمر في هذا واسع.... إذا إنسان درس الناس وهم جالسون قبل الجمعة لا حرج، يروى عن أبي هريرة أنه كان ..... بهذا -رضي الله عنه- نعم. المقدم: ما شاء الله جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9188/حكم-القاء-الدروس-قبل-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36604.mp3","categories":["صلاة الجمعة"]},{"id":11033,"question":"يقول أيضًا: هل يجوز رفع اليد عند دعاء الإمام في الخطبة الثانية من صلاة الجمعة؟","title":"حكم رفع اليدين أثناء الدعاء في خطبة الجمعة","answer":"الجواب:  إذا كان يستسقي أما غير الاستسقاء لا، لا يرفع الإمام ولا هم، لكن إذا استسقى طلب الغيث، يرفع يديه، سُن لهم أن يرفعوا أيدهم في الدعاء عند طلب الغيث في الجمعة، أو في غير الجمعة، نعم.","link":"https://binbaz.org.sa/fatwas/9211/حكم-رفع-اليدين-اثناء-الدعاء-في-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28715.mp3","categories":["صلاة الجمعة"]},{"id":11066,"question":"هذا السائل سماحة الشيخ رمز لاسمه بـ (ح. م. س) شمال سيناء، يقول: عندنا أذان واحد يوم الجمعة، ثم الخطبة، هل هذا الصحيح؟ نرجو توضيح ذلك مأجورين.","title":"حكم الاكتفاء بأذان واحد في الجمعة","answer":"الجواب: هذا هو الأصل في عهد النبي ﷺ كان أذانًا واحدًا بين يدي الخطيب عند دخول الخطيب، ثم في عهد عثمان  أمر بأذان قبل ذلك أول، يؤذن قبل دخول الخطيب، واستمر عليه العمل بعد عثمان  فإذا فعل فهو أحسن وإلا ما يضر، إذا اكتفي بأذان واحد لا حرج في ذلك، كما كان في عهد النبي ﷺ وعهد الصديق، وعهد عمر -رضي الله عنهما- لكن إذا جعل أذانًا ثانيًا للتنبيه على أنه يوم الجمعة حتى يستعد الناس، ويتأهبوا للجمعة هذا لا بأس به، بل هو حسن، وعليه العمل الآن لأن فيه فائدة كبيرة ينتبه الناس للجمعة ويستعدون. نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9244/حكم-الاكتفاء-باذان-واحد-في-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28814.mp3","categories":["صلاة الجمعة"]},{"id":11087,"question":"يقول: ما هو الحكم في خطبة الجمعة، هل هي واجبة؟ أم سنة؟ أم فرض؟ وهل هي من مكملات الصلاة؟ أفيدوني مأجورين.","title":"حكم خطبتي الجمعة","answer":"الجواب:  خطبة الجمعة شرط من شروط الصلاة؛ لأن الرسول ﷺ حافظ عليها، كان يخطب في الجمعة، ولم يتركها مرة واحدة، فهي شرط من شروط صحة صلاة الجمعة أن يخطب خطبتين؛ لقول النبي ﷺ: صلوا كما رأيتموني أصلي وكان يخطب خطبتين -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/9265/حكم-خطبتي-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28913.mp3","categories":["صلاة الجمعة"]},{"id":11160,"question":"إذا صليت صلاة الفجر في يوم العيد أو الجمعة، وبعد صلاتي أتوضأ مرة أخرى وأغتسل وأصلي صلاة حفظ الوضوء، فهل عملي هذا صحيح، ثم بعد ذلك أذهب إلى صلاة العيد، وأجلس أقرأ القرآن، ويوم الجمعة أصلي صلاة الضحى بينوا لنا ذلك مشكورين، جزاكم الله خيرًا؟","title":"حكم الاغتسال للجمعة وللعيدين","answer":"الجواب:  هذا طيب، الإنسان إذا أراد صلاة الجمعة فيغتسل سنة، أما صلاة العيد لم يرد فيها نص، ولكن إذا اغتسل فلا بأس؛ لأنها تشبه الجمعة من جهة أنها صلاة فيها اجتماع، لكن النص جاء في صلاة الجمعة، يستحب لها الغسل والوضوء عند قراءة القرآن أفضل، ولكن لا يجب الوضوء إلا إذا كان يقرأ من المصحف، أما إذا كان يقرأ عن ظهر قلب فليس بواجب الوضوء، له أن يقرأ وإن كان على حدث، إذا لم يكن جنبًا، أما الجنب فلا يقرأ حتى يغتسل. فالمقصود من هذا: أن القراءة عن طهارة أفضل وأولى، لكن لا تجب إلا إذا كان يقرأ من المصحف، أما إذا كان يقرأ عن ظهر قلب فلا حرج عليه أن يقرأ وإن كان على غير طهارة، إلا إذا كان جنبًا فليس له أن يقرأ حتى يغتسل، أما الحائض والنفساء اختلف فيهما العلماء -رحمة الله عليهم- هل هما كالجنب أم لا؟ والصواب أنهما ليستا كالجنب؛ لأن مدتهما تطول، فالأقرب أن لهما والأظهر أن لهما القراءة في غير المصحف عن ظهر قلب؛ حفظًا للوقت، وحرصًا على الفائدة العظيمة من قراءة القرآن، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9348/حكم-الاغتسال-للجمعة-وللعيدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37112.mp3","categories":["صلاة الجماعة","صلاة الجمعة","صلاة العيدين","الصلاة على الميت"]},{"id":11222,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من مكة المكرمة، باعثتها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (أ. ع. ص) أختنا عرضنا لها قضية في حلقة مضت، وفي هذه الحلقة تسأل سماحتكم وتقول: بالنسبة للمرأة في يوم الجمعة، هل يجوز لها أن تصلي الظهر قبل أن تقام الخطبة في المسجد، وجهوها جزاكم الله خيرًا؟","title":"هل يجوز للمرأة أن تصلي الظهر قبل خطبة الجمعة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد. فإن المرأة عليها أن تصلي الظهر في الوقت بعد الزوال، سواء كان الخطيب قد خطب أم لم يخطب، ليس لها تعلق بالجمعة، عليها أن تتحرى الوقت فإذا زالت الشمس ودخل وقت الظهر تصلي، سواء كان الخطيب خطب للجمعة أم لم يخطب، لكن عليها التثبت وعدم العجلة حتى تعلم أن الوقت دخل، وأن الشمس قد زالت ثم تصلي الظهر بعد ذلك، وإن صلت مع الناس جمعة أجزأتها الجمعة، إن صلت مع الناس الجمعة فالحمد لله، تكفيها الجمعة. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم، هل تنصحونها بمتابعة التقويم سماحة الشيخ حتى تكون متيقنة من الزوال؟ الشيخ: التقويم ينفع، يعين على ذلك، التقويم، مراجعة التقويم يعين على ذلك، لكن لا تعجل، بعد التقويم بربع ساعة، ثلث ساعة، حتى تحتاط لدينها، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9414/هل-يجوز-للمراة-ان-تصلي-الظهر-قبل-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37313.mp3","categories":["صلاة الجمعة","وقت الصلاة"]},{"id":11227,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من مكة المكرمة، باعثتها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (أ. ع. ص) أختنا عرضنا لها قضية في حلقة مضت، وفي هذه الحلقة تسأل سماحتكم وتقول: بالنسبة للمرأة في يوم الجمعة، هل يجوز لها أن تصلي الظهر قبل أن تقام الخطبة في المسجد، وجهوها جزاكم الله خيرًا؟","title":"هل يجوز للمرأة أن تصلي الظهر قبل خطبة الجمعة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد. فإن المرأة عليها أن تصلي الظهر في الوقت بعد الزوال، سواء كان الخطيب قد خطب أم لم يخطب، ليس لها تعلق بالجمعة، عليها أن تتحرى الوقت فإذا زالت الشمس ودخل وقت الظهر تصلي، سواء كان الخطيب خطب للجمعة أم لم يخطب، لكن عليها التثبت وعدم العجلة حتى تعلم أن الوقت دخل، وأن الشمس قد زالت ثم تصلي الظهر بعد ذلك، وإن صلت مع الناس جمعة أجزأتها الجمعة، إن صلت مع الناس الجمعة فالحمد لله، تكفيها الجمعة. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم، هل تنصحونها بمتابعة التقويم سماحة الشيخ حتى تكون متيقنة من الزوال؟ الشيخ: التقويم ينفع، يعين على ذلك، التقويم، مراجعة التقويم يعين على ذلك، لكن لا تعجل، بعد التقويم بربع ساعة، ثلث ساعة، حتى تحتاط لدينها، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9414/هل-يجوز-للمراة-ان-تصلي-الظهر-قبل-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37313.mp3","categories":["صلاة الجمعة","وقت الصلاة"]},{"id":11520,"question":"مستمع رمز إلى اسمه بالحروف (ص. ع. ش) يقول: أرجو أن تتفضلوا ببيان قضيتي، وإيضاح ما فيها، يقول: إنني وبعض الأشخاص نذهب يوم الجمعة إلى أداء صلاة الجمعة في مسجد جامع في قرى مجاورة بالرغم من وجود مسجد جامع لدينا وبه خطيب، فهل يجب علينا أن نصلي في ذلكم المسجد، أم أنه لا مانع من أن يصلي الإنسان في الجامع القريب منه؟ جزاكم الله خيرًا.","title":"حكم الانتقال في صلاة الجمعة لمسجد بعيد مع وجود الأقرب","answer":"الجواب:  ليس هناك مانع من الانتقال من جامع إلى جامع ولو كان أبعد من الجامع الذي قربك، لا حرج أن تذهبوا إلى جامع آخر لمصلحة شرعية؛ لأن خطيبه أعلم وأفقه، أو لأنك تتأثر بخطبته أكثر، أو لأسباب أخرى شرعية. المقصود: أنه لا حرج، فليس من اللازم أن تصلي في الجامع الذي حولك إذا لم يترتب على تركك له مضرة، فأنت بالخيار ... تصلي في أي جامع، ولاسيما الجامع الذي يحصل لك فيه التأثر، والخشوع، والانتفاع، والفائدة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9702/حكم-الانتقال-في-صلاة-الجمعة-لمسجد-بعيد-مع-وجود-الاقرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38418.mp3","categories":["صلاة الجمعة"]},{"id":11533,"question":"بعد هذا رسالة بعث بها المستمع: محمد زياد السبع من شمال سيناء، يقول: بعض الأئمة في خطبة الجمعة، وأثناء الخطبة يقول: سمعونا للصلاة على النبي بين الفينة والأخرى، وأكثر من خمس أو ست مرات في الخطبة الواحدة، ويقول ذلك باللهجة العامية، فهل هذا جائز؟ جزاكم الله خيرًا.","title":"حكم قول الخطيب أثناء الخطبة: سمعونا الصلاة على النبي","answer":"الجواب:  هذا غير مشروع، هذا ليس بمشروع، لا يقول: سمعونا. بل الواجب عليهم الإنصات للخطبة، الواجب على الجماعة الإنصات للخطيب حتى يستفيدوا من خطبته، وإذا صلى على النبي ﷺ بينه وبين نفسه عند سماع ذكره ﷺ لا بأس سنة، لا يرفع صوته بينه وبين نفسه حتى لا يشوش على غيره. والواجب الإنصات على المأمومين ينصتون لخطبة الخطيب يوم الجمعة، ولا يتكلمون بشيء يشوش عليهم، أو على غيرهم، ولكن إذا صلى على النبي ﷺ بينه وبين نفسه عند مرور ذكره -عليه الصلاة والسلام- هذا هو المشروع، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9716/حكم-قول-الخطيب-اثناء-الخطبة-سمعونا-الصلاة-على-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38512.mp3","categories":["صلاة الجمعة"]},{"id":11652,"question":"ما حكم من ترك صلاة الجمعة مرة أو مرتين متواصلة بالرغم أنه غير راض عن ذلك، ولكن مغصوبًا بموافقة الكفيل، بحجة العمل، رغم أن الكفيل موجود بالمزرعة، ومعه سيارة؟","title":"حكم التخلف عن صلاة الجمعة","answer":"الجواب: على كل حال ترك الجمعة لا يجوز، وهو على خطر، صاحبها على خطر إذا تعمد تركها، عند جمع من أهل العلم يراه كافرًا إذا تعمد تركها، فالواجب الحذر، في الحديث الصحيح يقول ﷺ في الحديث الصحيح: لينتهين أقوام عن ودعهم الجمعات، أو ليختمن الله على قلوبهم، ثم ليكونن من الغافلين وقال: من ترك الجمعة ثلاث جمع بغير عذر؛ طبع الله على قلبه. فالحاصل أنه يجب عليه الحذر، وأن يتوب إلى الله إذا تركها، وأن يقضيها ظهرًا، ولا يجوز طاعة أحد في ذلك، لا رئيس العمل، ولا غيره، يجب تقديم طاعة الله ورسوله إذا كان قريبًا من المسجد بحيث يسمع النداء. أما إذا كان في محل بعيد في الصحراء، بعيد عن البلد؛ يصلي ظهرًا، لكن ما دام حول البلد يسمع النداء؛ يجب أن يصلي مع الناس الجمعة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9823/حكم-التخلف-عن-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38910.mp3","categories":["صلاة الجمعة"]},{"id":11655,"question":"المستمع: سامي من العراق بعث يسأل ويقول: هل هناك سنة قبلية لصلاة الجمعة، أو بعدية؟ أفيدوني جزاكم الله خيرًا.","title":"سنة الجمعة القبلية والبعدية","answer":"الجواب:  الجمعة ليس لها سنة راتبة قبلها، يصلي ما يسر الله له، ثنتين أو أربعًا أو أكثر من ذلك، لقول النبي ﷺ: من اغتسل يوم الجمعة، ثم أتى المسجد، فصلى ما قدر له، ثم أنصت إذا خرج الإمام، ولم يقدر له شيء قال: صلى ما قدر له فدل ذلك على أنه يصلي ما كتب الله له، يصلي تسليمة تسليمتين، ثلاث أربع أكثر حتى يخرج الإمام، فإذا خرج الإمام؛ ترك الصلاة بعد ذلك، وانتظر الخطبة حتى ينصت لها، أما بعدها فلها سنة راتبة: ثنتان أو أربع، الأربع أكمل والثنتان كافيتان، وإن صلى أربعًا هو أفضل؛ لقول النبي ﷺ: من كان مصليًا بعد الجمعة؛ فليصل بعدها أربعًا وفي لفظ يقول ﷺ: إذا صليتم بعد الجمعة، فصلوا أربعًا وكان ﷺ إذا صلى الجمعة أتى بيته؛ فصلى ثنتين، في بيته، دل على أن ثنتين كافيتان والأربع أفضل. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9838/سنة-الجمعة-القبلية-والبعدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29807.mp3","categories":["صلاة الجمعة"]},{"id":11715,"question":"رسالة بعث بها مستمع إرتيري من الرياض -يبدو أنه مقيم هناك- يقول (س. م) حمدان يسأل ويقول: يوجد بجوارنا مسجد -ولله الحمد- وتقام فيه الجمعة، ولكن للأسف الشديد الخطيب لا يحسن الخطبة، ويتحدث في مواضيع لا تفيد كثيرًا، فهل يجوز لنا الذهاب لمسجد آخر أبعد منه؛ طلبًا للاستماع للخطبة الجيدة والمفيدة؟ جزاكم الله خيرًا.","title":"حكم صلاة الجمعة في المسجد الأبعد التماساً للخطيب المؤثر","answer":"الجواب:  نعم الإنسان يلتمس الخطب المؤثرة ولو بعدت، يلتمس الخطب المؤثرة، ويذهب إلى المساجد التي فيها الخطيب الجيد المؤثر، ولو بعد، وهذا الخطيب الذي ليس عنده بصيرة تبلغ الجهات المختصة حتى تلتمس من يقوم مقامه ممن هو خير منه، الجهات المختصة تبلغ عن هذا الخطيب الذي لا يصلح؛ حتى يلتمس من يقوم مقامه من أهل الخير. نعم. المقدم: الله المستعان، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9896/حكم-صلاة-الجمعة-في-المسجد-الابعد-التماسا-للخطيب-الموثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_392/39209.mp3","categories":["صلاة الجمعة"]},{"id":11750,"question":"المستمع عرفة عبدالمولى محمد علي من قرية الأعقاب في محافظة أسوان جمهورية مصر العربية، بعث برسالة وضمنها جمعًا من الأسئلة، في أحدها يقول: ماذا يقول الإنسان عندما ينوي الصلاة، وأعني بالذات صلاة الجمعة؟","title":"كيفية عقد النية قبل صلاة الجمعة","answer":"الجواب:  ينوي بقلبه ويكفي، لا يقول شيئًا إلا التكبير، ينوي بقلبه الصلاة مثل بقية الصلوات، ثم إذا كبر الإمام؛ كبر الله أكبر، ناويًا بقلبه صلاة الجمعة، مثلما يكبر ناويًا صلاة الظهر والعصر والمغرب والعشاء وصلاة العيد إلى غير ذلك. أما بعض ما يقول بعض الناس: نويت أن أصلي كذا، هذا لا أصل له، بدعة، لا يتلفظ بالنية، النية محلها القلب، فالتلفظ بها بدعة، سواء جهر، أو أسر، لا يجوز، ولكن ينوي بقلبه إذا قام إلى الصلاة، قام بنية الصلاة، فإذا كبر الإمام؛ كبر وقال: الله أكبر ناويًا بقلبه صلاة الجمعة، أو صلاة الظهر، أو صلاة الفجر إلى غير ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9932/كيفية-عقد-النية-قبل-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39313.mp3","categories":["صلاة الجمعة"]},{"id":11761,"question":"هل يجوز قراءة القرآن يوم الجمعة قبل الإمام حتى يستمع الحضور، ويستفيدوا، وذلك بصوت مرتفع؟","title":"حكم قراءة القرآن في المسجد بصوت مرتفع قبل الجمعة","answer":"الجواب:  إذا كان العدد محدود، ورضوا به، العدد محدود، ورضوا بأن يقرأ ويستمعون؛ فلا بأس، وإلا فليقرأ سرًا لا جهرًا حتى يتمكن كل واحد من القراءة، لا يشوش على غيره، هذا يقرأ، وهذا يقرأ بصوت ليس فيه تشويش، هذا هو المشروع، أما لو كانو جماعة محدودة مثل ... المسجد مثلًا في قرية صغيرة، جماعة محدودون، أربعون خمسون، ورضوا بأن يقرأ ويستمعون له؛ لحاجتهم إلى ذلك؛ فلا بأس بذلك. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9945/حكم-قراءة-القران-في-المسجد-بصوت-مرتفع-قبل-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39407.mp3","categories":["صلاة الجمعة"]},{"id":11865,"question":"بعد هذا رسالة وصلت إلى البرنامج من الجمهورية التونسية، وباعثها مستمع يقول: أخوكم في الله يوسف مفتاح، الأخ يوسف يقول: إنني أقطن بمنطقة نائية تبعد كثيرًا عن المسجد، وذلكم يمنعني من صلاة الجمعة، فهل لي أن أصلي صلاة الجمعة في بيتي أثناء نقلها مباشرة، وسماعها من الراديو؟ وجهوني جزاكم الله خيرًا.","title":"حكم الجمعة على من كان بعيداً عن المسجد","answer":"الجواب:  إذا استطعت أن تحضر؛ فعليك أن تحضر، إذا كنت تسمع النداء عند هدوء الأصوات؛ فعليك أن تحضر، أو كنت في طرف البلد؛ عليك أن تحضر مطلقًا، ولو بعدت، عليك أن تحضر الجمعة، أما إذا كنت بعيدًا خارج البلد، لا تسمع النداء، ويشق عليك الحضور؛ فلا حرج عليك، تصلي ظهرًا، لا تصلي جمعة، عليك أن تصلي ظهرًا أربع ركعات؛ لأن الجمعة إنما تصلى في الجماعة، أما الإنسان في بيته يصلي ظهرًا، لمرضه أو بعده، وهكذا النساء يصلين ظهرًا، أربع ركعات، لا يصلين جمعة، المرأة تصلي في بيتها ظهرًا أربع ركعات في كل مكان، وهكذا الرجل المريض الذي ما يحضر الجمعة يصلي ظهرًا أربع ركعات، وهكذا البعيد عن المساجد الذي لا يستطيع الحضور لبعده عن المساجد، ولا يسمع صوت المؤذن؛ فهذا يصلي ظهرًا أربع ركعات. لكن إذا تيسر لك ولو بالسيارة تحضر الخير، تشهد الجمعة؛ فهذا خير عظيم، أما إذا بعدت ولو بالسيارة لا يلزمك إذا كنت بعيدًا لا تسمع النداء عند هدوء الأصوات، أما سماعه بالمكبر فلا، يعني: يوجب الحضور إذا كنت بعيدًا، لكن إذا تجشمت المشقة، وصبرت، وجئت؛ فهذا خير لك عظيم..... سواء على رجليك، أو في السيارة، أو في الدراجة، أنت على خير عظيم.\nلكن لا يلزمك إذا كنت بعيدًا، إنما يلزمك إذا كنت قريبًا، تسمع صوت النداء عند هدوء الأصوات، تسمعه لو كانت الصلاة هادئة تسمعه، لقول النبي ﷺ: من سمع النداء، فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس: ما هو العذر؟ قال: خوف أو مرض، وفي الحديث الآخر يقول ﷺ لما سأله رجل أعمى قال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، هل لي من رخصة أن أصلي في بيتي؟ فقال -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10055/حكم-الجمعة-على-من-كان-بعيدا-عن-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39718.mp3","categories":["صلاة الجمعة"]},{"id":11937,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الطائف، باعثها أحد الإخوة المستمعين، اسمه المعتصم، يسأل سماحتكم شيخ عبدالعزيز فيقول: هل يجوز أن تصلي المرأة بالنساء؟ وإذا كان الجواب نعم، هل لهن أجر الجماعة؟ جزاكم الله خيرًا.","title":"حكم إمامة المرأة بالنساء","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا بأس أن تصلي المرأة بالنساء، قد ورد ذلك من فعل عائشة وأم سلمة -رضي الله عنهما- ونرجو لهن في ذلك فضل الجماعة، وأجر الجماعة، وفيه مصالح؛ لأن إمامتها للنساء فيه فوائد من التعليم والتوجيه، كل واحدة تتعلم من أخواتها ما تحتاج إليه في صلاتها، ولا سيما إذا كانت الإمامة متعلمة، وقد يكون فيهن أيضًا متعلمات؛ فيستفدن جميعًا، فصلاتهن جماعة فيها مصالح كثيرة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10121/حكم-امامة-المراة-بالنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42801.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":11950,"question":"المستمع صلاح القرشي بعث يسأل ويقول: ما حكم من دخل المسجد في الركعة الأخيرة في صلاة الجمعة، ولم يدرك منها إلا الركوع، هل يتمها ظهرًا أم جمعة؟","title":"حكم من أدرك الإمام في ركوع الركعة الأخيرة من الجمعة","answer":"الجواب:  من أدرك الإمام في صلاة الجمعة في الركوع الثاني؛ أتمها جمعة؛ لما جاء في الحديث عنه ﷺ أنه قال: من أدرك ركعة من الجمعة؛ فليضف إليها أخرى، وقد تمت صلاته ويقول ﷺ: من أدرك ركعة من الصلاة؛ فقد أدرك الصلاة.  والصلاة تدرك بالركوع، فإذا جاء والإمام راكع؛ ركع معه، وإذا سلم الإمام؛ قام فأتى بالركعة الفائتة، وتسقط عنه الفاتحة؛ لأنه فاته القيام، فصلاته صحيحة. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10135/حكم-من-ادرك-الامام-في-ركوع-الركعة-الاخيرة-من-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42814.mp3","categories":["صلاة الجمعة"]},{"id":11954,"question":"ما حكم الكلام مع الخطيب في يوم الجمعة؟","title":"حكم الكلام مع الخطيب أثناء خطبة الجمعة","answer":"الجواب:  إذا دعت الحاجة لا بأس، إذا دعت الحاجة أن يكلم الخطيب يقول: ادع الله استغث لنا، ادع الله لنا إنا في جدب في حاجة، أو يسأله عن شيء ينفع الناس؛ فلا بأس، فقد تقدم بعض الناس إلى النبي ﷺ وهو يخطب الجمعة فقال: \"يا رسول الله! هلكت الأموال، وانقطعتت .... السبل، فادع الله أن يغيثنا، فاستغاث، عليه الصلاة والسلام\" اللهم صل عليه وسلم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10139/حكم-الكلام-مع-الخطيب-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42818.mp3","categories":["صلاة الجمعة"]},{"id":12055,"question":"يسأل حول خطبة الجمعة، فيقول: هل يجب أن تكون خطبة مأثورة عن النبي ﷺ، أم تكون خطبة مرتجلة لمكافحة الخطايا التي تنشأ في المجتمع، بمعنى: هل يجب أن تكون الخطبة معاصرة، أم كيف توجهون الناس؟ جزاكم الله خيرًا.","title":"ضرورة مناسبة موضوع خطبة الجمعة لواقع الناس","answer":"الجواب: الخطب ليست توقيفية، فالإنسان يخطب بما يسر الله له، وإن لم يكن خطب بخطبة النبي، عليه الصلاة والسلام. المقصود: أن الخطب في الجمع والأعياد والمواعظ ليست توقيفية، لا يخطب الإنسان إلا بالشيء المنقول عن النبي -عليه الصلاة والسلام- لا، بل يخطب بما دل عليه الكتاب والسنة، ولو لم يحفظ هذا منقولًا عن النبي ﷺ أنه خطب بذلك، فيخطب يوم الجمعة بما يعظ الناس، وينفعهم في كل زمان، وفي كل عصر بما يناسبه، ففي الأماكن التي يكثر فيها الخمر؛ يعظ الناس في الخمر، ويحذرهم من الخمر، ويبين لهم أنه من الكبائر العظيمة، وما فيه من المفاسد والأخطار، وإذا كان في بلد كثر فيها الربا؛ يحذرهم من الربا، ويبين لهم شدة تحريم الربا، وإذا كان في بلد كثرت فيه الغيبة والنميمة؛ حذرهم من ذلك، وإذا كان في بلد كثر فيه الزنا واللواط؛ حذرهم من ذلك، وإذا كان في بلد كثر في الإعراض والغفلة والجهل؛ حثهم على طلب العلم، والتفقه في الدين، وأرشدهم إلى حلقات العلم، وإلى العلماء حتى يتعلموا، فهو يخاطب كل قوم بما يناسبهم، وبما هو أنسب لحالهم ولمعلوماتهم. المقصود: أنه يتحرى ما هو الأنفع في كل زمان، وفي كل مكان، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10240/ضرورة-مناسبة-موضوع-خطبة-الجمعة-لواقع-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43404.mp3","categories":["صلاة الجمعة"]},{"id":12071,"question":"المستمع محمد أحمد بن عبدالحكم من السودان بعث يسأل ويقول: حدث أن خطب الإمام يوم الجمعة خطبة واحدة، وهو رجل صلى بالنيابة عن الإمام لغياب الإمام، وهو كبير السن، وبعد نهاية خطبته الأولى قال للناس: قوموا للصلاة، فالناس قاموا وصلوا، ثم اختلف بعد ذلك كثيرًا من الناس، هل الصلاة صحيحة، أو لا؟ وأردنا من سماحتكم الإفادة، جزاكم الله خيرًا.","title":"حكم من خطب الجمعة خطبة واحدة","answer":"الجواب:  الصلاة غير صحيحة، فعليه أن يرجع، ويخطب الخطبة الثانية، ثم يعيد الصلاة، فلابد من خطبتين كما فعل النبي ﷺ وهما شرط لصحة الصلاة، هذا هو الأصح، فعلى هذا الرجل أن يعيد الصلاة، وأصحابه عليهم أن يعيدوا، عليه وعلى أصحابه أن يعيدوا الصلاة ظهرًا، وفي المستقبل لابد من خطبتين قبل الصلاة، نعم. المقدم: جزاكم الله خيرًا. السؤال: إذًا: يعيدون تلك الصلاة سماحة الشيخ؟ الجواب: ظهرًا، يعيدونها ظهرًا. المقدم: يعيدونها ظهرًا. الشيخ: نعم. أربع ركعات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10256/حكم-من-خطب-الجمعة-خطبة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43504.mp3","categories":["صلاة الجمعة"]},{"id":12263,"question":"مجموعة من الإخوة بعثوا بسؤالٍ يقولون فيه: نحن مجموعة من الأشخاص لا يزيد عددنا عن ستة، ويتعذر علينا حضور صلاة الجمعة؛ لأن أقرب جامع يبعد عنا خمسةً وستين كيلو، فنضطر لصلاة الجمعة ظهرًا، فهل علينا حرج في ذلك؟ نرجو الإفادة، جزاكم الله خيرًا.","title":"حكم صلاة الجمعة لستة أشخاص","answer":"الجواب:  لا حرج عليكم في ذلك، والحمد لله، لكن لو صليتم جمعة، صح ذلك في أصح قولي العلماء؛ لأن الجمعة تصح بثلاثة، فأكثر إذا كنتم مستوطنين، مقيمين في قرية، شتاءً وصيفًا، فإنكم من أهل الجمعة، على الصحيح، ولو كنتم ثلاثة، بدلًا من ستة، الصحيح أنها تنعقد الجمعة منكم، وتصح منكم الجمعة، فينبغي أن تقيموها في محلكم هذا إذا كنتم مقيمين مستوطنين في المحل، إقامةً تامة في بناء في بيوت فصلوا جمعةً، هذا هو الأرجح والأولى بكم، أما الماضي فصلاتكم صحيحة والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10463/حكم-صلاة-الجمعة-لستة-اشخاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44914.mp3","categories":["صلاة الجمعة"]},{"id":12355,"question":"مستمع رمز إلى اسمه بالحروف (أ. ل. س) من جمهورية مصر العربية يقول: أعمل في داخل المملكة في مزرعة، وأصلي كل أوقاتي في المزرعة، ولكن لا أصلي صلاة الجمعة في المسجد؛ لأني حينئذ في وقت العمل، وصاحب المزرعة لا يسمح لي بالخروج من المزرعة، والمسجد يبعد عني قرابة كيلو ونصف، فما هو توجيهكم؟","title":"حكم حضور صلاة الجمعة لحارس في مزرعة","answer":"الجواب:  أما الجمعة فعليك أن تصلي صلاة الجمعة، ولا يجوز لصاحبك أن يمنعك من الجمعة إلا إذا كان هناك خطر على المال الذي عندك، وأنت حارس له، فالحراسة عذر، أما إذا أمكن أن تصلي وليس هناك خطر على ما تحت يدك فإنك ... تصلي جمعة، لأن المسافة المذكورة لا تمنع من سماع النداء، وهكذا الصلوات الخمس عليك أن تصلي مع الجماعة، إلا إذا كنت حارسًا على أموال تخاف عليها لو ذهبت، فأنت في حكم الحارس المعذور، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10555/حكم-حضور-صلاة-الجمعة-لحارس-في-مزرعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39913.mp3","categories":["صلاة الجمعة"]},{"id":12379,"question":"يحيى من اليمن يقول: أعيش في قرية صغيرة، ويوجد في هذه القرية جامع، وعدد سكان القرية قرابة العشرين رجلًا، إضافة إلى الأطفال، وعندنا سوق، وموعده هو يوم الجمعة، ونضطر في هذا اليوم للذهاب إلى السوق لشراء بعض الأغراض، فلا يبقى في القرية إلا عشرة أشخاص أغلبهم صغار السن، فهل يجب على هذا العدد إقامة صلاة الجمعة، علمًا بأنه من الصعوبة أن نترك السوق؛ لأنه الوسيلة لشراء مستلزماتنا، وبيع ما عندنا؟","title":"العدد الذي تقام به الجمعة","answer":"الجواب:  إذا كان في العشرة ثلاثة مكلفون مستوطنون، فإنها تقام بهم الجمعة، والحمد لله، والباقي تبع، أما إذا كانوا كلهم صغارًا، ما فيهم ثلاثة، كلهم صغار، أو ما فيهم إلا واحد كبير، أو اثنان؛ يصلون ظهرًا، أما إذا كان فيهم ثلاثة، فأكثر مكلفون بالغون مستوطنون أحرار؛ فإنهم يصلون جمعةً، والباقي من الصغار تبع لهم في ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، سماحة الشيخ! هل تنصحونهم بتغيير يوم السوق من يوم الجمعة إلى يوم آخر؟ الشيخ: هذا مناسب، إذا تيسر؛ هو أطيب؛ لأجل الجمع بين المصلحتين، يتفرغون لهذا السوق، ويصلون الجمعة كاملة جميعًا، فإذا تيسر أن يحول السوق من يوم الجمعة إلى يوم الخميس، أو السبت؛ فهذا أحوط، نعم. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10592/العدد-الذي-تقام-به-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40111.mp3","categories":["صلاة الجمعة"]},{"id":12454,"question":"يسأل ويقول: ما هي الشروط اللازمة للخطيب، وهل تصح خطبة من هو أعزب، إذا لم يوجد غيره في البلد؟","title":"ما يشترط في الخطيب","answer":"الجواب:  شروط الخطيب أن يكون ذا علم، ذا بصيرة، أو يخطب من كتاب مأمون، قد وضعه أهل العلم والبصيرة، فيخطب منه على الناس، إذا كان صوته يسمع الناس، أو من طريق المكبر وكان عدلًا، أما إذا كان معروفًا بالمعاصي؛ فينبغي ألا يولى الخطابة، ينبغي أن يولى أهل العدل، وأهل الخير والفضل. فالمقصود: أن الخطيب إذا كان مسلمًا؛ صحت صلاته، وصحة خطبته؛ إذا حصل المقصود بها، من وعظ الناس، وتذكيرهم من جهة نفسه لكونه عالمًا، أو من كتاب يحصل به المقصود مما ألف في خطب الجمعة؛ فلا حرج في ذلك، وينبغي للمسؤولين ألا يولوا إلا أهل الفضل والعدالة والاستقامة، لكن لو قدر أنه ذو معصية، وصلى بالناس؛ صحت صلاته على الصحيح، مادام مسلمًا، فالمعصية لا تبطل صلاته، ولا صلاة من خلفه، لا جمعة ولا جماعة، لكن المسؤولين المشروع لهم، والواجب عليهم أن يتحروا في ذلك، وأن يجتهدوا في تولية الأخيار، وألا يولوا على أمور المسلمين لا في الإمامة، ولا في الأذان، ولا في الخطابة؛ إلا من عرف بالخير والاستقامة والأهلية للخطابة؛ لأنه ذو علم وبصيرة وللإمامة؛ لأنه ذو فضل وبصيرة، وصالح للإمامة. وهكذا في الأذان؛ لأنه ذو أمانة وعدالة وصوت حسن، فالمسؤولون يختارون لهذه المسائل، لهذه الوظائف من هو أهل لها، وإذا علموا أن هذا الرجل ليس صالحًا لهذه الوظيفة، إما لعي في لسانه، ما يصلح أن يكون خطيبًا، أو لأنه معروف بالمعاصي، أو بالبدعة؛ فلا يولى.  وهكذا الإمام لا يولى إذا كان معروفًا بالمعاصي، لا يولى على المسلمين إلا خيارهم وأفاضلهم، ومن هو صالح للإمامة لحسن تلاوته، وعدالته في نفسه، وكونه أهلًا للصلاة في طمأنينته، وأدائه حق الصلاة، وهكذا الخطيب يكون أهلًا لذلك كونه يحسن الخطابة، ولأنه ذو علم وفضل، أو لأنه يخطب من كتاب معروف معتمد من تأليف أهل العلم والبصيرة المعروفين بالاستقامة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10659/ما-يشترط-في-الخطيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45608.mp3","categories":["صلاة الجمعة"]},{"id":12491,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية مصر العربية محافظة الفيوم، باعث الرسالة مستمع رمز إلى اسمه بالحروف (ط. ش)، أخونا يسأل جمعًا من الأسئلة، أولها هذا السؤال، يقول: هل يجب على الخطيب عندما يصعد على المنبر أن يضع شيئًا على رأسه، على سبيل المثال العمامة، وهل يجوز للشاب غير المتزوج أن يكون خطيبًا؟ جزاكم الله خيرًا.","title":"هل يشترط في الخطيب أن يلبس عمامة؟ وأن يكون متزوجاً؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالسنة أن يكون للمؤمن إذا قصد الصلاة أن يأخذ زينته، ويوم الجمعة بوجه أخص، يستحب فيه أخذ الزينة، قال الله -جل وعلا-: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31] فالسنة للخطيب وغيره أخذ الزينة يوم الجمعة، ويوم العيد، وإذا كان غطاء الرأس في بلده معروفًا ومن الزينة؛ شرع له ذلك، وإذا كان أهل بلده لا يعتادون ذلك؛ فلا حرج. ولكن غطاء الرأس بالعمامة المعتادة، والزينة المعتادة يكون أفضل، وليس شرطًا؛ لأن الرأس ليس بعورة، والشاب له أن يكون خطيبًا وإن لم يتزوج، إذا كان أهلًا لذلك، إذا كان عنده علم، وعنده بصيرة، معروف بالخير؛ فلا حرج أن يكون خطيبًا، وليس من شرط الإمامة، أو الخطابة أن يكون الخطيب، أو الإمام ذا زوجة نعم. المقدم: بارك الله فيكم، وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/10690/هل-يشترط-في-الخطيب-ان-يلبس-عمامة-وان-يكون-متزوجا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40601.mp3","categories":["صلاة الجمعة"]},{"id":12496,"question":"رسالة وصلت إلى البرنامج من محافظة الحديدة في اليمن، باعثها المستمع علي بن أحمد، الأخ علي يسأل سماحتكم عن الشروط التي لا بد أن تتوفر في خطيب الجمعة؟ جزاكم الله خيرًا.","title":"الشروط الواجب توافرها في الخطيب","answer":"الجواب:  خطيب الجمعة يجب أن يكون ممن تتوافر فيه العدالة، ويفهم كيف يخطب؟ كيف يخطب الناس؟ وبعض أهل العلم يشترط فيه أن يكون مكلفًا، ولكن ولو صلى غير مكلف؛ أجزأ، فإن إمامة غير المكلف مجزئة، كما أم عمرو بن سلمة جماعته، والرسول ﷺ يقول: يؤم القوم أقرؤهم لكتاب الله فإذا كان قارئًا، يجيد الخطبة؛ فالحمد لله. والأولى أن يكون مكلفًا معروفًا بالخير، معروفًا بالعدالة الظاهرة، معروفًا بالخير حتى تطمئن قلوب الجماعة، ولكن ليس شرطًا أن يكون مكلفًا، وليس شرطًا أن يكون من أعلم الناس، أن يكون عالمًا، بل متى أحسن الخطبة، ولو كان ليس بعالم، متى أحسن الخطبة، ولو من صحيفة؛ أجزأ ذلك، وإذا كان معروفًا بالعدالة والاستقامة هذا هو الواجب، يكون معروفًا بالعدالة والاستقامة والسيرة الحميدة، هذا هو الواجب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10697/الشروط-الواجب-توافرها-في-الخطيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40608.mp3","categories":["صلاة الجمعة"]},{"id":12501,"question":"أيضًا يسأل عن الشروط التي لا بد أن تتوفر في خطيب الجمعة.","title":"شروط خطيب الجمعة","answer":"الجواب:  ينبغي أن يختار لخطبة الجمعة أهل العلم والبصيرة والتقوى، هكذا على المسؤولين في الأوقاف وغيرها، المسؤولين في تعيين الخطباء، الواجب أن يتحرى فيهم العلم والفضل والتقوى والعدالة وحسن السمعة؛ حتى يوجهوا الناس إلى الخير، وحتى يكونوا قدوة صالحة في أخلاقهم وأعمالهم، هكذا يختار للخطبة، الرجل المعروف بالعلم والفضل والسيرة الحميدة، والسمعة الحسنة، والصوت الحسن، هذا ينفع الله به الناس في علمه، وفي أخلاقه، وفي سيرته، ويكون قدوة في أخلاقه، نافعًا في علمه، وتوجيهاته، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10721/شروط-خطيب-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40715.mp3","categories":["صلاة الجمعة"]},{"id":12543,"question":"رجل تأخر عن صلاة الجمعة، فأدرك التشهد، ورجل تأخر عن صلاة الجمعة، فأدرك الركعة الثانية، ما العمل في كلا الحالتين؟ هل يتم الصلاة أربع ركعات، أم ركعتين؟","title":"حكم من أدرك ركعة من الجمعة أو أدرك التشهد","answer":"الجواب:  الذي أدرك الجمعة، أدرك ركعة من الجمعة هذا قد أدركها، هذا يضيف إليها أخرى بعد سلام الإمام، يأتي بركعة ثانية، ثم بعد التشهد والدعاء يسلم، وقد تمت جمعته، لما جاء في الحديث عنه ﷺ أنه قال: من أدرك ركعة من الجمعة؛ فليضف إليها أخرى، وقد تمت صلاته ولقوله ﷺ: من أدرك ركعة من الصلاة؛ فقد أدرك الصلاة. أما الذي أدرك التشهد فقط؛ فهذا يصلي ظهرًا، فاتته الجمعة، فإذا كانت الشمس قد زالت؛ صلى الظهر، وأما إن كان ما زالت الشمس، فإنه لا يصلي إلا بعد زوال الشمس؛ لأن بعض الناس قد يصلي الجمعة قبل زوال الشمس قد يبكر، والذي ينبغي للخطباء والأئمة أن يتأخروا حتى تزول الشمس، لأن الجمهور من أهل العلم يرون أنها لا تجزئ إلا بعد الزوال كالظهر. وذهب بعض أهل العلم: إلى أنها تجزئ قبل الزوال، لأدلةٍ وردت في ذلك، لكن الأحوط للمؤمن أن يتأخر حتى يصليها بعد الزوال؛ خروجًا من الخلاف، فإذا جاء المتأخر، وأدرك الإمام في التشهد، وقد زالت الشمس؛ فإنه يصلي أربعًا، إذا سلم الإمام يقوم فيصلي أربعًا بنية الظهر. أما إذا كان ما زالت الشمس؛ فإنه يصلي ركعتين نافلة، ويصلي الظهر بعد ذلك في بيته، أو في المسجد، أو في أي مكان. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10748/حكم-من-ادرك-ركعة-من-الجمعة-او-ادرك-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45611.mp3","categories":["صلاة الجمعة"]},{"id":12875,"question":"مستمع بعث برسالة مطولة، وضمنها جمعًا من الأسئلة، من بينها سؤال يقول فيه: هناك بعض الناس يصلون قبل صلاة الجمعة عشر ركعات، وبعد صلاة الجمعة عشر ركعات، ويقولون: إنها لازمة، هل ما قالوه صحيح؟","title":"حكم القول بلزوم عشر ركعات قبل الجمعة وبعدها","answer":"الجواب:  ليس بصحيح، لا يلزم قبلها شيء، ولا بعدها شيء، لا يلزم لا قبلها ولا بعدها، لكن يستحب للمؤمن إذا جاء المسجد يوم الجمعة أن يصلي ما كتب الله له قبل الإمام، قبل حضور الإمام يصلي ثنتين، أربعًا، ستًا، ثمانًا، أكثر يسلم من كل ثنتين، لقوله ﷺ في الأحاديث الصحيحة: من اغتسل، ثم أتى الجمعة، فصلى ما قدر له، ثم أنصت إذا خطب الإمام .. إلى آخره، فلم يقدر صلاة، بل قال: صلى ما قدر له فهو يصلي ما يسر الله له، حين يصل المسجد ثنتين تحية المسجد، أو يزيد يصلي تسليمتين، ثلاث تسليمات، أربع تسليمات، أكثر أقل؛ لا حرج في ذلك، أقلها ولو تسليمة واحدة، أقل ذلك بتسليمة واحدة تحية المسجد، أما أن يلزمه شيء لا يلزمه شيء لا عشر ولا غيرها. وهكذا بعدها، لا يلزمه عشر ولا غيرها، ولكن يستحب له أن يصلي بعدها أربعًا، هذا هو الأفضل، لقوله ﷺ: إذا صليتم الجمعة؛ فصلوا بعدها أربعًا وفي اللفظ الآخر: من كان مصليًا بعد الجمعة؛ فليصل بعدها أربعًا هذا هو الأفضل وليس بلازم بل سنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11090/حكم-القول-بلزوم-عشر-ركعات-قبل-الجمعة-وبعدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46607.mp3","categories":["صلاة الجمعة"]},{"id":12892,"question":"يسأل ويقول: ما هو قولكم في صلاة الجمعة خارج القرية أو المدينة، علمًا بأن الذين صلوا الجمعة خارج القرية، أو المدينة كانوا قد خرجوا للنزهة، أو ذهبوا إلى رحلة كما يقال، وقد جاؤوا بأدلة تثبت صلاة الجمعة خارج القرية، ونحن نعلم أن لصلاة الجمعة شروطَا -كما يقول- وجهونا جزاكم الله خيرًا؟","title":"حكم صلاة الجمعة على من سافر للنزهة","answer":"الجواب:  الواجب أن تصلى الجمعة مع المسلمين في المدن والقرى، أما صلاتها خارج البلد في أسفار النزهة فلا، يصلون ظهرًا، عليهم أن يصلوا ظهرًا، لا جمعة، وإنما تصلى الجمعة في المدن والقرى خاصة، هكذا جاءت الأحاديث عن رسول الله -عليه الصلاة والسلام- ولم يأمر البوادي التي حول المدينة، ولا المسافرين أن يصلوا جمعة، وقد وافقت حجته ﷺ يوم الجمعة، في يوم عرفة ما صلاها جمعة، صلى ظهرًا -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11107/حكم-صلاة-الجمعة-على-من-سافر-للنزهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_467/46707.mp3","categories":["صلاة الجمعة"]},{"id":12941,"question":"على بركة الله نبدأ هذا اللقاء برسالة المستمع سعد محمد يقول: ما حكم استعمال السواك والإمام يخطب، سواء كان ذلك في صلاة الجمعة، أو في صلاة العيدين والاستسقاء؟ وما حكم فرقعة الأصابع أثناء الصلاة ، جزاكم الله خيرًا؟","title":"حكم استعمال السواك أثناء استماع الخطبة","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن المشروع عند سماع الخطب الإنصات، والإصغاء، والتأثر بهذه الخطب؛ لأن المقصود منها وعظ الناس، وتذكيرهم، وحثهم على طاعة الله، وتنبيههم على ما يخفى عليهم. فالواجب العناية بالإنصات، والاستماع، والاستفادة، وترك السواك أولى؛ لأن وقت الاستماع ليس محل السواك، فالأولى ترك السواك؛ لأنه قد يكون شيء من العبث، فلا يتسوك في هذه الحالة، بل يعتني بالخطبة، ويصغي لها، ويقبل عليها بقلبه وقالبه. وهكذا فرقعة الأصابع وقت الصلاة، أو عند سماع الخطبة؛ لأنه نوع من العبث، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11157/حكم-استعمال-السواك-اثناء-استماع-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50201.mp3","categories":["صلاة الجمعة"]},{"id":12965,"question":"هذا السائل عبدالله من الأحساء .. المبرز، يقول في  ما المقصود بالساعة الأولى والساعة الثانية والثالثة والرابعة والخامسة من يوم الجمعة، هل هي الساعة المتعارف عليها، أم زمن نسبي، ومتى تبدأ الساعة الأولى؟","title":"المقصود بالساعة في الحديث: (من أتى في الساعة الأولى...)","answer":"الجواب:  الأقرب -والله أعلم- أنها تبدأ بعد ارتفاع الشمس قيد رمح؛ لأن هذا يشرع للمؤمن أن يجلس في مصلاه يذكر الله، ويدعو حتى ترتفع، فالأقرب -والله أعلم- أنها تدخل من ارتفاع الشمس، ويكون النهار مجزأ، ست ساعات ما بين خروجه من مسجده، أو من بيته إلى دخول الخطيب ست ساعات، تختلف لطول النهار، وقصر النهار، الساعة الأولى فيها بدنة، والذاهب في الساعة الثانية كأنما قرب بقرة، وفي الثالثة كأنما قرب كبشًا أقرن، وفي الرابعة كأنما قرب دجاجة، وفي الخامسة كأنما قرب بيضة، يكون ما بين ارتفاع الشمس إلى غروبها اثنا عشر ساعة، اثنا عشر ساعة مجزأة حسب طول النهار وقصره، نعم.  المقدم: شكر الله لكم -يا سماحة الشيخ- وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11182/المقصود-بالساعة-في-الحديث-من-اتى-في-الساعة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50221.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":12967,"question":"المستمع (م. س. م) من المدينة المنورة المليليح، بعث بعدد من الأسئلة من بينها سؤال يقول: إني أرى بعض الناس في يوم الجمعة يصلون، يقومون بعد الأذان الأول وهم يقولون: إنها سنة، فهل ما قالوه صحيح، وأنا سمعت في برنامجكم هذا أنها بدعة، أرجو الجواب الكافي؟ جزاكم الله خيرًا.","title":"حكم الصلاة بعد الأذان الأول يوم الجمعة","answer":"الجواب:  بعد الأذان الأول يوم الجمعة لا تشرع الصلاة بعد الأذان؛ لأنه شرع للتنبيه، وكان هذا بعد النبي ﷺ في خلافة عثمان  للتنبيه على أنه يوم الجمعة، ومن صلى؛ فلا حرج -إن شاء الله- لكن ترك ذلك أولى، ترك ذلك أولى، وبعض أهل العلم قال يصلي لعموم قوله ﷺ: بين كل أذانين صلاة بين كل أذانين صلاة. وهذا أذان شرعي، أحدثه الخليفة الراشد عثمان للمصلحة الشرعية، ولكن تركه أولى؛ لأنه ليس داخلًا في الحديث؛ لأن قوله ﷺ: بين كل أذانين صلاة مراده: الأذان والإقامة، وهذا ليس بين الأذان والإقامة، بين أذانين، بين الأذان الأول والأذان الثاني، فالأولى ترك ذلك، أما وصفه بأنه بدعة محل نظر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11184/حكم-الصلاة-بعد-الاذان-الاول-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47006.mp3","categories":["صلاة الجمعة"]},{"id":12969,"question":"يسأل أخونا ويقول: ما حكم رفع اليدين في الدعاء يوم الجمعة للمأمومين، ذلكم أني أرى هذه الظاهرة منتشرة بكثرة؟","title":"حكم رفع اليدين بالدعاء للمأمومين في خطبة الجمعة","answer":"الجواب:  أما حال الخطبة فلا يرفع الإمام، ولا يرفع المأمومون، ينصتون، ولا يرفعون أيديهم، ولا يرفعونها في الخطبة إلا في الاستسقاء، إذا استسقى طلب الغوث، طلب المطر؛ يرفع يديه، ويرفعون أيديهم معه، كما فعل النبي ﷺ والصحابة لما استسقى -عليه الصلاة والسلام- أما الخطبة العادية التي ليس فيها استسقاء، فإن السنة أنه لا يرفع هو، ولا يرفعون هم، ولو دعا، يدعو لكن من دون رفع. وهكذا خطبة العيد ليس فيها رفع إلا إذا استسقى، إذا طلب السقيا، طلب الغوث، طلب المطر؛ فإن السنة أنه يرفع يديه، والمأمومون كذلك يرفعون أيديهم في الجمعة، وفي غيرها، إذا استسقى يرفعون أيديهم حتى لو هو جالس بين أصحابه، لو جلس العالم بين أصحابه، واستسقى، ورفع يديه يرفعون أيديهم في حلقة العلم، أو في أي مكان، وهم محتاجون للغيث، ورفع يديه وهو في الحلقة قال: اللهم أغثنا، اللهم أغثنا، ورفعوا أيديهم، كله طيب، لا حرج في ذلك. ولا حرج في ذلك أيضًا إذا رفع الإنسان يديه يدعو ربه، يسأل ربه من فضله في بعض أوقاته في بيته، في المسجد، بعد صلاة النافلة، أو في أي مكان، إذا دعا ربه، ورفع يديه، فرفع اليدين من أسباب الإجابة، وفي الحديث عنه ﷺ أنه قال: إن ربكم حيي كريم، يستحي من عبده إذا رفع يديه إليه أن يردهما صفرًا يعني: خاليتين. فرفع اليدين من أسباب الإجابة، لكن المواضع التي لم يرفع فيها النبي ﷺ وقد وجدت في عهده لا نرفع فيها؛ لأن تركه حجة، وفعله حجة -عليه الصلاة والسلام- فخطبة الجمعة وخطبة العيد لم يرفع فيهما؛ فلا نرفع إلا إذا كان في الاستسقاء، في طلب الغيث، طلب الغوث والمطر.  وهكذا بعد الفرائض، إذا سلم من الفريضة ما كان يرفع يديه؛ فلا نرفع بعد الفريضة، وهكذا في دعاء آخر الصلاة قبل أن يسلم، كان يدعو قبل أن يسلم، ولم يرفع يديه، وهكذا بين السجدتين كان يدعو ولا يرفع يديه، فالشيء الذي ما رفع فيه النبي ﷺ وهو موجود في عهده، وقد فعله؛ نكون مثله لا نرفع أيدينا فيه -عليه الصلاة والسلام- تأسيًا به ﷺ في الفعل والترك -والله المستعان- نعم. المقدم: الله المستعان. جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11188/حكم-رفع-اليدين-بالدعاء-للمامومين-في-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47007.mp3","categories":["صلاة الجمعة"]},{"id":13006,"question":"يقول: عندنا عادة وهي: بعد صلاة كل جمعة نقوم بعد الصلاة بصلاة الظهر، وذلك بعد الانتهاء من صلاة الجمعة، فهل يجوز هذا، أم أنه بدعة؟","title":"حكم صلاة الظهر بعد صلاة الجمعة","answer":"الجواب:  صلاة الظهر بعد الجمعة بدعة، لا أصل لها، لم يفعلها سلف الأمة، لا الصحابة، ولا من بعدهم من سلف الأمة، بل هي بدعة ونوع وسوسة، كأنهم يقولون: لا ندري أصحت الجمعة، أم لا، وهذا وسواس لا وجه له، وشك لا وجه له. فالواجب على المؤمن حسن الظن بالله، وحسن الظن بما درج عليه المسلمون قبله، وعدم الشك الذي لا وجه له، ولا موجب له، فصلاة الجمعة كافٍ، والحمد لله، والله ما فرض على العباد إلا خمس صلوات في اليوم والليلة، فإذا صليت الظهر بعد الجمعة؛ جعلتها ستًا، وهذا لا يجوز، فصلاة الظهر بعد الجمعة بدعة، لا تجوز أبدًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11223/حكم-صلاة-الظهر-بعد-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47102.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":13038,"question":"صلاة الجمعة هل تصح بأقل من اثني عشر رجلًا؟","title":"أقل ما تنعقد به صلاة الجمعة","answer":"الجواب:  صلاة الجمعة في عددها خلاف كبير بين العلماء، وأرجح الأقوال ثلاثة، أقل جماعة ثلاثة، الإمام واثنان معه إذا كانوا مستوطنين في قرية مقيمين بها، تجب عليهم الجمعة فأكثر، أربعة، خمسة، عشرة، عشرين. أما القول بأنه لابد من اثني عشر، أو من أربعين؛ فلا أصل له، ليس عليه دليل واضح، وأقل ما قيل في ذلك: ثلاثة، وهو أرجحها؛ لأنها أقل جمع بالنسبة إلى الجمعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11255/اقل-ما-تنعقد-به-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47218.mp3","categories":["صلاة الجمعة"]},{"id":13069,"question":"السائل أيضًا له سؤال ثاني يقول: هل تصلى الظهر بعد صلاة الجمعة، فبعض الناس بعد أن يصلي الجمعة يصلي بعدها أربع ركعات، هل هذا صحيح؟","title":"حكم المداومة على صلاة الظهر بعد صلاة الجمعة","answer":"الجواب:  لا، هذا بدعة لا يجوز، صلاة الجمعة كافية والحمد لله عن الظهر، وكونه يصلي الظهر بعدها هذه بدعة، يقول بعض الناس: إنه إذا كان في البلد جمعات كثيرة ... أخشى أن هذه الجمعة ما صحت، هذا من وساوس الشيطان، فلا يجوز أن تصلى الظهر بعد الجمعة، بل يجب أن يكتفي بالجمعة، لكن من فاتته الجمعة، جاء وقد صلوا، أو مريض ما حضر الجمعة، أو مسافر؛ يصلي ظهرًا. وأما من صلى الجمعة؛ فليس عليه صلاة ظهر، بل صلاة الظهر مع الجمعة جميعًا بدعة، لا في المسجد، ولا في غير المسجد، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11286/حكم-المداومة-على-صلاة-الظهر-بعد-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50702.mp3","categories":["صلاة الجمعة"]},{"id":13176,"question":"يقول: في بلدي تعودنا في القرية في يوم الجمعة، وقبل الصلاة أن يشغلوا الإذاعة، أي: إذاعة القرآن الكريم من مكبرات الصوت، ويبدأ القاري في قراءة القرآن حتى أذان الجمعة، فما حكم الإسلام في هذا العمل، جزاكم الله خيرًا؟","title":"حكم فتح القرآن في المسجد بمكبرات الصوت في يوم الجمعة","answer":"الجواب:  أما إذاعة القرآن من الإذاعة العامة للناس هذا فيه خير كثير.\nأما إذاعة القرآن بين المصلين في المسجد فهذا لا أصل له؛ لأنه يشوش على القراء، ويشوش على المصلين، فالواجب ترك ذلك حتى يقرأ من شاء، ويصلي من شاء، لا يشوش على الناس، كونه تشغل الإذاعة في المسجد حتى يقرأ القاري، والناس الذين يصلون، والناس يقرؤون، هذا لا أصل له، فالواجب تركه حتى يقرأ من يقرأ لنفسه، وحتى يسبح من يسبح، وحتى يصلي من يصلي، ولا يشوش عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11431/حكم-فتح-القران-في-المسجد-بمكبرات-الصوت-في-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51112.mp3","categories":["صلاة الجمعة","المساجد ومواضع السجود"]},{"id":13295,"question":"في آخر أسئلته يقول يا سماحة الشيخ: هل تجوز صلاة الجمعة لثلاثة أشخاص إذا كانوا في الصحراء، أو متابعة ذلك على الراديو، وماذا يصلونها مأجورين؟","title":"حكم صلاة الجمعة على أهل البادية والصحراء","answer":"الجواب: صلوا ظهرًا، في الصحراء صلوا ظهرًا، وليس لكم جمعة، أنتم في حكم المسافرين إن كنتم مسافرين، أو في حكم غير المسافرين كالبادية، ليس عليكم جمعة، ولو كنتم غير مسافرين؛ لأن البادية ليس عليهم جمعة، يصلون ظهرًا، والمسافر ليس عليه جمعة، يصلي ظهرًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11580/حكم-صلاة-الجمعة-على-اهل-البادية-والصحراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50924.mp3","categories":["صلاة الجمعة"]},{"id":13299,"question":"السائل (ع. ف. ر) مصري الجنسية يقول: أعمل بمزرعة في مدينة الرياض حارس على بوابة، وقد طلب مني ألا أترك البوابة يوم الجمعة ما دام صاحب المزرعة موجودًا، وأنا أصلي صلاة الجمعة داخل غرفتي المجاورة للبوابة، مع العلم بأن المزرعة بها مسجد، ولكن سيغضب هذا الشخص صاحب هذه المزرعة عندما أذهب إلى المسجد البعيد، فهل يجوز لي أن أصلي داخل الغرفة؟","title":"حكم صلاة الجمعة للحارس في المزرعة","answer":"الجواب: عليك أن تصلي ظهرًا، لك عذر شرعي في عدم حضور الجماعة، الحارس معذور، الحارس معذور، فيصلي ظهرًا، لا يصلي جمعة، يصلي الظهر أربعًا، ولا يصلي جمعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11584/حكم-صلاة-الجمعة-للحارس-في-المزرعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52207.mp3","categories":["صلاة الجمعة"]},{"id":13325,"question":"السائل يقول في هذا  سماحة الشيخ! هل تجوز الصلاة في مسجد يهجر أكثر من أربعة أشهر؟ وماذا علينا لو كانت صلاتنا غير صحيحة؟ وهل نعيد صلاة الجمعة أم ماذا نفعل؟","title":"حكم صلاة الجمعة في مسجد مهجور","answer":"الجواب: على أهل الحي أن يصلوا في المسجد المناسب لهم إذا كان مسجدًا مهجورًا، وهو مناسب لهم، وهو قريب منهم، وليس فيه محذور، يصلون فيه الحمد لله. فالمقصود: أن على أهل الحي -سكان الحي المعين- عليهم أن يقيموا مسجدًا لهم، يعمروا مسجدًا لهم إن استطاعوا، فإن لم يستطاعوا؛ صلوا في محل معين اتخذوه مصلى لهم، يصلون فيه، ويجتمعون فيه؛ لأن الصلاة في الجماعة أمر لازم، أوجب الله الصلاة في الجماعة، وأوجبها رسوله -عليه الصلاة والسلام- الله يقول: وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] وفي صلاة الخوف قال: وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ الصَّلاةَ فَلْتَقُمْ طَائِفَةٌ مِنْهُمْ مَعَكَ [النساء:102] فأمر بالجماعة حتى في صلاة الخوف، لكن إذا كان عندهم مسجد مهجور، وهو صالح؛ فإنهم يصلون فيه، والحمد لله يجتمعون فيه، ولا يهجرونه، وإذا كان بعيدًا عنهم، وتيسر لهم مسجد أقرب منه يعمرونه، ويجتمعون فيه؛ فذلك طيب، وحسن. المقصود: أنهم يعملون الشيء الذي يجمعهم، ويعينهم على أداء الصلاة جماعة، سواء كان مسجدًا مهجورًا، أو غير مهجور، إذا كان بعيدًا عنهم، ويشق عليهم؛ عمروا مسجدًا بينهم، متوسطًا بينهم حتى يجتمعوا فيه، ويصلوا فيه جميعًا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11611/حكم-صلاة-الجمعة-في-مسجد-مهجور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54107.mp3","categories":["صلاة الجمعة"]},{"id":13445,"question":"السائل عادل خفاجي له مجموعة من الأسئلة يقول: أين تقف الزوجة إذا صلت مع زوجها؟","title":"مكان وقوف المرأة إذا صلت مع زوجها","answer":"الجواب: إذا صلت مع زوجها؛ تقف خلفه، وإن كان معها نساء؛ يقفن معها، ولا تقف مع الرجل، لا مع زوجها، ولا مع غيره، هكذا علم النبي ﷺ النساء، كان يصلي في بعض الأيام ببعض النساء لما زارهم، فكانت المرأة خلفهم، فالمرأة تصلي خلف الرجال، ولو أنها واحدة، ولو أنه زوجها تصلي خلفه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11743/مكان-وقوف-المراة-اذا-صلت-مع-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52715.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":13480,"question":"رسالة وصلت إلى البرنامج من الجماهيرية الليبية وباعثها المستمع محمد علي شعبان، أخونا محمد يقول في أحد أسئلته: نحن نعمل في أحد الحقول النفطية بالصحراء، لدينا مسجد داخل الحقل، الحقل له بوابة واحدة، وأقرب منطقة عنده تقدر بحوالي أربعين كيلو مترًا، ليس هناك أحد مقيم داخل الحقل، أو خارجه بأسرته، وأطول مدة ممكن يقضيها أحدنا بالحقل أربعين يومًا تقريبًا، وليس لدينا إمام معين، و هل تصح في هذا المسجد صلاة العيد، وصلاة الجمعة؟ أفيدونا جزاكم الله خيرًا.","title":"حكم الجمعة والعيدين على من يعمل في حقول النفط بالصحراء؟","answer":"الجواب: ما دام الحال كما ذكره السائل فليس عليكم جمعة ولا عيد؛ لأنكم لستم مستوطنين؛ إنما تقيمون أربعين يومًا، ثم ترجعون إلى أهليكم، فأنتم في هذه الحالة كسكان البادية تصلون ظهرًا أربعًا وعصرًا أربعًا وهكذا. وليس عليكم جمعة، ما دام الأمر كما ذكرتم ليس هناك سكان، وإنما هم العمال يعملون أكثر ما يعملون أربعين يومًا، ثم يرجعون إلى أهليهم، ويأتي غيرهم، فعليكم الصلوات الخمس أن تصلوها جماعة، يؤمكم أفضلكم وأقرؤكم، وإذا اخترتم واحدًا يؤمكم هو أقرؤكم كان ذلك أولى وأفضل، وليس عليكم جمعة، ولا عيد. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11783/حكم-الجمعة-والعيدين-على-من-يعمل-في-حقول-النفط-بالصحراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47809.mp3","categories":["صلاة الجماعة","صلاة الجمعة","صلاة العيدين","الصلاة على الميت"]},{"id":13485,"question":"السؤال الأخير يقول: هل النساء تؤمهن واحدة منهن، وكيف يكون وقوفها؟ جزاكم الله خيرًا.","title":"صفة صلاة النساء جماعة","answer":"الجواب: إذا تيسر من يؤمهن فهو أفضل، يتعلمن، ويستفدن، وتكون وسطهن، عن يمينها، وعن شمالها لا تتقدم، بل تكون وسطهن، عن يمينها قوم، وعن شمالها قوم، ترفع صوتها بالقراءة؛ حتى يستفيدوا في المغرب والعشاء والفجر كالرجل، وتعظهن إذا تيسر ذلك، وتذكرهن، وتعلمهن بعد الصلاة، أو قبل الصلاة، وهن عن يمينها وشمالها وخلفها، ويخترن أفضلهن، أقرأهن وأفضلهن، وإن صلت كل واحدة وحدها فلا حرج، الحمد لله.. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11788/صفة-صلاة-النساء-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47814.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":13587,"question":"السائل من اليمن يقول في هذا  هل تجوز الصلاة على النبي ﷺ وقول: آمين عند دعاء الخطيب بالنسبة للمستمعين، أم يعتبر ذلك من اللغو؟","title":"حكم الصلاة على النبي ﷺ أثناء الخطبة","answer":"الجواب: لا بأس بالصلاة على النبي ﷺ من غير جهر يشوش على من حولك، إذا صلى الإمام .. ذكر النبي ﷺ تصلي عليه؛ لقوله ﷺ: رغم أنف امرئ ذكرت عنده فلم يصل علي فإذا سمعت الصلاة على النبي ﷺ تصلي عليه، بينك وبين نفسك من غير جهر، وهكذا غيرك؛ للحديث المذكور، وغيره من الأحاديث. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11922/حكم-الصلاة-على-النبي-ﷺ-اثناء-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53308.mp3","categories":["صلاة الجمعة"]},{"id":13594,"question":"يقول: هل يجوز تخصيص ليلة الجمعة لإقامة الليل؟ علمًا بأننا طلبة، وموظفون، ولكي ننتهز فرصة عطلة الجمعة للراحة لأن أحد الإخوان قال: يوجد حديث يدل على عدم تخصيص يوم، أو ليلة للعبادة. نرجو فتواكم جزاكم الله خيرًا.","title":"حكم تخصيص ليلة الجمعة بقيام","answer":"الجواب: نعم، لا يجوز تخصيص ليلة الجمعة بالتهجد؛ لأن الرسول نهى عن هذا -عليه الصلاة والسلام- ولا يجوز تخصيص يومها أيضًا بالصوم، النبي ﷺ قال: لا تخصوا يوم الجمعة بصيام إلا أن يكون في صوم يصومه أحدكم، ولا تخصوا ليلة الجمعة بقيام فلا تخص ليلتها بالقيام، ولا يومها بالصيام، وهكذا لا يجوز اتخاذ ليلة معينة يخصها الناس بالتهجد؛ لعدم الدليل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11925/حكم-تخصيص-ليلة-الجمعة-بقيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48008.mp3","categories":["صلاة الجمعة"]},{"id":13689,"question":"بعد ذلك ننتقل إلى رسالة هذا السائل الذي رمز لاسمه بـ (ص. ع. ش) السؤال هو: أنني وبعض الأشخاص نذهب يوم الجمعة إلى أداء صلاة الجمعة في مسجد جامع في قرى مجاورة بالرغم من وجود مسجد جامع لدينا، وبه خطيب، فهل يجب أن يصلي الشخص في الجامع الموجود في قريته؟ أم أنه يصلي الجمعة في أي جامع آخر؟ والسلام عليكم.","title":"حكم الذهاب للمساجد المجاورة لأداء الجمعة وترك مسجد القرية","answer":"الجواب:  لا حرج على المسلم أن يصلي في أي جامع، ولاسيما إذا كان الجامع الذي يقصده خطبة صاحبه أحسن وأنفع، أو صلاته أرشد، أو جماعته أكثر، لا بأس إذا ترك المسجد الذي حوله لمصلحة شرعية، وإن صلى في المسجد الذي قربه؛ فلا بأس والحمد لله، لكن إذا ترك المسجد الأقرب لمصلحة شرعية من أجل كثرة الخطى، أو من أجل أن خطيب ذلك المسجد أكثر فائدة، أو صلاته أكمل، أو لأسباب أخرى؛ فلا بأس. أما إذا ترك المسجد القريب على وجه -يعني- يشق على أهل تركه لهم، أو يوجب أنهم يتهمونه بأنه غير راض عن الإمام، أو يتهموا الإمام؛ ينبغي أن يدفع عن نفسه الشيء الذي يخشى منه، ينبغي يصلي مع هذا تارة، ومع هذا تارة؛ حتى لا تكون هناك شكوك وأوهام إذا كان إمام المسجد الذي حوله طيب، ولا شبهة فيه يصلي معه بعض الأحيان؛ حتى لا يظن أنه ظن به السوء، أو أنه لا يصلح. المقصود: إذا كانت صلاته في المسجد البعيد لا يترتب عليها شيء من المضار؛ فلا بأس، ولاسيما إذا كان تجاوزه هذا المسجد قد يسبب ظنًا بإمامه، وأنه ليس أهلًا للإمامة، فينبغي له أن يصلي فيه بعض الأحيان حتى تزول هذه الشكوك، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12041/حكم-الذهاب-للمساجد-المجاورة-لاداء-الجمعة-وترك-مسجد-القرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51918.mp3","categories":["صلاة الجمعة","نصائح وتوجيهات"]},{"id":13756,"question":"سماحة الشيخ! السائل يقول: ما المقصود بالنهي عن التحلق يوم الجمعة؟","title":"المقصود بالنهي عن التحلق يوم الجمعة","answer":"الجواب: على ظاهره، كونهم يتحلقون للدرس، والفائدة، أو لقراءة القرآن، يكون حلقة أمام معلمهم، أو قارئهم، هذا منهي عنه. أما كون واحد في الصف يقرأ، والآخر في الصف، أو مستند على جدار، أو على عمود يقرأ، كل واحد يقرأ لنفسه، ما يسمى حلقات هذا. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12132/المقصود-بالنهي-عن-التحلق-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53525.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":13761,"question":"سماحة الشيخ! السائل يقول: ما المقصود بالنهي عن التحلق يوم الجمعة؟","title":"المقصود بالنهي عن التحلق يوم الجمعة","answer":"الجواب: على ظاهره، كونهم يتحلقون للدرس، والفائدة، أو لقراءة القرآن، يكون حلقة أمام معلمهم، أو قارئهم، هذا منهي عنه. أما كون واحد في الصف يقرأ، والآخر في الصف، أو مستند على جدار، أو على عمود يقرأ، كل واحد يقرأ لنفسه، ما يسمى حلقات هذا. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12132/المقصود-بالنهي-عن-التحلق-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53525.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":13786,"question":"سمعت من بعض الناس أن المرأة في يوم الجمعة لا تصلي حتى يخرج الرجال من المسجد، فهل هذا صحيح؟","title":"متى تصلي المرأة الظهر يوم الجمعة؟","answer":"الجواب: ليس بصحيح، تصلي إذا دخل الوقت إذا زالت الشمس تصلي ولو ما صلى الناس الجمعة، ولو قبل صلاة الجمعة، إذا زالت الشمس دخل الوقت، لكن لا تعجل لأن بعض الناس قد يصلي قبل دخول الوقت في الجمعة، قد يقدمونها على الزوال، فينبغي لها ألا تعجل حتى تجزم وتتحقق أن وقت الظهر قد دخل، فإذا دخل وقت الظهر تصلي، ولا تنظر إلى كونهم صلوا الجمعة أو ما صلوا الجمعة. نعم..\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12142/متى-تصلي-المراة-الظهر-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48123.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":13796,"question":"هل ورد ما يؤكد بأن صلاة الجمعة لا تجزي عن صلاة الظهر وأنه يجب أن يصلى صلاة الظهر بعدها؟","title":"هل يُصلى الظهر بعد الجمعة؟","answer":"الجواب: لا ما في هذا، هذا باطل، الجمعة كافية ولا يجوز هذا الظن، ولا يجوز أن يصلي بعدها ظهر، الله جعلها كافية عن الظهر، والذين أحدثوا صلاة ظهر بعد الجمعة هذه بدعة، من صلى الجمعة كفته عن الظهر والحمد لله. نعم.\nالمقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/12173/هل-يصلى-الظهر-بعد-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53620.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":13814,"question":"إذا كان الإنسان في سفر في يوم الجمعة وفاتته صلاة الجمعة، وهو في الطريق في سفره، هل يصليها قصرًا ركعتين أم أربع ظهرًا؟","title":"كم يصلي من فاتته الجمعة أثناء السفر؟","answer":"الجواب: يصليها ظهرًا ركعتين في السفر، إذا غادر البلد ضحى قبل الزوال يصليها ركعتين ظهرًا، إذا كان مسافر، لكن إن زالت الشمس وهو موجود يصلي مع الناس الجمعة، يصلي مع الناس الجمعة لا يخرج، لأنه وجبت عليه، إلا إذا خاف فوت الرفقة فله أجر، المقصود: أنه إذا حضرت الصلاة وزالت الشمس يصلي جمعة مع الناس ثم يسافر، أما لو خرج ضحى قبل الزوال، فلا حرج عليه ويصلي في الطريق ظهرًا ركعتين. نعم.","link":"https://binbaz.org.sa/fatwas/12176/كم-يصلي-من-فاتته-الجمعة-اثناء-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53622.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":13815,"question":"سماحة الشيخ! أولئك الذين جعلوا من يوم الجمعة وقتًا لفسحهم ونزههم وتركهم هذا اليوم العظيم، هل من توجيه سماحة الشيخ؟","title":"توجيه لمن يترك الجمعة ويذهب للنزهة","answer":"الجواب: نعم، السنة للمؤمن أن يتحرى الجمعة وأن يحرص على حضورها وسماع الخطبة ولا يفرح بالذهاب إلى النزهة؛ لأن هذا يفوت عليه خيرًا كثيرًا، فالأفضل للمؤمن أن يتحرى الجمعة ويحرص على أدائها مع الناس وسماع الخطبة لما في هذا من الخير العظيم والفائدة الكبيرة. نعم. الله المستعان.\nالمقدم: الله المستعان!","link":"https://binbaz.org.sa/fatwas/12178/توجيه-لمن-يترك-الجمعة-ويذهب-للنزهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53622.mp3","categories":["صلاة الجمعة"]},{"id":13840,"question":"يقول السائل في سؤال له، قال النبي ﷺ: من قال: اسكت والإمام يخطب فقد لغا، فما حكم التأمين والصلاة على النبي ﷺ جهرًا والإمام يخطب؟","title":"حكم التأمين والصلاة على النبي ﷺ أثناء الخطبة","answer":"الجواب: السنة للمؤمن الإنصات أثناء الخطبة ينصت لسماع الخطيب ولا يتكلم، ولهذا قال ﷺ: إذا قلت لصاحبك: أنصت يوم الجمعة والإمام يخطب فقد لغوت، فلا يجوز له أن يتكلم ولا يقول: أنصت يا فلان، ولا اسكت يا فلان، بل ينصت، لكن يشير إشارة، لا مانع من الإشارة للمتكلم حتى يسكت، أما أنه يتكلم فلا، ومعنى فقد لغوت يعني: لغت الجمعة يعني فضلها يعني: فاته فضلها وإلا صار صحيح، لكن .. فاته الفضل.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12211/حكم-التامين-والصلاة-على-النبي-ﷺ-اثناء-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53012.mp3","categories":["صلاة الجمعة"]},{"id":13853,"question":"من الأردن السائل (و. ع) يقول في هذا  ما حكم الاحتباء -وهو ضم الفخذين إلى البطن بالثوب أو اليدين- عند الاستماع إلى الخطبة؟ جزاكم الله خيرًا.","title":"حكم الاحتباء أثناء سماع الخطبة","answer":"الجواب: تركه أولى؛ لأنه قد يسبب النوم والكسل، تركه أولى يكون على جلسة أخرى؛ لأن ذلك أقرب إلى النشاط والبعد عن النوم. نعم.","link":"https://binbaz.org.sa/fatwas/12224/حكم-الاحتباء-اثناء-سماع-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53721.mp3","categories":["صلاة الجمعة"]},{"id":13939,"question":"تسأل هل من الأفضل أن تصلي المرأة وحدها؟ أو تصلي في جماعة النساء؟","title":"ما الأفضل صلاة المرأة جماعة أم منفردة؟","answer":"الجواب: كل ذلك جائز، إن صلت وحدها فلا بأس وإن صلت مع النساء فلا بأس، الأمر واسع في ذلك، وكان النساء في عهد النبي ﷺ يصلين وحدهن كل واحدة تصلي وحدها، فإذا تيسر جماعة من النساء وصلين جميعًا في البيت وأمتهن خيرهن فذلك حسن، وقد روي عن أم سلمة وعن عائشة أنهما أمتا بعض النساء في بعض الأحيان.\nفالحاصل أنه لا بأس بأن تصلي في جماعة من النساء وتكون الإمامة وسطهن، عن يمينها بعضهن وعن يسارها بعضهن، ترفع صوتها بالتكبير والقراءة في أوقات الجهر كالمغرب والعشاء والفجر، وتعمل كما يعمل الرجل تكبر وترفع يديها إلى حذاء منكبيها أو أذنيها، وتقول بعد التكبير: سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك، أو تأتي بنوع من أنواع الاستفتاح الصحيحة الثابتة عن رسول الله عليه الصلاة والسلام، ثم تقول: أعوذ بالله من الشيطان الرجيم، ثم تسمي، ثم تقرأ الفاتحة، ثم تقرأ سورة معها، وهكذا في الثانية في المغرب والعشاء، أما في الثالثة تقرأ الفاتحة فقط، وهكذا في الثالثة والرابعة في العشاء الفاتحة فقط، وفي الفجر تقرأ الفاتحة وما تيسر معها لكن أطول من العشاء والمغرب، وهكذا في الظهر والعصر تصلي بهم سرًا ليس فيها جهرًا بقراءة.\nفالحاصل أنها مثلما يصلي الرجل لكنها تكون وسطهن لا تقدم .... بصلاتها وتطمئن وتحرص أن تعلمهن السنة إذا كانت تعرف السنة، حتى يقتدين بها ويستفدن منها، وفي هذا لها أجر كبير لما فيه من التعليم، فإذا كانت المرأة فقيهة في دينها وأمت من تيسر من النساء في بيتها حتى تعلمهن هذا خير عظيم وفيه فضل كبير ولكن ليس بواجب بل متى صلت وحدها فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/12352/ما-الافضل-صلاة-المراة-جماعة-ام-منفردة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60403.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":14011,"question":"ورد أن النبي ﷺ قال: إذا قلت لصاحبك: أنصت -يوم الجمعة- والإمام يخطب، فقد لغوت إذا دخل رجل وسلم على الجماعة، فهل نرد عليه السلام؟ ولا يتعارض هذا مع الحديث؟","title":"كيفية رد السلام أثناء خطبة الجمعة","answer":"الجواب: ترد بالإشارة، إذا كان الإمام يخطب، مثل اللي يصلي، ترد بالإشارة، تشير بيدك ردًا عليه، مثل ما لو سلم عليك وأنت تصلي، ترد بالإشارة، لأنك مأمور بالإنصات. نعم.","link":"https://binbaz.org.sa/fatwas/12427/كيفية-رد-السلام-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_483/48311.mp3","categories":["صلاة الجمعة"]},{"id":14043,"question":"رسالة وصلت إلى البرنامج من الجمهورية العراقية باعثها مستمع من هناك يقول: كاظم جاسم يسأل ويقول: نعلم أن اللغو في المسجد يوم الجمعة لا يجوز ومن لغى فلا جمعة له، ولكن نحن نقرأ الحديث الصحيح الذي مفاده أن ساعة الاستجابة يوم الجمعة تبدأ من صعود الخطيب على المنبر إلى أن يسلم من الصلاة، فنقوم بالدعاء في هذا الوقت فيرتفع صوتنا أحيانًا، وكذلك قد يذكر الخطيب اسم النبي ﷺ فنصلي عليه بصوت مرتفع، وقد يقوم بعض الناس بإطلاق الصيحات أثناء الخطبة عند ذكر أحد الأئمة الصالحين أو عند تأثير الخطبة على مشاعرهم، وإنني أتحرج من الجمع بين هذه الأشياء وبين الحديث الذي ينهى عن اللغو في أثناء الخطبة، فهل يعتبر هذا من اللغو أفيدونا بذلك؟ وفقكم الله.","title":"حكم رفع الصوت بالدعاء وغيره أثناء الخطبة","answer":"الجواب: ليس الدعاء وليس الصلاة على النبي ﷺ من اللغو، ولكن يكون سرًا بينك وبين نفسك لا ترفع صوتك فإذا سمعت شيء ما يوجب الدعاء ودعوت في حال السر بينك وبين نفسك كالتأمين على الدعاء والصلاة على النبي ﷺ لا حرج في ذلك ولكن يكون ذلك بصوت خفي بينك وبين ربك لا يشوش على من حولك، وإن أنصت ولم تقل شيئًا فلا حرج عليك؛ لأنك مأمور بالإنصات، وقد قال النبي ﷺ: إذا قلت لصاحبك أنصت يوم الجمعة والإمام يخطب فقد لغوت، وهو أمر بمعروف ونهي عن منكر ومع هذا سماه لغوًا عليه الصلاة والسلام، فعليك أن تنصت للخطبة وتستفيد ويتعظ قلبك لكن لو دعوت سرًا عندما يجب الدعاء أو صليت على النبي ﷺ سرًا أو قلت: آمين. سرًا، فنرجو أن لا يكون عليك حرج؛ لأن الصلاة أعظم ويجوز فيها ذلك.\nفالحاصل أنك تقول ما تقول من الدعوات أو الصلاة على النبي ﷺ سرًا بينك وبين ربك لا يكون فيها تشويش على من حولك، والذين يرفعون أصواتهم بالصيحات هذا غلط، لا يجوز هذا الكلام، بل الواجب عليهم الإنصات والاستماع والإصغاء والتأدب حال الخطبة، والدعوات التي ترجى إجابتها ممكنة سرًا بينك وبين نفسك وبين ربك حين يجلس الإمام وبين الخطبتين وفي سجود الصلاة، أما في حال الخطبة فتنصت وتقبل على الخطبة بقلبك للاستفادة منها، وإذا أمنت على الدعوة أو صليت على النبي ﷺ سرًا فنرجو ألا حرج عليك في ذلك ولكن مع العناية بالسرية وعدم التشويش على من حولك، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين. جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12458/حكم-رفع-الصوت-بالدعاء-وغيره-اثناء-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_612/61206.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":14046,"question":"له سؤال آخر قريب من السؤال الأول فهو يقول: في أثناء الخطبة يقوم الخطيب بالدعاء رافعًا يديه إلى السماء والناس يؤمنون على دعائه بقولهم: آمين، وقد سمعنا من خلال برنامجكم أن هذا غير جائز أي: أن التأمين على دعاء الخطيب غير وارد، فالسؤال هنا: ماذا يفعل الجالسون إذا قام الخطيب بالدعاء بصوت مرتفع هل يرفعون أيديهم معه أم ماذا يفعلون؟ وأرجو أن تفيدونا عن الأفضل للخطيب فعله في الخطبة هل هو تطويلها أم اختصارها؟ وما هي المواضيع التي تفضلون للخطيب أن يتناولها هل هي سرد القصص؟ أم بيان الأمور الفقهية؟ أم فيما يخص العقيدة؟ أرشدونا إلى الصواب، وجزاكم الله عنا كل خير؟","title":"حكم رفع اليدين في الخطبة وما يشرع التذكير به فيها","answer":"الجواب: المشروع للخطيب الاقتصاد في الخطبة وعدم التطويل، قال النبي عليه الصلاة والسلام في الحديث الصحيح يقول عليه الصلاة والسلام: إن طول صلاة الرجل وقصر خطبته مئنة من فقهه فأطيلوا الصلاة وأقصروا الخطبة خرجه مسلم في صحيحه من حديث عمار بن ياسر . وهذا يدل على أن السنة والأفضل أن يطيل الصلاة ويقصر الخطبة تقصيرًا لا يخل بالمقصود، ويشرع له أن يتحرى ما يحرك القلوب ويقربها من الله ويباعدها من أسباب غضبه، ويذكر في خطبته ما يحتاجه الناس من الأحكام الشرعية، وبيان ما أوجب الله وما حرم الله، ويكون فيها تحريك القلوب بالوعظ والقصص المفيدة النافعة والآيات القرآنية التي فيها الوعظ والتذكير والترغيب والترهيب، ولا يرفع يديه في الخطبة إلا في الاستسقاء إذا كان يستغيث يطلب السقيا يطلب المطر يرفع يديه كما فعل النبي ﷺ لما استسقى في خطبة الجمعة رفع يديه، أما الخطب العادية التي ليس فيها استسقاء فإنه لا يشرع فيها رفع اليدين بل يدعو من دون رفع اليدين، هكذا السنة. والمأموم إذا أمن بينه وبين نفسه على الدعاء لا حرج إن شاء الله بينه وبين نفسه كما تقدم، ولا يرفع يديه، المأموم كالإمام لا يرفع يديه إلا في الاستسقاء، إذا استسقى يعني إذا طلب الغوث من الله وهو المطر فإنه يرفع يديه كما رفع النبي ﷺ يديه في الاستسقاء، والمأمومون كذلك يرفعون أيديهم إذا رفع الإمام في الاستسقاء، أما خطب الجمعة العادية فإنه لا يرفع فيها، وهكذا خطب العيد لا يرفع فيها، الرفع في خطبة الاستسقاء خاصة كما ثبت ذلك عن رسول الله عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12461/حكم-رفع-اليدين-في-الخطبة-وما-يشرع-التذكير-به-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_612/61207.mp3","categories":["صلاة الجمعة"]},{"id":14059,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول فيها: نحن نعمل بمنطقة جبلية وليس بها مساجد، والمساجد القريبة منا يصعب الوصول إليها لظروف عملنا، ونحن جماعة قليلون، فكم عدد المصلين التي تصح بهم صلاة الجمعة؟","title":"هل يقيمون جمعة من هم بعيدون عن المساجد؟","answer":"الجواب: الواجب عليكم السعي إلى الجمعة، إذا كنتم تسمعون النداء، وتستطيعون الإجابة، على الأقدام أو بالسيارة؛ لأن الجمعة جامعة، تجمع أهل القرية، تجمع أهل المحل، فالواجب عليكم السعي إليها، والصلاة مع المسلمين في القرية التي أنتم فيها، وليس لكم الترخص وأن تقيموا جمعة وحدكم.\nإلا إذا كانت المسافة بعيدة؛ فعليكم أن تستفتوا وتقدموا إلى دار الإفتاء إذا كنتم في المملكة، ودار الإفتاء تنظر في الأمر، وتكتب إلى المحكمة في طرفكم؛ حتى تعرف الحقيقة، ثم تصدر الفتوى بذلك، لكن مهما أمكن المؤمن أن يسعى إلى الجمعة، ويشارك إخوانه في الجمعة، فهذا هو الخير العظيم، وله في خطواته أجر كبير، وحط سيئات؛ فينبغي له أن يشارك في الخير، وأن يحرص على الجمعة ولو بعدت؛ لكثرة الأجر ولاجتماعه بإخوانه وتكثير سوادهم، واطلاعه على أحوالهم وتعرفه عليهم؛ حتى يتعاون الجميع على البر والتقوى، ويتساعد الجميع على ما فيه الخير، فإذا كان هناك مشقة بينة؛ فلا مانع من إرسال استفتاء إلى دار الإفتاء، وهي تنظر في الأمر إن شاء الله.\nالمقدم: إن شاء الله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12490/هل-يقيمون-جمعة-من-هم-بعيدون-عن-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60809.mp3","categories":["صلاة الجمعة"]},{"id":14277,"question":"السائلة أم تركي تقول في هذا  سماحة الشيخ! إذا أذن الراديو وذلك الأذان الأول ليوم الجمعة أقوم وأتوضأ وأجلس لاستماع الخطبة وأنا في بيتي، وأذا أقيمت الصلاة في الراديو فأقوم وأصلي، فهل صلاتي صحيحة لمتابعتي الراديو؟ أم أن علي الإعادة؟","title":"ما يجب على من صلت الجمعة خلف الراديو؟","answer":"الجواب: بل عليك الإعادة؛ لأن الصلاة ... لو كنت معهم في المسجد، أما وأنت في بيتك على الراديو لا، عليك أن تصلي ظهرًا، وعليك أن تعيدي ما صليت جمعة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12735/ما-يجب-على-من-صلت-الجمعة-خلف-الراديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54915.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":14378,"question":"هذه السائلة (دعاء. م. م) من جمهورية مصر العربية، تقول: قرأتُ حديثًا بأن قول الإمام عند الانتهاء من خطبة الجمعة: إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ ... [النحل:90] إلى آخر الآية، هذا بدعةٌ، فهل هذا صحيحٌ؟ وإن كان كذلك فكيف يقع هذا من أئمة المساجد؟جزاكم الله خيرًا.","title":"حكم قول: {إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ ...} [النحل:90] في الخطبة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومَن اهتدى بهداه، أما بعد: فكان النبي ﷺ يقرأ في الخطبة -خطبة الجمعة- بعض الآيات -عليه الصلاة والسلام-، وهذه الآية: إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَى [النحل:90] من أجمع الآيات؛ فلهذا كان الكثير من الخطباء يقرأها في الخطبة، فقراءتها من أفضل القربات؛ لأنها آيةٌ جامعةٌ للأمر بالخير، والنهي عن الشر: إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَى وَيَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ وَالْبَغْيِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ [النحل:90] فهي آيةٌ عظيمةٌ جامعةٌ، من جوامع الكلم، فلا بأس بقراءتها في الخُطب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12859/حكم-قول-ان-الله-يامر-بالعدل-والاحسان-النحل90-في-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55201.mp3","categories":["صلاة الجمعة"]},{"id":14482,"question":"أرى بعض أئمة المساجد إذا دخل المسجد يوم الجمعة يشرع في الصلاة، فيصلي تحية المسجد، ثم يصعد إلى المنبر، فهل هذا جائز؟","title":"حكم صلاة الخطيب تحية المسجد قبل صعود المنبر","answer":"الجواب: لا نعلم لهذا أصلًا، كان النبي ﷺ إذا دخل يقصد المنبر مباشرة، ولا يصلي تحية المسجد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12970/حكم-صلاة-الخطيب-تحية-المسجد-قبل-صعود-المنبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62503.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":14489,"question":"أريد أن أعرف كيفية صلاة الجمعة بالنسبة للمرأة، هل تصلي مثل الرجل، أو تصلي الظهر كبقية الأيام؟ وهل يجوز أن تصلي قبل إقامة الصلاة؟ وهل يصح أن تصلي على أذان جامع آخر إذا سمعت الأذان فيه، قبل أذان الجامع الذي بجوار المنزل؟أرشدونا، جزاكم الله خيرًا.","title":"كيفية صلاة الجمعة للمرأة، ومتى تصلي الظهر؟","answer":"الجواب: المرأة ليس عليها جمعة، الجمعة من شأن الرجال، فتصلي ظهرًا أربع ركعات إذا كانت مقيمة، وركعتين إذا كانت مسافرة، وليس عليها جمعة، إنما الجمعة في حق الرجال فقط، لكن لو حضرت مع الرجال، وصلت الجمعة معهم أجزأتها، كما كان بعض النساء يصلين مع النبي ﷺ الجمعة وتجزئهن، إذا صلت المرأة مع المسلمين الجمعة أجزأتها عن الظهر. أما متى تصلي؟ فهي تصلي إذا دخل الوقت، وليس لها تعلق بالرجال، إذا دخل الوقت وعلمت دخول الوقت بسماع الأذان المعروف المضبوط، أو بزوال الشمس، تعرف زوال الشمس برؤية الشمس إذا زالت صلت، ولا عليها من الرجال، ولو ما سمعت إقامة الرجال، ولو ما بعد صلى الرجال تصلي قبلهم أو بعدهم لا شيء عليها في ذلك، هي مسؤولة عن نفسها، ليس لها تعلق بصلاة الرجال. لكن الواجب أنها لا تعجل حتى تجزم بالوقت، وحتى تتأكد الوقت، يمضي بعض الوقت حتى تكون صلاتها على بصيرة في الوقت فلا تعجل؛ لأن بعض المؤذنين قد يعجل، وقد يكون استعجل قبل الوقت، قد تكون ساعته مقدمة، ويعتمدها ويؤذن قبل الوقت فلا تعجل حتى ينتهي الناس من الأذان، حتى يمضي وقت ربع ساعة مثلًا، أو ما حول ذلك حتى تطمئن أن الوقت دخل دخل وقت الظهر، دخل وقت العصر، دخل وقت المغرب إلى آخره، لا تعجل. وهكذا المريض الذي ما يخرج إلى المساجد لا يعجل عند سماع أول مؤذن لا يعجل؛ لأن الصلاة قبل وقتها غير صحيحة باطلة، وكونه يؤخرها بعض الشيء ما في خطر، فلا يعجل الإنسان لا المريض، ولا المرأة، لا تعجل حتى يطمئن كل منهما إلى أن الوقت قد دخل بفراغ المؤذنين، أو سماع أهل المساجد يصلون، يعني يتيقن أن الوقت قد دخل، ولكن ليس مضبوطًا بالمصلين، لو صلت المرأة قبل الناس، أو بعدهم أو صلى المريض قبل الناس، أو بعدهم بعد دخول الوقت لا حرج في ذلك. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12983/كيفية-صلاة-الجمعة-للمراة-ومتى-تصلي-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_632/nour_63210.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":14494,"question":"أولى أسئلة هذه الحلقة بقية أسئلة أحد السادة المستمعين، الذين بعثوا إلى هذا البرنامج، هذا المستمع بعث بعشرة أسئلة، عرضنا أربعة منها في حلقة مضت، وفي هذه الحلقة بقي له عدد آخر، فيسأل ويقول: لظروف عملي أسافر يوم الجمعة قبل أذان الظهر، أو بعد الأذان، وأقوم بصلاة الظهر والعصر جمع تقديم وقصر في نفس الوقت، هل هذا جائز؟ وهل يجوز لي التأخير؟علمًا بأن هذا يحدث في كل شهر مرة.","title":"حكم السفر قبل صلاة الجمعة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فإذا كان السفر قبل الأذان -قبل زوال الشمس- فلا حرج -إن شاء الله-، والأفضل لك عدم السفر حتى تصلي الجمعة، هذا هو الأفضل لك، لكن إن سافرت قبل دخول الوقت فلا حرج عليك في ذلك، ولا حرج في الجمع ما دام السفر سفر قصر، كالسفر إلى الخرج، أو مكة، أو الحوطة، وغير ذلك، المقصود: مسافة ثمانين كيلو تقريبًا، يعني: يوم وليلة للمطية سابقًا، وهي الآن بالكيلو سبعون كيلو، ثمانون كيلو، ما يقارب هذه المسافة تعد سفرًا، لكن ينبغي لك -يا أخي- أن تحرص على حضور الجمعة لما فيها من الخير العظيم، والفائدة الكبيرة؛ ولئلا تتخذ هذا عادة، فيقسو القلب، ويقل الاعتناء بهذا الأمر، فأنصحك أن تجاهد نفسك حتى تصلي الجمعة ثم تسافر، لكن لا يلزمك ذلك إذا كان السفر قبل وقت الجمعة، قبل الزوال، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ يقول: إنه يفعل هذا في كل شهر مرة؟\nالشيخ: سواء في الشهر مرة، أو في الشهرين، الحكم واحد، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12964/حكم-السفر-قبل-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62501.mp3","categories":["صلاة الجمعة","نصائح وتوجيهات"]},{"id":14503,"question":"أولى رسائل هذه الحلقة رسالة المستمع حسني محمد عبدالرحيم، الأخ حسني يقيم الآن في جزيرة قبرص، عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول:إنني وحيد في جزيرة قبرص، ولم أجد مسلمين أصلي معهم، ولا يوجد أي مسجد، إلا أنني أسمع الأذان عن طريق إحدى الدول العربية بالراديو، وأصلي الجمعة خلف المذياع في إحدى الدول العربية، فهل صلاتي هذه تعتبر صلاة جماعة؟ وماذا أفعل -إذًا- وأنا أتأخر في بعض أوقات الصلاة؛ لأنه لا بد لي من الاغتسال خوفًا أن يكون عملي -الذي سبق وأن ذكرته لكم وهو في مصنع للحوم الخنازير- أخشى أن يكون في عملي هذا شيء من النجاسة، فأغتسل قبل الصلاة، أرجو توجيهي حيال ما سألت، جزاكم الله خيرًا.","title":"حكم صلاة الجمعة خلف المذياع والعمل في مصنع لحوم الخنازير","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أنّ صلاة الجمعة واجبة على المسلمين، ولكن ليس لك أن تصلي على المذياع، بل الواجب عليك أن تلتمس من المسلمين من يقيم الصلاة صلاة الجمعة، وعليك أن تجتهد في ذلك، فإذا تيسر لك جماعة من المسلمين في أي مسجد من المساجد تصلي معهم الجمعة، ولو اثنين، وتكون أنت الثالث؛ لأن الصحيح أنّ الجمعة تنعقد من ثلاثة، فإذا كانوا مستوطنين مقيمين في بلد ليسوا مسافرين بل مقيمون مستوطنون، فإنكم تصلون جميعًا جمعة، وإذا كانوا أكثر من ثلاثة فأحسن وأحسن.\nوينبغي لك وأمثالك من الإخوان الطيبين أن يسعوا في هذا الأمر، وأن يجتهدوا في إقامة صلاة الجمعة، وصلاة الجماعة في المساجد الموجودة، وأن تحرصوا على فتحها؛ لأنه بلغني أنّ هناك مساجد كثيرة مغلقة، فينبغي لك أنت وإخوانك أن تسعوا حثيثًا في فتح ما تيسر منها، وأن تقيموا صلاة الجمعة فيما تيسر منها، ولا تصل خلف مذياع، لكن إذا لم يتيسر لك أحد تصلي ظهرًا، صل أربعًا ظهرًا بعد زوال الشمس، بعد دخول الوقت، ولا تصل جمعة إلا إذا كان معك اثنان أو أكثر من الناس المستوطنين في البلد، هكذا بيّن أهل العلم.\nونسأل الله أن يجعلك مباركًا، وأن يعينك على أسباب الخير، وأن يجعلك مفتاحًا للخير. أما الغسل فهو سنة سنة مؤكدة يوم الجمعة لمن يصلي الجمعة، وذهب بعض أهل العلم إلى وجوبه، وقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: من جاء منكم الجمعة فليغتسل وقال أيضًا -عليه الصلاة والسلام-: غسل يوم الجمعة واجب على كل محتلم، وأن يستاك ويتطيب. قال جمهور أهل العلم: معنى واجب يعني: متأكد، فيسن لك الغسل للجمعة إذا كنت تصلي الجمعة. أما صلاة الأوقات فلا يشرع لها الغسل، وإذا كنت تعلم أن في ثوبك نجاسة، أو بدنك نجاسة من لحم الخنزير، أو دم الخنزير، أو من بول أو غير ذلك فاغسله، اغسل المحل فقط، وليس عليك غسل، عليك أن تغسل ما أصابه الدم أو النجاسة من الخنزير في يدك أو رجلك أو ثوبك، أما الغسل فلا يلزمك، لكن يستحب لك الغسل في الجمعة. ويجب عليك الغسل للجنابة إذا جامعت زوجتك، أو أنزلت مني بشهوة تغتسل للجنابة، نسأل الله أن يعينك على الخير، وأن يمنحنا وإياك الفقه في الدين، والثبات عليه، ونوصيك مرة أخرى بالحرص على جمع إخوانك، والتعاون معهم، وأن تصلوا جميعًا الجمعة والجماعة، وأن تجتهدوا في فتح المساجد تشجيع من حولها من المسلمين يصلوا فيها الجمعة والجماعة، كل مسجد حوله جماعة يصلوا فيه الجماعة، وإذا كانت الجمعة بعيدة عنهم صلوا جمعة أيضًا، وإذا كانوا متقاربين اجتمعوا في واحد من المساجد وصلوا جمعة، ولا يتفرقوا، بل يصلون جميعًا في مسجد واحد، إلا إذا تباعدت المساجد والمحلات تباعدًا كثيرًا، فكل حي يصلون في حيهم جمعة إذا صار بعيدًا عن الحي الآخر بما يشق معهم الذهاب إلى الحي الآخر، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.\nسماحة الشيخ، بم توصونه تجاه عمله في هذا المصنع، مصنع للحوم الخنزير؟\nالشيخ: تقدم أن أوصيناه بأنه يجب عليه تركه، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] ليس له أن يعمل في مصنع الخنزير، وليس لأحد أن يساعد صناع ما حرم الله من صناعة الخمر، أو بيع لحم الخنزير، أو غير هذا مما حرم الله، ليس للمسلم أن يشاركهم في ذلك، ولا أن يعينهم في ذلك؛ لأن الله يقول: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] والنبي ﷺ لعن الخمر وشاربها وساقيها وعاصرها ومعتصرها وحاملها، والمحمولة إليه، وبائعها ومشتريها، وآكل ثمنها؛ لماذا؟ لأنهم ساعدوا على الباطل؛ لأنهم عاونوا على الشر، فلهذا لعنوا.\nفالواجب على كل مسلم وعلى كل مسلمة الحذر من الإعانة على ما حرم الله، عملًا بقوله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ [المائدة:2] فالذي يعين على بيع الخمر، أو بيع الخنزير، أو أكل لحم الخنزير، أو شرب المسكر، أو يعين على أكل الربا، أو يكتب الربا، أو يشهد على الربا كلهم داخلون في اللعنة، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12993/حكم-صلاة-الجمعة-خلف-المذياع-والعمل-في-مصنع-لحوم-الخنازير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62601.mp3","categories":["صلاة الجمعة","الإجارة"]},{"id":14510,"question":"أولى رسائل هذه الحلقة رسالة المستمع حسني محمد عبدالرحيم، الأخ حسني يقيم الآن في جزيرة قبرص، عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول:إنني وحيد في جزيرة قبرص، ولم أجد مسلمين أصلي معهم، ولا يوجد أي مسجد، إلا أنني أسمع الأذان عن طريق إحدى الدول العربية بالراديو، وأصلي الجمعة خلف المذياع في إحدى الدول العربية، فهل صلاتي هذه تعتبر صلاة جماعة؟ وماذا أفعل -إذًا- وأنا أتأخر في بعض أوقات الصلاة؛ لأنه لا بد لي من الاغتسال خوفًا أن يكون عملي -الذي سبق وأن ذكرته لكم وهو في مصنع للحوم الخنازير- أخشى أن يكون في عملي هذا شيء من النجاسة، فأغتسل قبل الصلاة، أرجو توجيهي حيال ما سألت، جزاكم الله خيرًا.","title":"حكم صلاة الجمعة خلف المذياع والعمل في مصنع لحوم الخنازير","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أنّ صلاة الجمعة واجبة على المسلمين، ولكن ليس لك أن تصلي على المذياع، بل الواجب عليك أن تلتمس من المسلمين من يقيم الصلاة صلاة الجمعة، وعليك أن تجتهد في ذلك، فإذا تيسر لك جماعة من المسلمين في أي مسجد من المساجد تصلي معهم الجمعة، ولو اثنين، وتكون أنت الثالث؛ لأن الصحيح أنّ الجمعة تنعقد من ثلاثة، فإذا كانوا مستوطنين مقيمين في بلد ليسوا مسافرين بل مقيمون مستوطنون، فإنكم تصلون جميعًا جمعة، وإذا كانوا أكثر من ثلاثة فأحسن وأحسن.\nوينبغي لك وأمثالك من الإخوان الطيبين أن يسعوا في هذا الأمر، وأن يجتهدوا في إقامة صلاة الجمعة، وصلاة الجماعة في المساجد الموجودة، وأن تحرصوا على فتحها؛ لأنه بلغني أنّ هناك مساجد كثيرة مغلقة، فينبغي لك أنت وإخوانك أن تسعوا حثيثًا في فتح ما تيسر منها، وأن تقيموا صلاة الجمعة فيما تيسر منها، ولا تصل خلف مذياع، لكن إذا لم يتيسر لك أحد تصلي ظهرًا، صل أربعًا ظهرًا بعد زوال الشمس، بعد دخول الوقت، ولا تصل جمعة إلا إذا كان معك اثنان أو أكثر من الناس المستوطنين في البلد، هكذا بيّن أهل العلم.\nونسأل الله أن يجعلك مباركًا، وأن يعينك على أسباب الخير، وأن يجعلك مفتاحًا للخير. أما الغسل فهو سنة سنة مؤكدة يوم الجمعة لمن يصلي الجمعة، وذهب بعض أهل العلم إلى وجوبه، وقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: من جاء منكم الجمعة فليغتسل وقال أيضًا -عليه الصلاة والسلام-: غسل يوم الجمعة واجب على كل محتلم، وأن يستاك ويتطيب. قال جمهور أهل العلم: معنى واجب يعني: متأكد، فيسن لك الغسل للجمعة إذا كنت تصلي الجمعة. أما صلاة الأوقات فلا يشرع لها الغسل، وإذا كنت تعلم أن في ثوبك نجاسة، أو بدنك نجاسة من لحم الخنزير، أو دم الخنزير، أو من بول أو غير ذلك فاغسله، اغسل المحل فقط، وليس عليك غسل، عليك أن تغسل ما أصابه الدم أو النجاسة من الخنزير في يدك أو رجلك أو ثوبك، أما الغسل فلا يلزمك، لكن يستحب لك الغسل في الجمعة. ويجب عليك الغسل للجنابة إذا جامعت زوجتك، أو أنزلت مني بشهوة تغتسل للجنابة، نسأل الله أن يعينك على الخير، وأن يمنحنا وإياك الفقه في الدين، والثبات عليه، ونوصيك مرة أخرى بالحرص على جمع إخوانك، والتعاون معهم، وأن تصلوا جميعًا الجمعة والجماعة، وأن تجتهدوا في فتح المساجد تشجيع من حولها من المسلمين يصلوا فيها الجمعة والجماعة، كل مسجد حوله جماعة يصلوا فيه الجماعة، وإذا كانت الجمعة بعيدة عنهم صلوا جمعة أيضًا، وإذا كانوا متقاربين اجتمعوا في واحد من المساجد وصلوا جمعة، ولا يتفرقوا، بل يصلون جميعًا في مسجد واحد، إلا إذا تباعدت المساجد والمحلات تباعدًا كثيرًا، فكل حي يصلون في حيهم جمعة إذا صار بعيدًا عن الحي الآخر بما يشق معهم الذهاب إلى الحي الآخر، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.\nسماحة الشيخ، بم توصونه تجاه عمله في هذا المصنع، مصنع للحوم الخنزير؟\nالشيخ: تقدم أن أوصيناه بأنه يجب عليه تركه، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] ليس له أن يعمل في مصنع الخنزير، وليس لأحد أن يساعد صناع ما حرم الله من صناعة الخمر، أو بيع لحم الخنزير، أو غير هذا مما حرم الله، ليس للمسلم أن يشاركهم في ذلك، ولا أن يعينهم في ذلك؛ لأن الله يقول: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] والنبي ﷺ لعن الخمر وشاربها وساقيها وعاصرها ومعتصرها وحاملها، والمحمولة إليه، وبائعها ومشتريها، وآكل ثمنها؛ لماذا؟ لأنهم ساعدوا على الباطل؛ لأنهم عاونوا على الشر، فلهذا لعنوا.\nفالواجب على كل مسلم وعلى كل مسلمة الحذر من الإعانة على ما حرم الله، عملًا بقوله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ [المائدة:2] فالذي يعين على بيع الخمر، أو بيع الخنزير، أو أكل لحم الخنزير، أو شرب المسكر، أو يعين على أكل الربا، أو يكتب الربا، أو يشهد على الربا كلهم داخلون في اللعنة، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12993/حكم-صلاة-الجمعة-خلف-المذياع-والعمل-في-مصنع-لحوم-الخنازير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62601.mp3","categories":["صلاة الجمعة","الإجارة"]},{"id":14616,"question":"كثر السؤال -يا سماحة الشيخ- عن رفع اليدين للدعاء في يوم الجمعة، وكذلك الإمام حين يدعو بالمأمومين، ويجهر بصوته، وتأمين المأموم هل هذا صحيح أو لا؟","title":"ما حكم رفع الأيدي بالدعاء في خطبة الجمعة؟","answer":"الجواب: السنة للإمام يوم الجمعة في الخطبة أن لا يرفع يديه، ما كان يرفع النبي يديه -عليه الصلاة والسلام- لا في الجمعة، ولا في العيد، وهكذا الجماعة لا يرفعون أيديهم، ولكن إذا أمنوا بينهم وبين أنفسهم على دعاءه سمعوا الدعاء، وأمنوا بينهم وبين أنفسهم، فلا حرج في ذلك.  وإنما الرفع يكون في خطبة الاستسقاء، كان النبي ﷺ إذا استسقى وطلب الغيث، رفع يديه، واستسقى، والسنة للجماعة أن يرفعوا أيديهم أيضًا كما رفع الإمام؛ لأن الرسول ﷺ رفع يديه، ورفع الصحابة أيديهم في الاستسقاء في طلب الغيث، طلب المطر، أما الجمعة والعيد فيدعو الإمام في الخطبة، ولكن لا يرفع يديه، وهكذا الجماعة لا يرفعون أيديهم، هذا هو السنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13120/ما-حكم-رفع-الايدي-بالدعاء-في-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63608.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":14617,"question":"أحد الإخوة المستمعين من المملكة الأردنية الهاشمية، ممن يسأل عن السنة القبلية لصلاة الجمعة، هل لها سنة؟ أو لًا؟","title":"هل للجمعة سنة قبلية؟","answer":"الجواب: تقدم أنه لا سنة لها قبلية، ولكن يصلي ما كتب الله له، يصلي ثنتين أو تسليمتين، أو ثلاث تسليمات، يعني: ركعتين ركعتين حسب ما يسر الله له، إذا وصل إلى المسجد، يصلي ما قدر الله له، كما قال النبي ﷺ ثم يجلس ينتظر خروج الإمام، وسماع الخطبة والصلاة.  فالحاصل: أنه ليس لها سنة راتبة قبلية، ولكن يصلي ما يسر الله له، وإذا صلى ركعتين تحية المسجد كفى، وإذا صلى معهما ركعات أخرى كان أفضل وأكمل؛ لأنه يوم عظيم، ويوم فاضل، ويوم عيد، فإذا صلى قبلها ركعات يسلم من كل ثنتين كان ذلك أفضل، ثم يجلس ينتظر مسبحًا ومهللًا أو قارئًا أو مستغفرًاً أو ساكتًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13115/هل-للجمعة-سنة-قبلية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63606.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":14651,"question":"تقول في سؤالها الثاني: ما هي فروض الغسل من الحيض والجنابة؟","title":"فروض الغسل من الحيض والجنابة","answer":"الجواب: الفرض تعميم الجسم من الجنابة والحيض والنفاس، يعمه بالماء، إذا عم الجسم بالماء بنية الطهارة كفى عن المرأة والرجل، عليه جنابة والمرأة من الحيض والنفاس إذا عمت جسمها بالماء، واغتسلت بنية الطهارة، كفى، لكن الأفضل أن يبدأ بالوضوء إذا كان جنبًا أو يبدأ بالضوء، الوضوء الشرعي، ثم يعم بدنه بالماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13137/فروض-الغسل-من-الحيض-والجنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55917.mp3","categories":["صلاة الجمعة","الغسل","قضايا المرأة"]},{"id":14658,"question":"المسافر يوم الجمعة هل يصليها ظهرًا أربع ركعات أو ركعتين؟","title":"كيف يصلي المسافر الجمعة؟ وكم ركعة؟","answer":"الجواب: يصليها ظهرًا، إذا سافر يصليها ظهرًا ركعتين في السفر، إذا سافر قبل الزوال قبل الأذان الأخير يصليها في السفر ركعتين صلاة ظهر، النبي ﷺ في حجة الوداع صلى يوم الجمعة ظهرًا، يوم عرفة صلى الظهر ثنتين، والعصر ثنتين، ما صلى جمعة -عليه الصلاة والسلام- في حجة الوداع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13147/كيف-يصلي-المسافر-الجمعة-وكم-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56002.mp3","categories":["صلاة الجمعة"]},{"id":14829,"question":"من ليبيا طرابلس، هذه رسالة بعث بها المستمع فرج عيسى زعيق، له سؤالان، يقول في سؤاله الأول: إذا دخلت المسجد في يوم الجمعة والإمام يخطب فهل أجلس، أم أصلي ركعتين؟ وما الدليل على ذلك؟","title":"ما المشروع لمن دخل المسجد والإمام يخطب؟","answer":"الجواب: السنة -يا أخي- أن تصلي ركعتين قبل أن تجلس، ولو أن الإمام يخطب؛ لما ثبت في صحيح مسلم عن النبي -عليه الصلاة والسلام- أنه قال: إذا جاء أحد المسجد والإمام يخطب فليركع ركعتين؛ وليتجوز فيهما يعني: يخففهما تخفيفًا لا يمنع الطمأنينة، هكذا أمر -عليه الصلاة والسلام-، أمر الداخل والإمام يخطب أنه يصلي ركعتين، لكن لا يطول فيهما حتى يفعل السنة، ويتمكن من سماع الخطبة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13332/ما-المشروع-لمن-دخل-المسجد-والامام-يخطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64313.mp3","categories":["صلاة الجمعة"]},{"id":14964,"question":"هذه رسالة وردتنا من المستمع صالح عليان الحويطي، يقول: أنا حارس على شيء مهم من ممتلكات الدولة، وحولي مسجد جمعة، لكن أخشى بعد ذهابي على ما كلفت بحراسته، فهل يجوز لي تركه والذهاب للصلاة؟","title":"ما حكم الجمعة والجماعة على الحارس؟","answer":"الجواب: لا، الحراسة عذر، الحارس على الشيء المهم الذي يخشى عليه، ليس له أن يدعه ويذهب إلى صلاة الجمعة والجماعة، بل عليه أن يصلي في محله، ويسقط عنه حضور الجمعة والجماعة في هذه الحال، إلا إذا وجد من ينوب عنه ممن لا جمعة عليه: كالمملوك والنساء وأشباه ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/13461/ما-حكم-الجمعة-والجماعة-على-الحارس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_650/nour_65002.mp3","categories":["صلاة الجماعة","صلاة الجمعة"]},{"id":14967,"question":"أيضًا وردتنا رسالة من أحد السادة المستمعين يقول في رسالته المستمع المستفيد محمد عثمان سلامة، يقول في سؤاله: نعمل في مزرعة تبعد عن المدن بحوالي خمسة كيلو مترات، وعدد الرجال خمسة عشر رجلًا، فهل يصلح لنا صلاة الجمعة أم لا؟ وأنا أجيد الخطبة -والحمد لله-، وأجد معي من القرآن الجزء عم وبعض الأحاديث الدينية، وبعض من الدعاء. نرجو إفادتنا هل نقيم جمعة أم لا؟","title":"حكم الجمعة على من يعملون في مزرعة بعيدة عن المدن","answer":"الجواب: إذا كانت المزرعة يستوطنها أهلها، ويقيمون فيها شتاءً وصيفًا مستوطنون فيها، وهم ثلاثة؛ فأكثر وجب عليهم أن يقيموا الجمعة، ومن حضر صلى معهم، أما إذا كانت عارضة يقيمون فيها أيام أو مدة للزراعة،ثم ينزلون البلد وليست محل استيطان، وليست محل إقامة، فهذه لا تقام فيها الجمعة؛ لأنها ليست وطنًا، وليست محل استيطان، وهم بعيدون عن الجمعة، فتسقط عنهم الجمعة لبعدهم، ويصلون ظهرًا.  أما إن كانوا مستوطنين مقيمين فيها شتاءً وصيفًا، قد عمروا فيها مساكن، واستقاموا فيها؛ فيصلون جمعة إذا كانوا مستوطنين إذا كانوا ثلاثة فأكثر، نعم.","link":"https://binbaz.org.sa/fatwas/13469/حكم-الجمعة-على-من-يعملون-في-مزرعة-بعيدة-عن-المدن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_650/nour_65007.mp3","categories":["صلاة الجمعة"]},{"id":14994,"question":"هل الدعاء وارد في خطـبة الجمعة، أي: في نهايتها؟ وهل للمأموم أو المستمع، أن يقول: آمين. سواءً كان ذلك سرًا أم بصوت مرتفع؟","title":"حكم الدعاء في خطبة الجمعة والتأمين عليه","answer":"الجواب: النبي ﷺ كان يدعو في خطبه، فإذا دعا الإمام أمن المأموم بينه وبين نفسه تأمين بنفسه، يعني: بينه وبين نفسه لا يجهر، نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13491/حكم-الدعاء-في-خطبة-الجمعة-والتامين-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_002/306080.mp3","categories":["صلاة الجمعة"]},{"id":15115,"question":"يقول: في قريتنا لا يوجد جامع، وفي إحدى القرى المجاورة لنا جامع، وأهل قريتنا لا يذهبون ليصلوا صلاة الجمعة، فما حكمهم؟","title":"حكم ترك الجمعة لعدم وجود مسجد في القرية","answer":"الجواب: يجب عليهم أن يصلوا مع إخوانهم في الجامع الثاني، وإن كان بعيدًا عليهم وجب عليهم أن يصلوا في محلهم. أما تركها فلا يجوز لهم، هذا منكر عظيم، نعوذ بالله من ذلك، بل تقدم ما يدل على أنه ردة، ترك الصلاة بغير عذر شرعي، يقول ﷺ: لينتهين أقوام عن ودعهم الجمعات، أو ليختمن الله على قلوبهم، ثم ليكونون من الغافلين وقال -عليه الصلاة والسلام-: من ترك الجمعة ثلاث مرات بغير عذر طبع على قلبه. فالحاصل: أن الواجب على المسلم أن يصلي الجمعة، وأن يحافظ عليها إذا كان مقيمًا غير مسافر، وإذا كانت قريته ليس فيها جمعة لصغرها وجنبها قرية فيها جمعة صلى مع إخوانه في القرية الثانية، وإن كان فيه مشقة أقاموا الجمعة في محلهم في القريتين، هذه فيها جمعة، وهذه فيها جمعة، لكن إذا كانتا متقاربتين جدًا كالقرية الواحدة، صلوا جميعًا في مسجد واحد، والحمد لله، إذا كان المسجد يسعهم، وإلا صلوا في مسجدين، كما لو تباعدت القرى، صلوا كل واحد في مسجده. ولا يجوز لأهل القرية أن يهملوها، بل إما أن يصلوا وحدهم إذا كانوا بعيدين، وإما أن يصلوا مع إخوانهم الذين تقام عندهم الجمعة، ولا يجوز التساهل في هذا والتهاون، بل يجب البدار بالصلاة، مع إخوانهم الذين يصلون الجمعة، أو يجمعون جمعة، ويسألون المحكمة عندهم، المحكمة أو المفتي إذا كان في بلادهم مفتي حتى يوجههم إلى الحكم الشرعي، وحتى يبين لهم ما يجب عليهم، ولا يجوز التساهل في هذا الأمر. وإن كان في السعودية -السائل- فلا مانع أن يكتب لنا حتى ننظر في الموضوع؛ لأن الجمع إلى دار الإفتاء، فيكتب لدار الإفتاء يكتب لنا ننظر في الأمر، حتى إذا كانت القريتان متقاربتين، وأمكن صلاتهما جميعًا، فالحمد لله، وإلا كل قرية تقيم صلاة الجمعة وحدها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13615/حكم-ترك-الجمعة-لعدم-وجود-مسجد-في-القرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49412.mp3","categories":["صلاة الجمعة"]},{"id":15127,"question":"أفيدونا عن صلاة العيد إذا وافقت يوم الجمعة، هل تجزئ عن صلاة الجمعة؟","title":"هل تلزم صلاة الجمعة لمن صلى العيد؟","answer":"الجواب: نعم، إذا وافقت صلاة العيد، وصلى مع الناس صلاة العيد، لا تلزمه الجمعة، كما نص عليه النبي ﷺ، لكن يصلي ظهرًا، عليه أن يصلي ظهرًا، إن تيسر جماعة صلاها جماعة، وإلا صلاها وحده، وإن صلى الجمعة مع الناس فهو أفضل.  فإذا وافق يوم الجمعة يوم العيد، وصار ممن حضر صلاة العيد مع الناس، سقطت عنه الجمعة، وصلاها ظهرًا، وإن صلى مع الناس الجمعة فإن الأئمة عليهم أن يقيموا الجمعة، على أهل المساجد أن يقيموا الجمعة لمن حضر، ومن لم يصل معهم صلى ظهرًا، نعم. المقدم: طيب، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13627/هل-تلزم-صلاة-الجمعة-لمن-صلى-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49511.mp3","categories":["صلاة الجمعة"]},{"id":15271,"question":"السائل، سعد عبدالوهاب، من خميس مشيط، يقول: صليت إحدى الجمع في أحد المساجد، في إحدى القرى، وعند انتهاء الخطيب من الخطبة، ونزوله للشروع في الصلاة، رأيته يقدم شخصًا آخر بدلًا عنه، وعند الانتهاء من الصلاة قام الشخص الآخر بإلقاء موعظة لمدة عشر دقائق، وعند خروجنا من المسجد قال لي أحد المصلين: بأن هذا لا يجوز، خطبة على خطبة؛ لذا فإنه لم يجلس للاستماع إليها، فهل هذا صحيح يا سماحة الشيخ؟","title":"حكم الوعظ بعد صلاة الجمعة","answer":"الجواب: لا حرج أن يصلي الجمعة غير الخطيب، لا حرج، إذا رأى الخطيب تقديم من يصلي الجمعة لا بأس.  وإذا وعظ إنسان بعد الجمعة فلا حرج، والذي يقول: خطبة بعد خطبة، ليس عنده علم، فإذا وعظ واعظ بعد الجمعة، وذكر مذكر بعد الجمعة فلا حرج، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/13773/حكم-الوعظ-بعد-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56516.mp3","categories":["صلاة الجمعة"]},{"id":15316,"question":"هذه رسالة من المستمع (ح. م. د) من جمهورية اليمن الديمقراطية الشعبية، ضمنها عدة أسئلة، وقد سبق الإجابة على بعضها في حلقة مضت، بقي له سؤال واحد يقول فيه: إذا جاء شخص يوم الجمعة إلى المسجد، ووجد الصلاة قد قضيت، ووجد رجلًا بقيت عليه ركعة، فهل يكملها ظهرًا أو يكملها جمعة؟ ولو انضم إليه شخص آخر فبعد أن قضى ركعة فهل أيضًا يكملها ظهرًا، أم يكملها جمعة؟","title":"حكم الصلاة خلف المسبوق لمن فاتته الجمعة","answer":"الجواب: الواجب يكملها ظهرًا؛ لأن الجمعة فاتت لما لم يدرك منها شيئًا، فاتت الجمعة، وإنما تدرك بركعة واحدة، إذا أدرك الركعة الثانية مع الإمام صلاها جمعة، أما إذا لم يأت إلا بعد السلام، أو بعد الركعة الثانية في التشهد، أو في حالة السجود في الركعة الثانية، فإنه لا يصليها جمعة، ولكن يصليها ظهرًا؛ لقول النبي ﷺ: من أدرك ركعة من الجمعة فليضف إليها أخرى، وقد تمت صلاته فمفهومه أنه إذا ما أدرك إلا أقل من ركعة فإنه لا يكون مدركًا للجمعة، ولكنه يصلي ظهرًا، هذا هو المشروع أنه يصلي ظهرًا، وإذا أدرك إنسانًا يقضي وصلى معه فإنه يصلي ظهرًا ولا يصلي جمعة، نعم. وهذا أيضًا يلاحظ فيه أن يكون بعد الزوال، أما إذا كانت الجمعة صلوها قبل الزوال، فإنه لا يصلي الظهر إلا بعد الزوال، والجمعة يجوز أن تصلى قبل الزوال في الساعة السادسة قبل الزوال، لا بأس على الصحيح، فلو كانت الجمعة صليت، حين فاتته صليت قبل الزوال، فإنه لا يصلي الظهر إلا بعد الزوال، نعم.","link":"https://binbaz.org.sa/fatwas/13818/حكم-الصلاة-خلف-المسبوق-لمن-فاتته-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_676/nour_67605.mp3","categories":["صلاة الجمعة"]},{"id":15388,"question":"مصطفى محمد من السودان يقول: سماحة الشيخ، إذا دخلت المسجد ووجدت الإمام قائمًا، وأدركت معه الركعة الأخيرة من صلاة الجمعة، فكيف أتم صلاتي؟","title":"كيفية إتمام الجمعة لمن أدرك الإمام في الركعة الثانية","answer":"الجواب: تأتي بركعة ثانية، إذا أدركت ركعة من الجمعة، وسلم الإمام تقوم وتأتي بركعة ثانية، والحمد لله، وأجزأتك؛ لقوله ﷺ: من أدرك ركعة من الجمعة فليضف إليها أخرى، وقد تمت صلاته.","link":"https://binbaz.org.sa/fatwas/13889/كيفية-اتمام-الجمعة-لمن-ادرك-الامام-في-الركعة-الثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56715.mp3","categories":["صلاة الجمعة"]},{"id":15390,"question":"هل من توجيه -يا سماحة الشيخ- للذين يتأخرون عن صلاة الجمعة هذا اليوم العظيم؟","title":"الحث على التبكير لصلاة الجمعة","answer":"الجواب: الواجب على كل مسلم أن يبادر إلى الجمعة قبل الأذان الأخير؛ لأن هذا الأذان بعده الخطبة؛ فالواجب أن يبادر حتى يسمع الخطبة ويحضر الصلاة، والله -جل وعلا- بين لعباده أن الواجب إذا نودي للصلاة بالجمعة أن يذروا البيع، ويتركوا المشاغل. فالواجب على المؤمن أن يتحرى الوقت المناسب يوم الجمعة، ويفرغ نفسه حتى يبكر لها، يصلي ما تيسر، يقرأ من القرآن ما تيسر، حتى إذا جاء الخطيب، فإذا هو قد فرغ من صلاته، وقراءته التي أراد. المقصود: أن المشروع للمؤمن أن يبكر، ويبادر إلى الجمعة، والذي يأتي لها في أول الوقت كالمهدي بدنة، والذي يليه كالمهدي بقرة، والذي يليه كالمهدي كبش، والذي يليه كالمهدي دجاجة، والخامس كالمهدي بيضة.  فالمشروع للمؤمن أن يبادر ويسارع قبل الأذان الأخير، حتى إذا أذن الأخير إذا هو حاضر قد فرغ، وقد استعد لسماع الخطبة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13891/الحث-على-التبكير-لصلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56716.mp3","categories":["صلاة الجمعة","نصائح وتوجيهات"]},{"id":15461,"question":"الدعاء في الخطبة يوم الجمعة الدعاء الطويل، هل هو وارد -يا فضيلة الشيخ- في خطبة الجمعة؟","title":"حكم الدعاء في خطبة الجمعة","answer":"الجواب: ما أذكر شيئًا عن الدعاء الطويل، لكن يدعو بما تيسر، ثبت عنه ﷺ أنه كان يقرأ سورة ق في الجمعة، فإذا قرأها، أو قرأ ما تيسر منها، أو قسمها في الخطبتين، كله حسن -إن شاء الله-؛ لأن فيها عظة عظيمة سورة ق، وإذا دعا بدعوات مما يسر الله له، المهم أنه يأتي بما شرع الله في الخطبة من الحمد لله، والثناء عليه، والصلاة على رسوله، والشهادتين، والوعظ بما يسر الله، يحمد الله، ويثني عليه، ويصلي على نبيه، ويأتي بالشهادتين، ويقرأ ما تيسر من القرآن، ويعظ بكلمات واعظة من آيات أو أحاديث، أو كلمات مناسبة؛ لأن المقصود من الخطبة تذكير الناس، ووعظهم وتوجيههم إلى الخير، وتحذيرهم من الشر، فيقرأ من الآيات والأحاديث ما يحصل به المطلوب من الوعظ والتذكير. ولا يطيل إطالة تشق على الناس، تكون الخطبة وسط أصلًا، ليس فيها إطالة إلا عند الحاجة، إذا كانت هناك حاجة للإطالة في بعض الأحيان فلا بأس عند الحاجة، كان النبي ﷺ لا يطول، يقول ﷺ: إن طول صلاة الرجل وقصر خطبته مئنة من فقهه، فأطيلوا الصلاة، وأقصروا الخطبة. وكان ﷺ خطبته قصدًا، هذا الغالب عليه قصدًا، هذا الغالب، ليس فيها طول ممل، وليس فيها اقتصار مخل، بل وسط، يتحرى فيها ما ينفع الناس -عليه الصلاة والسلام-، فالخطيب كذلك يتحرى ما ينفع الناس، وإيضاح ما قد يشكل عليهم، وإذا كان هناك بدع ظاهرة، أو معاصٍ ظاهرة، نبه عليها، وحذر منها، نعم.","link":"https://binbaz.org.sa/fatwas/13981/حكم-الدعاء-في-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56812.mp3","categories":["صلاة الجمعة"]},{"id":15464,"question":"ما الأمور -يا سماحة الشيخ حفظكم الله- التي يجب أن تشتمل عليها خطبة الجمعة؟","title":"ما ينبغي أن تشتمل عليه خطبة الجمعة؟","answer":"الجواب: مثلما تقدم، أولًا: حمد الله، والصلاة على النبي ﷺ، ويأتي بالشهادتين، ثم الموعظة، تذكير الناس، وعظهم بما يسر الله من الآيات والأحاديث، والكلام الطيب، ويقرأ بعض الآيات، نعم. المقدم: قراءة سَبِّحِ والغاشية -يا شيخ- واردة؟\nالشيخ: سنة مؤكدة، في صلاة الجمعة، سَبِّحِ والغاشية، أو الجمعة والمنافقين، سورة الجمعة وسورة المنافقين، أو سورة الجمعة مع هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ [الغاشية:1] كلها واردة. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13987/ما-ينبغي-ان-تشتمل-عليه-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56813.mp3","categories":["صلاة الجمعة"]},{"id":15500,"question":"سؤاله الثاني يقول: هل يشترط لصلاة العيد عدد معين، كصلاة الجمعة مثلًا، وما الحكم لو صادف العيد يوم الجمعة بالنسبة لصلاة الجمعة، فقد سمعت أنه لا جمعة للمأمومين بعكس الإمام، فكيف تجب على الإمام لوحده؟ وكيف يقيمها بمفرده؟","title":"العدد المطلوب لصلاة العيد، وحكم الجمعة والعيد إذا اجتمعا","answer":"الجواب: صلاة العيد وصلاة الجمعة من الشعائر العظيمة للمسلمين، فالجمعة عيد الأسبوع، وصلاة العيد عيد الأضحى، والفطر عيد سنوي، وكلاهما وكلتاهما واجبة: الجمعة فرض عين، وصلاة العيد فرض كفاية عند الأكثر، وفرض عين عند بعض أهل العلم كالجمعة. واختلف العلماء في العدد المشترط لهما، وأصح ما قيل في ذلك: أن أقل عدد ثلاثة فأكثر، وأما من اشترط أربعين فليس له دليل واضح يعتمد عليه.  ومن شرطها: الاستيطان تكون في البلد، أما أهل البر أهل البادية والمسافرون فليس عليهم جمعة ولا عيدًا؛ ولهذا لما حج النبي ﷺ حجة الوداع صادف الجمعة، ولم يصل جمعة، ولم يصل عيد يوم النحر؛ فدل ذلك على أن المسافرين ليس عليهم عيد ولا جمعة. وهكذا سكان البادية لا عيد ولا جمعة، وإذا وافق العيد يوم الجمعة جاز لمن حضر العيد أن لا يصلي الجمعة، وأن يصليها ظهرًا؛ لما ثبت عن النبي في هذا -عليه الصلاة والسلام-، فإنه ثبت عنه ﷺ أنه رخص في الجمعة لمن حضر العيد، وقال: اجتمع في يومكم هذا عيدان، فمن شهد العيد فلا جمعة عليه. فالمقصود: أو ما هذا معناه من كلامه ﷺ، المقصود: أنه ثبت عنه ﷺ ما يدل على الرخصة لمن شهد العيد أن لا يصلي الجمعة، ولكن لا يدع الظهر، بل عليه أن يصلي ظهرًا؛ لأنه أوجب علينا خمس صلوات في اليوم والليلة، فإذا لم يصل جمعة صلى ظهرًا، وليس لدينا يوم لا يجب فيه إلا أربع، بل علينا خمس صلوات سوى العيد، العيد صلاة سادسة، فإذا صادف العيد يوم الجمعة فإن عليه أن يصلي الظهر، إذا لم يصل الجمعة، نعم. المقدم: والإمام تكليف الإمام؟\nالشيخ: أما الإمام فيصلي بالناس يصلي بمن حضر، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14032/العدد-المطلوب-لصلاة-العيد-وحكم-الجمعة-والعيد-اذا-اجتمعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_702/nour_70202.mp3","categories":["صلاة الجمعة"]},{"id":15638,"question":"يقول: إذا كنت راع للغنم فهل تسقط عني صلاة الجمعة؟","title":"حكم صلاة الجمعة على راعي الغنم","answer":"الجواب: إذا كنت بعيدًا عن البلد لا تسمع الأذان بعيدًا؛ صل ظهرًا، أما إذا كنت تسمع النداء قريب من البلد فعليك أن تصلي الجمعة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14180/حكم-صلاة-الجمعة-على-راعي-الغنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70508.mp3","categories":["صلاة الجمعة"]},{"id":15687,"question":"رسالة وصلت إلى البرنامج من الجماهيرية الليبية، وباعثها المستمع: محمد علي شعبان، أخونا محمد يقول في أحد أسئلته: نحن نعمل في أحد الحقول النفطية بالصحراء، لدينا مسجد داخل الحقل، الحقل له بوابة واحدة، أقرب منطقة عنده تقدر بحوالي أربعين كيلو متر، ليس هناك أحد مقيم داخل الحقل أو خارجه بأسرته طول مدة يقضيها أحدنا بالحقل، وأكثر ما نقضي في الحقل أربعين يومًا، وليس لدينا إمام معين، وسؤالنا: هل تصح في هذا المسجد صلاة العيد وصلاة الجمعة؟جزاكم الله خيرًا.","title":"حكم صلاة العيد والجمعة لمن يعمل في الصحراء","answer":"الجواب: ما دام الحال كما ذكره السائل فليس عليكم جمعة ولا عيد؛ لأنكم لستم مستوطنين، إنما تقيمون أربعين يومًا، ثم ترجعون إلى أهليكم، فأنتم في هذه الحالة كسكان البادية، تصلون ظهرًا أربعًا، والعصر أربعًا، وهكذا، وليس عليكم جمعة، ما دام الأمر كما ذكرتم: ليس هناك سكان، وإنما هم العمال يعملون أكثر ما يعملون أربعين يومًا، ثم يرجعون إلى أهليهم، ويأتي غيرهم. فعليكم الصلوات الخمس أن تصلوها جماعة، يؤمكم أفضلكم وأقرؤكم، وإذا اخترتم واحدًا يؤمكم هو أقرؤكم كان ذلك أولى وأفضل، وليس عليكم جمعة ولا عيد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14241/حكم-صلاة-العيد-والجمعة-لمن-يعمل-في-الصحراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57208.mp3","categories":["صلاة الجمعة","صلاة العيدين"]},{"id":15689,"question":"يسأل سؤالًا آخر، ويقول: هل الرجل يؤم زوجته ومحارمه؟ وأين يكون وضع الإمام إذا كانت امرأة واحدة هل هي بجانبه أو خلفه؟","title":"حكم إمامة الرجل لمحارمه وأين تقف المرأة من الإمام؟","answer":"الجواب: يجوز له أن يأمهم إذا فاتته الصلاة مثلًا، أو كان مريضًا، أو في النافلة، يؤمهم، إن كن ثنتين أو ثلاث أو أكثر صففن خلفه، وإن كانت واحدة كذلك تكون خلفه، ولا يصفون معه، ولا عن يمينه، ولا عن شماله، ولو أنها واحدة، ولو أنها زوجته، الرسول ﷺ أمر أن يكون صفوفهن متأخرة عن الرجال، ولما صلى ذات يوم في بيت أنس بـأنس واليتيم صلت المرأة خلفهم، أم سليم خلف الجميع وهي واحدة، ولم تصف مع ابنها أنس، وابن ابنها اليتيم. فالمقصود: أن موقف المرأة خلف الرجال، ولو كانت واحدة، تقف خلف الرجل، ولو أنه زوجها أو أخوها تقف خلفه، لا عن يمينه، ولا عن شماله. أما الرجل فيقف عن يمنيه إذا كان واحدًا، وإن كان الرجال اثنين فأكثر وقفوا خلف الإمام. أما النساء فيقفن خلفه مطلقًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14243/حكم-امامة-الرجل-لمحارمه-واين-تقف-المراة-من-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57210.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":15690,"question":"السؤال الأخير يقول: هل النساء تؤمهن واحدة منهن؟ وكيف يكون وقوفها؟جزاكم الله خيرًا.","title":"كيفية صلاة النساء جماعة","answer":"الجواب: إذا تيسر من يؤمهن فهو أفضل، يتعلمن ويستفدن، وتكون وسطهن عن يمينها وعن شمالها، لا تتقدم، بل تكون وسطهن عن يمينها قوم، وعن شمالها قوم، ترفع صوتها بالقراءة حتى يستفيدوا في المغرب والعشاء والفجر كالرجل، وتعظهن إذا تيسر ذلك، وتذكرهن وتعلمهن بعد الصلاة، أو قبل الصلاة، وهن عن يمينها وشمالها وخلفها، نعم.\nويخترن أفضلهن أقرؤهن وأفضلهن، وإن صلت كل واحدة وحدها فلا حرج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14244/كيفية-صلاة-النساء-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57211.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":15712,"question":"سماحة الشيخ، هذا سائل يقول: نحن في مكان يبعد عن المسجد بمقدار أربعة كيلو متر، ولا نسمع الأذان، مع الرغم أن هناك خطيبًا يعيش معنا، فما الحد الأدنى لعدد المصلين لإتمام صلاة الجمعة؟","title":"العدد الذي تقام به الجمعة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد اختلف أهل العلم في العدد الذي تنعقد به الجمعة على أقوال، وأرجحها وأصوبها أن الثلاثة كافية، وأنه تقام بهم الجمعة، وتلزم بهم الجمعة إذا كانوا مستوطنين أحرارًا، فإذا كنتم ثلاثة أو عشرة أو أكثر أقيموا الجمعة لبعدكم عن مساجد الجمعة.  المقصود: أن الثلاثة فأكثر تقام بهم الجمعة إذا كانوا مستوطنين في المحل، أو كانوا أحرارًا، لا أرقاء، فإنهم تقام بهم الجمعة، هذا هو أسلم ما قيل في ذلك؛ لما في الجمعة من الخير العظيم في إقامتها من الخير العظيم، والمواعظ والتذكير، نعم.","link":"https://binbaz.org.sa/fatwas/14270/العدد-الذي-تقام-به-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57402.mp3","categories":["صلاة الجمعة"]},{"id":15758,"question":"رسالة وصلت إلى البرنامج من أحد المستمعين رمز إلى اسمه بالحروف (أ. م) من اليمن، يقول في أحد أسئلته: سماحة الشيخ، كنت في الماضي لا أصلي الجمعة، بل أصلي في البيت، وقبل ذلك كنت أصلي الظهر والجمعة؛ وذلك لجهلي، فماذا عليّ الآن؟ هل أصلي ركعتين إلى ركعتي الجمعة السابقتين بنية الظهر؟ وكيف الحال للتشهد؟بارك الله فيكم.","title":"ما يلزم من ترك الجمعة في المسجد فترة من الزمن؟","answer":"الجواب: عليك التوبة إلى الله مما سلف، التوبة الصادقة بالندم على الماضي، والعزم ألا تعود، وعليك أن تحضر الجمعة، وتصلي الجمعة مع المسلمين، والماضي عليك التوبة إلى الله منه، والحمد لله التوبة تجب ما قبلها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14356/ما-يلزم-من-ترك-الجمعة-في-المسجد-فترة-من-الزمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74110.mp3","categories":["صلاة الجمعة"]},{"id":15772,"question":"صليت الجمعة وأنا مسافر، فهل ما فعلته صحيح، وإن لم يكن فماذا أفعل؟","title":"صلاة الجمعة للمسافر تجزئ عن الظهر","answer":"الجواب: نعم، إذا صلى المسافر مع المقيمين صلاة الجمعة أجزأته عن الظهر، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14362/صلاة-الجمعة-للمسافر-تجزى-عن-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74115.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":15778,"question":"هل تجوز صلاة الجمعة بأقل من أربعين مصلٍ؟","title":"العدد الذي تقام به صلاة الجمعة","answer":"الجواب: نعم، الصواب أنه لا يشترط أربعون؛ لعدم الدليل، المشروط جماعة ثلاثة فأكثر، الشرط أن يكونوا جماعة ثلاثة فأكثر، هذا هو الصحيح إذا كانوا مستوطنين في قرية، وكانوا أحرارًا، فإنهم يصلون جمعة، ولو كانوا أقل من أربعين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14366/العدد-الذي-تقام-به-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74203.mp3","categories":["صلاة الجمعة"]},{"id":15836,"question":"ياسر القحطاني أرسل بمجموعة من الأسئلة يقول في السؤال الأول سماحة الشيخ: هل يكون الاستغفار في يوم الجمعة في الخطبة بين الخطبتين باللسان أو بالقلب؟ وإذا كان باللسان فهل أكون قد لغوت؟","title":"كيفية الاستغفار يوم الجمعة بين الخطبتين","answer":"الجواب: بين الخطبتين لا بأس يدعو أو يسبح أو يستغفر، بين الخطبتين لا بأس؛ لأنه ما هو بمحل سماع، الخطيب ساكت، وهكذا قبل الخطبة وبعد الخطبة ما يضر، لكن حال الخطبة ينصت ولا يتكلم بشيء، ينصت ويستمع إلا إذا مر ذكر النبي ﷺ يصلي -عليه عليه الصلاة والسلام-، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14427/كيفية-الاستغفار-يوم-الجمعة-بين-الخطبتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57528.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":15879,"question":"هل تجب على أهل البادية صلاة الجمعة وصلاة العيدين وغيرها من السنن المؤكدة؟","title":"حكم صلاة الجمعة والعيد على أهل البادية","answer":"الجواب: أهل البادية ليس عليهم صلاة جمعة، ولا عيد، لكن يصلون الظهر بسنتها، والمغرب والعشاء بسنتها، والفجر بسنتها، ويستحب لهم أن يصلوا قبل العصر أربع ركعات....، لكن الجمعة لا تجب عليهم، إنما تجب على أهل القرى والأمصار، وهكذا صلاة العيد، نعم.\nالمقدم: جزاكم الله خيرًا.\nالمقدم: يسأل سماحتكم عن السنن المؤكدة أيضًا؟\nالشيخ: هذا تعم الجميع؛ سنة الضحى، والتهجد بالليل، وسنة الاستخارة، كل هذه تعم الجميع البادية والحاضرة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14470/حكم-صلاة-الجمعة-والعيد-على-اهل-البادية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74416.mp3","categories":["صلاة الجمعة","صلاة العيدين"]},{"id":15930,"question":"نختم هذا اللقاء بهذا السؤال من أحد الإخوة السائلين، يقول: سماحة الشيخ، نحن مجموعة عمال عددنا خمسة عشر عاملًا، نعمل في الحراسة في المزارع أو الاستراحات، وليس حولنا جوامع تقيم الجمعة إلا بعيدًا، ويوم الجمعة نعاني كثيرًا حيث إن الجامع الذي يصلى فيه يبعد عنا مسافات طويلة يصعب علينا الذهاب إليه، فهل نقيم الجمعة في محلنا وعددنا كما ذكرت خمسة عشر، ويؤمنا ويخطب فينا أحد الإخوة ممن عندهم علم شرعي؟","title":"حكم صلاة الجمعة على من يعمل في الحراسة","answer":"الجواب: ليس لكم إقامة الجمعة، بل تصلون ظهرًا، إن تيسر لكم الصلاة في الجوامع الموجودة، فالحمد لله، وإلا صلوا ظهرًا إذا كنتم إنما أقمتم للحراسة لستم مستوطنين في المحل ساكنين في المحل سكن استيطان، إنما إقامتكم مؤقتة للحراسة، فليس عليكم جمعة، عليكم أن تصلوا ظهرًا، إلا إذا تيسر لكم الذهاب إلى الجوامع تصلوا فيها، ولو بعدت صليتم معهم جمعة، وإذا صبرتم وصليتم في الجوامع فهذا خير لكم عظيم.  نسأل الله لنا ولكم العون والتوفيق.\nالمقدم: إذا كانوا مستمرين في الحراسة لسنوات طويلة يا شيخ؟\nالشيخ: ولو، ليس عليهم جمعة إلا إذا استقروا فيها مستوطنين، مقيمين استيطانًا.\nالمقدم: وما أقل عدد تقام فيه الجمعة يا سماحة الشيخ؟ الشيخ: أصح ما قيل في ذلك ثلاثة إذا كانوا مستوطنين أحرار، في قرية مستوطنين.","link":"https://binbaz.org.sa/fatwas/14527/حكم-صلاة-الجمعة-على-من-يعمل-في-الحراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57720.mp3","categories":["صلاة الجمعة"]},{"id":15992,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول فيها: إني أعيش في البادية، وفي يوم الجمعة أسافر إلى أقرب قرية، وأصلي الجمعة، وأعود إلى أهلي في آخر النهار، وفي أثناء الطريق يجيء وقت العصر، هل الأفضل أن أقصر العصر ركعتين، أم أصلي أربعًا؟جزاكم الله خيرًا.","title":"حكم سفر أهل البادية لأداء صلاة الجمعة","answer":"الجواب: لا يلزمك السفر إلى القرية حتى تصلي الجمعة، وإنما عليك أن تصليها في محلك أربعًا، لكن إذا سافرت فلا بأس وصليت معهم الجمعة، أما كونك تصلي العصر في الطريق ركعتين، فهذا يحتاج إلى معرفة السفر، فإن كان ما بين محلك والقرية يعتبر مسافة قصر، يعني: يعتبر المسافة في يوم وليلة للمطية قدر ثمانين كيلو أو خمسة وسبعين كيلو تقريبًا، فلا مانع أن تقصر في الطريق، أما إذا كانت المسافة قريبة ثلاثين كيلو، أربعين كيلو، عشرين كيلو، تصليها أربعًا، هذا ما يسمى سفرًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14600/حكم-سفر-اهل-البادية-لاداء-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74702.mp3","categories":["صلاة الجمعة"]},{"id":16120,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من المستمع غازي علي الجرفي من ذمار يسأل جمعًا من الأسئلة في أحدها يقول: إذا كان الخطيب يخطب، والناس يتكلمون خارج هذا المسجد، فكيف تنصحونهم؟ جزاكم الله خيرًا، وهل للخطيب أن ينبههم إلى ما ينبغي أن يكونوا عليه؟","title":"توجيه الخطيب بإسكات الناس أثناء الخطبة","answer":"الجواب: نعم، إذا وجد من يشوش على الناس حول المسجد ينبههم الخطيب إذا كانوا يسمعون، أو يرسل لهم من يأمرهم بالسكوت، والبعد عن المسجد إذا لم يكونوا من أهل الصلاة، أو بالدخول في المسجد حتى يصلوا مع المسلمين، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14771/توجيه-الخطيب-باسكات-الناس-اثناء-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74915.mp3","categories":["صلاة الجمعة"]},{"id":16184,"question":"من أسئلة السائل يقول -يا سماحة الشيخ-: ما حكم الدعاء، ورفع اليدين بعد استراحة الخطيب يوم الجمعة؟ وما هي أوقات الإجابة في ذلك اليوم؟ جزاكم الله خيرًا.","title":"حكم رفع اليدين بين خطبتي الجمعة وأوقات الإجابه فيها","answer":"الجواب: رفع اليدين لا أعلم ورد في هذا شيء، لكن الدعاء طيب بين الخطبتين، إذا دعا ترجى الإجابة، وهكذا في سجوده في صلاة الجمعة، وفي التحيات، وبعد الشهادة، وبعد الصلاة على النبي ﷺ الدعاء ترجى إجابته في آخر صلاة الجمعة قبل أن يسلم، وفي السجود؛ كل هذا محل دعاء، وكذلك في ما بين السجدتين، إذا دعا؛ ترجى الإجابة. أما رفع اليدين ما أعلم ورد في هذا شيء في هذا الوقت، ولعل عدم الرفع أولى؛ لعدم وروده، والأصل جواز رفع اليدين؛ لأن النبي ﷺ أخبر أن رفع اليدين من أسباب الإجابة، فإذا رفع يديه في موضع لم يعلم عن النبي ﷺ أنه رفع وترك؛ فلا حرج. أما الموضع الذي يعرف أن النبي ﷺ ما رفع لا يرفع، مثل خطبة الجمعة لا يرفع؛ لأن النبي ﷺ ما رفع يديه في دعاء خطبة الجمعة، ولا في الدعاء بين السجدتين، ولا في الدعاء في التحيات لا يرفع، ولا إذا سلم من الصلاة الفريضة لا يرفع؛ لأن النبي ﷺ ما رفع في هذه المواضع.  أما إذا رفع في دعواته إذا دعا ربه، رفع بينه وبين ربه، أو بعد النافلة، إذا رفع بعض الأحيان بعد النافلة؛ فلا حرج، أما في دعائه بين الخطبتين هذا محل نظر، لم يبلغنا أن النبي ﷺ رفع، فالترك أحوط في مثل هذا؛ لأنه لم يبلغنا أن النبي ﷺ رفع بين الخطبتين، ولا دعا بين الخطبتين، فالأفضل الترك في هذا، يدعو بينه وبين نفسه فقط. المقدم: وما أرجى وقت للاستجابة يوم الجمعة؟ يا سماحة الشيخ يقول السائل. الشيخ: إذا جلس الإمام على المنبر إلى أن تقضى الصلاة، وكذلك بعد صلاة العصر إلى غروب الشمس، هذا أرجى يوم الجمعة، الإمام إذا صعد على المنبر حتى تنتهي الصلاة، وبعد صلاة العصر إلى غروب الشمس؛ هذا أرجى وقت للدعوة في يوم الجمعة ساعة الجمعة. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14853/حكم-رفع-اليدين-بين-خطبتي-الجمعة-واوقات-الاجابه-فيها","audio":"","categories":["صلاة الجمعة"]},{"id":16188,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: بعض الناس من المسلمين يستعملون المسواك، والخطيب يخطب يوم الجمعة، فما حكم عملهم؟ جزاكم الله خيرًا.","title":"حكم استخدام السواك أثناء الخطبة","answer":"الجواب: السنة وقت الخطبة الإنصات، وترك العبث؛ ولهذا قال ﷺ: من مس الحصى؛ فقد لغى السنة أن يترك السواك، ويترك العبث بالحركة، ويقبل على الخطبة مستمعًا منصتًا خاشعًا، هذا هو الأولى بالمؤمن، ولو أن السواك مشروع، لكن في غير هذا المحل، مشروع عند الدخول في الصلاة عند الوضوء ..... أن يتسوك في هذه الحالة، الأولى ترك ذلك؛ لأنه قد يشغله عن الاستماع المطلوب، مثلما أن مس الحصى، أو شبه ذلك قد يشغله عن ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14875/حكم-استخدام-السواك-اثناء-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75105.mp3","categories":["صلاة الجمعة"]},{"id":16210,"question":"من أسئلة السائل يقول -يا سماحة الشيخ-: ما حكم الدعاء ورفع اليدين بعد استراحة الخطيب يوم الجمعة؟ وما هي أوقات الإجابة في ذلك اليوم؟ جزاكم الله خيرًا.","title":"حكم الدعاء ورفع اليدين بين خطبتي الجمعة","answer":"الجواب: رفع اليدين لا أعلم ورد في هذا شيء، لكن الدعاء طيب بين الخطبتين، إذا دعا ترجى الإجابة، وهكذا في سجوده في صلاة الجمعة، وفي التحيات، وبعد الشهادة، وبعد الصلاة على النبي ﷺ الدعاء ترجى إجابته في آخر صلاة الجمعة قبل أن يسلم، وفي السجود؛ كل هذا محل دعاء، وكذلك فيما بين السجدتين إذا دعا؛ ترجى الإجابة. أما رفع اليدين ما أعلم ورد في هذا شيء في هذا الوقت، ولعل عدم الرفع أولى لعدم وروده، والأصل جواز رفع اليدين؛ لأن النبي ﷺ أخبر أن رفع اليدين من أسباب الإجابة، فإذا رفع يديه في موضع لم يعلم عن النبي ﷺ أنه رفع وترك؛ فلا حرج، أما الموضع الذي يعرف أن النبي ﷺ ما رفع لا يرفع، مثل خطبة الجمعة لا يرفع؛ لأن النبي ﷺ ما رفع يديه في دعاء خطبة الجمعة، ولا في الدعاء بين السجدتين، ولا في الدعاء في التحيات لا يرفع، ولا إذا سلم من الصلاة الفريضة لا يرفع؛ لأن النبي ﷺ ما رفع في هذه المواضع. أما إذا رفع في دعواته، إذا دعا ربه؛ رفع بينه وبين ربه، أو بعد النافلة إذا رفع بعض الأحيان بعد النافلة؛ فلا حرج، أما في دعائه بين الخطبتين هذا محل نظر؛ لم يبلغنا أن النبي ﷺ رفع، فالترك أحوط في مثل هذا؛ لأنه لم يبلغنا أن النبي ﷺ رفع بين الخطبتين، ولا دعا بين الخطبتين؛ فالأفضل الترك في هذا، يدعو بينه وبين نفسه فقط. المقدم: وما أرجى وقت للاستجابة يوم الجمعة يا سماحة الشيخ يقول السائل؟ الشيخ: إذا جلس الإمام على المنبر إلى أن تقضى الصلاة، وكذلك بعد صلاة العصر إلى غروب الشمس، هذا أرجى يوم الجمعة، الإمام إذا صعد على المنبر حتى تنتهي الصلاة، وبعد صلاة العصر إلى غروب الشمس؛ هذا أرجى وقت للدعوة في يوم الجمعة ساعة الجمعة. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14876/حكم-الدعاء-ورفع-اليدين-بين-خطبتي-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_580/58010.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":16329,"question":"يقول: إنني أعمل في مكان، وهذا المكان لا يمكّنني من أداء صلاة الجمعة، لكني بحمد الله أصلي كل فرض، فبم توجهونني؟","title":"حكم من كان في مكان لا يمكّنه من أداء الجمعة","answer":"الجواب: إذا كنت بعيدًا عن محل الجمعة فلا حرج عليك، إذا كنت بعيدًا لا تسمع النداء، خارج البلد في مزارع بعيدة؛ فليس عليك جمعة، عليك الظهر، أما إذا كنت تسمع النداء؛ فعليك أن تجيب الدعوة، عليك أن تحضر الجمعة إذا استطعت، أما إن كنت مريضًا لا تستطيع، أو حارسًا لا تستطيع ترك محل الحراسة؛ فأنت معذور، وإلا فالواجب عليك أن تبادر، وأن تصلي الجمعة مع الناس إذا كنت قريبًا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15018/حكم-من-كان-في-مكان-لا-يمكنه-من-اداء-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753016.mp3","categories":["صلاة الجمعة"]},{"id":16343,"question":"أيضًا من المدينة المنورة رسالة بتوقيع إحدى الأخوات تقول المرسلة: (م. أ) أختنا تسأل سماحتكم عن حكم غسل الجمعة للنساء اللائي لا يذهبن إلى المساجد، بل يصلين في بيوتهن، وإذا كان واجب عليهن فمتى يكون؟ هل هو قبل الظهر؟ جزاكم الله خيرًا.","title":"ما حكم غُسل الجمعة على النساء؟","answer":"الجواب: ليس على النساء غسل الجمعة، الغسل على من راح إلى الجمعة، كما قال النبي ﷺ: من راح إلى الجمعة؛ فليغتسل أما هن فالسنة لهن الصلاة في البيوت، وليس عليهن غسل، وإنما هو على الرجال، نعم.","link":"https://binbaz.org.sa/fatwas/15037/ما-حكم-غسل-الجمعة-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71406.mp3","categories":["صلاة الجمعة","الغسل"]},{"id":16373,"question":"يقول: أنا أعمل في مزرعة، والمسافة بين المزرعة والمسجد ثمانية كيلو مترات، وعندما أذهب لصلاة الجمعة أذهب ماشيًا على الأقدام، وأرجع ماشيًا، ولكن المشوار يؤثر علي في العمل، ولم أكمل في هذا اليوم عملي؛ لأني أحس بالتعب والإرهاق، هل علي ذنب في هذا العمل؟ أم أصلي في المزرعة؛ خوفًا من الله بأني قصرت في عملي في هذا اليوم؟ أفيدونا جزاكم الله خيرًا.","title":"حكم الجمعة لمن يؤثر بُعد المسجد عليه وعلى عمله","answer":"الجواب: إذا كان الواقع هو ما ذكرت؛ فلا يلزمك الذهاب إلى المسجد الذي يبعد عن المزرعة هذه المسافة ثمانية كيلو، ولك أن تصلي في المزرعة ظهرًا، وهكذا بقية الأوقات إذا كان حولك مسجد، وإذا كان عندك جماعة؛ صل مع الجماعة، صل مع الجماعة، ولا تصل وحدك، ولا تلزمك الصلاة في المسجد البعيد الذي ذكرت؛ لأن الرسول  قال: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر وهذه مسافة لا يسمع معها النداء، أما سماعه بالمكبر فلا يترتب عليه حكم. المقصود: سماعه بالسمع المعتاد، والصوت المعتاد، والأذان المعتاد، أما المكبرات فقد تسمع من بعيد، فلا يتعلق الحكم بها، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15083/حكم-الجمعة-لمن-يوثر-بعد-المسجد-عليه-وعلى-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75410.mp3","categories":["صلاة الجمعة"]},{"id":16402,"question":"هذا السائل مصري، ومقيم في المملكة، يقول سماحة الشيخ: أنا أعمل حارس معدات في شركة لوحدي في المحل، ويوجد جامع صلاة يبعد عن محلنا ثلاثة كيلو مترًا، هل أترك المحل، أو محل عملي، وأذهب للصلاة في الجامع؟ أم أصلي في محلي ظهرًا.","title":"حكم ترك صلاة الجمعة لأجل الحراسة","answer":"الجواب: إذا كنت مأمورًا بالحراسة، وتخشى على المحل؛ لا تذهب، صل في المحل، أما إذا كان المحل ما عليه خطر، في محل يغلق، وتذهب وتصلي وتعود، تذهب وتصلي مع الناس، أما إذا كان المحل عليه خطر، وأنت مأمور بالحراسة دائمًا حتى وقت الصلاة؛ فأنت معذور، تصلي في محلك. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15102/حكم-ترك-صلاة-الجمعة-لاجل-الحراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58120.mp3","categories":["صلاة الجمعة"]},{"id":16461,"question":"يقول: منعني صاحب العمل من أداء صلاة الجمعة لكي أعمل، وأواظب على الساعات الثمان، فماذا علي أن أفعل في ترك صلاة الجمعة؟","title":"حكم من يمنعه صاحب العمل من أداء الجمعة","answer":"لجواب: إن كنت حارسًا وقت الجمعة فالحارس معفو عنه، أما أن تدع الجمعة لقول صاحبك لا، لا... ولا يجوز طاعته في المعصية: إنما الطاعة في المعروف. فالعمال يصلون الجمعة مع الناس، ثم يرجعون للعمل كما يصلوا الأوقات الأخرى الخمس، على العامل والموظف أن يصلي الصلاة مع الجماعة في وقتها، ثم يرجع إلى عمله، إلا إذا كان حارسًا على شيء، إذا خرجوا يحرس؛ لئلا يؤخذ، أو لئلا يفسد، فهذا الحارس له عذر. فالحارس يصلي في مكانه الذي هو معذور، أما إنسان ليس بحارس، فالواجب عليه أن يصلي مع الناس في الجماعة العامل، وغير العامل، نعم. المقدم: جزاكم الله خيرًا، هو كما ذكر في سؤاله الأول سائق سماحة الشيخ؟ الشيخ: يلزمه أن يصلي مع الناس، نعم. المقدم: يلزمه أن يصلي مع الناس؟ الشيخ: يلزمه أن يصلي مع الناس، نعم. المقدم: وعليه أن يناقش صاحب العمل هذا؟ الشيخ: نعم، يقول النبي ﷺ: إنما الطاعة في المعروف ويقول ﷺ: لا طاعة لمخلوق في معصية الخالق نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15211/حكم-من-يمنعه-صاحب-العمل-من-اداء-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81311.mp3","categories":["صلاة الجمعة"]},{"id":16480,"question":"السؤال الأخير الذي نعرضه لأختنا في هذه الحلقة تقول: ما أرجى وقتٍ لساعة الإجابة في يوم الجمعة؟ جزاكم الله خيرًا.","title":"أرجى ساعةٍ للدعاء يوم الجمعة","answer":"الجواب: يوم الجمعة فيه ساعةٌ لا يُرد فيها سائلٌ سأل الله، وضرع إليه، وأخلص له، وصدق في الدعاء، كما أخبر بذلك الرسول الكريم -عليه الصلاة والسلام- ذكر أن فيه ساعةً لا يُرد فيها سائلٌ، وثبت عنه ﷺ ما يدل على أن أرجى وقتٍ لهذه الساعة وقتان: أحدهما: إذا جلس الإمام يوم الجمعة على المنبر للصلاة والخطبة؛ لأن فيه حديثًا صحيحًا رواه مسلمٌ عن بُريدة: أن هذه الساعة لا يُرد فيها السؤال ما بين جلوس الإمام على المنبر، إلى أن تُقضى الصلاة يوم الجمعة. والوقت الثاني: ما بين صلاة العصر إلى غروب الشمس، جاءت في ذلك أحاديث أيضًا تدل على أن هذا الوقت تُرجى فيه الإجابة من يوم الجمعة: ما بين صلاة العصر إلى غروب الشمس، هذا الوقت الثاني. وجميع أوقات الجمعة كلها محل دعاءٍ، إذا دعا بعد صلاة الجمعة، أو في الصباح، في أي جزءٍ من يوم الجمعة تُرجى فيه الإجابة، لكن هاتان الساعتان أرجى الساعات للإجابة، وهما: ما بين أن يجلس الإمام على المنبر إلى أن تُقضى الصلاة، وما بين صلاة العصر إلى غروب الشمس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15192/ارجى-ساعة-للدعاء-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75605.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":16507,"question":"من إحدى الأخوات المستمعات من المدينة المنورة تقول السائلة: (ن. ع) من المدينة المنورة، تقول: أرجو الإجابة على هذا السؤال، وجزاكم الله خيرًا: امرأة تسكن مع زوجها في الطابق الأعلى من المسجد، وهي تقوم بالصلاة وراء الإمام، وهي في غرفتها فوق المسجد، فهل صلاتها جائزة، أم لا؟ مع العلم أنها تقوم بمتابعة الإمام في الصلاة منذ سنتين تقريبًا، فهل الصلاة جائزة وصحيحة، أم لا؟ وإذا كانت غير جائزة، هل تقوم بقضائها؟ جزاكم الله خيرًا.","title":"حكم اقتداء المرأة بإمام لا تراه","answer":"الجواب: إذا كانت لا ترى الإمام، ولا المأمومين، فلا ينبغي لها أن تقتدي بالإمام، بل تصلي وحدها، وما مضى لا إعادة عليها فيه؛ لأن المسألة فيها خلاف بين أهل العلم، منهم من رأى جواز ذلك، فنرجو ألا يكون عليها إعادة، ولكن في المستقبل ننصحها أن تصلي وحدها، لا تتابع الإمام، إلا إذا كانت ترى الإمام، أو ترى بعض من خلفه، وإلا فإنها تصلي وحدها؛ لأن محلها ليس تابعًا للمسجد، المسجد مستقل، سطح المسجد على ما ذكره السائل مستقل، كأن الذي بنى المسجد إنما بنى خراج الطابق الأسفل، أما الطابق الأعلى فجعله مسكنًا، ليس من المسجد، ولهذا سكنه هو وأهله. فالحاصل: إذا كان سطح المسجد ليس تابعًا للمسجد، فإن أهله ينامون فيه، ويجامع زوجته، ويقضي حاجته؛ لأنه ليس تابعًا للمسجد، إنما بنى المسجد الذي تحت السقف. أما إذا كان المسجد بني للعبادة، وسقفه تبع له، ناويه تبع للمسجد، فهذا لا يسكن فيه فوق للمرأة وأهلها بحيث يجامعها فيه، وبحيث تحيض فيه، وبحيث تقضي حاجتها، ويقضي حاجته هذا؛ لأنه من المسجد، بل يصلى فيه، ويحفظ، ويصان؛ لأنه تابع للمسجد. أما إذا كان المسجد إنما هو الأسفل، وأما السطح فالذي عمر المسجد ما نوى السطح تبع المسجد، بل نواه سكنًا له، أو للتأجير، فهذا مستقل، ولا يكون له حكم المسجد، وللساكن فيه لا يصلي بإمامه في المسجد، إلا إذا كان يرى الإمام، أو يرى من خلفه، أو بعضهم من المأمومين، وإلا فإن المرأة فيه تصلي وحدها، أو المريض الذي فيه يصلي وحده، لا يصلي مع الناس، ما دام لا يرى الإمام، ولا يرى بعض من خلفه، لكن إذا كان السطح تابعًا للمسجد؛ فإنه لا يتخذ سكنًا بحيث يجامع فيه الرجل امرأته، وبحيث يقضي حاجته من بول، أو غيره، أو تجلس فيه الحائض؛ لأنه تابع للمسجد. أما إذا كان ليس تابعًا للمسجد، بل المسجد إنما هو ما تحته، فهو لأهله، مملوك لأهله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15246/حكم-اقتداء-المراة-بامام-لا-تراه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81405.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":16519,"question":"الرسالة التالية من المستمع محمد حسن النهاري ضمنها عدة قضايا في إحداها يقول: أنا خطيب جمعة في أحد المساجد في بلدتي، بم تنصحونني، وأي الكتب أقتنيها من أجل الخطبة؟ جزاكم الله خيرًا.","title":"الكتب المناسبة لخطيب الجمعة","answer":"الجواب: ننصحك بأن تعتني بالكتب التي ألفها العلماء الأخيار، وتستفيد منها في خطب الجمعة، وننصحك بعدم التطويل، بالاختصار، وعدم التطويل الذي يشق على الناس لقول النبي ﷺ: إن طول صلاة الرجل، وقصر خطبته مئنة من فقهه؛ فأطيلوا الصلاة، وأقصروا الخطبة رواه مسلم في الصحيح من حديث عمار بن ياسر . والكتب المؤلفة في هذا كثيرة، مؤلفة في خطب الجمعة، تقتني منها ما تيسر، وتستفيد منها، تنتفع منها، منها: لمشايخ أئمة الدعوة؛ الشيخ محمد عبدالوهاب، وغيره من المشايخ، منها: خطب لفضيلة الشيخ محمد بن صالح بن عثيمين، فضيلة الشيخ عبدالله بن حسن بن قعود، فضيلة الشيخ عبدالله خياط، وكتب أخرى تستفيد منها، تنتفع بها. ولكن مثل ما تقدم تحرص على عدم التطويل الذي يشق على الناس، وتتحرى الكلمات المناسبة الواضحة، وإيضاح الأحكام التي يحتاجها الناس، ولا سيما في الأوقات التي يناسب إيضاح الأحكام التي تناسبها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15235/الكتب-المناسبة-لخطيب-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75616.mp3","categories":["صلاة الجمعة"]},{"id":16544,"question":"تقول: كنت أجهل أن المرأة تصلي صلاة الجمعة ظهرًا أربع ركعات، بل كنت أصليها كما يصليها الرجال في البيت، فما الحكم؟ جزاكم الله خيرًا.","title":"ما يلزم من كانت تصلي الظهر يوم الجمعة ركعتين؟","answer":"الجواب: عليك أن تقضي تلك الأيام ظهرًا، حسب ظنك، واجتهادك ..","link":"https://binbaz.org.sa/fatwas/15282/ما-يلزم-من-كانت-تصلي-الظهر-يوم-الجمعة-ركعتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81512.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":16546,"question":"يسأل في سؤال طويل، ويذكر جدلًا دار بين جماعة حول السنة القبلية ليوم الجمعة، وملخص هذا  معرفة الحكم عن السنة القبلية ليوم الجمعة؟","title":"حكم السنة القبلية ليوم الجمعة","answer":"الجواب: يوم الجمعة ليس لها سنة قبلية، بل يصلي الإنسان ما يسر الله له، إذا جاء المسجد؛ صلى ما كتب الله له، ولم يحدد النبي ﷺ ركعات معدودة، بل قال: يصلي ما قدر له ويكفي، هكذا قال ﷺ قال ﷺ: من اغتسل يوم الجمعة، ثم أتى المسجد، فصلى ما قدر له، ثم أنصت حتى يفرغ من خطبته، غفر له ما بينه وبين الجمعة الأخرى، وفضل ثلاثة أيام. المقصود قوله: فصلى ما قدر له ولم يحدد ركعات معلومة، فدل ذلك على أنه مستحب، له أن يصلي ما يسر الله له، ركعتين على الأقل، أو أربع ركعات، أو أكثر من ذلك، ولو صلى حتى يخرج الإمام؛ فلا شيء عليه، كله طيب كله طيب، يصلي ثمانًا، أو عشرًا، أو أكثر، فإذا خرج الإمام للخطبة؛ جلس ينتظر الخطبة، والاستماع لها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15272/حكم-السنة-القبلية-ليوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81505.mp3","categories":["صلاة الجمعة"]},{"id":16552,"question":"من الدكتور (ب. أ. م) بالحرس الوطني رسالة وضمنها جمعًا من الأسئلة في أحد أسئلته يقول: نرى يوم الجمعة بين يدي الخطيب، وقبل الخطبة -والمؤذن يؤذن الأذان الثاني- أناسًا يقفون منتظرين انتهاء الأذان، ثم يصلون ركعتي تحية المسجد، فهل هناك من دليل على هذا؟ أم أنهم يصلون الركعتين غير منتظرين انتهاء الأذان؛ حتى يدركوا الخطبة، والتي هي واجب، والأذان سنة كما نعلم؟ جزاكم الله خيرًا.","title":"ما يفعل من دخل المسجد يوم الجمعة والمؤذن يؤذن؟","answer":"الجواب: هذا هو الأفضل، أن يسمع الأذان، ويجيب المؤذن، ثم يصلي ركعتين، ولا يمنعه ذلك من سماع الخطبة؛ لأن صلاة الركعتين أمر خفيف، وقتها خفيف، في إمكانه أن يصليها، والخطيب لم ينته من مقدمة الخطبة.  المقصود: أن الأفضل أنه يجيب المؤذن، ثم يصلي ركعتين، وإن صلى ركعتين وهو يؤذن، فلا حرج في ذلك، والحمد لله، لكن كونه يجمع بين السنتين: سنة إجابة المؤذن، وسنة تحية المسجد، فهذا هو الأفضل، لقول النبي ﷺ: إذا سمعتم المؤذن فقولوا مثل ما يقول. وقوله ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين فيجمع بين السنتين، هذا هو الأفضل أن يجمع بينهما، ولا يفوته بذلك سماع الخطبة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، الذي يناقش سماحة الشيخ، ويناقش كثيرًا من الناس معه، كيف أن الإنسان يهتم بالسنة، ويترك الواجب، ألا وهو الإنصات للخطبة، ما هو توجيهكم؟ الشيخ: الواجب الإنصات، إذا فرغ ينصت، يستمع، ولا يعبث، ولا يتكلم، هذا واجب عليه. الواجب على الجماعة أن ينصتوا للخطبة، الرسول ﷺ أمرهم بهذا، أمرهم بالإنصات، فالواجب أن ينصتوا، ويستفيدوا؛ لأن الخطبة من أجلهم، من أجل وعظهم، وتذكيرهم، فالواجب أن ينصتوا لها، ويستفيدوا مما يقوله الإمام، نعم. المقدم: جزاكم الله خيرًا، الذين يرون أن الانشغال بتأدية تحية المسجد عن الاستماع للخطبة، يرون أن هذا غير مستساغ ما هو توجيهكم؟ الشيخ: لا يضر هذا... لأنه يصلي ركعتين، والركعتان دقيقتان، أو دقيقة ونصف، ما تعطله عن الخطبة، الخطيب يجيب المؤذن، ويأتي بالذكر، بالدعاء بعد الأذان، والداخل كذلك يجيب المؤذن، ويأتي بالذكر بالدعاء، الشرعي، ثم يصلي ركعتين، والإمام في مقدمة الخطبة، نعم، وقد يسمع ما يقوله الخطيب، وهو في الصلاة لا يفوته.  المقدم: وهو في الصلاة. الشيخ: ما يفوته. المقدم: ولا يؤثر.  الشيخ: قد يسمع ما يقول الخطيب، وينتفع بما يقول الخطيب وهو في الصلاة. المقدم: جزاكم الله خيرًا. الشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/15283/ما-يفعل-من-دخل-المسجد-يوم-الجمعة-والموذن-يوذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75712.mp3","categories":["صلاة الجمعة"]},{"id":16584,"question":"السؤال الأخير الذي نعرضه له في هذه الحلقة يقول: إذا دخلت المسجد يوم الجمعة، وأدركت التشهد فقط من صلاة الجمعة، فهل أصلي ركعتين؟ أم أصليها ظهرًا أربع ركعات؟ وإذا صلى خلفي رجل آخر لم يدرك التشهد هل يصلي الجمعة، أم الظهر؟ جزاكم الله خيرًا؟","title":"حكم من أدرك التشهد من صلاة الجمعة","answer":"الجواب: عليكم أن تصلوا ظهرًا؛ لأن الجمعة ما تدرك إلا بركعة، فإذا جاء المسبوق، وقد فاتت الركعتان؛ يصلي ظهرًا، ينويها ظهرًا أربعًا، والذي يقتدي به كذلك ظهرًا؛ لأن الجمعة إنما تدرك بركعة واحدة يقول النبي ﷺ: من أدرك ركعة من الصلاة؛ فقد أدرك الصلاة نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15339/حكم-من-ادرك-التشهد-من-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75809.mp3","categories":["صلاة الجمعة"]},{"id":16634,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من نينوى، باعثها المستمع طالب ياسين علي عبدالرحمن، الأخ طالب عرضنا بعض أسئلته في حلقات مضت من حلقات هذا البرنامج، وبقي له في هذه الحلقة بعض الأسئلة يسأل هذا السؤال فيقول: هل صحيح أن صلاة الجمعة لا تصح إلا بعشرة مصلين؟ وأن الأفضل، والأتم أربعون مصليًا؟ أفيدونا أفادكم الله، ونفع بعلمكم.","title":"العدد الذي تنعقد به صلاة الجمعة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فقد اختلف أهل العلم في العدد الذي تصح به الجمعة، فقال جماعة: أربعون، وقال جماعة: أقل من ذلك، وقال بعضهم: أكثر من ذلك، والصواب: أنها تنعقد بثلاثة، الإمام، واثنين، فما زاد، هذا هو أرجح الأقوال في ذلك، فإذا وجد في القرية ثلاثة فأكثر، مستوطنون مكلفون؛ فإنها تقام فيهم الجمعة؛ لعموم الأدلة الشرعية؛ ولأن الثلاثة جمع؛ فتعمهم الأحاديث، وتعمهم الآية الكريمة، هذا هو أرجح الأقوال في هذه المسألة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15367/العدد-الذي-تنعقد-به-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_760/nour_76001.mp3","categories":["صلاة الجمعة"]},{"id":16796,"question":"يقول هذا السائل من ليبيا الطاهر: سماحة الشيخ! ما هي الشروط الواجب توفرها في خطيب الجمعة؟ وكذلك للصلوات الخمس؟","title":"شروط خطيب الجمعة وإمام الصلوات","answer":"الجواب: كونه مسلمًا، يجيد القراءة هذا هو المشروط فيه، أما كونه أعلم الناس، أو كونه عالمًا، أو كونه سنه كذا لا يشترط، لكن إذا تيسر أنه ذو بصيرة، وأن قراءته حسنة، ويجيد الخطبة هذا هو المطلوب يؤم القوم أقرؤهم لكتاب الله. هذا هو الأفضل، أن يكون أقرأ من غيره، يعني ذا قراءة جيدة، وذا علم وبصيرة، يستطيع الخطبة، سواءٌ كان كبير السن، أو شابًا، لكن يكون قد بلغ الحلم خروجًا من خلاف من قال: لا يؤم المتنفل المفترض، فإذا كان قد بلغ الحلم مكلفًا، كان أحوط؛ خروجًا من الخلاف، ويكون ممن يجيد القراءة، ويجيد الصلاة، يحسن الصلاة، ويجيد الخطبة إذا كان في الجمعة، وفي الأعياد ممن يجيد الخطبة، ولا يلحن في الفاتحة، بل يجيد قراءة الفاتحة. المقصود: أن يكون ممن يجيد القراءة التي تصح معها الصلاة، وأن يكون يجيد الخطبة حتى يعظ الناس، حتى يذكرهم في خطبة الجمعة، والأعياد، والأحوط أن يكون قد بلغ الحلم؛ خروجًا من خلاف من قال: لا تصح إمامة من كان متنفلًا بمن كان مفترضًا.  والصحيح: أنه تجوز إمامة المتنفل بمفترض، قد كان معاذ  يصلي مع النبي ﷺ العشاء، ثم يرجع فيصلي بأصحابه فريضتهم، وهو متنفل، والنبي ﷺ صلى صلاة الخوف فريضة في جماعة، ثم صلى صلاة الخوف بآخرين جماعة، وهي له نافلة، ولهم فرض -عليه الصلاة والسلام- نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15548/شروط-خطيب-الجمعة-وامام-الصلوات","audio":"","categories":["صلاة الجماعة","صلاة الجمعة"]},{"id":16802,"question":"من أسئلة هذا السائل يقول يا سماحة الشيخ: هل هناك دعاء معين يستحب لخطيب الجمعة أن يذكره عند صعوده للمنبر؟ وكيف يكون ذلك؟","title":"ما يقال عند صعود الخطيب المنبر؟","answer":"الجواب: لا أعلم شيئًا في هذا. أقول: لا أعلم شيئًا في هذا، نعم.","link":"https://binbaz.org.sa/fatwas/15550/ما-يقال-عند-صعود-الخطيب-المنبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58511.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":16810,"question":"من أسئلته عن خطبة الجمعة، يقول: شخص يخطب الجمعة خطبة واحدة، هل يكون قد خالف السنة بذلك؟","title":"حكم الاكتفاء بخطبة واحدة في الجمعة","answer":"الجواب: نعم، لا بد من خطبتين، من شرط صحة الجمعة خطبتان، كما كان النبي يفعل ﷺ وإذا لم يخطب إلا خطبة لم تصح الجمعة، بل عليه أن يأتي بالخطبة الثانية، ويعيد صلاة الجمعة، نعم.  المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15552/حكم-الاكتفاء-بخطبة-واحدة-في-الجمعة","audio":"","categories":["صلاة الجمعة"]},{"id":16834,"question":"هل تسقط صلاة الجمعة عن المسافر؟ وهل هناك مدة محددة للسفر، يكون المرء بعدها مقيمًا؟","title":"حكم صلاة الجمعة للمسافر","answer":"الجواب: المسافر لا تلزمه الجمعة، لكن إذا حضرها أجزأته، إذا مر ببلد، وصلى معهم أجزأته، وإلا فلا تلزمه، وقد صلى النبي ﷺ في حجة الوداع يوم الجمعة صلاة الظهر يوم عرفة، ولم يصل جمعة؛ لأنه مسافر، صلاها ظهرًا، كان يصلي في أسفاره ظهرًا، ولا يصلي جمعة.  والمدة التي يمنع فيها الإنسان من القصر، وتلزمه الجمعة أربعة أيام، فإذا نوى أكثر من أربعة أيام صلى جمعة، وصلى تمامًا، هذا الذي عليه جمهور أهل العلم، إذا نوى، دخل البلد ينوي إقامة أكثر من أربعة أيام عازمًا عليها من أجل حاجة في البلد؛ فإنه تلزمه الجمعة تبعًا لغيره، ويلزمه أن يصلي أربعًا، أما إن كانت النية أربعة أيام فأقل؛ فإنه يصلي ركعتين، لكن يلزمه أن يصلي الجماعة إذا كان ما عنده أحد، إذا كان وحده لا يصلي وحده، يصلي مع الناس جماعة؛ لأن الجماعة واجبة، فيصلي مع إخوانه جماعة، ويصلي أربعًا؛ لأن المسافر إذا صلى مع المقيمين صلى معهم أربعًا، وأما إذا كانوا جماعة اثنين فأكثر، فهم مخيرون، إن شاؤوا صلوا وحدهم قصرًا، وإن شاؤوا صلوا مع الجماعة أربعًا، نعم. المقدم: جزاكم الله خيرًا، إذًا أولئك الذين يقولون: الشخص المسافر وإن أقام أكثر من أربعة أيام في قولهم نظر سماحة الشيخ؟ الجواب: قول مرجوح نعم، وفيه خلاف بين العلماء، بعضهم يحدد خمسة عشر يومًا، بعض العلماء يحدد تسعة عشر يومًا، وبعضهم يحدد بأكثر من ذلك، وبعضهم لا يحدد. والأقرب والأظهر ما قاله الجمهور -رحمة الله عليهم- الأكثرون من التحديد بأكثر من أربعة أيام، إذا نوى أكثر من أربعة أيام؛ لأن الأصل في حق المقيم أن يصلي أربعًا، هذا هو الأصل، والأصل في حق المسافر أن يصلي ثنتين، ومن أقام أكثر غلب عليه حكم الإقامة، غلب عليه حكم الإقامة؛ ولأنه ﷺ لما أقام في حجة الوداع أربعة أيام صلى ثنتين، فدل على أن أربع لا ... السفر؛ لأنه قدم يوم الرابع من ذي الحجة ولم يصل ثنتين حتى توجه إلى منى وعرفات، عليه الصلاة والسلام. المقدم: اللهم صل على محمد، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15606/حكم-صلاة-الجمعة-للمسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82405.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":16851,"question":"هل تسقط صلاة الجمعة عن المسافر؟ وهل هناك مدة محددة للسفر، يكون المرء بعدها مقيمًا؟","title":"حكم صلاة الجمعة للمسافر","answer":"الجواب: المسافر لا تلزمه الجمعة، لكن إذا حضرها أجزأته، إذا مر ببلد، وصلى معهم أجزأته، وإلا فلا تلزمه، وقد صلى النبي ﷺ في حجة الوداع يوم الجمعة صلاة الظهر يوم عرفة، ولم يصل جمعة؛ لأنه مسافر، صلاها ظهرًا، كان يصلي في أسفاره ظهرًا، ولا يصلي جمعة.  والمدة التي يمنع فيها الإنسان من القصر، وتلزمه الجمعة أربعة أيام، فإذا نوى أكثر من أربعة أيام صلى جمعة، وصلى تمامًا، هذا الذي عليه جمهور أهل العلم، إذا نوى، دخل البلد ينوي إقامة أكثر من أربعة أيام عازمًا عليها من أجل حاجة في البلد؛ فإنه تلزمه الجمعة تبعًا لغيره، ويلزمه أن يصلي أربعًا، أما إن كانت النية أربعة أيام فأقل؛ فإنه يصلي ركعتين، لكن يلزمه أن يصلي الجماعة إذا كان ما عنده أحد، إذا كان وحده لا يصلي وحده، يصلي مع الناس جماعة؛ لأن الجماعة واجبة، فيصلي مع إخوانه جماعة، ويصلي أربعًا؛ لأن المسافر إذا صلى مع المقيمين صلى معهم أربعًا، وأما إذا كانوا جماعة اثنين فأكثر، فهم مخيرون، إن شاؤوا صلوا وحدهم قصرًا، وإن شاؤوا صلوا مع الجماعة أربعًا، نعم. المقدم: جزاكم الله خيرًا، إذًا أولئك الذين يقولون: الشخص المسافر وإن أقام أكثر من أربعة أيام في قولهم نظر سماحة الشيخ؟ الجواب: قول مرجوح نعم، وفيه خلاف بين العلماء، بعضهم يحدد خمسة عشر يومًا، بعض العلماء يحدد تسعة عشر يومًا، وبعضهم يحدد بأكثر من ذلك، وبعضهم لا يحدد. والأقرب والأظهر ما قاله الجمهور -رحمة الله عليهم- الأكثرون من التحديد بأكثر من أربعة أيام، إذا نوى أكثر من أربعة أيام؛ لأن الأصل في حق المقيم أن يصلي أربعًا، هذا هو الأصل، والأصل في حق المسافر أن يصلي ثنتين، ومن أقام أكثر غلب عليه حكم الإقامة، غلب عليه حكم الإقامة؛ ولأنه ﷺ لما أقام في حجة الوداع أربعة أيام صلى ثنتين، فدل على أن أربع لا ... السفر؛ لأنه قدم يوم الرابع من ذي الحجة ولم يصل ثنتين حتى توجه إلى منى وعرفات، عليه الصلاة والسلام. المقدم: اللهم صل على محمد، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15606/حكم-صلاة-الجمعة-للمسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82405.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":16857,"question":"هذه أخت سائلة (ح. م. أ) من المملكة تقول: سماحة الشيخ فتاة في أيام الامتحانات تذاكر، وجاء وقت صلاة العشاء، ولم تصل، وتعلم بخروج الوقت إلى أن أصبحت الساعة الثانية عشرة ليلًا، وبعدما انتهت من المذاكرة؛ صلت العشاء، فما الحكم؟ وهي نادمة على ذلك، هل عليها كفارة؟","title":"ما حكم تأخير العشاء إلى منتصف الليل؟","answer":"الجواب: الواجب عليها التوبة إلى الله إذا خرج الوقت؛ لأن الوقت ينتهي بنصف الليل، عليها أن تصلي العشاء قبل نصف الليل، فإذا تساهلت؛ فعليها التوبة والاستغفار، تصلي ولو بعد نصف الليل، لكن تستغفر ربها، ولا تعود، النبي ﷺ قال: وقت العشاء إلى نصف الليل يبتدئ حساب الليل من غروب الشمس بالساعة. فالمقصود: أن السنة لها، بل الواجب عليها، وعلى غيرها أن تكون صلاة العشاء قبل نصف الليل، ولا بأس بتأخيرها بعد الثلث الأول قبل نصف الليل، لا بأس، لكن التأخير إلى بعد نصف الليل لا يجوز.","link":"https://binbaz.org.sa/fatwas/15597/ما-حكم-تاخير-العشاء-الى-منتصف-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58605.mp3","categories":["صلاة الجمعة","وقت الصلاة","قضايا المرأة"]},{"id":16913,"question":"يقول: هل هناك سنة للجمعة؟ لأن بعض المؤذنين هنا بعد الانتهاء من الأذان الأول يقول: سنة الجمعة، يرحمكم الله.","title":"سنة الجمعة القبلية والبعدية","answer":"الجواب: هذا غلط، هذا المؤذن الذي يقول هكذا؛ ..... غلط، بدعة لا أصل لها، والجمعة ليس لها راتبة قبلها، بل يصلي ما يسر الله، يصلي ثنتين، أو أربع ركعات -تسليمتين- أو ست ركعات -ثلاث تسليمات- أو أكثر، يصلي ما قدر له إذا وصل المسجد، والحمد لله، وليس هناك حد محدود قبل صلاة الجمعة، ولو صلى مائة ركعة قبل أن يدخل الإمام، يسلم من كل ثنتين. أما بعدها، فالأفضل أربع ركعات، النبي  قال: إذا صلى أحدكم الجمعة فليصل بعدها أربعًا وقال: من كان مصليًا بعد الجمعة فليصل بعدها أربعًا فالسنة أن يصلي بعدها أربعا -تسليمتين- سواء في المسجد، أو في البيت، هذا هو الأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15687/سنة-الجمعة-القبلية-والبعدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82607.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":17077,"question":"السائل محمود القرالة من الأردن، يقول: سماحة الشيخ! أود أن أسأل عن خطبة الجمعة إذا قال الخطيب: قولوا: لا إله إلا الله، فهل نفعل ذلك؟ أم يكون هذا غير جائز؟ وهل نرفع الأيدي أثناء التأمين على دعاء الخطيب؛ لأن إمام المسجد ينكر على من يرفع يديه أثناء التأمين على الدعاء؟","title":"حكم رفع الأيدي بالدعاء أثناء خطبة الجمعة","answer":"الجواب: إذا قال: قولوا: لا إله إلا الله، أو صلوا على رسول الله، نعم، يذكر الله، ويصلي على النبي، لكن من دون جهر، من دون أن يشغل من حوله، بصوتٍ منخفض، يصلي على الرسول، يذكر الله بصوتٍ منخفض.  ولكن لا يرفع الأيدي، لا الإمام ولا المأموم، لا يرفعون أيديهم، إنما هذا في الاستسقاء، إذا استسقى، طلب السقيا، طلب المطر يرفع يديه، والمأمومون يرفعون أيديهم. أما الخطبة العادية يوم الجمعة إذا دعا فيها لا يرفع يديه، ولا يرفعون أيديهم المأمومون، كلهم لا يرفعون؛ لأن الرسول ما كان يرفع -عليه الصلاة والسلام- إلا في الاستسقاء. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15885/حكم-رفع-الايدي-بالدعاء-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58817.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":17124,"question":"من أسئلته يقول: أيهما أفضل للمرأة: الصلاة في بيتها، أو في المسجد؟","title":"أفضلية الصلاة في البيت على المسجد للمرأة","answer":"الجواب: الصلاة في بيتها أفضل، قال النبي ﷺ: بيوتهن خير لهن وهو أستر لهن، وأبعد عن الفتنة، فالبيت أفضل.","link":"https://binbaz.org.sa/fatwas/15937/افضلية-الصلاة-في-البيت-على-المسجد-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58919.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":17131,"question":"من أسئلة هذا السائل يا سماحة الشيخ يقول حفظكم الله: بأنه يعمل راعيًا في البر، ولم يصل الجمعة حتى يعود إلى بلده، وذلك لمدة سنتين، ولا يوجد -يقول- مسجد عندنا، فما الحكم في ذلك؟","title":"حكم صلاة الجمعة لمن لا يسمع النداء","answer":"الجواب: إذا كان بعيدًا عن المساجد، لا يسمع النداء، ما عليه جمعة، إذا كان في البر مع الإبل، أو مع البقر، أو مع الغنم راعيًا؛ ليس عليه جمعة، يصلي ظهرًا، أما إذا كان في البلد يصلي مع الناس جمعة، أما إذا كان بعيدًا لا يسمع النداء في البر فهذا يصلي ظهرًا. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15950/حكم-صلاة-الجمعة-لمن-لا-يسمع-النداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58922.mp3","categories":["صلاة الجمعة"]},{"id":17203,"question":"تقول السائلة من الأردن سماحة الشيخ من عمان: ما هو الأفضل للمرأة، أن تصلي في البيت؟ أم في المسجد؟","title":"أفضلية صلاة المرأة في البيت","answer":"الجواب: الأفضل لها في البيت، صلاة المرأة، في بيتها أفضل مع الطمأنينة والخشوع والعناية بالوقت والطهارة، صلاتها في البيت أفضل، وإن صلت مع الرجال متسترة محتشمة لطلب الفائدة، وسماع المواعظ، وسماع الأحاديث فلا بأس، الرسول ﷺ نهى أن يمنعن من المساجد، لكن يخرجن وهن متسترات. نعم.","link":"https://binbaz.org.sa/fatwas/16025/افضلية-صلاة-المراة-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59031.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":17256,"question":"يقول هذا السائل سماحة الشيخ: أرجو منكم التوضيح عن الساعة الأولى في يوم الجمعة، فأنا أريد أن أذهب في الساعات الأول؟ وهل هي الساعة العاشرة، أو التاسعة، أو الثامنة؟ وماذا ورد في الأحاديث في التبكير لصلاة الجمعة يا سماحة الشيخ؟","title":"تحديد الساعة الأولى من يوم الجمعة","answer":"الجواب: ثبت في الصحيحين أنه ﷺ قال: من راح في الساعة الأولى فكأنما قرب بدنة، ومن راح في الساعة الثانية فكأنما قرب بقرة، ومن راح في الثالثة فكأنما قرب كبشًا أقرن، ومن راح في الساعة الرابعة فكأنما قرب دجاجة، ومن راح في الساعة الخامسة فكأنما قرب بيضة. هذا فيه فضل عظيم ينبغي التبكير، والمسارعة إلى الجمعة حتى يجتهد في القراءة، والصلاة قبل أن يأتي الإمام، إذا جاء المسجد يشتغل بالصلاة، ويصلي ما كتب الله له، ثم يجتهد في القراءة، يقرأ ما كتب الله له، حتى يطلع الإمام، حتى يخرج الإمام للصلاة، هذا فضل عظيم. أما الساعة الأولى فالله أعلم بها، لكن الأقرب -والله أعلم- أنها بعد ارتفاع الشمس بقيد رمح، بعدما يصلي سنة الإشراق، سنة الضحى المبكرة، هذا هو الأقرب -والله أعلم- أن هذه الساعة الأولى؛ لأن السنة للمصلي أن يبقى في مصلاه حتى ترتفع الشمس، فيكون بعد هذا إذا راح في الساعة الأولى بعدما تطلع الشمس، وبعدما يقضي حاجته في بيته، يذهب إلى المسجد، هذه هي الساعة الأولى -والله أعلم- هذا هو الأقرب، والله أعلم. نعم.  المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16095/تحديد-الساعة-الاولى-من-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59210.mp3","categories":["صلاة الجمعة"]},{"id":17318,"question":"يسأل ويقول: ما حكم المداومة على الدعاء بعد نهاية خطبة الجمعة، هل هو بدعة؟ أم أن ذلك من الجواز؟ جزاكم الله خيرًا.","title":"حكم المداومة على الدعاء في نهاية خطبة الجمعة","answer":"الجواب: كان النبي ﷺ يدعو في خطبته، كان النبي يدعو في خطبه -عليه الصلاة والسلام- فلا حرج إذا دعا في خطبته، فهو مشروع. نعم. الجمعة، والعيد، والاستسقاء كلها يدعى فيها. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16172/حكم-المداومة-على-الدعاء-في-نهاية-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83310.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":17399,"question":"من السائل من الجمهورية العربية اليمنية ناحية وصاب السافل، عبده حسن قائد يسأل ويقول: إذا دخلت المسجد يوم الجمعة، والمؤذن يؤذن الأذان الأخير، فهل أصلي تحية المسجد؟ أم أستمع للأذان؟ والناس قد أنكروا علي إذ صليت والمؤذن يؤذن، وقالوا: يستحسن أن تتابع المؤذن، ثم تصلي السنة.","title":"المشروع لمن دخل المسجد والمؤذن يؤذن للجمعة","answer":"الجواب: هذا هو الأفضل، قد أصابوا في نصيحتك، فالأفضل أن تجمع بين الحسنيين، وبين العبادتين، تجيب المؤذن، ثم تصلي ركعتين، والحمد لله، ثم تجلس للاستماع. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16272/المشروع-لمن-دخل-المسجد-والموذن-يوذن-للجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83507.mp3","categories":["صلاة الجمعة"]},{"id":17499,"question":"السائلون في هذا السؤال يقولون: نحن مجموعة من الشباب من جمهورية مصر العربية نقيم بالمملكة ونعمل لمدة ما يقارب من اثنا عشر ساعة فترة مسائية من سبع مساء وحتى السابعة صباحًا، في بعض الأوقات تفوتنا صلاة الظهر خاصة يوم الجمعة، وهذا الدوام الليلي بصفة مستمرة، مما يترتب علينا النوم بالنهار لفترات طويلة، ماذا نعمل في ذلك؟ وهل نأثم بتركنا صلاة الجمعة وصلاة الظهر؟","title":"حكم النوم عن صلاة الظهر وصلاة الجمعة","answer":"الشيخ: نعم، عليكم أن تصلوا الجمعة وأن تصلوا الظهر مع الناس، ولا يجوز لكم الموافقة على عمل يمنعكم ذلك، لا طاعة لمخلوق في معصية الخالق، يقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق، فالواجب عليكم أن تصلوا الجمعة، وأن تصلوا مع الناس، وعلى صاحبكم أن يسمح لكم بذلك، وأن تكون فترات الصلاة مستثناة، فترات الصلاة مستثناة يجب عليكم وعلى صاحبكم. ولا يجوز التساهل في هذا الأمر بل يجب أن تعتنوا بهذا الأمر، وأن تشترطوا عليه أن أوقات الصلاة مستثناة؛ لأنها فرض على الجميع، فالله يقول جل وعلا: حَافِظُوا عَلَى الصَّلَوَاتِ[البقرة:238]، ويقول: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ[البقرة:43]، ويقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر قيل لابن عباس ما هو العذر؟ قال: خوف أو مرض». وتقدم حديث الأعمى الذي قال: «يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ قال: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب، أعمى ليس له قائد أمره أن يجيب، يلتمس من يقوده حتى يوصله إلى المسجد. نعم.\nالمقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16422/حكم-النوم-عن-صلاة-الظهر-وصلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_774/nour_77409.mp3","categories":["صلاة الجمعة"]},{"id":17560,"question":"هذا السائل يقول في سؤاله لم يذكر الاسم في هذه الرسالة: متى يدخل يوم الجمعة، وهل يجوز أن يغتسل الإنسان بعد صلاة المغرب يوم الخميس عن غسل الجمعة، ومتى ينتهي هذا اليوم؟ جزاكم الله خيرًا.","title":"متى يدخل يوم الجمعة؟","answer":"الجواب: يوم الجمعة مثل غيره يدخل بطلوع الفجر، فإذا اغتسل بعد طلوع الفجر أو بعد طلوع الشمس حصل له السنة، والأفضل أن يكون اغتساله عند التوجه إلى الصلاة إذا أراد التوجه يغتسل عند التوجه، هذا هو الأفضل، وإن اغتسل بعد صلاة الفجر أو بعد طلوع الشمس فلا بأس.\nالمقصود أن يوم الجمعة مثل غيره يدخل يوم الجمعة كل يوم يدخل بطلوع الفجر. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16473/متى-يدخل-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77517.mp3","categories":["صلاة الجمعة"]},{"id":17561,"question":"من اليمن السائلة (هـ. ن. أ) تقول: هل يجوز للمرأة أن تصلي صلاة الفجر بعد الأذان الأول مباشرة قبل الإقامة وقبل الأذان الثاني بحيث إنني سمعت أن المرأة ليس لها إقامة؟","title":"حكم صلاة المرأة للفجر بعد الأذان الأول","answer":"الجواب: الواجب على الرجال والنساء ألا يصلوا الفجر إلا بعد طلوع الفجر الصادق، بعد طلوع الفجر الصادق، وبعد الأذان الذي أذان الفجر، أما الأذان الأول الذي يؤذن به في آخر الليل لتنبيه الناس هذا ما يدخل به وقت الصلاة، ولا تصلى الفريضة بعده، ولكن إذا أذن المؤذن الذي يؤذن على طلوع الفجر الصادق على الصبح فيصلي الرجال والنساء، أما الأذان الأول اللي قبل طلوع الفجر فهذا للإعلام فقط أن الفجر قريب حتى يعلم الناس أنه قريب، اللي يوتر يوتر، واللي يقوم يتوضأ. وأما الفريضة فلا تصلى إلا بعد طلوع الفجر الصادق للرجل والمرأة جميعًا، وليس للمرأة إقامة ولا أذان، لكن متى طلع الفجر وأذن المؤذن، وسمعت الأذان؛ تتأخر بعض الشيء ثم تصلي، لا تعجل حتى يمضي وقت من باب الاحتياط، فإذا مضى وقت ربع ساعة ثلث ساعة صلت أو نصف ساعة صلت الفجر، ولا يلزمها التقيد بالمساجد وأن تسمع الإقامة، لا، صلاتها مستقلة تصلي سواء سمعت الإقامة أو ما سمعت الإقامة، متى أذن ومضى وقت بعد الأذان ربع ساعة ثلث ساعة للاحتياط صلت الفريضة، وهكذا الظهر، والعصر، والمغرب، والعشاء. نعم.\nالمقدم: جزاكم الله خيرًا، بعض النساء يا سماحة الشيخ ينتظرن حتى يخرج الرجال من المساجد؟\nالشيخ: هذا لا أصل له، صلاة المرأة ما هي مربوطة بالرجال، تصلي في بيتها متى دخل الوقت وأذن المؤذن والحمد لله، الرجال لهم صلاتهم، وهي لها صلاتها في بيتها، غير مربوطة بالرجال. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16484/حكم-صلاة-المراة-للفجر-بعد-الاذان-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77521.mp3","categories":["صلاة الجمعة","وقت الصلاة","قضايا المرأة"]},{"id":17646,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من الأردن جرش، باعثة الرسالة إحدى الأخوات المستمعات من هناك، تقول: أختكم في الله فاطمة محمد ، أختنا عرضنا لها سؤالًا في حلقةٍ مضت، وفي هذه الحلقة تسأل عن حديث الرسول ﷺ الذي معناه: ومن مس الحصى فقد لغا ماذا يقصد بالحصى؟ وهل هي مقصودة لذاتها؟ أو أنها تشير إلى معانٍ فقط؟ جزاكم الله خيرًا.","title":"معنى حديث: \"من مس الحصى فقد لغا\"","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد:\nهذا الحديث الصحيح أرشد به النبي ﷺ إلى الإنصات للخطيب يوم الجمعة، وعدم العبث بما يشغله عن سماع الخطبة، ومس الحصى من ذلك، وليس مقصودًا بذاته، بل المقصود العناية في الاستماع، والبعد عما يشغل عن الاستماع والإنصات، فإذا مس الحصى، أو مس أشياء أخرى في المسجد، من أهداب الفرش، أو من أوراقٍ عنده، أو ما أشبه ذلك، أشبه ذلك مس الحصى.\nفالمقصود كله؛ هو أن ينصت للخطيب، وأن يفرغ قلبه لذلك، ويكف جوارحه عن العبث الذي قد يشغله عن الاستماع، ومعنى فقد لغا أي لغت جمعته، يعني ما يكون له ثواب الجمعة، يكون له ثواب الظهر، ما هو ثواب الجمعة؛ يعني يفوته الثواب العظيم الذي رتبه الله على الجمعة. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16577/معنى-حديث-من-مس-الحصى-فقد-لغا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72701.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":17786,"question":"هذا سائل للبرنامج من الكويت (أ. ف) يقول سماحة الشيخ حفظكم الله: قرأت في كتاب العبارات التالية وأريد من سماحتكم بيان صحة ذلك، العبارة: واختلف في هذه الساعة -يعني: ساعة الاستجابة في يوم الجمعة - ففي أفراد مسلم من حديث أبي موسى: أنها ما بين أن يجلس الإمام إلى أن تنقضي الصلاة وفي حديث آخر: هي ما بين فراغ الإمام من الخطبة إلى أن تقضى الصلاة، وفي حديث جابر: بأنها في آخر ساعة بعد العصر، وفي حديث أنس قال: التمسوها ما بين صلاة العصر إلى غروب الشمس، وقال أبو بكر الأثرم: لا تخلو هذه الأحاديث من وجهين:إما أن يكون بعضها أصح من بعض.وإما أن تكون هذه الساعة تنتقل في الأوقات، كتنقل ليلة القدر في ليالي العشر.هل صحيح يا سماحة الشيخ أن هذه الساعة تنتقل في الأوقات؟ وكذلك ليلة القدر تنتقل في ليالي العشر؟","title":"فضيلة ساعة الجمعة ووقت التماسها","answer":"الجواب: نعم، ليلة القدر تتنقل في الليالي العشر من الحادية والعشرين إلى الثلاثين، ترجى في الليالي كلها، لكنها في الأوتار آكد، وهكذا ساعة الجمعة ترجى فيما بين جلوس الإمام على المنبر إلى أن تقضى الصلاة، وبعد العصر إلى غروب الشمس، كلها مظنة لهذه الساعة كما جاءت بها الأحاديث، فيستحب للمؤمن أن يتحراها في هذه الأوقات، يدعو في هذه الأوقات: بين جلوس الإمام على المنبر يوم الجمعة إلى أن تقضى الصلاة: في سجوده، وبين الخطبتين، وقبل الدخول في الصلاة، يدعو بما تيسر من الدعوات الطيبة، وفي آخر الصلاة قبل أن يسلم، وهكذا بعد العصر: يجلس في مصلاه ينتظر الصلاة؛ لأن من جلس ينتظر الصلاة فهو في صلاة، فإذا جلس في مصلاه ينتظر صلاة المغرب، ودعا ربه آخر نهار الجمعة؛ ترجى له الإجابة. نعم.","link":"https://binbaz.org.sa/fatwas/16771/فضيلة-ساعة-الجمعة-ووقت-التماسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59703.mp3","categories":["صلاة الجمعة"]},{"id":17808,"question":"تقول هذه السائلة يا سماحة الشيخ: هل للمرأة صلاة جمعة في المسجد الحرام؟ وهل تصلي مثل الرجال صلاة جمعة؟ أم لا بد أن تصلي صلاة الظهر حتى ولو كان في المسجد الحرام؟","title":"حكم صلاة المرأة للجمعة","answer":"الجواب: ليس عليها جمعة المرأة، ليس عليها جمعة بل عليها أن تصلي الظهر في بيتها، فإن صلت مع الناس الجمعة أجزأتها إن صلت الجمعة مع الناس في المسجد أجزأتها عن الظهر وكفت، وإلا فإنها تصلي في بيتها ظهرًا أربع ركعات، لكن لو حضرت الجمعة في المسجد الحرام أو غيره وصلَّت مع الناس الجمعة أجزأت وكفت عن الظهر والحمد لله.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16799/حكم-صلاة-المراة-للجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77818.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":17863,"question":"تقول السائلة من مكة المكرمة سماحة الشيخ: قال ﷺ: من توضأ يوم الجمعة فبها ونعمت، ومن اغتسل فالغسل أفضل رواه أحمد ، وحديث: غسل الجمعة واجب على كل محتلم رواه الشيخان، كيف نجمع بين هذين الحديثين، وهل الاغتسال سنة أم واجب، وما معنى على كل محتلم، واشرحوا لنا الأحاديث؟","title":"الجمع بين «غسل الجمعة واجب على كل محتلم»، «ومن اغتسل فالغسل أفضل»","answer":"معنى واجب يعني: متأكد، ليس معناه الوجوب الذي يأثم به، معناه المتأكد، ولهذا جاء في الحديث معناه: \"وأن يستاك ويتطيب\" والسواك والطيب مستحبان عند الجميع، بإجماع أهل العلم، وجاء في الحديث من توضأ يوم الجمعة ثم أتى المسجد وصلى ما قدر له ثم أنصت حتى ... الخطبة كتب له .. كان له ثواب الجمعة وما بعدها إلى جمعة أخرى.","link":"https://binbaz.org.sa/fatwas/16872/الجمع-بين-غسل-الجمعة-واجب-على-كل-محتلم-ومن-اغتسل-فالغسل-افضل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59808.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":17907,"question":"رسالة بعث بها المستمع: أحمد مصبح أحمد، من الدقهلية، في جمهورية مصر العربية، أخونا يقول: إنني من سكان قرية الحجايجة بمحافظة الدقهلية بجمهورية مصر العربية، يقول: يوجد بأغلب المساجد يوم الجمعة قارئٌ للقرآن يقرأ القرآن بصوتٍ عالٍ في الميكرفون، ويستمع إليه المصلون حوالي نصف ساعة، وعندما ينتهي من قراءة آية من القرآن؛ يهللون، وترتفع أصواتهم، علمًا بأن أغلب المصلين يجهلون القراءة والكتابة، فرجائي من سماحتكم إفادتي بصحة قراءة القرآن يوم الجمعة بهذه الصورة، أم أن هذه دخلت علينا من باب البدع؟ وهل هي مكروهة؟ وهل للجمعة أذانان؟ أم أذانٌ واحد؟ جزاكم الله خيرًا.","title":"حكم قراءة القرآن يوم الجمعة في الميكرفون","answer":"الجواب: إذا كان المأمومون محدودين، ورضوا بذلك؛ أن يقرأ قارئ حتى يستمعوا ويستفيدوا، لأنهم لا يقرءون؛ فلا حرج في ذلك، ولكن ليس لهم هذه الفوضى والكلام بعد ذلك، وإنما يستمعون، وينصتون، وإذا مرت آية فيها تسبيح، أو دعاء، ودعوا؛ لا بأس، أما هذا الضجيج الذي يفعلونه بعد ذلك، هذا لا ينبغي لهم.\nأما إذا كان ليس عددهم مضبوطًا، وليس كلهم موافقين؛ فإنه لا ينبغي هذا، لأن هذا يشغلهم، ويمنع الآخرين من القراءة، فالأولى أن كل واحد يقرأ لنفسه، يستفيد، يقرأ لنفسه، ويستمع من حوله، و لا يزعجهم واحد بالمكبر.\nأما إذا كانوا محدودين، أميين محدودين، وحبوا أن يسمعوا قارئ منهم؛ حتى يحضر الخطيب، فلا حرج في ذلك. سؤاله الثاني.","link":"https://binbaz.org.sa/fatwas/16912/حكم-قراءة-القران-يوم-الجمعة-في-الميكرفون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72813.mp3","categories":["القرآن وعلومه","صلاة الجمعة"]},{"id":18099,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة يقول: المرسل ( عبد العزيز . س. ع) أخونا له تسعة أسئلة، من أسئلته يسأل ويقول: ما هي ساعات الجمعة التي وردت في حديث الرسول ﷺ فيما معناه: من أتى في الساعة الأولى فكأنه قدم بدنة إلى آخر الحديث؟","title":"شرح حديث: \"من راح إلى الجمعة...\"","answer":"الجواب: هذا الحديث صح عن رسول الله عليه الصلاة والسلام في الصحيحين أنه قال عليه الصلاة والسلام: من راح إلى الجمعة في الساعة الأولى فكأنما قرب بدنة، ومن راح في الساعة الثانية فكأنما قرب بقرة، ومن راح في الساعة الثالثة فكأنما قرب كبشًا أقرن، ومن راح في الرابعة فكأنما قرب دجاجة، ومن راح في الخامسة فكأنما قرب بيضة الحديث. وهو حديث عظيم شريف صحيح وهو يدل على شرعية التبكير إلى الجمعة، وذلك أمر معروف عند أهل العلم ودلت عليه الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام. أما المبدأ فقيل: يبدأ من بعد صلاة الفجر، وقيل: من طلوع الشمس، وهذا محتمل؛ لأن الرسول ﷺ ما بين المبدأ، قال: (من راح)، (من بكر وابتكر) فلم يبين المبدأ. والأقرب والله أعلم أنه من طلوع الشمس؛ لأن الصفرة تابعة لما قبلها وهي محل الجلوس في المساجد والتعبد والذكر والاستغفار وقراءة القرآن أو الذهاب إلى البيت لحاجة وقضاء الحاجة من تعاطي أول الطعام الذي يستعين به على البقاء في المسجد للجمعة.. إلى غير ذلك. فالأقرب والله أعلم والأحرى أنه يكون بعد ارتفاع الشمس، حتى إذا ذهب للمسجد يكون محل الصلاة والتعبد، هذا هو الأقرب والأظهر والله أعلم، يعني الساعة الأولى من بعد ارتفاع الشمس وحل الصلاة للمسلم في مسجده وبيته، هذا هو الأقرب والأحرى. نعم. المقدم: جزاكم الله خيرًا. هل قسم الليل والنهار سماحة الشيخ في عهد النبي ﷺ أو في عهد صحابته؟ الشيخ: ظاهر الأحاديث أن الليل اثنا عشر والنهار اثنا عشر، يجزأ اثنا عشر ساعة والنهار كذلك. نعم. المقدم: جزاكم الله خيرًا، إذًا التقسيم وارد فكأن الوقت الأول ما يقرب من الواحدة صباحًا بالتوقيت ..... الشيخ: ....... على حسب اختلاف الأوقات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17134/شرح-حديث-من-راح-الى-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_903/nour_90306.mp3","categories":["صلاة الجمعة","شروح الحديث"]},{"id":18121,"question":"السائل جلال حباب له مجموعة من الأسئلة يقول: إلى والدنا سماحة الشيخ عبد العزيز بن باز لي مجموعة من الأسئلة، يقول في سؤاله الأول: ماذا يقول خطيب الجمعة عندما يصعد المنبر في خطبة الجمعة؟","title":"ما يقوله الخطيب عند صعوده المنبر","answer":"الجواب: يسلم، يقول: السلام عليكم، إذا صعد الخطيب يسلم ثم يجلس، فإذا فرغ المؤذن قام وخطب، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17156/ما-يقوله-الخطيب-عند-صعوده-المنبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78106.mp3","categories":["صلاة الجمعة"]},{"id":18167,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخ المستمع سعد إبراهيم عبد الحميد أبو دوقة مصري يعمل في القصيم - بريدة، أخونا بدأ رسالته بقوله: بسم الله الرحمن الرحيم موجه لسماحة الشيخ عبد العزيز بن باز ، أشهد الله أنني أحبك في الله، وأرجو أن تتفضل بإجابتي على الآتي:أولاً: يوجد بالشركة التي نعمل بها عمال ينطقون بأكثر من عشر لغات ولا يعلمون اللغة العربية، فهل يجوز خلال خطبة الجمعة أن يوجد من يترجم الخطبة، يعني يخطب الخطيب لمدة عشر دقائق ثم يليه المترجم وهكذا، أرجو أن توجهونا؟ جزاكم الله خيرًا.","title":"حكم إلقاء خطبة الجمعة بغير اللغة العربية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا ريب أن تفهيم الناس مقاصد الخطبة بلغتهم التي يفهمونها أمر مهم، والحاجة إليه ماسة، كتبنا في ذلك ما شاء الله مما نرجو أن ينفع الله به الأمة، والذي نرى في ذلك هو أنه ينبغي للخطيب إذا كان يجيد لغة الحاضرين أن يبين لهم بلغتهم معاني الخطبة ومقاصد الخطبة حتى تتم الفائدة، وإذا كان لا يجيد ذلك فلا مانع من وجود مترجم يترجم مقاصد الخطبة للحاضرين الذين لا يفهمون اللغة العربية، سواء كان ذلك في أثناء الخطبة بعد كل جمل يتكلم بمعانيها بلغتهم، أو عند نهاية الخطبة يترجم لهم مقاصدها ومعانيها حتى يستفيدوا من ذلك وحتى تحصل الفائدة لهم كما حصلت لغيرهم من إخوانهم الذين يفهمون لغة الخطيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17206/حكم-القاء-خطبة-الجمعة-بغير-اللغة-العربية","audio":"","categories":["صلاة الجمعة"]},{"id":18188,"question":"السائلة من الرياض تذكر في سؤالها تقول: في مسجد الحي يوجد مدرسة لتحفيظ القرآن الكريم خاصة بالنساء وهي موجودة في الجزء الخلفي من المسجد، ومفصولة عنه بجدار بينهما، باب مغلق، هذه المدرسة تدرس أو تدرس فيها الطالبات حتى ولو كن حيض، بحكم انعزالها عن المسجد.والسؤال هو: بأنه إذا مات أحد الأقارب قامت النساء بالصلاة على الجنازة مقتديات بالإمام في صلاة الجنازة وصلاة الفرض معها في هذا المكان أي المدرسة، فما حكم هذا الفعل وهل الصلاة تصح؟","title":"حكم صلاة النساء مع الإمام في مكان ملاصق للمسجد","answer":"الجواب: ما دمن يرين الإمام والمأمومين، لا بأس تصح الصلاة؛ لأنها ليست تبع المسجد، فلا حرج أن يحضرها النساء الحيض وغير ذلك ما دام خارجة عن سور المسجد، وإذا صلى فيها النساء تبع الإمام على جنازة أو في الفريضة وهن يرين الإمام أو المأمومين، ويسمعن الصوت؛ لا حرج، الحمد لله. نعم. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/17241/حكم-صلاة-النساء-مع-الامام-في-مكان-ملاصق-للمسجد","audio":"","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":18333,"question":"هذا السائل يقول يا سماحة الشيخ! ما هو المشروع أثناء دعاء الخطيب في صلاة الجمعة، هل نؤمن على دعاء الإمام رافعين اليدين؟ أم نؤمن على دعائه دون رفع اليدين؟","title":"حكم رفع اليدين والتأمين في خطبة الجمعة","answer":"الجواب: لا يرفع يديه، ولا ترفعون أيديكم، لا يرفع هو ولا يرفع المأمومون، التأمين بينك وبين نفسك، وهو يدعو من دون حاجة إلى رفع اليدين، إلا في الاستسقاء؛ إذا كان يستغيث يرفع يديه ويرفعون أيديهم، أما الدعاء العادي في الخطب خطبة الجمعة لا يرفع يديه لا يرفع هو ولا يرفع المأموم؛ لأن النبي ﷺ ما كان يرفع في الخطبة خطبة الجمعة عليه الصلاة والسلام. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/17384/حكم-رفع-اليدين-والتامين-في-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91316.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":18362,"question":"من سوريا أبو محمد يقول: هل ورد أحاديث وآيات تدل على فضل التبكير لصلاة الجمعة يا شيخ؟","title":"فضل التبكير إلى صلاة الجمعة","answer":"الجواب: نعم، التبكير لها سنة، ومن هذا الحديث الصحيح الذي رواه الشيخان في الصحيحين أنه قال ﷺ: الرائح إلى الجمعة في الساعة الأولى كالمقرب بدنة، وفي الساعة الثانية كالمقرب بقرة، وفي الساعة الثالثة كالمقرب كبشًا، وفي الرابعة كالمهدي دجاجة، والخامسة كالمهدي بيضة. هذا يدل على شرعية التبكير وتفاوته، وأن السنة للمؤمن أن يبكر للصلاة لما في هذا من الخير العظيم، يصلي ما يسر الله من الركعات، يقرأ القرآن، يشتغل بالتسبيح والتهليل والاستغفار، فيه فوائد جمة -في التبكير- فالسنة التبكير إليها؛ لما في ذلك من الخير العظيم والفوائد الجمة. نعم. المقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/17424/فضل-التبكير-الى-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78323.mp3","categories":["صلاة الجمعة"]},{"id":18474,"question":"أختنا تسأل أيضًا وتقول: عندما يؤذن المؤذن، هل يصح للمرأة أن تصلي أم تتأخر وقتًا قليلًا حتى تقام الصلاة، وبعد ذلك تصلي لنفسها؟","title":"هل تصلي المرأة بعد الأذان أم تنتظر الإقامة من المساجد؟","answer":"الجواب: ليس لها ارتباط بالرجال، بل متى دخل الوقت؛ فإنها تصلي سواء كان ذلك قبل صلاة الرجال أو بعد صلاة الرجال، وليس لها ارتباط بإقامة الصلاة في المساجد، بل متى أذن ومضى بعض الوقت؛ فإنها تصلي ولا تبادر من حين الأذان؛ لأنه قد يكون الأذان مبكرًا، فإذا تركت قليلًا وتمهلت قليلًا، ثم تصلي فهو أحسن، احتياطًا من دخول الوقت. نعم.","link":"https://binbaz.org.sa/fatwas/17564/هل-تصلي-المراة-بعد-الاذان-ام-تنتظر-الاقامة-من-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_866/nour_86605.mp3","categories":["صلاة الجمعة","وقت الصلاة","قضايا المرأة"]},{"id":18522,"question":"في سؤالهن الأول يقلن: ما حكم إمامة المرأة في الشريعة الإسلامية؟ وما دليل ذلك من القرآن أو السنة أو من اجتهاد الأئمة الأربعة؟","title":"حكم إمامة المرأة","answer":"الجواب: فإمامة المرأة للنساء لا بأس بها، ولا حرج فيها، وهي جائزة، بل مستحبة عند الحاجة إلى ذلك للتعليم والتوجيه، ويعمهن قوله ﷺ: يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء فأعلمهم بالسنة، فإن كانوا في السنة سواء فأقدمهم هجرة الحديث.. قد ثبت عن عائشة وأم سلمة أنهما أمتا بعض النساء، فإذا تيسر للمرأة القارئة الفقيهة أن تؤم نساء أهل دارها، أو يجتمع عندها بعض أخواتها، وتأمهن، فهذا كله حسن، وفيه مصالح، وقد روي عن أم ورقة -رضي الله عنها- أنها كانت تؤم أهل دارها. فالحاصل: أن إمامة المرأة للنساء لا بأس بها، ولا حرج فيها، بل هي مستحبة إذا دعت الحاجة إلى ذلك، وصارت الإمامة عندها علم وفقه، حتى تعلم أخواتها وتفقهن، وحتى يتأسين بصلاتها في قراءتها وركوعها وسجودها وجلستها بين السجدتين واعتدالها بعد الركوع إلى غير ذلك، هذا كله ينفع النساء كما ينفع الرجال، نعم.","link":"https://binbaz.org.sa/fatwas/17618/حكم-امامة-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_869/nour_86902.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":18531,"question":"في سؤالهن الأول يقلن: ما حكم إمامة المرأة في الشريعة الإسلامية؟ وما دليل ذلك من القرآن أو السنة أو من اجتهاد الأئمة الأربعة؟","title":"حكم إمامة المرأة","answer":"الجواب: فإمامة المرأة للنساء لا بأس بها، ولا حرج فيها، وهي جائزة، بل مستحبة عند الحاجة إلى ذلك للتعليم والتوجيه، ويعمهن قوله ﷺ: يؤم القوم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء فأعلمهم بالسنة، فإن كانوا في السنة سواء فأقدمهم هجرة الحديث.. قد ثبت عن عائشة وأم سلمة أنهما أمتا بعض النساء، فإذا تيسر للمرأة القارئة الفقيهة أن تؤم نساء أهل دارها، أو يجتمع عندها بعض أخواتها، وتأمهن، فهذا كله حسن، وفيه مصالح، وقد روي عن أم ورقة -رضي الله عنها- أنها كانت تؤم أهل دارها. فالحاصل: أن إمامة المرأة للنساء لا بأس بها، ولا حرج فيها، بل هي مستحبة إذا دعت الحاجة إلى ذلك، وصارت الإمامة عندها علم وفقه، حتى تعلم أخواتها وتفقهن، وحتى يتأسين بصلاتها في قراءتها وركوعها وسجودها وجلستها بين السجدتين واعتدالها بعد الركوع إلى غير ذلك، هذا كله ينفع النساء كما ينفع الرجال، نعم.","link":"https://binbaz.org.sa/fatwas/17618/حكم-امامة-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_869/nour_86902.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":18612,"question":"هل يحرم البيع أثناء الأذان وبعده؟ وكيف الحال في يوم الجمعة؟ هل يحرم البيع بعد الأذان الأول أو الثاني؟جزاكم الله خيرًا.","title":"حكم البيع أثناء أذان الجمعة وغيره","answer":"الجواب: البيع يحرم بعد الأذان الأول في الجمعة؛ لأن الله قال: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ [الجمعة:9] فلا يجوز البيع والشراء ولا الإجارة ولا المساقات ولا غير ذلك، بل يجب أن يتفرغ للعبادة، ويبادر لصلاة الجمعة، ولا يتشاغل بشيء آخر. أما الأوقات الأخرى فقد تلحق بالجمعة، وقد لا تلحق، فالأحوط له أن لا يفعل شيئًا بعد الأذان، .. الظهر أو العصر أو المغرب؛ لأنه قد يشغله عن الجماعة، فالأحوط له أن يحذر ذلك، إلا أن يكون شيئًا يسيرًا لا يشغل، فلعله لا حرج فيه؛ لأن الله -جل وعلا- إنما جاء عنه النص في صلاة الجمعة؛ لأن أمرها عظيم، ويجب حضورها، وتفوت بفواتها، فأمرها أعظم، وهي فرض الأسبوع. فالمقصود: أن الجمعة لا يقاس عليها غيرها، لكن إذا حذر هذا الشيء، وابتعد عنه؛ لئلا يشغله عن الجماعة كان هذا أولى، وبكل حال إذا كان بيعه قد يشغله عن أداء الصلاة في الجماعة حرم، لكن في بعض الأحيان تكون الصلاة متأخرة، كأن يتأخر الإمام، ويمكن الإنسان أن في طريقه أن يشتري السلعة ويبيعها، فقد لا يضر حضوره للصلاة، وبكل حال أن كونه يبتعد عن هذا الشيء......، فيما جاء في الجمعة، يكون هذا أحوط حتى تكون حتى.....، الجمعة بالحذر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17719/حكم-البيع-اثناء-اذان-الجمعة-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_734/nour_73411.mp3","categories":["صلاة الجمعة"]},{"id":18628,"question":"هذا سائل للبرنامج يقول في سؤاله الأول: هل يجوز للخطيب إذا طلع على المنبر أن يخطب باللغة العربية، ويعيد الترجمة بعد ذلك في بعض اللغات على المنبر؟ علمًا بأن أكثر المصلين لا يفهمون اللغة العربية سماحة الشيخ.","title":"حكم ترجمة خطبة الجمعة بعد إلقائها بالعربية","answer":"الجواب: هذا أحسن -إن شاء الله- يخطب باللغة العربية، ويفسر للحاضرين بلغتهم التي يعقلونها إذا كان أكثرهم لا يعقلون اللغة العربية ولا يفهمونها؛ حتى يحصل لهم الفائدة، يوضح لهم ويبين في الخطبة المهمات التي تنفعهم، حتى يحصل لهم الفائدة من الخطبة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17748/حكم-ترجمة-خطبة-الجمعة-بعد-القاىها-بالعربية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78715.mp3","categories":["صلاة الجمعة"]},{"id":18634,"question":"في آخر أسئلة هذا السائل يقول: هل يجوز للمصلين لصلاة الجمعة أن يصلوا الجمعة وبعد ذلك مباشرة يصلون الظهر؟ علمًا بأنهم ناس مستوطنين ومقيمين في هذه المدينة.","title":"حكم أداء صلاة الظهر بعد صلاة الجمعة","answer":"الجواب: صلاة الظهر بعد الجمعة بدعة لا يجوز، الجمعة كافية، ولا يجوز صلاة الظهر صلاتين، الله ما أوجب إلا خمس صلوات، هذا يأتي بصلاة سادسة، لا يجوز هذا، الجمعة كافية، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17752/حكم-اداء-صلاة-الظهر-بعد-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78717.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":18638,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع: ياسر محمد خليل، سوري مقيم في العراق، أخونا يقول: إنني في بلد غير بلدي، ولا أعرف مدة الإقامة في هذا البلد، فهل تعتبر صلاة الجمعة واجبة علي؟ وهل أعتبر مسافرًا أم لا؟ أفيدوني جزاكم الله خيرًا.","title":"حكم صلاة الجمعة لمن في بلد ولا يعرف مدة إقامته","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد بين أهل العلم مقتضى ما دلت عليه سنة رسول الله -عليه الصلاة والسلام- أن الرجل إذا أقام في بلد وليس له نية معروفة، يعني: لا يدري هل يقيم يومًا أو يومين أو أربعًا أو أكثر، فإنه في حكم السفر، وله القصر، وله الجمع، ولا تلزمه الجمعة، بل له حكم المسافرين، لكن إذا كان فردًا ليس معه أحد، فالواجب عليه أن يصلي مع الجماعة لوجوب الجماعة، فيصلي مع الجماعة الأوقات الخمسة، ويصلي معهم الجمعة من أجل وجوب الجماعة. وأما إن كان الموجود اثنين فأكثر فهم مخيرون؛ إن شاؤوا صلوا مع الجماعة، وأتموا أربعًا، وصلوا الجمعة وأجزأتهم، وإن شاؤوا صلوا ظهرًا قصرًا، نعم. المقدم: جزاكم الله خيرًا. هذا إذا لم يعرف مدة الإقامة؟ الشيخ: نعم. المقدم: وإذا عرف؟ الشيخ: أما إذا أجمع الإقامة على مدة أكثر من أربعة أيام، فإنه تلزمه الجمعة بغيره، تلزمه بغيره، ويلزمه أن يتم الأربع، يتم الظهر والعصر والعشاء أربعًا عند جمهور أهل العلم، نعم. المقدم: جزاكم الله خيرًا، إذا صادف ذلكم الصيام شيخ عبد العزيز ؟ الشيخ: كذلك يصوم. المقدم: يصوم؟ الشيخ: نعم، يصوم رمضان، ليس له الفطر، إذا كان أجمع الإقامة أكثر من أربعة أيام، نعم، عند جمهور أهل العلم، وهو قول جيد، وفيه جمع بين الأقوال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17750/حكم-صلاة-الجمعة-لمن-في-بلد-ولا-يعرف-مدة-اقامته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91901.mp3","categories":["صلاة الجمعة","صلاة المسافر"]},{"id":18639,"question":"يقول: هل يجوز للنساء الذهاب إلى المسجد ليصلين الجمعة والجماعة، علمًا بأن مدخل المسجد واحد، ولكن النساء يصلين لحالهن في غرفة مستترة؟","title":"حكم صلاة الجمعة والجماعة في المسجد للنساء","answer":"الجواب: يجوز نعم، لكن بيوتهن خير لهن، صلاتها في البيت ظهرًا أفضل، لا تصلي جمعة، تصلي في البيت أفضل، مثلما قال ﷺ: بيوتهن خير لهن يقول ﷺ: لا تمنعوا إماء الله مساجد الله، وبيوتهن خير لهن فإذا صلين في المسجد متسترات بعيدات عن الفتنة، وعن الطيب؛ فلا حرج، ولكن بيتها خير لها وأفضل، وإذا صلت مع الناس الجمعة أجزأتها الجمعة، أما في بيتها فإنها لا تصلي إلا ظهرًا أربعًا، تصلي في بيتها ظهرًا أربعًا، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17751/حكم-صلاة-الجمعة-والجماعة-في-المسجد-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78716.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":18641,"question":"يسأل أخونا: هل تجب إعادة صلاة الظهر بعد صلاة الجمعة في بلد تعددت فيه المساجد؟","title":"هل يصلى الظهر بعد الجمعة في بلد به عدة مساجد؟","answer":"الجواب: لا، لا يجوز ذلك، بل الواجب أن يتحرى ويصلي الجمعة والحمد لله، وليس له أن يعيد ظهرًا؛ لأن هذه بدعة ليس لها أصل، متى صلى الجمعة فالحمد لله، والتعدد له مسوغات، فحسن الظن بالمسلمين وأنها إنما تعددت لمسوغ شرعي أولى من سوء الظن، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17753/هل-يصلى-الظهر-بعد-الجمعة-في-بلد-به-عدة-مساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91902.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":18779,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخ المستمع سعد إبراهيم عبد الحميد أبو دوقة مصري يعمل في القصيم، بريدة، أخونا بدأ رسالته بقوله:بسم الله الرحمن الرحيم، موجه لسماحة الشيخ عبد العزيز بن باز ، أشهد الله أنني أحبك في الله، وأرجو أن تتفضل بإجابتي على الآتي:أولًا: يوجد بالشركة التي نعمل بها عمال ينطقون بأكثر من عشر لغات، ولا يعلمون اللغة العربية، فهل يجوز خلال خطبة الجمعة أن يوجد من يترجم الخطبة، يعني يخطب الخطيب لمدة عشر دقائق، ثم يليه المترجم وهكذا؟أرجو أن توجهونا، جزاكم الله خيرًا.","title":"حكم ترجمة خطبة الجمعة أثناء إلقاء الخطيب","answer":"الجواب: بسم الله الرحمن الرحيم  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا ريب أن تفهيم الناس مقاصد الخطبة بلغتهم التي يفهمونها أمر مهم، والحاجة إليه ماسة، كتبنا في ذلك ما شاء الله مما نرجو أن ينفع الله به الأمة، والذي نرى في ذلك هو أنه ينبغي للخطيب إذا كان يجيد لغة الحاضرين أن يبين لهم بلغتهم معاني الخطبة، ومقاصد الخطبة حتى تتم الفائدة. وإذا كان لا يجيد ذلك فلا مانع من وجود مترجم يترجم مقاصد الخطبة للحاضرين الذين لا يفهمون اللغة العربية، سواء كان ذلك في أثناء الخطبة بعد كل جمل يتكلم بمعانيها بلغتهم، أو عند نهاية الخطبة يترجم لهم مقاصدها ومعانيها حتى يستفيدوا من ذلك، وحتى تحصل الفائدة لهم كما حصلت لغيرهم من إخوانهم الذين يفهمون لغة الخطيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17908/حكم-ترجمة-خطبة-الجمعة-اثناء-القاء-الخطيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_906/nour_90601.mp3","categories":["صلاة الجمعة"]},{"id":18836,"question":"يسأل أخونا ويقول: هل يجوز رفع الأيدي عندما يدعو الخطيب يوم الجمعة؛ لأني سمعت أنه لا يجوز رفع الأيدي عند دعاء يوم الجمعة؟","title":"حكم رفع الأيدي أثناء دعاء الخطيب يوم الجمعة","answer":"الجواب: لم يرد عن النبي ﷺ أنه كان يرفع يديه في خطبة الجمعة؛ ولما رأى بعض الصحابة بعض الأمراء يرفع يديه في خطبة الجمعة أنكر ذلك، والعبادة توقيفية ليس للرأي فيها مجال، فلا ينبغي للخطيب يوم الجمعة أن يرفع يديه في الدعاء؛ لأن هذا لم ينقل عن النبي ﷺ إلا إذا كان يستسقي، يعني: يستغيث يطلب الله الغوث من أجل الجدب والقحط فلا بأس أن يرفع يديه في خطبة الجمعة، عند دعاء الاستغاثة، كما فعل ذلك النبي الكريم -عليه الصلاة والسلام-، فإنه لما استغاث يوم الجمعة في خطبة الجمعة رفع يديه، ودعا، ورفع الناس أيديهم. أما في الخطب العادية التي ليس فيها استغاثة، فإنه لا يرفع يديه؛ لماذا؟ لأن الرسول ﷺ ما كان يرفع يديه، وهو الذي يقول: صلوا كما رأيتموني أصلي والله يقول: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، فلما كان -عليه الصلاة والسلام- لا يرفع في خطبة الجمعة، وهكذا خطبة العيد، فإنه لا يشرع لنا أن نرفع فيهما إلا في الاستسقاء في خطبة الاستسقاء، أو في الجمعة، أو في العيد إذا استسقى يرفع يديه، كما فعل النبي -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17968/حكم-رفع-الايدي-اثناء-دعاء-الخطيب-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92110.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":18894,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع سلامة عبد الخالق، أخونا يقول: نحن عشرة، ونعمل في مزرعة، ونبعد عن أقرب مسجد لنا حوالي أربعة كيلو مترات، فقام فرد منا نحن العشرة، وحضر خطبة الجمعة، وخطب فينا في نفس مكان العمل، هل ما فعلناه صحيح؟جزاكم الله خيرًا.","title":"حكم إقامة الجمعة في مزرعة بعيدة عن المسجد","answer":"الجواب: إذا كنتم ساكنين في المحل فلا بأس أن تقيموا صلاة الجمعة؛ لأنكم بعيدون عن الجوامع، أما إذا كنتم لا، إنما تأتون إلى المزرعة لبعض الإصلاحات؛ فليس لكم أن تصلوا الجمعة فيها، بل عليكم أن تسعوا إلى الجمعة، فإن لم تسعوا صلوا ظهرًا في محلكم؛ لأنكم بعيدون، وإن سعيتم وصليتم مع الناس فذلك أفضل لكم، وإن كنتم بعيدين في السيارات، والحمد لله. المقصود: أن المحل هذا إذا كان فيه مستوطنون مقيمون شتاءً وصيفًا؛ فإنها تقام بينهم الجمعة، وأنتم معهم تصلوا معهم الجمعة، أما إذا كان لا، إنما أنتم عمال غير مستوطنين، وأنتم تزورون المحل زيارة فقط، فليس لكم أن تقيموا الجمعة في المحل هذا، ولكن تصلون مع الناس الجمعة، وإن صادف يوم الجمعة وأنتم هناك، وصليتم ظهرًا فلا بأس، للبعد، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18038/حكم-اقامة-الجمعة-في-مزرعة-بعيدة-عن-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73621.mp3","categories":["صلاة الجمعة"]},{"id":18914,"question":"لأخينا سؤال آخر يسأل فيه سماحتكم عن رأيكم فيمن يصلي الجمعة، ثم يصلي الظهر أيضًا في يوم الجمعة.","title":"حكم صلاة الظهر عقب أداء صلاة الجمعة","answer":"الجواب: هذا بدعة، ما يفعله بعض الناس من صلاة الظهر بعد الجمعة هذا بدعة لا أصل له، والمشروع للمؤمن إذا صلى الجمعة أن يصلي بعدها أربع ركعات نافلة، كما قال -عليه الصلاة والسلام-: إذا صليتم بعد الجمعة فصلوا بعدها أربعًا -عليه الصلاة والسلام- وكان يصلي في البيت ركعتين -عليه الصلاة والسلام-. فالسنة أن يصلى بعد الجمعة أربع، وإن صلى ركعتين فلا بأس، أما أنه يصلي الظهر هذا بدعة لا أصل له، ولا ينبغي أن يغتر بما يفعله بعض الناس في بعض البلدان، هذا شيء لا أصل له، وهو ناشئ عن الشك، بعضهم يقول: أخشى أن الجمعة غير صحيحة، هذا شيء لا محل له، ولا ينبغي هذا التشكك وهذه الوسوسة، نسأل الله السلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18055/حكم-صلاة-الظهر-عقب-اداء-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92314.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":18954,"question":"يقول السائل: إذا تعطلت الميكرفونات يوم الجمعة والإمام يخطب فهل القيام بتصليحها يعتبر جائزًا أم لا؟","title":"حكم إصلاح الميكرفونات والإمام يخطب","answer":"الجواب: لا، طيب مناسب، لا يضر -إن شاء الله-، تصليحها لا يضر؛ لأنه في مصلحة المسلمين. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18115/حكم-اصلاح-الميكرفونات-والامام-يخطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88232.mp3","categories":["صلاة الجمعة"]},{"id":19180,"question":"المستمع إبراهيم محمود مصري مقيم في الرياض له سؤال يقول فيه: في صلاة الجمعة أذن رجل الأذان الأول وأذن آخر الأذان الثاني، وخطب خطبتي الجمعة رجل، وصلى بنا رجل آخر، ما حكم ذلك؟","title":"حكم إمامة غير الخطيب في صلاة الجمعة","answer":"الجواب: ليس في هذا حرج والحمد لله، يجوز أن يتولى الأذان الأول واحد، والثاني آخر، والخطبة شخص، والإمامة شخص، كل هذا لا حرج فيه، والحمد لله. لكن الأفضل أن يتولى الخطبة من يتولى الصلاة، ويتولى الصلاة من يتولى الخطبة إذا تيسر ذلك، إذا تيسر ذلك فالأفضل أن الإمام هو الخطيب، كما كان النبي ﷺ والخلفاء الراشدون وغيرهم، هذا هو الأفضل. لكن لو خطب إنسان وصلى آخر فلا حرج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18355/حكم-امامة-غير-الخطيب-في-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93209.mp3","categories":["صلاة الجمعة"]},{"id":19215,"question":"ما حكم من يرفع يديه والخطيب يدعو للمسلمين في الخطبة الثانية مع الدليل؟ أثابكم الله وجزاكم خيرًا.","title":"حكم رفع اليدين أثناء دعاء الخطيب يوم الجمعة","answer":"الجواب: رفع اليدين غير مشروع في خطبة الجمعة، ولا في خطبة العيد لا للإمام ولا للمأمومين، وإنما الإنصات للخطيب، والتأمين على دعائه بينه وبين نفسه من دون رفع صوت، وأما رفع اليدين فلا يشرع. ولم يكن نبينا ﷺ يرفع يديه في خطبة الجمعة ولا في خطبة الأعياد، ولما رأى بعض الصحابة بعض الأمراء يرفع يديه في خطبة الجمعة أنكر عليه ذلك قال: ما كان النبي يرفعهما عليه الصلاة والسلام. نعم إذا كان في استسقاء يستغيث يوم الجمعة في خطبة الجمعة؛ فإنه يرفع يديه في حال الاستغاثة حال الاستسقاء طلب الغيث طلب المطر. كان النبي ﷺ يرفع يديه في هذه الحالة إذا استسقى في خطبة الجمعة أو في خطبة العيد، كان يرفع يديه عليه الصلاة والسلام. أما في الخطبة التي ليس فيها استسقاء فما كان يرفع عليه الصلاة والسلام. نعم. المقدم: اللهم صل وسلم عليه، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18390/حكم-رفع-اليدين-اثناء-دعاء-الخطيب-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93310.mp3","categories":["صلاة الجمعة","الأدعية والأذكار"]},{"id":19301,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها مجموعة من الأسئلة، ويقول المرسل (ي. م. ر) أخونا يقول: في صلاة الجمعة بعد الأذان يضعون شريط كاست في مسجل ليقرأ القرآن وبصوت عالٍ؛ بحيث يسمع جميع أهل الحي، وينصت الناس الذين في المسجد إلى هذا القرآن إلى أن يحين موعد الأذان الثاني مع العلم ألا أحد يقرأ القرآن بنفسه، هل هذا العمل جائز أو لا؟","title":"حكم قراءة القرآن عبر مكبرات المساجد قبل صلاة الجمعة","answer":"الجواب: إذا كان أهل المسجد متفقين على ذلك فلا بأس، إذا اتفقوا على أن يقرأ واحد منهم ويستمعون له أو من شريط ويستمعون له؛ لأن أكثرهم عوام ويرغبون أن يسمعوا هذا القارئ فهذا كله لا بأس به، كما لو جعلوا أحدهم يقرأ وهم يستمعون. أما أن يفعل ذلك من غير اختيار أهل المسجد فلا؛ لأن فيهم من يريد الصلاة حتى يخرج الإمام، وفيهم من يحب أن يقرأ بنفسه، فلا أرى أن هذا مناسب إلا باختيارهم ومشاورتهم، وإذا كانوا محصورين وجماعة قليلة ووافقوا على هذا فلا بأس أن يقرأ واحد وهم يستمعون، أو من شريط بصوت حسن القراءة فلا بأس بذلك إن كان الجماعة معدودين وراضين بهذا الشيء موافقين عليه، وإلا فالذي ينبغي ترك الناس وعدم جعل شريط يسمعهم القراءة، ولا أن يجهر أحد على أحد، بل كل واحد يقرأ فيما بينه وبين نفسه بقراءة لا تشغل من حوله ولا تؤذي من حوله، ولا تشوش على من حوله، كل يقرأ لنفسه ما تيسر. وكذلك من يصلي لا يتشوش بقراءة من حوله إذا كان يخفضها، فإن بعض الناس قد يصلي إلى دخول الإمام أو إلى قرب دخول الإمام، فوجود من يقرأ برفع الصوت يشوش على القارئين وعلى المصلين، والله المستعان. المقدم: الله المستعان، حزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/18514/حكم-قراءة-القران-عبر-مكبرات-المساجد-قبل-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89411.mp3","categories":["صلاة الجمعة"]},{"id":19311,"question":"أختنا تسأل وتقول: هل صحيح أنه يجب على المرأة أن لا تصلي الظهر يوم الجمعة إلا إذا خرج الرجال من المسجد؟","title":"وقت صلاة الجمعة للمرأة","answer":"الجواب: ليس بصحيح، فوقتها وقت الظهر، إذا زالت الشمس فإنها تصلي الظهر ولو أن الرجال لم يصلوا الجمعة، المهم دخول الوقت؛ فإن الواجب في حق المرأة هو الظهر، وهكذا المريض الذي ما يحضر الجمعة في بيته فإنه يصلي ظهرًا إذا زالت الشمس ولو لم يصل الرجال الجمعة، فإن بعض الخطباء قد يطول الخطبة، وقد يتأخر في الصلاة -صلاة الجمعة- فلا يلزم أن يتأخر المريض أو المرأة في بيتها، لا، متى دخل الوقت صلى المريض وصلت المرأة في بيتها ولو لم يصلوا صلاة الجمعة. المقدم: طيب، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18496/وقت-صلاة-الجمعة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89402.mp3","categories":["صلاة الجمعة"]},{"id":19339,"question":"يقول أخونا في سؤاله الأخير: عندما يصعد الخطيب فوق المنبر يبدأ الأذان يوم الجمعة بعد الأذن مباشرة يقوم الإمام الخامس ويقول: عن أبي هريرة عن النبي ﷺ قال: إذا قلت لصاحبك يوم الجمعة أنصت والإمام يخطب فقد لغوت، ومن لغا فلا جمعة له أنصتوا يرحمكم الله، أنصتوا يرحمكم الله، أنصتوا يرحمكم الله، بعد إتمام هذا الحديث يجلس ويقوم الإمام لبدء خطبة الجمعة، مع العلم أن هذا يتكرر كل جمعة، أفتونا في هذا؟ جزاكم الله خيرًا.","title":"حكم قول: (أنصتوا يرحمكم الله) عقب أذان الجمعة","answer":"الجواب: هذا العمل ليس له أصل في الشرع، بل هو بدعة كونه يقوم إنسان ويقول: أيها الناس! يتلو الحديث، عن النبي ﷺ أنه قال: إذا قلت لصاحبك أنصت يوم الجمعة، والإمام يخطب؛ فقد لغوت، ومن مس الحصا فقد لغا هذا ليس له أصل، وما كان يفعله المسلمون في عهد النبي ﷺ ولا عهد خلفائه الراشدين، بل هو من البدع، بل إذا أذن المؤذن يوم الجمعة قام الخطيب، وخطب الناس، وليس هناك من ينبه الناس، ويقول لهم: أنصتوا، لا بتلاوة الحديث ولا بغير ذلك، فهذا من المحدثات التي ليس لها أصل. والواجب على من أحدثها أن يدعها، وأن يتوب إلى الله من ذلك، لقول النبي عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد، وقوله عليه الصلاة والسلام: من أحدث في أمرنا - يعني: في ديننا - ما ليس منه فهو رد يعني: فهو مردود. وكان عليه الصلاة والسلام في خطبة الجمعة يقول: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها وكل بدعة ضلالة خرجه مسلم في صحيحه. فالواجب على أهل الإسلام التمسك بالسنة في كل شيء، والسير عليها، والتواصي بها، والحذر من البدع التي أحدثها الناس، ومن ذلك ما ذكرته أنه يفعل عندكم قبل الخطبة بأن يقوم إنسان يتلو الحديث، المعروف عن النبي ﷺ: إذا قلت لصاحبك: أنصت يوم الجمعة فقد لغوت ثم يكرر يقول: أنصتوا أنصتوا كل هذا لا أصل له كما سمعت، نسأل الله للجميع الهداية والتوفيق لما فيه اتباع السنة. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18546/حكم-قول-انصتوا-يرحمكم-الله-عقب-اذان-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_941/nour_94108.mp3","categories":["صلاة الجمعة","البدع والمحدثات"]},{"id":19410,"question":"هل فضل صلاة جماعة النساء، مثل فضل جماعة الرجال؟","title":"فضل جماعة النساء","answer":"الجواب: لا أعلم ذلك، الله أعلم؛ لأن الجماعة شرعت للرجال، أما النساء فقصارى ما يقال فيهن: أنه يجوز لهن أن يصلين جماعة، وأما هن فلسن مأمورات بالجماعة مأمورات أن يصلين في بيوتهن، ولسن مأمورات بالجماعة، لكن لو صلين جماعة فلا بأس ونرجو لهن الخير في ذلك، إذا كان المقصود من الجماعة الاستفادة حتى يتعلم بعضهن من بعض ويستفيد بعضهن من بعض هذا طيب، وقد روي عن أم سلمة وعائشة أنهما صلتا ببعض النساء جماعة للتعليم والتوجيه فلا بأس بهذا ولا حرج، أما كونها يحصل لها فضل الجماعة التي وعد الله بها الرجال فلا أعلم ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18637/فضل-جماعة-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93606.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":19415,"question":"مستمع بعث برسالة يقول فيها: بلغني أن بعض المرضى، والنساء يبادرون بإقامة صلاة الظهر يوم الجمعة عند سماع النداء الثاني، وحيث إن أكثر خطباء الجوامع يبدؤون بخطبة الجمعة بعد رفع النداء الثاني، وذلك قبل دخول وقت الظهر بعشرين أو خمس عشرة دقيقة، فآمل من سماحتكم توجيه الناس، جزاكم الله خيرًا.","title":"حكم صلاة الظهر عند الأذان الثاني للجمعة لأهل الأعذار","answer":"الجواب: الواجب على النساء والمرضى الذين يصلون في البيوت، أو في المستشفيات ألا يعجلوا؛ حتى يتحققوا دخول الوقت يوم الجمعة، وكذلك بقية الأيام، وعندهم التقاويم التي أصدرتها الأوقاف، في إمكانهم الاستفادة منها، ولا سيما يوم الجمعة؛ فإن بعض الخطباء قد يدخل المسجد، ويبدأ بالخطبة قبل الوقت، وقد يتساهل مع أنه ينبغي للخطباء ألا يبدؤوا إلا بعد الزوال، وألا يؤذن للجمعة إلا بعد الزوال، كما هو قول جمهور أهل العلم. وأكثر العلماء على أن الخطبة تكون بعد الزوال، ولا تصلح قبل الزوال، فينبغي للخطباء أن يحتاطوا لدينهم، وأن يحتاطوا لإخوانهم المسلمين؛ فيكون الدخول والصلاة بعد الأذان - يعني بعد الزوال - يأتي إلى الجمعة بعد الزوال، والساعات موجودة ومتوفرة والحمد لله، حتى يؤذن المؤذن بعد الزوال، وتكون الخطبة والجمعة بعد الزوال فيحتاطوا للمسلمين، ويبتعدوا عما يسبب وقوعهم فيما يخالف الشرع المطهر، ولا سيما المرضى والنساء. وعلى النساء، وعلى المرضى التثبت في الأمور، وألا يصلوا إلا بعد دخول الوقت، والتأكد من دخول الوقت: الظهر، والعصر، والمغرب، والعشاء، والفجر في الجمعة وغيرها. هذا هو الواجب على الجميع.","link":"https://binbaz.org.sa/fatwas/18642/حكم-صلاة-الظهر-عند-الاذان-الثاني-للجمعة-لاهل-الاعذار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93611.mp3","categories":["صلاة الجمعة","وقت الصلاة","قضايا المرأة"]},{"id":19483,"question":"هذا السائل ماهر، له مجموعة من الأسئلة يقول: في يوم الجمعة هل يصلي الإنسان الأربع الرواتب قبلها أي: الظهر والركعتين بعدها؟ أم يقتصر على ركعتين أو أربع بعد الجمعة، ويترك راتبتي الظهر يوم الجمعة دون سائر الأيام؟","title":"النوافل المشروعة قبل الجمعة وبعدها","answer":"الجواب: يوم الجمعة يصلي قبلها ما تيسر أربع وإلا ست وإلا ثمان وإلا عشر وإلا أكثر، النبي ﷺ ما حدد شيء قال:  صلى ما قدر له. أما بعدها فالسنة أن يصلي أربعًا تسليمتين، النبي عليه السلام قال: إذا صلى أحدكم الجمعة فليصل بعدها أربعًا يعني: تسليمتين. أما قبلها يقول ﷺ: ثم أتى المسجد فصلى ما قدر له صل ما تيسر قبلها ثنتين أو أربع تسليمتين أو ثلاث تسليمات، أو أربع تسليمات، أو خمس تسليمات أو أكثر ما في شيء محدود، والحمد لله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18730/النوافل-المشروعة-قبل-الجمعة-وبعدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93917.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":19555,"question":"الأخت السائلة من حائل تقول: يا سماحة الشيخ! هل النساء كحكم الرجال في المسائل التالية: في أجر انتظار الصلاة في بيتها، وعلى مصلاها، وفي البقاء بعد الصلاة في مصلاها، وفي غسل يوم الجمعة، والتطيب قبل صلاة الظهر من ذلك اليوم -يوم الجمعة- وفي سنة قراءة سورة السجدة، والإنسان، في فجر يوم الجمعة؟","title":"هل حكم النساء كالرجال في العبادات التي تؤديها في بيتها","answer":"الجواب: نعم، الأصل أن النساء والرجال سواء فيما شرع الله من الأحكام من صلاة وغيرها، هذا هو الأصل، الأصل أن النساء والرجال سواء فيما شرع الله من الأحكام، إلا ما دل الدليل على تخصيص المرأة أو الرجل به، وإلا فالأصل أنهما سواء، فالتبكير بالصلاة، والخشوع فيها، والإقبال عليها، والاجتهاد فيها؛ كل هذا مشروع للجميع، وإحضار القلب فيها، والطمأنينة كل هذا مشروع للجميع. أما غسل يوم الجمعة فهذا خاص بالرجال؛ لأنهم يتوجهون إلى المسجد، ويجتمعون بالناس، فقد يحصل منهم رائحة تؤذي من حولهم من جيرانهم، وهكذا الطيب. فالظاهر -والله أعلم- أن هذا من خصائص الرجال: الطيب، والغسل يوم الجمعة من خصائص الرجال؛ لأن المقصود عدم إيذاء من يصلي حوله، ومع كونه يأتي الصلاة بحالة فيها النشاط، والقوة، والرغبة في الخير، وهذا مفقود في حق النساء؛ لأنهن يصلين في البيوت، وإذا صلت مع الرجال في الجمعة، إذا صلى النساء مع الرجال واغتسلت فلا أعلم بأسًا في ذلك ولا حرجًا في ذلك لوجود العلة، لكن الطيب لا؛ لأن المرأة عورة، والطيب قد يفتن عند خروجها من بيتها إلى المسجد ورجوعها، ولكن الاغتسال لا بأس به، لو اغتسلت وصلت مع الناس يوم الجمعة فلا حرج في ذلك، لكن بيتها أفضل، بيتها خير لها كما قال لها النبي ﷺ. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18803/هل-حكم-النساء-كالرجال-في-العبادات-التي-توديها-في-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94702.mp3","categories":["صلاة الجماعة","صلاة الجمعة","قضايا المرأة"]},{"id":19719,"question":"بعد الخطبة يداوم على الصلاة على النبي ﷺ في الخطبة؟","title":"حكم الصلاة على النبي أثناء الخُطبة","answer":"الجواب: إذا ذُكر النبي يُصلي عليه، إذا قال أشهد أن محمدًا عبده ورسوله يصلي عليه عليه الصلاة والسلام، وهكذا إذا مرّ ذكرُه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/28164/حكم-الصلاة-على-النبي-اثناء-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/%D8%AD%D9%83%D9%85%20%D8%A7%D9%84%D8%B5%D9%84%D8%A7%D8%A9%20%D8%B9%D9%84%D9%89%20%D8%A7%D9%84%D9%86%D8%A8%D9%8A%20%D8%A3%D8%AB%D9%86%D8%A7%D8%A1%20%D8%A7%D9%84%D8%AE%D8%B7%D8%A8%D8%A9.mp3","categories":["صلاة الجمعة"]}]
